def _meeting_alignment_job_span(
    job: "MeetingAlignmentJob",
) -> tuple[datetime | None, datetime | None]:
    """A stored job's own start and end, read back from the source it was built from."""
    end = _parse_optional_datetime(job.ended_at)
    start = None
    try:
        source = json.loads(job.source_json or "{}")
    except (TypeError, ValueError):
        source = {}
    discovery = source.get("discovery")
    if isinstance(discovery, dict):
        start = _parse_optional_datetime(discovery.get("started_at"))
    return start, end


def _parse_optional_datetime(value: object) -> datetime | None:
    if not isinstance(value, str) or not value.strip():
        return None
    try:
        return datetime.fromisoformat(value)
    except ValueError:
        return None


_INITIALIZED_STORE_PATHS: set[Path] = set()


def _sqlite_caller_chain(frame) -> str:
    callers = []
    for _ in range(8):
        callers.append(
            f"{Path(frame.f_code.co_filename).name}:{frame.f_lineno}:{frame.f_code.co_name}"
        )
        frame = frame.f_back
        if frame is None:
            break
    return " <- ".join(callers)


def _name_sqlite_extended_error(path: Path, error: sqlite3.Error) -> None:
    """Name the SQLite extended result code on a failure's way out.

    `disk I/O error` is the primary code SQLITE_IOERR and says nothing about
    which operation failed. The extended code separates a failing read from a
    failing shared-memory map or fsync, which is the part that tells a bad page
    apart from a filesystem or locking problem. The error is re-raised
    unchanged; this only names it.
    """
    name = getattr(error, "sqlite_errorname", "")
    if not name:
        return
    callers = _sqlite_caller_chain(sys._getframe(1))
    print(
        f"sqlite {name} code={getattr(error, 'sqlite_errorcode', '')} "
        f"path={path} thread={threading.get_ident()} callers={callers}: {error}",
        file=sys.stderr,
        flush=True,
    )

_INITIALIZE_LOCK = threading.Lock()






