class CodexSessionLock:
    def __init__(self, store, conversation_id: str, owner: str):
        self.store = store
        self.conversation_id = conversation_id
        self.owner = owner

    def __enter__(self):
        if not self.store.acquire_codex_session_lock(self.conversation_id, self.owner):
            raise RuntimeError(f"codex session locked: {self.conversation_id}")
        return self

    def __exit__(self, exc_type, exc, tb):
        released = self.store.release_codex_session_lock(
            self.conversation_id,
            self.owner,
        )
        if not released and exc_type is None:
            raise RuntimeError(
                f"codex session lock release failed: {self.conversation_id}"
            )
        return False


def _embedding_score(
    query_embedding: list[float] | None,
    stored_embedding: list[float],
) -> float:
    if not query_embedding or not stored_embedding:
        return 0.0
    pairs = list(zip(query_embedding, stored_embedding))
    if not pairs:
        return 0.0
    dot = sum(left * right for left, right in pairs)
    left_norm = sum(left * left for left, _ in pairs) ** 0.5
    right_norm = sum(right * right for _, right in pairs) ** 0.5
    if not left_norm or not right_norm:
        return 0.0
    return dot / (left_norm * right_norm)


_MEETING_SEARCH_CACHE_LOCK = threading.Lock()
_MEETING_SEARCH_CORPUS_CACHE: OrderedDict[tuple, tuple[str, str]] = OrderedDict()
_MEETING_SEARCH_VECTOR_CACHE: OrderedDict[tuple, list[float]] = OrderedDict()
_MEETING_SEARCH_CACHE_LIMIT = 256


def _meeting_search_cache_get(cache: OrderedDict, key: tuple):
    with _MEETING_SEARCH_CACHE_LOCK:
        value = cache.get(key)
        if value is not None:
            cache.move_to_end(key)
        return value


def _meeting_search_cache_put(cache: OrderedDict, key: tuple, value: object) -> None:
    with _MEETING_SEARCH_CACHE_LOCK:
        cache[key] = value
        cache.move_to_end(key)
        while len(cache) > _MEETING_SEARCH_CACHE_LIMIT:
            cache.popitem(last=False)


def _utc_store_time(now: str | datetime | None = None) -> tuple[datetime, str]:
    if now is None:
        value = datetime.now(timezone.utc)
    elif isinstance(now, datetime):
        value = now
    elif isinstance(now, str) and now.strip():
        try:
            value = datetime.fromisoformat(now.strip().replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValueError("now must be an ISO timestamp") from exc
    else:
        raise ValueError("now must be an ISO timestamp or datetime")
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    else:
        value = value.astimezone(timezone.utc)
    value = value.replace(microsecond=0)
    return value, value.strftime("%Y-%m-%d %H:%M:%S")


def _json_object_text(value: object, *, field: str) -> str:
    if not isinstance(value, dict):
        raise ValueError(f"{field} must be a JSON object")
    try:
        text = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field} must be a JSON object") from exc
    if not isinstance(json.loads(text), dict):
        raise ValueError(f"{field} must be a JSON object")
    return text


def _canonical_json_sha256(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _is_sqlite_lock_error(exc: sqlite3.OperationalError) -> bool:
    message = str(exc).lower()
    return "locked" in message or "busy" in message


def _is_sqlite_missing_schema_error(exc: sqlite3.Error) -> bool:
    if getattr(exc, "sqlite_errorcode", None) != sqlite3.SQLITE_ERROR:
        return False
    message = str(exc).casefold()
    return message.startswith("no such table:") or message.startswith(
        "no such column:"
    )


# Opening a SQLite connection re-parses the whole schema (hundreds of objects
# with JSON generated columns), which dominated service CPU when every store
# call opened its own.  Each thread keeps one idle connection per database
# file; nested or concurrent use in the same thread opens its own, as before.
_IDLE_CONNECTIONS = threading.local()


def _database_file_identity(path: Path) -> tuple[int, int] | None:
    try:
        stat = os.stat(path)
    except OSError:
        return None
    return (stat.st_dev, stat.st_ino)


def _take_idle_connection(
    key: tuple[str, int | None, object], path: Path
) -> tuple[sqlite3.Connection, tuple[int, int], int] | None:
    pool = getattr(_IDLE_CONNECTIONS, "pool", None)
    entry = pool.pop(key, None) if pool else None
    if entry is None:
        return None
    connection, identity, _changes = entry
    if identity != _database_file_identity(path):
        with suppress(sqlite3.Error):
            connection.close()
        return None
    return entry


def _close_idle_connections() -> None:
    """Close this thread's idle connections (tests, and callers that must be
    the only connection to a database file)."""
    pool = getattr(_IDLE_CONNECTIONS, "pool", None) or {}
    for connection, _identity, _changes in pool.values():
        with suppress(sqlite3.Error):
            connection.close()
    pool.clear()


def _return_idle_connection(
    key: tuple[str, int | None, object],
    connection: sqlite3.Connection,
    identity: tuple[int, int] | None,
) -> None:
    pool = _IDLE_CONNECTIONS.__dict__.setdefault("pool", {})
    try:
        reusable = (
            identity is not None
            and key not in pool
            and not connection.in_transaction
            and connection.execute("pragma foreign_keys").fetchone()[0] == 1
        )
    except sqlite3.Error:
        reusable = False
    if reusable:
        # What is worth keeping is the parsed schema; the page cache (up to
        # SQLITE_READ_CACHE_SIZE per connection) is not, and an idle connection
        # per thread per database would otherwise hold it for good.
        with suppress(sqlite3.Error):
            connection.execute("pragma shrink_memory")
        pool[key] = (connection, identity, connection.total_changes)
    else:
        with suppress(sqlite3.Error):
            connection.close()


class AutoReplyStore(LogicalRunStoreMixin, ReviewedCandidateStoreMixin):
    def __init__(
        self,
        path: Path,
        *,
        busy_timeout_seconds: int = SQLITE_BUSY_TIMEOUT_SECONDS,
    ):
        self.path = path
        self.busy_timeout_seconds = busy_timeout_seconds
        self.busy_timeout_milliseconds = busy_timeout_seconds * 1000
        self._read_snapshot_connection: ContextVar[sqlite3.Connection | None] = (
            ContextVar(f"audit_read_snapshot_{id(self)}", default=None)
        )
        self._reused_connection: ContextVar[sqlite3.Connection | None] = (
            ContextVar(f"sqlite_reused_connection_{id(self)}", default=None)
        )
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._ensure_initialized()

    def _ensure_initialized(self) -> None:
        require_current_pair(self.path)
        path_key = self.path.resolve()
        if self._cached_initialized_path_is_healthy(path_key):
            return
        with _INITIALIZE_LOCK:
            if self._cached_initialized_path_is_healthy(path_key):
                return
            with self._schema_initialize_lock():
                require_current_pair(self.path)
                if self._cached_initialized_path_is_healthy(path_key):
                    return
                self._require_supported_store_bootstrap_source()
                self._ensure_wal_journal_mode()
                if self._schema_is_current_after_lock_retry():
                    _INITIALIZED_STORE_PATHS.add(path_key)
                    return
                self._initialize()
                if not self._schema_manifest_is_current_after_lock_retry():
                    raise FeedbackProcessingSchemaIntegrityError(
                        FEEDBACK_PROCESSING_SCHEMA_MIGRATION_INTEGRITY_ERROR
                    )
                _INITIALIZED_STORE_PATHS.add(path_key)

    def _cached_initialized_path_is_healthy(self, path_key: Path) -> bool:
        if path_key not in _INITIALIZED_STORE_PATHS:
            return False
        try:
            with self._connect() as db:
                healthy = self._schema_manifest_is_current_in_connection(db, include_run_snapshots=False)
        except BaseException:
            _INITIALIZED_STORE_PATHS.discard(path_key)
            raise
        if healthy:
            return True
        _INITIALIZED_STORE_PATHS.discard(path_key)
        return False




    def _ensure_wal_journal_mode(self) -> None:
        with self._connect() as db:
            journal_mode = str(db.execute("pragma journal_mode = wal").fetchone()[0])
        if journal_mode.casefold() != "wal":
            raise RuntimeError(
                f"failed to enable SQLite WAL journal mode: {journal_mode}"
            )

    def _schema_is_current_after_lock_retry(self) -> bool:
        for attempt in range(SCHEMA_CHECK_LOCK_RETRY_ATTEMPTS):
            try:
                return self._schema_is_current()
            except sqlite3.OperationalError as exc:
                if not _is_sqlite_lock_error(exc):
                    raise
                if attempt + 1 >= SCHEMA_CHECK_LOCK_RETRY_ATTEMPTS:
                    raise
                time.sleep(SCHEMA_CHECK_LOCK_RETRY_DELAY_SECONDS)
        raise RuntimeError("schema check retry loop exhausted")

    @contextmanager
    def _schema_initialize_lock(self) -> Iterator[None]:
        """Serialize schema work across processes sharing this database."""
        with schema_initialize_lock(self.path):
            yield

    @contextmanager
    def managed_skill_baseline_initialization_lock(self) -> Iterator[None]:
        """Serialize managed-Skill baseline reconciliation across processes."""
        with self._schema_initialize_lock():
            yield

    @staticmethod
    def _feedback_processing_round_storage_is_valid(
        db: sqlite3.Connection,
    ) -> bool:
        return (
            db.execute(
                """
                select 1
                  from feedback_processing_rounds
                 where typeof(round_number) <> 'integer'
                    or round_number <= 0
                 limit 1
                """
            ).fetchone()
            is None
        )

    @classmethod
    def _validate_feedback_processing_round_storage(
        cls,
        db: sqlite3.Connection,
    ) -> None:
        if not cls._feedback_processing_round_storage_is_valid(db):
            raise FeedbackProcessingRoundMigrationIntegrityError(
                FEEDBACK_PROCESSING_ROUND_MIGRATION_INTEGRITY_ERROR
            )







    def _scheduled_task_run_snapshots_are_current(
        self,
        db: sqlite3.Connection,
    ) -> bool:
        """Whether every persisted run snapshot carries the command fields.

        This reads rows, so it only runs where a migration has just claimed to
        have produced them.  Running it on every store construction made one
        damaged page in a table that grows with every scheduled run fatal at
        startup for every CLI subprocess, and `database disk image is
        malformed` arrives as `sqlite3.DatabaseError`, which the callers'
        `except sqlite3.OperationalError` does not catch.
        """
        # Ask SQLite for the first offending row instead of materialising the
        # table.  A snapshot that cannot be parsed is corrupt data, not an
        # out-of-date schema: migrating cannot repair it, so json_valid
        # excludes it here and the row still fails where it is read.
        # json_type() distinguishes an absent key (NULL) from a key whose
        # value is JSON null, which is what the presence test needs.
        return (
            db.execute(
                f"""
                select 1 from ({config_projection('scheduled_task_config_versions')})
                where json_valid(snapshot_json)
                  and json_type(snapshot_json) = 'object'
                  and (
                    json_type(snapshot_json, '$.command') is null
                    or json_type(
                        snapshot_json, '$.required_runtime_capabilities'
                    ) is null
                  )
                limit 1
                """
            ).fetchone()
            is None
        )

    def _schema_manifest_is_current_in_connection(self, db, *, include_run_snapshots):
        return (schema_is_current(db)
                and self._feedback_processing_round_storage_is_valid(db)
                and (not include_run_snapshots or self._scheduled_task_run_snapshots_are_current(db)))


    def _schema_manifest_is_current(self) -> bool:
        try:
            with self._connect() as db:
                # Post-migration verification: a migration has just claimed to
                # have written the snapshot fields, so read them back.
                return self._schema_manifest_is_current_in_connection(
                    db, include_run_snapshots=True
                )
        except sqlite3.Error as exc:
            if _is_sqlite_missing_schema_error(exc):
                return False
            raise

    def _schema_manifest_is_current_after_lock_retry(self) -> bool:
        for attempt in range(SCHEMA_CHECK_LOCK_RETRY_ATTEMPTS):
            try:
                return self._schema_manifest_is_current()
            except sqlite3.OperationalError as exc:
                if not _is_sqlite_lock_error(exc):
                    raise
                if attempt + 1 >= SCHEMA_CHECK_LOCK_RETRY_ATTEMPTS:
                    raise
                time.sleep(SCHEMA_CHECK_LOCK_RETRY_DELAY_SECONDS)
        raise RuntimeError("schema manifest check retry loop exhausted")

    def _schema_is_current(self) -> bool:
        # A fresh database has no State table yet. This probe is an
        # expected pre-initialization miss, so keep it off the normal
        # connection path that annotates every SQLite error as an operational
        # failure.
        connection = self._open_connection()
        try:
            with connection:
                row = connection.execute(
                    f"select value from ({state_projection('service_state')}) where key=?",
                    (STORE_SCHEMA_VERSION_KEY,),
                ).fetchone()
                return bool(
                    row is not None
                    and str(row["value"] or "") == STORE_SCHEMA_VERSION
                    # Fast path on every store construction: structure only.
                    # The version is written only after a migration passed the
                    # row check, so a matching version already implies it.
                    and self._schema_manifest_is_current_in_connection(
                        connection, include_run_snapshots=False
                    )
                )
        except sqlite3.Error as exc:
            if _is_sqlite_missing_schema_error(exc):
                return False
            _name_sqlite_extended_error(self.path, exc)
            raise
        finally:
            connection.close()

    @contextmanager
    def _connect(self) -> Iterator[sqlite3.Connection]:
        snapshot = self._read_snapshot_connection.get()
        if snapshot is not None:
            started_at = time.monotonic()
            try:
                yield snapshot
            finally:
                elapsed = time.monotonic() - started_at
                if elapsed >= 1.0:
                    print(
                        f"slow sqlite context elapsed_seconds={elapsed:.3f} "
                        f"body_seconds={elapsed:.3f} "
                        "finish_seconds=0.000 close_seconds=0.000 "
                        f"callers={_sqlite_caller_chain(sys._getframe(2))}",
                        file=sys.stderr,
                        flush=True,
                    )
            return
        reused = self._reused_connection.get()
        pool_key = None
        identity = None
        if reused is not None:
            connection = reused
        else:
            opener = self._open_connection
            pool_key = (
                str(self.path),
                getattr(self, "busy_timeout_seconds", None),
                getattr(opener, "__func__", opener),
            )
            idle = _take_idle_connection(pool_key, self.path)
            if idle is not None:
                connection, identity, _ = idle
            else:
                connection = self._open_connection()
                identity = _database_file_identity(self.path)
        completed = False
        started_at = time.monotonic()
        body_finished_at = started_at
        starting_changes = 0
        try:
            try:
                terminal_event_runs = []
                with connection:
                    starting_changes = connection.total_changes
                    try:
                        yield connection
                    finally:
                        body_finished_at = time.monotonic()
                    if connection.total_changes != starting_changes:
                        from app.native_trajectory import terminal_cached_run_ids
                        terminal_event_runs = terminal_cached_run_ids(connection, str(self.path.resolve()))
                if terminal_event_runs:
                    from app.native_trajectory import forget_live_events
                    forget_live_events(str(self.path.resolve()), terminal_event_runs)
                completed = True
            finally:
                close_started_at = time.monotonic()
                if reused is None:
                    if completed:
                        _return_idle_connection(pool_key, connection, identity)
                    else:
                        with suppress(sqlite3.Error):
                            connection.close()
                closed_at = time.monotonic()
                elapsed = closed_at - started_at
                if elapsed >= 1.0:
                    print(
                        f"slow sqlite context elapsed_seconds={elapsed:.3f} "
                        f"body_seconds={body_finished_at - started_at:.3f} "
                        f"finish_seconds={close_started_at - body_finished_at:.3f} "
                        f"close_seconds={closed_at - close_started_at:.3f} "
                        f"callers={_sqlite_caller_chain(sys._getframe(2))}",
                        file=sys.stderr,
                        flush=True,
                    )
        except sqlite3.Error as error:
            _name_sqlite_extended_error(self.path, error)
            raise

    @contextmanager
    def _optional_connection(
        self, connection: sqlite3.Connection | None
    ) -> Iterator[sqlite3.Connection]:
        if connection is not None:
            yield connection
            return
        with self._connect() as db:
            yield db

    @contextmanager
    def _immediate_write_transaction(self) -> Iterator[sqlite3.Connection]:
        """Acquire a short SQLite write transaction with bounded lock retry."""
        started_at = time.monotonic()
        lock_wait_seconds = 0.0
        transaction_hold_seconds = 0.0
        body_started = False
        try:
            for attempt in range(STORE_WRITE_LOCK_RETRY_ATTEMPTS):
                acquired_at: float | None = None
                try:
                    with self._connect() as db:
                        begin_started_at = time.monotonic()
                        try:
                            db.execute("begin immediate")
                        finally:
                            lock_wait_seconds += time.monotonic() - begin_started_at
                        acquired_at = time.monotonic()
                        body_started = True
                        yield db
                        return
                except sqlite3.OperationalError as exc:
                    if (
                        body_started
                        or not _is_sqlite_lock_error(exc)
                        or attempt + 1 >= STORE_WRITE_LOCK_RETRY_ATTEMPTS
                    ):
                        raise
                    retry_wait_started_at = time.monotonic()
                    try:
                        time.sleep(
                            STORE_WRITE_LOCK_RETRY_DELAY_SECONDS * (attempt + 1)
                        )
                    finally:
                        lock_wait_seconds += (
                            time.monotonic() - retry_wait_started_at
                        )
                finally:
                    if acquired_at is not None:
                        transaction_hold_seconds += (
                            time.monotonic() - acquired_at
                        )
            raise RuntimeError("SQLite write transaction retry loop exhausted")
        finally:
            elapsed = time.monotonic() - started_at
            if elapsed >= 1.0:
                print(
                    f"slow sqlite write transaction elapsed_seconds={elapsed:.3f} "
                    f"lock_wait_seconds={lock_wait_seconds:.3f} "
                    f"hold_seconds={transaction_hold_seconds:.3f} "
                    f"callers={_sqlite_caller_chain(sys._getframe(2))}",
                    file=sys.stderr,
                    flush=True,
                )

    def _open_connection(self) -> sqlite3.Connection:
        connection: sqlite3.Connection | None = None
        try:
            connection = sqlite3.connect(
                self.path,
                timeout=self.busy_timeout_seconds,
            )
            register_task8_functions(connection)
            connection.execute(
                f"pragma busy_timeout = {self.busy_timeout_milliseconds}"
            )
            connection.execute("pragma synchronous = normal")
            # History is a read-heavy UNION over a large, text-heavy database.
            # Bound the per-connection cache, but keep the mutable WAL database
            # off SQLite's mapped-page path.
            connection.execute(f"pragma cache_size = {SQLITE_READ_CACHE_SIZE}")
            connection.execute(f"pragma mmap_size = {SQLITE_MMAP_SIZE_BYTES}")
            connection.execute("pragma foreign_keys = on")
            connection.row_factory = sqlite3.Row
            return connection
        except sqlite3.Error as error:
            _name_sqlite_extended_error(self.path, error)
            if connection is not None:
                with suppress(sqlite3.Error):
                    connection.close()
            raise

    @contextmanager
    def reuse_connection(self) -> Iterator[None]:
        """Keep one connection for this synchronous operation sequence.

        Each _connect retains its own commit/rollback boundary. ContextVar
        scoping keeps the execution thread separate from heartbeat threads.
        """
        if self._reused_connection.get() is not None:
            yield
            return
        connection = self._open_connection()
        token = self._reused_connection.set(connection)
        try:
            yield
        finally:
            self._reused_connection.reset(token)
            connection.close()

    @contextmanager
    def read_snapshot(self) -> Iterator[None]:
        """Reuse one read-only SQLite snapshot for a related audit render."""
        if self._read_snapshot_connection.get() is not None:
            yield
            return
        connection = self._open_connection()
        try:
            connection.execute("pragma query_only = on")
            connection.execute("begin")
            token = self._read_snapshot_connection.set(connection)
            try:
                yield
            finally:
                self._read_snapshot_connection.reset(token)
        finally:
            connection.rollback()
            connection.close()

    def _initialize(self) -> None:
        if not self._require_supported_store_bootstrap_source():
            return
        from app.current_database_schema import create_current_database_schema
        with self._connect() as db:
            db.execute("pragma foreign_keys=off")
            db.execute("begin immediate")
            create_current_database_schema(db)
            if not self._schema_manifest_is_current_in_connection(db, include_run_snapshots=True):
                raise FeedbackProcessingSchemaIntegrityError(FEEDBACK_PROCESSING_SCHEMA_MIGRATION_INTEGRITY_ERROR)
            upsert_state(db, "service_state",
                         {"key": STORE_SCHEMA_VERSION_KEY, "value": STORE_SCHEMA_VERSION},
                         {"value": state_json_field("value"), "updated_at": "json_quote(current_timestamp)"})


    def prepare_meeting_alignment_message(
        self, *, delivery_key: str, body: str, original_text: str,
        target_kind: str, target_id: str, feedback_base_url: str | None = None,
    ) -> PreparedOutboundMessage:
        """Atomically bind one meeting preparation to its immutable recipient."""
        _, key = normalize_outbound_postfix_inputs(
            channel="dingtalk", delivery_key=delivery_key, body=body
        )
        if target_kind not in {"group", "user", "open_user"} or not target_id.strip():
            raise ValueError("meeting delivery target is invalid")
        state_key = f"meeting_delivery_target:v1:dingtalk:{key}"
        target_json = json.dumps(
            {"kind": target_kind, "id": target_id.strip()}, sort_keys=True
        )
        with self._immediate_write_transaction() as db:
            target = db.execute(f"select value from ({state_projection('service_state')}) where key=?", (state_key,)).fetchone()
            prepared = db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_SQL}) where channel='dingtalk' and delivery_key=?", (key,)
            ).fetchone()
            if target is not None:
                if str(target["value"]) != target_json or prepared is None:
                    raise ValueError("meeting prepared target binding conflicts")
            elif prepared is not None:
                # Legacy receipts do not establish their recipient by body equality.
                raise ValueError("meeting prepared target is unverified")
            message = self._prepare_outbound_postfix_in_transaction(
                db, channel="dingtalk", delivery_key=key, body=body,
                original_text=original_text, feedback_base_url=feedback_base_url,
            )
            if target is None:
                insert_state(db, 'service_state', {'key': state_key, 'value': target_json})
            return message

    def resolve_meeting_alignment_delivery_key(
        self, delivery_key: str, *, target_kind: str, target_id: str,
    ) -> str:
        """Reuse a legacy key only for its exact bound recipient; scope new keys."""
        legacy_key = delivery_key.strip()
        if not legacy_key:
            raise ValueError("meeting delivery key is required")
        if target_kind not in {"group", "user", "open_user"} or not target_id.strip():
            raise ValueError("meeting delivery target is invalid")
        target_json = json.dumps(
            {"kind": target_kind, "id": target_id.strip()}, sort_keys=True
        )
        state_key = f"meeting_delivery_target:v1:dingtalk:{legacy_key}"
        bound = self.get_service_state(state_key)
        prepared = self.get_outbound_postfix("dingtalk", legacy_key)
        receipt = self.get_outbound_postfix_receipt("dingtalk", legacy_key)
        if bound == target_json and prepared is not None:
            return legacy_key
        if bound is not None and prepared is None:
            raise ValueError("meeting prepared target binding conflicts")
        if bound is None and (prepared is not None or receipt is not None):
            raise ValueError("meeting prepared target is unverified")
        target_digest = hashlib.sha256(target_json.encode("utf-8")).hexdigest()
        return f"{legacy_key}:target:{target_digest}"

    def verify_meeting_alignment_target(self, delivery_key: str, *, target_kind: str, target_id: str) -> None:
        expected = json.dumps({"kind": target_kind, "id": target_id.strip()}, sort_keys=True)
        bound = self.get_service_state(f"meeting_delivery_target:v1:dingtalk:{delivery_key.strip()}")
        if bound != expected:
            raise ValueError("meeting prepared target binding conflicts")

    def prepare_outbound_postfix(
        self,
        channel: str,
        delivery_key: str,
        body: str,
        original_text: str,
        *,
        feedback_base_url: str | None = None,
    ) -> PreparedOutboundMessage:
        """Persist and return the immutable final form for one provider delivery."""
        with self._immediate_write_transaction() as db:
            return self._prepare_outbound_postfix_in_transaction(
                db,
                channel=channel,
                delivery_key=delivery_key,
                body=body,
                original_text=original_text,
                feedback_base_url=feedback_base_url,
            )

    @staticmethod
    def _prepare_outbound_postfix_in_transaction(
        db: sqlite3.Connection,
        *,
        channel: str,
        delivery_key: str,
        body: str,
        original_text: str,
        feedback_base_url: str | None = None,
    ) -> PreparedOutboundMessage:
        """Prepare one immutable body inside the caller's existing transaction."""
        normalized_channel, normalized_delivery_key = normalize_outbound_postfix_inputs(
            channel=channel,
            delivery_key=delivery_key,
            body=body,
        )
        row = db.execute(
            f'select channel, delivery_key, final_body, feedback_token, postfix_version\n               from ({OUTBOUND_POSTFIX_SQL})\n               where channel=? and delivery_key=?',
            (normalized_channel, normalized_delivery_key),
        ).fetchone()
        if row is not None:
            return PreparedOutboundMessage(
                channel=str(row["channel"]),
                delivery_key=str(row["delivery_key"]),
                final_body=str(row["final_body"]),
                feedback_token=str(row["feedback_token"]),
                postfix_version=str(row["postfix_version"]),
            )
        prepared = compose_outbound_postfix(
            channel=normalized_channel,
            delivery_key=normalized_delivery_key,
            body=body,
            original_text=original_text,
            feedback_base_url=(
                feedback_spike_vercel_base_url()
                if feedback_base_url is None
                else feedback_base_url
            ),
        )
        shared_action_lifecycle.prepare_outbound_action(
            db, channel=prepared.channel, delivery_key=prepared.delivery_key,
            final_body=prepared.final_body, feedback_token=prepared.feedback_token,
            postfix_version=prepared.postfix_version,
        )
        return prepared

    def get_outbound_postfix(
        self,
        channel: str,
        delivery_key: str,
    ) -> PreparedOutboundMessage | None:
        """Return an already-prepared outbound message without creating one."""
        normalized_channel = channel.strip()
        normalized_delivery_key = delivery_key.strip()
        if normalized_channel not in {"dingtalk", "wechat"}:
            raise ValueError("unsupported outbound channel")
        if not normalized_delivery_key:
            raise ValueError("delivery key is required")
        with self._connect() as db:
            row = db.execute(
                f'select channel, delivery_key, final_body, feedback_token, postfix_version\n                   from ({OUTBOUND_POSTFIX_SQL})\n                   where channel=? and delivery_key=?',
                (normalized_channel, normalized_delivery_key),
            ).fetchone()
        if row is None:
            return None
        return PreparedOutboundMessage(
            channel=str(row["channel"]),
            delivery_key=str(row["delivery_key"]),
            final_body=str(row["final_body"]),
            feedback_token=str(row["feedback_token"]),
            postfix_version=str(row["postfix_version"]),
        )

    def recorded_outbound_body_keys(self, channel: str, since: str) -> set[str]:
        """Echo keys for every message this service sent on a channel since `since`.

        DWS sends as the signed-in user, so a message the service delivered into
        the user's own robot chat carries the user's identity and cannot be told
        apart from something the user typed. This record of what we sent is the
        only thing that separates the two.
        """
        normalized_channel = channel.strip()
        if normalized_channel not in {"dingtalk", "wechat"}:
            raise ValueError("unsupported outbound channel")
        with self._connect() as db:
            rows = db.execute(
                f'select final_body from ({OUTBOUND_POSTFIX_SQL})\n                   where channel=? and created_at>=?',
                (normalized_channel, since),
            ).fetchall()
        return {outbound_body_echo_key(str(row["final_body"])) for row in rows}

    def claim_native_reply_dispatch(self, channel: str, delivery_key: str, *, operation: str) -> bool:
        """Commit the possible-effect boundary before calling the provider."""
        with self._immediate_write_transaction() as db:
            cursor = shared_action_lifecycle.claim_outbound_action(
                db, channel=channel, delivery_key=delivery_key, operation=operation,
            )
            return cursor.rowcount == 1

    def get_outbound_postfix_receipt(
        self,
        channel: str,
        delivery_key: str,
    ) -> object | None:
        """Return the durable provider receipt for one prepared delivery."""
        normalized_channel, normalized_delivery_key = normalize_outbound_postfix_inputs(
            channel=channel,
            delivery_key=delivery_key,
            body="receipt",
        )
        with self._connect() as db:
            row = db.execute(
                f'select provider_result_json from ({OUTBOUND_POSTFIX_RECEIPT_SQL})\n                   where channel=? and delivery_key=?',
                (normalized_channel, normalized_delivery_key),
            ).fetchone()
        return None if row is None else json.loads(str(row["provider_result_json"]))

    def record_outbound_postfix_receipt(
        self,
        channel: str,
        delivery_key: str,
        provider_result: object,
        *,
        operation: str,
    ) -> object:
        """Persist a provider result once so native replies are not replayed."""
        normalized_channel, normalized_delivery_key = normalize_outbound_postfix_inputs(
            channel=channel,
            delivery_key=delivery_key,
            body="receipt",
        )
        serialized = json.dumps(provider_result, ensure_ascii=False, default=str)
        with self._immediate_write_transaction() as db:
            shared_action_lifecycle.record_outbound_action_receipt(
                db, channel=normalized_channel, delivery_key=normalized_delivery_key,
                provider_result_json=serialized, operation=operation,
            )
            row = db.execute(
                f'select provider_result_json from ({OUTBOUND_POSTFIX_RECEIPT_SQL})\n                   where channel=? and delivery_key=?',
                (normalized_channel, normalized_delivery_key),
            ).fetchone()
        assert row is not None
        return json.loads(str(row["provider_result_json"]))

    @staticmethod
    def _managed_skill_from_row(row: sqlite3.Row) -> ManagedSkill:
        return ManagedSkill(
            id=int(row["id"]),
            name=str(row["name"]),
            display_name=str(row["display_name"]),
            created_at=str(row["created_at"]),
        )

    @staticmethod
    def _managed_skill_revision_from_row(
        row: sqlite3.Row,
    ) -> ManagedSkillRevision:
        parent_revision_id = row["parent_revision_id"]
        return ManagedSkillRevision(
            id=int(row["id"]),
            skill_id=int(row["skill_id"]),
            revision_number=int(row["revision_number"]),
            content=str(row["content"]),
            sha256=str(row["sha256"]),
            parent_revision_id=(
                int(parent_revision_id) if parent_revision_id is not None else None
            ),
            source=str(row["source"]),
            created_at=str(row["created_at"]),
        )

    def create_managed_skill(self, name: str, display_name: str) -> ManagedSkill:
        if not isinstance(display_name, str):
            raise ValueError("managed Skill display name must be nonempty")
        name = validate_managed_skill_name(name)
        display_name = display_name.strip()
        if not display_name:
            raise ValueError("managed Skill display name must be nonempty")
        with self._immediate_write_transaction() as db:
            if db.execute(
                f"select 1 from ({config_projection('managed_skills')}) where name=?",
                (name,),
            ).fetchone() is not None:
                raise ValueError("managed Skill already exists")
            try:
                cursor = insert_config(db, "managed_skills", {"name": name, "display_name": display_name})
            except sqlite3.IntegrityError as exc:
                if "idx_configs_skill_name" in str(exc) or "configs.skill_name" in str(exc):
                    raise ValueError("managed Skill already exists") from exc
                raise
            row = db.execute(
                f"select * from ({config_projection('managed_skills')}) where id=?",
                (cursor.lastrowid,),
            ).fetchone()
            assert row is not None
            return self._managed_skill_from_row(row)

    def list_managed_skills(self) -> tuple[ManagedSkill, ...]:
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({config_projection('managed_skills')}) order by id"
            ).fetchall()
        return tuple(self._managed_skill_from_row(row) for row in rows)

    def get_managed_skill(self, skill_id: int) -> ManagedSkill | None:
        with self._connect() as db:
            row = db.execute(
                f"select * from ({config_projection('managed_skills')}) where id=?",
                (skill_id,),
            ).fetchone()
        return self._managed_skill_from_row(row) if row is not None else None

    def get_managed_skill_by_name(self, name: str) -> ManagedSkill | None:
        if not isinstance(name, str) or not name:
            return None
        with self._connect() as db:
            row = db.execute(
                f"select * from ({config_projection('managed_skills')}) where name=?",
                (name,),
            ).fetchone()
        return self._managed_skill_from_row(row) if row is not None else None

    def create_managed_skill_revision(
        self,
        skill_id: int,
        content: str,
        *,
        source: str,
        parent_revision_id: int | None = None,
        require_managed_marker: bool = True,
    ) -> ManagedSkillRevision:
        if not isinstance(source, str) or not source.strip():
            raise ValueError("managed Skill revision source must be nonempty")
        with self._immediate_write_transaction() as db:
            skill_row = db.execute(
                f"select name from ({config_projection('managed_skills')}) where id=?", (skill_id,)
            ).fetchone()
            if skill_row is None:
                raise ValueError("managed Skill does not exist")
            sha256 = validate_managed_skill_content(
                str(skill_row["name"]),
                content,
                require_managed_marker=require_managed_marker,
            )
            latest_row = db.execute(
                f"""
                select id, revision_number from ({config_projection('managed_skill_revisions')})
                where skill_id=? order by revision_number desc limit 1
                """,
                (skill_id,),
            ).fetchone()
            if parent_revision_id is None and latest_row is not None:
                parent_revision_id = int(latest_row["id"])
            if parent_revision_id is not None:
                parent_row = db.execute(
                    f"select skill_id from ({config_projection('managed_skill_revisions')}) where id=?",
                    (parent_revision_id,),
                ).fetchone()
                if parent_row is None:
                    raise ValueError("managed Skill parent revision does not exist")
                if int(parent_row["skill_id"]) != skill_id:
                    raise ValueError(
                        "parent revision does not belong to managed Skill"
                    )
            revision_number = (
                int(latest_row["revision_number"]) + 1
                if latest_row is not None
                else 1
            )
            if db.execute(
                f"select 1 from ({config_projection('managed_skill_revisions')}) "
                "where skill_id=? and sha256=? and source=?",
                (skill_id, sha256, source),
            ).fetchone() is not None:
                raise ValueError("managed Skill revision content already exists")
            try:
                cursor = insert_config(db, "managed_skill_revisions", {
                    "skill_id": skill_id, "revision_number": revision_number,
                    "content": content, "sha256": sha256,
                    "parent_revision_id": parent_revision_id, "source": source,
                })
            except sqlite3.IntegrityError as exc:
                if "configs.skill_revision_skill_id, configs.skill_revision_sha256" in str(exc):
                    raise ValueError(
                        "managed Skill revision content already exists"
                    ) from exc
                raise
            row = db.execute(
                f"select * from ({config_projection('managed_skill_revisions')}) where id=?",
                (cursor.lastrowid,),
            ).fetchone()
            assert row is not None
            return self._managed_skill_revision_from_row(row)

    def install_repository_skill(
        self, name: str, display_name: str, content: str, *, source: str,
        expected_parent_id: int | None, publish_package: Callable[[], None],
    ) -> tuple[ManagedSkillRevision, RuntimeSkillConfig]:
        """Publish one new external Skill with its pending config in one transaction."""
        name = validate_managed_skill_name(name)
        digest = validate_managed_skill_content(name, content, require_managed_marker=False)
        with self._immediate_write_transaction() as db:
            if db.execute(f"select 1 from ({config_projection('managed_skills')}) where name=?", (name,)).fetchone():
                raise ValueError("Skill name conflict")
            latest = db.execute(f"select id,status from ({config_projection('runtime_skill_configs')}) order by id desc limit 1").fetchone()
            parent = int(latest["id"]) if latest else None
            if parent != expected_parent_id:
                raise ValueError("runtime Skill configuration parent conflict")
            effective_parent = parent
            if latest and latest["status"] == "load_failed":
                active = db.execute(f"select id from ({config_projection('runtime_skill_configs')}) where status='active' order by id desc limit 1").fetchone()
                effective_parent = int(active["id"]) if active else None
            old_bindings = db.execute(f"select * from ({config_projection('runtime_skill_bindings')}) where config_id=? order by load_order", (effective_parent,)).fetchall()
            capability = db.execute(f"select enabled from ({config_projection('runtime_feedback_iteration_capabilities')}) where config_id=?", (effective_parent,)).fetchone()
            publish_package()
            skill_id = int(insert_config(db, "managed_skills", {"name": name, "display_name": display_name}).lastrowid)
            revision_id = int(insert_config(db, "managed_skill_revisions", {
                "skill_id": skill_id, "revision_number": 1, "content": content,
                "sha256": digest, "parent_revision_id": None, "source": source,
            }).lastrowid)
            config_id = int(insert_config(db, "runtime_skill_configs", {"parent_id": parent, "status": "pending_restart"}).lastrowid)
            insert_config(db, "runtime_feedback_iteration_capabilities", {"config_id": config_id, "enabled": int(capability["enabled"]) if capability else 1})
            for binding in old_bindings:
                insert_config(db, "runtime_skill_bindings", {"config_id": config_id, **{key: binding[key] for key in ("skill_id", "revision_id", "enabled", "load_order", "purpose")}})
            insert_config(db, "runtime_skill_bindings", {
                "config_id": config_id, "skill_id": skill_id, "revision_id": revision_id,
                "enabled": 1, "load_order": max((b["load_order"] for b in old_bindings), default=-1) + 1, "purpose": "business",
            })
            revision_row = db.execute(f"select * from ({config_projection('managed_skill_revisions')}) where id=?", (revision_id,)).fetchone()
            config_row = db.execute(f"select * from ({config_projection('runtime_skill_configs')}) where id=?", (config_id,)).fetchone()
            return self._managed_skill_revision_from_row(revision_row), self._runtime_skill_config_from_row(config_row)

    def get_managed_skill_revision(
        self, revision_id: int
    ) -> ManagedSkillRevision | None:
        with self._connect() as db:
            row = db.execute(
                f"select * from ({config_projection('managed_skill_revisions')}) where id=?",
                (revision_id,),
            ).fetchone()
        return self._managed_skill_revision_from_row(row) if row is not None else None

    def list_managed_skill_revisions(
        self, skill_id: int
    ) -> tuple[ManagedSkillRevision, ...]:
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({config_projection('managed_skill_revisions')}) "
                "where skill_id=? order by revision_number",
                (skill_id,),
            ).fetchall()
        return tuple(self._managed_skill_revision_from_row(row) for row in rows)

    @staticmethod
    def _scheduled_task_time_text(value: datetime, *, field: str) -> str:
        return ensure_utc_datetime(value, field=field).isoformat(timespec="seconds")

    @staticmethod
    def _require_scheduled_task_text(value: object, *, field: str) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{field} must be nonempty")
        return value.strip()

    @staticmethod
    def _scheduled_task_result_summary(value: object) -> str:
        if not isinstance(value, str):
            raise ValueError("scheduled task run result summary must be text")
        return value.strip()

    @staticmethod
    def _require_scheduled_task_version(value: object) -> int:
        if type(value) is not int or value <= 0:
            raise ValueError(
                "expected scheduled task version must be a positive integer"
            )
        return value

    @staticmethod
    def _normalize_scheduled_task_skill_refs(
        skill_refs: Sequence[ScheduledTaskSkillRef],
    ) -> tuple[ScheduledTaskSkillRef, ...]:
        if not isinstance(skill_refs, Sequence) or isinstance(skill_refs, (str, bytes)):
            raise ValueError("scheduled task Skill refs must be a sequence")
        refs = tuple(skill_refs)
        if any(not isinstance(ref, ScheduledTaskSkillRef) for ref in refs):
            raise ValueError("scheduled task Skill refs contain an invalid item")
        positions = tuple(ref.position for ref in refs)
        if positions != tuple(range(len(refs))):
            raise ValueError("scheduled task Skill ref positions must be contiguous")
        return refs

    @classmethod
    def _validate_scheduled_task_skill_refs(
        cls,
        db: sqlite3.Connection,
        skill_refs: Sequence[ScheduledTaskSkillRef],
        *,
        scheduled_task_id: int = 0,
    ) -> tuple[ScheduledTaskSkillRef, ...]:
        refs = cls._normalize_scheduled_task_skill_refs(skill_refs)
        for ref in refs:
            if ref.scheduled_task_id not in (0, scheduled_task_id):
                raise ValueError("scheduled task Skill ref belongs to another task")
            skill_name = cls._require_scheduled_task_text(
                ref.skill_name,
                field="scheduled task Skill ref name",
            )
            if ref.skill_source == "managed":
                if ref.managed_skill_id is None or ref.managed_revision_id is None:
                    raise ValueError("managed Skill ref requires an exact revision")
                row = db.execute(
                    f"""
                    select skill.name
                      from ({config_projection('managed_skills')}) skill
                      join ({config_projection('managed_skill_revisions')}) revision
                        on revision.skill_id=skill.id
                     where skill.id=? and revision.id=?
                    """,
                    (ref.managed_skill_id, ref.managed_revision_id),
                ).fetchone()
                if row is None:
                    skill = db.execute(
                        f"select 1 from ({config_projection('managed_skills')}) where id=?",
                        (ref.managed_skill_id,),
                    ).fetchone()
                    if skill is None:
                        raise ValueError("managed Skill does not exist")
                    raise ValueError("managed Skill revision does not belong to Skill")
                if str(row["name"]) != skill_name:
                    raise ValueError("managed Skill ref name does not match Skill")
            elif ref.skill_source == "operation":
                if (
                    ref.managed_skill_id is not None
                    or ref.managed_revision_id is not None
                ):
                    raise ValueError(
                        "operation Skill ref must not include managed identifiers"
                    )
            else:
                raise ValueError("scheduled task Skill ref source is invalid")
        return refs

    @staticmethod
    def _scheduled_task_skill_refs_in_connection(
        db: sqlite3.Connection,
        scheduled_task_id: int,
    ) -> tuple[ScheduledTaskSkillRef, ...]:
        rows = db.execute(
            f"""
            select scheduled_task_id, skill_source, skill_name,
                   managed_skill_id, managed_revision_id, position
              from ({config_projection('scheduled_task_skill_refs')})
             where scheduled_task_id=?
             order by position
            """,
            (scheduled_task_id,),
        ).fetchall()
        return tuple(
            ScheduledTaskSkillRef(
                scheduled_task_id=int(row["scheduled_task_id"]),
                skill_source=str(row["skill_source"]),
                skill_name=str(row["skill_name"]),
                managed_skill_id=(
                    int(row["managed_skill_id"])
                    if row["managed_skill_id"] is not None
                    else None
                ),
                managed_revision_id=(
                    int(row["managed_revision_id"])
                    if row["managed_revision_id"] is not None
                    else None
                ),
                position=int(row["position"]),
            )
            for row in rows
        )

    @classmethod
    def _scheduled_task_from_row(
        cls,
        db: sqlite3.Connection,
        row: sqlite3.Row,
    ) -> ScheduledTask:
        deleted_at = row["deleted_at"]
        task_id = int(row["id"])
        runtime_options_json = canonical_json_object(
            decode_json_object(
                str(row["runtime_options_json"]),
                field="scheduled task runtime options",
            ),
            field="scheduled task runtime options",
        )
        required_runtime_capabilities_json = canonical_capabilities_json(
            decode_capabilities_json(
                str(row["required_runtime_capabilities_json"]),
                field="scheduled task required runtime capabilities",
            ),
            field="scheduled task required runtime capabilities",
        )
        return ScheduledTask(
            id=task_id,
            migration_key=(
                str(row["migration_key"])
                if row["migration_key"] is not None
                else None
            ),
            name=str(row["name"]),
            description=str(row["description"] or row["name"]),
            prompt=str(row["prompt"]),
            command=str(row["command"]),
            cron_expression=str(row["cron_expression"]),
            timezone_name=str(row["timezone"]),
            runtime_id=str(row["runtime_id"]),
            runtime_options_json=runtime_options_json,
            required_runtime_capabilities_json=(
                required_runtime_capabilities_json
            ),
            working_directory=str(row["working_directory"]),
            enabled=bool(row["enabled"]),
            notify_on_completion=bool(row["notify_on_completion"]),
            version=int(row["version"]),
            skill_refs=cls._scheduled_task_skill_refs_in_connection(db, task_id),
            created_at=parse_utc_datetime(
                row["created_at"], field="scheduled task created_at"
            ),
            updated_at=parse_utc_datetime(
                row["updated_at"], field="scheduled task updated_at"
            ),
            deleted_at=(
                parse_utc_datetime(deleted_at, field="scheduled task deleted_at")
                if deleted_at is not None
                else None
            ),
        )

    @staticmethod
    def _scheduled_task_columns() -> str:
        return (
            "id, migration_key, name, description, prompt, command, cron_expression, timezone, "
            "runtime_id, runtime_options_json, working_directory, enabled, notify_on_completion, "
            "required_runtime_capabilities_json, "
            "version, created_at, updated_at, deleted_at"
        )

    @staticmethod
    def _validate_scheduled_task_execution(
        *,
        command: str,
        prompt: str,
        runtime_id: str,
        runtime_options_json: str,
        required_runtime_capabilities_json: str,
        working_directory: str,
        skill_refs: Sequence[ScheduledTaskSkillRef],
    ) -> None:
        """Keep trigger execution separate from its downstream Agent instructions."""
        if command:
            runtime_fields = (
                runtime_id,
                working_directory,
                runtime_options_json != "{}",
                required_runtime_capabilities_json != "[]",
            )
            if any(runtime_fields):
                raise ValueError(
                    "service command scheduled task must not carry runtime "
                    "or working directory settings"
                )
            if bool(prompt) != bool(skill_refs):
                raise ValueError(
                    "service command scheduled task must carry its consumer "
                    "prompt and Skill refs together"
                )
            if skill_refs:
                from app.agent_cron.commands import consumer_skill_names_from_prompt

                if consumer_skill_names_from_prompt(prompt) != tuple(
                    ref.skill_name for ref in skill_refs
                ):
                    raise ValueError(
                        "service command scheduled task Skill refs must exactly "
                        "match $skill references in prompt"
                    )
            return
        if not prompt:
            raise ValueError("scheduled task prompt must be nonempty")
        if not runtime_id:
            raise ValueError("scheduled task runtime must be nonempty")

    @classmethod
    def _replace_scheduled_task_skill_refs(
        cls,
        db: sqlite3.Connection,
        scheduled_task_id: int,
        skill_refs: Sequence[ScheduledTaskSkillRef],
    ) -> None:
        refs = cls._validate_scheduled_task_skill_refs(
            db,
            skill_refs,
            scheduled_task_id=scheduled_task_id,
        )
        for row in db.execute(
            f"select rowid from ({config_projection('scheduled_task_skill_refs', include_rowid=True)}) "
            "where scheduled_task_id=?", (scheduled_task_id,)
        ).fetchall():
            delete_config(db, "scheduled_task_skill_refs", row["rowid"])
        for ref in refs:
            insert_config(db, "scheduled_task_skill_refs", {
                "scheduled_task_id": scheduled_task_id,
                "skill_source": ref.skill_source,
                "skill_name": ref.skill_name.strip(),
                "managed_skill_id": ref.managed_skill_id,
                "managed_revision_id": ref.managed_revision_id,
                "position": ref.position,
            })

    def create_scheduled_task(
        self,
        *,
        name: str,
        description: str = "",
        prompt: str = "",
        command: str = "",
        cron_expression: str,
        timezone_name: str,
        runtime_id: str = "",
        runtime_options: Mapping[str, object] = MappingProxyType({}),
        required_runtime_capabilities: Sequence[str] = (),
        working_directory: str = "",
        skill_refs: Sequence[ScheduledTaskSkillRef] = (),
        enabled: bool = True,
        notify_on_completion: bool = True,
        migration_key: str | None = None,
        now: datetime | None = None,
    ) -> ScheduledTask:
        name = self._require_scheduled_task_text(name, field="scheduled task name")
        cron_expression = self._require_scheduled_task_text(
            cron_expression, field="scheduled task Cron expression"
        )
        timezone_name = self._require_scheduled_task_text(
            timezone_name, field="scheduled task timezone"
        )
        for field_name, value in (
            ("description", description),
            ("prompt", prompt),
            ("command", command),
            ("runtime", runtime_id),
            ("working directory", working_directory),
        ):
            if not isinstance(value, str):
                raise ValueError(f"scheduled task {field_name} must be text")
        description = description.strip() or name
        prompt, command, runtime_id = prompt.strip(), command.strip(), runtime_id.strip()
        if not isinstance(enabled, bool):
            raise ValueError("scheduled task enabled must be a boolean")
        if not isinstance(notify_on_completion, bool):
            raise ValueError("scheduled task notification preference must be a boolean")
        if migration_key is not None:
            migration_key = self._require_scheduled_task_text(
                migration_key, field="scheduled task migration key"
            )
        runtime_options_json = canonical_json_object(
            runtime_options,
            field="scheduled task runtime options",
        )
        required_runtime_capabilities_json = canonical_capabilities_json(
            required_runtime_capabilities,
            field="scheduled task required runtime capabilities",
        )
        self._validate_scheduled_task_execution(
            command=command,
            prompt=prompt,
            runtime_id=runtime_id,
            runtime_options_json=runtime_options_json,
            required_runtime_capabilities_json=required_runtime_capabilities_json,
            working_directory=working_directory,
            skill_refs=skill_refs,
        )
        now_value = ensure_utc_datetime(
            now or datetime.now(timezone.utc),
            field="scheduled task now",
        )
        now_text = now_value.isoformat(timespec="seconds")
        with self._immediate_write_transaction() as db:
            if migration_key is not None:
                existing = db.execute(
                    f"select {self._scheduled_task_columns()} "
                    f"from ({schedule_projection()}) where migration_key=?",
                    (migration_key,),
                ).fetchone()
                if existing is not None:
                    return self._scheduled_task_from_row(db, existing)
            refs = self._validate_scheduled_task_skill_refs(db, skill_refs)
            task_id = int(insert_schedule(db, {
                "migration_key": migration_key, "name": name,
                "description": description, "prompt": prompt, "command": command,
                "cron_expression": cron_expression, "timezone": timezone_name,
                "runtime_id": runtime_id, "runtime_options_json": runtime_options_json,
                "working_directory": working_directory,
                "required_runtime_capabilities_json": required_runtime_capabilities_json,
                "enabled": int(enabled), "notify_on_completion": int(notify_on_completion), "version": 1,
                "created_at": now_text, "updated_at": now_text,
            }))
            self._replace_scheduled_task_skill_refs(db, task_id, refs)
            row = db.execute(
                f"select {self._scheduled_task_columns()} "
                f"from ({schedule_projection()}) where id=?",
                (task_id,),
            ).fetchone()
            assert row is not None
            return self._scheduled_task_from_row(db, row)

    def get_scheduled_task(
        self,
        task_id: int,
        *,
        include_deleted: bool = False,
    ) -> ScheduledTask | None:
        deleted_filter = "" if include_deleted else " and deleted_at is null"
        with self._connect() as db:
            row = db.execute(
                f"select {self._scheduled_task_columns()} "
                f"from ({schedule_projection()}) where id=?{deleted_filter}",
                (task_id,),
            ).fetchone()
            return self._scheduled_task_from_row(db, row) if row is not None else None

    def list_scheduled_tasks(
        self,
        *,
        include_deleted: bool = False,
    ) -> tuple[ScheduledTask, ...]:
        deleted_filter = "" if include_deleted else " where deleted_at is null"
        with self._connect() as db:
            rows = db.execute(
                f"select {self._scheduled_task_columns()} from ({schedule_projection()})"
                f"{deleted_filter} order by id"
            ).fetchall()
            return tuple(self._scheduled_task_from_row(db, row) for row in rows)

    def scheduled_task_ids_for_reply_tasks(
        self, reply_task_ids: tuple[int, ...]
    ) -> dict[int, int]:
        """Map a reply task id to the scheduled task that queued it, if any.

        Derek, 2026-09-27: a queue row for a scheduled task's own reply task
        had nowhere to link while it was still running (no Attempt exists
        yet), so History sent it to the generic Status page. It belongs on
        that scheduled task's own run history instead.
        """
        if not reply_task_ids:
            return {}
        placeholders = ",".join("?" for _ in reply_task_ids)
        with self._connect() as db:
            rows = db.execute(
                f"""
                select execution_id, scheduled_task_id
                from schedule_occurrences as scheduled_task_runs
                where execution_kind='reply_task' and execution_id in ({placeholders})
                order by id
                """,
                reply_task_ids,
            ).fetchall()
        # A reply task is queued by at most one scheduled task run; keep the
        # latest if a stale row is ever reused.
        return {int(row["execution_id"]): int(row["scheduled_task_id"]) for row in rows}

    @staticmethod
    def _business_task_signal_from_row(row: sqlite3.Row) -> BusinessTaskSignalFact:
        values = dict(row)
        binding = SourceVersionBinding(**{field: values[field] for field in SOURCE_FIELDS})
        return BusinessTaskSignalFact(
            id=values["id"], source=binding,
            conversation_title=values["conversation_title"], context_json=values["context_json"],
            dedupe_key=values["dedupe_key"], created_at=values["created_at"],
        )

