    # ---- WeChat channel: reply scopes ----
    def replace_wechat_reply_scopes(
        self, account_id: str, scopes: list[WechatReplyScope]
    ) -> None:
        if any(scope.account_id != account_id for scope in scopes):
            raise ValueError("scope account mismatch")
        activation_at = datetime.now().astimezone().isoformat()
        with self._connect() as db:
            db.execute("begin immediate")
            now_text = db.execute("select current_timestamp").fetchone()[0]
            existing = {
                (row["target_type"], row["target_id"]): row
                for row in db.execute(
                    f"select * from ({config_projection('wechat_reply_scopes', include_rowid=True)}) where account_id=?",
                    (account_id,),
                ).fetchall()
            }
            current_rowids = {
                key: row["rowid"] for key, row in existing.items()
            }
            for row in existing.values():
                update_config(db, "wechat_reply_scopes", row["rowid"], {
                    "enabled": 0, "disabled_reason": "not_selected",
                    "updated_at": now_text,
                })
            for scope in scopes:
                key = (scope.target_type, scope.target_id)
                previous = existing.get(key)
                if scope.last_active_at:
                    watermark = scope.last_active_at
                elif previous is not None and bool(previous["enabled"]):
                    watermark = previous["last_discovered_at"] or activation_at
                else:
                    watermark = activation_at
                values = {
                    "account_id": scope.account_id,
                    "target_type": scope.target_type, "target_id": scope.target_id,
                    "conversation_id": scope.conversation_id,
                    "display_name": scope.display_name,
                    "trigger_mode": scope.trigger_mode,
                    "enabled": int(scope.enabled),
                    "binding_status": scope.binding_status,
                    "binding_evidence_json": json.dumps(scope.binding_evidence, ensure_ascii=False),
                    "disabled_reason": "", "last_discovered_at": watermark,
                    "updated_at": now_text,
                }
                rowid = current_rowids.get(key)
                if rowid is None:
                    inserted = insert_config(db, "wechat_reply_scopes", values)
                    current_rowids[key] = inserted.lastrowid
                else:
                    update_config(db, "wechat_reply_scopes", rowid, values)

    def advance_wechat_scope_watermark(
        self, account_id: str, target_type: str, target_id: str, sent_at: str
    ) -> bool:
        if not sent_at:
            raise ValueError("scope watermark requires sent_at")
        with self._connect() as db:
            db.execute("begin immediate")
            row = db.execute(
                f"select * from ({config_projection('wechat_reply_scopes', include_rowid=True)}) "
                "where account_id=? and target_type=? and target_id=?",
                (account_id, target_type, target_id),
            ).fetchone()
            if row is None or (row["last_discovered_at"] and row["last_discovered_at"] >= sent_at):
                return False
            return update_config(db, "wechat_reply_scopes", row["rowid"], {
                "last_discovered_at": sent_at,
                "updated_at": db.execute("select current_timestamp").fetchone()[0],
            }) == 1

    def list_wechat_reply_scopes(
        self, account_id: str, *, enabled_only: bool = False
    ) -> list[WechatReplyScope]:
        where = "where account_id=?" + (" and enabled=1" if enabled_only else "")
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({config_projection('wechat_reply_scopes')}) {where} "
                f"order by target_type, display_name, target_id",
                (account_id,),
            ).fetchall()
        return [
            WechatReplyScope(
                account_id=row["account_id"], target_type=row["target_type"],
                target_id=row["target_id"], conversation_id=row["conversation_id"],
                display_name=row["display_name"], trigger_mode=row["trigger_mode"],
                enabled=bool(row["enabled"]), binding_status=row["binding_status"],
                binding_evidence=json.loads(row["binding_evidence_json"]),
                disabled_reason=row["disabled_reason"],
                last_active_at=row["last_discovered_at"],
            )
            for row in rows
        ]

    def get_wechat_reply_scope(
        self, account_id: str, target_type: str, target_id: str
    ) -> WechatReplyScope | None:
        return next(
            (
                scope for scope in self.list_wechat_reply_scopes(account_id)
                if scope.target_type == target_type and scope.target_id == target_id
            ),
            None,
        )

    # ---- WeChat channel: read state ----
    def upsert_wechat_read_state(
        self, *, account_id: str, account_dir: str, db_dir: str,
        app_version: str, self_user_id: str, capability_status: str,
        capability_reason: str = "", watermark_sent_at: str = "",
        watermark_message_id: str = "", last_scan_at: str = "",
    ) -> None:
        values = {
            "account_id": account_id, "account_dir": account_dir, "db_dir": db_dir,
            "app_version": app_version, "self_user_id": self_user_id,
            "capability_status": capability_status,
            "capability_reason": capability_reason,
            "watermark_sent_at": watermark_sent_at,
            "watermark_message_id": watermark_message_id,
            "last_scan_at": last_scan_at,
        }
        updates = {
            field: state_json_field(field) for field in (
                "account_dir", "db_dir", "app_version", "capability_status",
                "capability_reason",
            )
        }
        for field in ("self_user_id", "watermark_sent_at",
                      "watermark_message_id", "last_scan_at"):
            updates[field] = (
                f"case when nullif(excluded.{field}, '') is not null then " +
                state_json_field(field) + " else " +
                state_json_field(field, "state") + " end"
            )
        updates["updated_at"] = "json_quote(current_timestamp)"
        with self._connect() as db:
            db.execute("begin")
            upsert_state(db, "wechat_read_state", values, updates)

    def get_wechat_read_state(self, account_id: str) -> dict[str, str] | None:
        projection = "(" + state_projection("wechat_read_state") + ")"
        with self._connect() as db:
            row = db.execute(
                f"select * from {projection} where account_id=?", (account_id,)
            ).fetchone()
        return dict(row) if row is not None else None

    def list_wechat_read_states(self) -> list[dict[str, str]]:
        projection = "(" + state_projection("wechat_read_state") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"select * from {projection} order by account_id"
            ).fetchall()
        return [dict(row) for row in rows]

    def list_wechat_reply_scopes_for_ready_account(
        self, *, enabled_only: bool = True
    ) -> list[WechatReplyScope]:
        ready = [
            row for row in self.list_wechat_read_states()
            if row["capability_status"] == "ready"
        ]
        if len(ready) != 1:
            return []
        return self.list_wechat_reply_scopes(
            ready[0]["account_id"], enabled_only=enabled_only
        )

    # ---- WeChat channel: deliveries ----
    @classmethod
    def _supersede_ready_wechat_delivery(
        cls,
        db: sqlite3.Connection,
        task_id: int,
        new_generation: str,
    ) -> None:
        row = db.execute(
            f"select id from ({WECHAT_DELIVERY_SQL}) "
            "where reply_task_id=? and status='ready_to_send'",
            (task_id,),
        ).fetchone()
        if row is None:
            return
        error = f"superseded_by_generation:{new_generation}"
        assignments, set_args = task_delivery_set_parts(
            "wechat_deliveries", {"status": "superseded", "error": error},
            update_sql={"updated_at": "current_timestamp"},
        )
        db.execute(
            f"update actions set {assignments} "
            "where record_type='wechat_deliveries' and cast(legacy_key as integer)=? "
            "and td_status='ready_to_send'",
            (*set_args, row["id"]),
        )
        cls._sync_wechat_delivery_reply_attempt(
            db,
            delivery_id=int(row["id"]),
            delivery_status="superseded",
            error=error,
        )

    @classmethod
    def _prepare_new_wechat_delivery(
        cls,
        db: sqlite3.Connection,
        *,
        reply_task_id: int,
        account_id: str,
        target_type: str,
        target_id: str,
        conversation_id: str,
    ) -> None:
        unresolved = db.execute(
            f"""
            select 1
            from ({WECHAT_DELIVERY_SQL})
            where reply_task_id!=?
              and account_id=?
              and target_type=?
              and target_id=?
              and conversation_id=?
              and status in ('sending', 'send_unknown')
            limit 1
            """,
            (
                reply_task_id,
                account_id,
                target_type,
                target_id,
                conversation_id,
            ),
        ).fetchone()
        if unresolved is not None:
            raise ValueError(
                "WeChat delivery reconciliation required before a newer trigger"
            )
        error = f"superseded_by_newer_wechat_trigger:{reply_task_id}"
        older_deliveries = db.execute(
            f"""
            select id
            from ({WECHAT_DELIVERY_SQL})
            where reply_task_id!=?
              and account_id=?
              and target_type=?
              and target_id=?
              and conversation_id=?
              and status in ('ready_to_send', 'failed')
              and error!='user_rejected'
            """,
            (
                reply_task_id,
                account_id,
                target_type,
                target_id,
                conversation_id,
            ),
        ).fetchall()
        for older in older_deliveries:
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries", {"status": "superseded", "error": error},
                update_sql={"updated_at": "current_timestamp"},
            )
            db.execute(
                f"update actions set {assignments} "
                "where record_type='wechat_deliveries' and cast(legacy_key as integer)=?",
                (*set_args, older["id"]),
            )
            cls._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=older["id"],
                delivery_status="superseded",
                error=error,
            )

    def get_wechat_delivery_for_task(self, reply_task_id: int):
        from app.wechat.models import WechatDelivery
        with self._connect() as db:
            row = db.execute(
                f"""select deliveries.* from ({WECHAT_DELIVERY_SQL}) as deliveries
                   join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks on tasks.id=deliveries.reply_task_id
                   where deliveries.reply_task_id=?
                   order by (deliveries.execution_generation=tasks.execution_generation)
                            desc, deliveries.id desc
                   limit 1""",
                (reply_task_id,),
            ).fetchone()
        if row is None:
            return None
        return WechatDelivery(
            id=row["id"], task_id=row["reply_task_id"], account_id=row["account_id"],
            target_type=row["target_type"], target_id=row["target_id"],
            conversation_id=row["conversation_id"], reply_text=row["reply_text"],
            action_started_at=row["action_started_at"],
            execution_generation=row["execution_generation"],
            status=row["status"], evidence=json.loads(row["evidence_json"]),
            error=row["error"],
            pre_action_failure=bool(row["pre_action_failure"]),
        )

    def list_wechat_deliveries_by_status(self, status: str) -> list:
        from app.wechat.models import WechatDelivery
        with self._connect() as db:
            rows = db.execute(
                f"""
                select wechat_deliveries.* from ({WECHAT_DELIVERY_SQL}) as wechat_deliveries
                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks on reply_tasks.id=wechat_deliveries.reply_task_id
                where wechat_deliveries.status=?
                  and wechat_deliveries.execution_generation=
                      reply_tasks.execution_generation
                order by wechat_deliveries.id
                """,
                (status,),
            ).fetchall()
        return [
            WechatDelivery(
                id=row["id"], task_id=row["reply_task_id"], account_id=row["account_id"],
                target_type=row["target_type"], target_id=row["target_id"],
                conversation_id=row["conversation_id"], reply_text=row["reply_text"],
                action_started_at=row["action_started_at"],
                execution_generation=row["execution_generation"],
                status=row["status"], evidence=json.loads(row["evidence_json"]),
                error=row["error"],
                pre_action_failure=bool(row["pre_action_failure"]),
            )
            for row in rows
        ]

    def ready_wechat_delivery_ids_for_messages(
        self,
        message_keys: list[tuple[str, str]],
    ) -> dict[tuple[str, str], int]:
        if not message_keys:
            return {}
        placeholders = ",".join(["(?, ?)"] * len(message_keys))
        args = [value for key in message_keys for value in key]
        with self._connect() as db:
            rows = db.execute(
                f"""
                select
                    reply_tasks.conversation_id,
                    reply_tasks.trigger_message_id,
                    wechat_deliveries.id as delivery_id
                from ({WECHAT_DELIVERY_SQL}) as wechat_deliveries
                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks on reply_tasks.id=wechat_deliveries.reply_task_id
                where wechat_deliveries.status='ready_to_send'
                  and wechat_deliveries.execution_generation=
                      reply_tasks.execution_generation
                  and reply_tasks.channel='wechat'
                  and (reply_tasks.conversation_id, reply_tasks.trigger_message_id)
                      in ({placeholders})
                """,
                args,
            ).fetchall()
        return {
            (str(row["conversation_id"]), str(row["trigger_message_id"])):
            int(row["delivery_id"])
            for row in rows
        }

    def requeue_unperformed_wechat_deliveries(
        self,
        *,
        max_retries: int = MAX_AUTOMATIC_RETRIES,
        retry_delay_seconds: int = 5 * 60,
    ) -> int:
        """Return aged pre-action failures to the send queue for a bounded retry."""
        if max_retries < 1:
            return 0
        if retry_delay_seconds < 0:
            raise ValueError("retry_delay_seconds must not be negative")
        with self._immediate_write_transaction() as db:
            rows = db.execute(
                f"""
                select deliveries.id as delivery_id, (
                    select attempts.id
                    from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                    where attempts.channel='wechat'
                      and attempts.conversation_id=tasks.conversation_id
                      and attempts.trigger_message_id=tasks.trigger_message_id
                    order by attempts.id desc
                    limit 1
                ) as attempt_id
                from ({WECHAT_DELIVERY_SQL}) as deliveries
                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks on tasks.id=deliveries.reply_task_id
                where deliveries.status='failed'
                  and deliveries.pre_action_failure=1
                  and deliveries.action_started_at<>''
                  and datetime(deliveries.action_started_at) <=
                      datetime('now', printf('-%d seconds', ?))
                  and deliveries.execution_generation=tasks.execution_generation
                  and coalesce((
                      select attempts.retry_count
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                      where attempts.channel='wechat'
                        and attempts.conversation_id=tasks.conversation_id
                        and attempts.trigger_message_id=tasks.trigger_message_id
                      order by attempts.id desc
                      limit 1
                  ), ?) < ?
                """,
                (retry_delay_seconds, 0, max_retries),
            ).fetchall()
            requeued = 0
            for row in rows:
                delivery_id = int(row["delivery_id"])
                assignments, set_args = task_delivery_set_parts(
                    "wechat_deliveries",
                    {"status": "ready_to_send", "error": "", "pre_action_failure": 0},
                    update_sql={"updated_at": "current_timestamp"},
                )
                cursor = db.execute(
                    f"""
                    update actions as wechat_deliveries set {assignments}
                    where wechat_deliveries.record_type='wechat_deliveries'
                      and cast(wechat_deliveries.legacy_key as integer)=?
                      and wechat_deliveries.td_status='failed'
                      and wechat_deliveries.td_pre_action_failure=1
                      and exists (
                      select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                      where reply_tasks.id=wechat_deliveries.td_reply_task_id
                        and reply_tasks.execution_generation=
                            wechat_deliveries.td_execution_generation
                      )
                    """,
                    (*set_args, delivery_id),
                )
                if cursor.rowcount != 1:
                    continue
                self._sync_wechat_delivery_reply_attempt(
                    db,
                    delivery_id=delivery_id,
                    delivery_status="ready_to_send",
                    error="",
                )
                if row["attempt_id"] is None:
                    task = db.execute(
                        f"""
                        select conversation_id, conversation_title,
                               trigger_message_id, trigger_sender, trigger_text
                        from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                        where id=(
                            select reply_task_id from ({WECHAT_DELIVERY_SQL}) where id=?
                        )
                        """,
                        (delivery_id,),
                    ).fetchone()
                    if task is None:
                        raise RuntimeError("wechat delivery retry task is missing")
                    insert_action(db, "reply_attempts", {
                        "conversation_id": task["conversation_id"],
                        "conversation_title": task["conversation_title"],
                        "trigger_message_id": task["trigger_message_id"],
                        "trigger_sender": task["trigger_sender"],
                        "trigger_text": task["trigger_text"],
                        "action": "send_reply", "sensitivity_kind": "normal",
                        "codex_reason": "legacy_wechat_delivery_recovery",
                        "audit_summary": "created during bounded legacy delivery recovery",
                        "send_status": "pending",
                        "send_error": "wechat_delivery_ready_to_send",
                        "retry_count": 1, "channel": "wechat",
                    })
                else:
                    attempt = db.execute(
                        f"select retry_count from ({REPLY_ATTEMPT_COMMON_SQL}) where id=?",
                        (row["attempt_id"],),
                    ).fetchone()
                    if attempt is not None:
                        update_action(db, "reply_attempts", row["attempt_id"],
                                      {"retry_count": attempt["retry_count"] + 1})
                requeued += 1
            return requeued

    def requeue_wechat_deliveries_after_accessibility_recovery(self) -> int:
        """Restore only permission-blocked, pre-action deliveries.

        A missing macOS Accessibility grant is an external dependency, not a
        failed send attempt. Once the dedicated Sender has confirmed that the
        grant is available again, let the same unsent delivery have one fresh
        dispatch without reopening any ambiguous or target-related failure.
        """
        return self._requeue_wechat_deliveries_waiting_on("accessibility_not_trusted")

    def requeue_wechat_deliveries_blocked_by_user_activity(self) -> int:
        """Restore deliveries the Sender did not start because the user was busy.

        The Sender only works after 30 quiet seconds and stops when the user
        touches the computer (Derek, 2026-10-28). That is waiting, not a failed
        send, so it does not use the bounded retry budget.
        """
        return self._requeue_wechat_deliveries_waiting_on("user_active")

    def _requeue_wechat_deliveries_waiting_on(self, error: str) -> int:
        if error not in {"accessibility_not_trusted", "user_active"}:
            raise ValueError("unsupported waiting WeChat delivery error")
        with self._immediate_write_transaction() as db:
            rows = db.execute(
                f"""
                select deliveries.id as delivery_id
                from ({WECHAT_DELIVERY_SQL}) as deliveries
                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks on tasks.id=deliveries.reply_task_id
                where deliveries.status='failed'
                  and deliveries.error=?
                  and deliveries.pre_action_failure=1
                  and deliveries.action_started_at<>''
                  and deliveries.execution_generation=tasks.execution_generation
                """,
                (error,),
            ).fetchall()
            requeued = 0
            for row in rows:
                delivery_id = int(row["delivery_id"])
                assignments, set_args = task_delivery_set_parts(
                    "wechat_deliveries",
                    {"status": "ready_to_send", "error": "", "pre_action_failure": 0},
                    update_sql={"updated_at": "current_timestamp"},
                )
                cursor = db.execute(
                    f"""
                    update actions as wechat_deliveries set {assignments}
                    where wechat_deliveries.record_type='wechat_deliveries'
                      and cast(wechat_deliveries.legacy_key as integer)=?
                      and wechat_deliveries.td_status='failed'
                      and wechat_deliveries.td_error=?
                      and wechat_deliveries.td_pre_action_failure=1
                      and exists (
                          select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                          where reply_tasks.id=wechat_deliveries.td_reply_task_id
                            and reply_tasks.execution_generation=
                                wechat_deliveries.td_execution_generation
                      )
                    """,
                    (*set_args, delivery_id, error),
                )
                if cursor.rowcount != 1:
                    continue
                self._sync_wechat_delivery_reply_attempt(
                    db,
                    delivery_id=delivery_id,
                    delivery_status="ready_to_send",
                    error="",
                )
                requeued += 1
            return requeued

    def requeue_expired_wechat_delivery_for_user(self, delivery_id: int):
        """Restore one never-dispatched delivery after explicit user action.

        Automatic retries deliberately stop after their bounded budget.  The
        record is still safe for a user to retry when a pre-action failure
        closed it, either still ``failed`` or already moved to ``skipped``: that
        path records a non-empty action start time but never performed a send.
        User-rejected, Audit-rejected (never claimed, so no action start),
        sent, and uncertain deliveries do not meet this transition.
        """
        from app.wechat.models import WechatDelivery, principal_reply_supersession

        if delivery_id < 1:
            raise ValueError("delivery_id must be positive")
        with self._immediate_write_transaction() as db:
            closed = db.execute(f"select error from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)).fetchone()
            if closed is not None and principal_reply_supersession(closed["error"]):
                raise AgentRunLeaseLostError(f"WeChat delivery superseded by principal reply: {delivery_id}")
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries",
                {"status": "ready_to_send", "error": "", "pre_action_failure": 0},
                update_sql={"updated_at": "current_timestamp"},
            )
            cursor = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and (
                      wechat_deliveries.td_status='skipped'
                      or (
                          wechat_deliveries.td_status='failed'
                          and wechat_deliveries.td_pre_action_failure=1
                      )
                  )
                  and trim(wechat_deliveries.td_action_started_at)<>''
                  and exists (
                      select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                      where tasks.id=wechat_deliveries.td_reply_task_id
                        and tasks.execution_generation=
                            wechat_deliveries.td_execution_generation
                  )
                """,
                (*set_args, delivery_id),
            )
            if cursor.rowcount != 1:
                raise AgentRunLeaseLostError(
                    f"WeChat delivery is not a pre-action retry: {delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="ready_to_send",
                error="",
            )
            row = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)
            ).fetchone()
        return WechatDelivery(
            id=row["id"], task_id=row["reply_task_id"],
            account_id=row["account_id"], target_type=row["target_type"],
            target_id=row["target_id"], conversation_id=row["conversation_id"],
            reply_text=row["reply_text"], action_started_at=row["action_started_at"],
            execution_generation=row["execution_generation"], status=row["status"],
            evidence=json.loads(row["evidence_json"]), error=row["error"],
            pre_action_failure=bool(row["pre_action_failure"]),
        )

    def requeue_readback_absent_wechat_delivery_for_user(self, delivery_id: int):
        """Restore one uncertain delivery after readback proves it was not sent.

        This transition is intentionally narrower than an ordinary retry.  It
        only accepts the reconciliation state produced when target-scoped,
        read-only history found no matching outbound message, and only while
        the delivery still belongs to the task's current execution generation.
        """
        from app.wechat.models import WechatDelivery

        if delivery_id < 1:
            raise ValueError("delivery_id must be positive")
        with self._immediate_write_transaction() as db:
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries",
                {"status": "ready_to_send", "error": "", "pre_action_failure": 0},
                update_sql={"updated_at": "current_timestamp"},
            )
            cursor = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and wechat_deliveries.td_status='send_unknown'
                  and wechat_deliveries.td_error='read_only_reconciliation_inconclusive'
                  and trim(wechat_deliveries.td_action_started_at)<>''
                  and exists (
                      select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                      where tasks.id=wechat_deliveries.td_reply_task_id
                        and tasks.execution_generation=
                            wechat_deliveries.td_execution_generation
                  )
                """,
                (*set_args, delivery_id),
            )
            if cursor.rowcount != 1:
                raise AgentRunLeaseLostError(
                    "WeChat delivery is not a current readback-absent retry: "
                    f"{delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="ready_to_send",
                error="",
            )
            row = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)
            ).fetchone()
        return WechatDelivery(
            id=row["id"], task_id=row["reply_task_id"],
            account_id=row["account_id"], target_type=row["target_type"],
            target_id=row["target_id"], conversation_id=row["conversation_id"],
            reply_text=row["reply_text"], action_started_at=row["action_started_at"],
            execution_generation=row["execution_generation"], status=row["status"],
            evidence=json.loads(row["evidence_json"]), error=row["error"],
            pre_action_failure=bool(row["pre_action_failure"]),
        )

    def claim_wechat_delivery(
        self,
        delivery_id: int,
        *,
        expected_execution_generation: str,
        now: str = "",
    ):
        from app.wechat.models import WechatDelivery

        with self._immediate_write_transaction() as db:
            review_delivery = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)
            ).fetchone()
            if review_delivery is None:
                return None
            review_task = db.execute(
                f"select * from ({NATIVE_REPLY_TASK_CURRENT_SQL}) where id=?",
                (review_delivery["reply_task_id"],),
            ).fetchone()
            if (review_task is None
                or review_task["execution_generation"] != expected_execution_generation
                or not self._wechat_review_approved_in_connection(
                    db, review_delivery, review_task
                )):
                return None
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries",
                {"status": "sending", "pre_action_failure": 0, "error": ""},
                update_sql={
                    "action_started_at": "case when ?='' then current_timestamp else ? end",
                    "updated_at": "current_timestamp",
                },
                update_parameters=(now, now),
            )
            cursor = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and wechat_deliveries.td_status='ready_to_send'
                  and wechat_deliveries.td_execution_generation=?
                  and exists (
                      select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                      where reply_tasks.id=wechat_deliveries.td_reply_task_id
                        and reply_tasks.execution_generation=?
                  )
                """,
                (
                    *set_args,
                    delivery_id,
                    expected_execution_generation,
                    expected_execution_generation,
                ),
            )
            if cursor.rowcount != 1:
                return None
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="sending",
                error="",
            )
            row = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)
            ).fetchone()
        return WechatDelivery(
            id=row["id"], task_id=row["reply_task_id"],
            account_id=row["account_id"], target_type=row["target_type"],
            target_id=row["target_id"], conversation_id=row["conversation_id"],
            reply_text=row["reply_text"],
            action_started_at=row["action_started_at"],
            execution_generation=row["execution_generation"],
            status=row["status"], evidence=json.loads(row["evidence_json"]),
            error=row["error"],
            pre_action_failure=bool(row["pre_action_failure"]),
        )

    def mark_wechat_delivery_sending(self, delivery_id: int, *, now: str = "") -> None:
        delivery = self.get_wechat_delivery_by_id(delivery_id)
        if delivery is None or self.claim_wechat_delivery(
            delivery_id,
            expected_execution_generation=delivery.execution_generation,
            now=now,
        ) is None:
            raise ValueError("WeChat delivery is not claimable")

    def get_wechat_delivery_by_id(self, delivery_id: int):
        from app.wechat.models import WechatDelivery
        with self._connect() as db:
            row = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?", (delivery_id,)
            ).fetchone()
        if row is None:
            return None
        return WechatDelivery(
            id=row["id"], task_id=row["reply_task_id"],
            account_id=row["account_id"], target_type=row["target_type"],
            target_id=row["target_id"], conversation_id=row["conversation_id"],
            reply_text=row["reply_text"],
            action_started_at=row["action_started_at"],
            execution_generation=row["execution_generation"],
            status=row["status"], evidence=json.loads(row["evidence_json"]),
            error=row["error"],
            pre_action_failure=bool(row["pre_action_failure"]),
        )

    @staticmethod
    def _wechat_review_approved_in_connection(db, delivery, task) -> bool:
        """A delivery may be sent only when the standard Consumer -> Audit review approved
        exactly this target and text (``standard_*`` evidence, re-verified here)."""
        evidence = json.loads(delivery["evidence_json"])
        if "standard_review_id" not in evidence:
            return False
        return AutoReplyStore._standard_wechat_review_approves(db, delivery, evidence)

    @staticmethod
    def _standard_wechat_review_rows(db, candidate_id: int, review_id: int):
        """The adopted candidate and its approving Audit review, or None.

        The candidate must still be valid and owned by a completed Consumer run;
        the review must be an approval of exactly that candidate's digest, made
        by a completed Audit run whose parent is that Consumer run.
        """
        row = db.execute(
            """select c.candidate_json, c.candidate_digest, c.invalidated_at,
                      owner.task_id, owner.execution_generation, owner.role, owner.status,
                      r.decision, r.candidate_digest as review_digest, r.audit_run_id
               from run_adopted_reviews r
               join run_adopted_results c on c.consumer_run_id=r.consumer_run_id
               join runs owner on owner.id=c.consumer_run_id
               where r.id=? and r.consumer_run_id=?""",
            (review_id, candidate_id),
        ).fetchone()
        if (row is None or row["decision"] != "approve"
                or row["review_digest"] != row["candidate_digest"]
                or row["invalidated_at"]
                or row["role"] != "consumer" or row["status"] != "completed"):
            return None
        audit = db.execute(
            "select role, status, task_id, execution_generation, parent_id "
            "from runs where id=?", (row["audit_run_id"],),
        ).fetchone()
        if (audit is None or audit["role"] != "audit" or audit["status"] != "completed"
                or audit["task_id"] != row["task_id"]
                or audit["execution_generation"] != row["execution_generation"]
                or audit["parent_id"] != candidate_id):
            return None
        return row

    @staticmethod
    def _standard_wechat_review_approves(db, delivery, evidence) -> bool:
        """Fail closed: every binding below must hold, or the delivery is not approved."""
        from app.wechat.standard_review import action_matches_delivery, approved_send_action

        try:
            candidate_id = int(evidence["standard_candidate_id"])
            review_id = int(evidence["standard_review_id"])
        except (KeyError, TypeError, ValueError):
            return False
        identity = evidence.get("standard_action_identity")
        if not isinstance(identity, str) or not identity:
            return False
        row = AutoReplyStore._standard_wechat_review_rows(db, candidate_id, review_id)
        if (row is None or row["task_id"] != delivery["reply_task_id"]
                or row["execution_generation"] != delivery["execution_generation"]):
            return False
        action = approved_send_action(row["candidate_json"], identity)
        return bool(action is not None and action_matches_delivery(
            action,
            account_id=delivery["account_id"], target_type=delivery["target_type"],
            target_id=delivery["target_id"], conversation_id=delivery["conversation_id"],
            reply_text=delivery["reply_text"],
        ))

    def create_standard_wechat_delivery(
        self, *, candidate_id: int, review_id: int, action_identity: str,
    ) -> int:
        """Create the one ready-to-send delivery for a standard-pipeline send.

        Target and text come from the approved action itself, never from the
        caller, and the approval is bound into the delivery's evidence so the
        send gate can re-check it. The approved text is already the final body,
        so no outbound suffix is added here.
        """
        from app.wechat.standard_review import (
            STANDARD_EVIDENCE_KEYS, approved_send_action, send_fields,
        )

        with self._immediate_write_transaction() as db:
            row = self._standard_wechat_review_rows(db, candidate_id, review_id)
            if row is None:
                raise ValueError("WeChat send is not backed by an approving standard review")
            action = approved_send_action(row["candidate_json"], action_identity)
            fields = send_fields(action) if action is not None else None
            if fields is None:
                raise ValueError("reviewed candidate has no valid WeChat send action")
            task = db.execute(
                f"""select execution_generation from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                   where id=? and channel='wechat'""",
                (row["task_id"],),
            ).fetchone()
            if task is None or str(task["execution_generation"]) != row["execution_generation"]:
                raise ValueError("reviewed candidate is not for the current WeChat task generation")
            generation = str(task["execution_generation"])
            existing = db.execute(
                f"""select * from ({WECHAT_DELIVERY_SQL})
                   where reply_task_id=? and execution_generation=?""",
                (row["task_id"], generation),
            ).fetchone()
            if existing is not None:
                if existing["reply_text"] != fields["text"]:
                    raise ValueError("a different WeChat delivery already exists for this task")
                if existing["status"] == "failed" and bool(existing["pre_action_failure"]):
                    # Nothing reached WeChat, so a retried dispatch may try again.
                    assignments, set_args = task_delivery_set_parts(
                        "wechat_deliveries",
                        {"status": "ready_to_send", "pre_action_failure": 0, "error": ""},
                        update_sql={"updated_at": "current_timestamp"},
                    )
                    db.execute(
                        f"update actions set {assignments} "
                        "where record_type='wechat_deliveries' and cast(legacy_key as integer)=?",
                        (*set_args, int(existing["id"])),
                    )
                return int(existing["id"])
            self._prepare_new_wechat_delivery(
                db, reply_task_id=row["task_id"], account_id=fields["account_id"],
                target_type=fields["target_type"], target_id=fields["target_id"],
                conversation_id=fields["conversation_id"],
            )
            evidence = dict(zip(STANDARD_EVIDENCE_KEYS, (
                str(candidate_id), str(review_id), action_identity)))
            return int(insert_task_delivery_action(db, "wechat_deliveries", {
                "reply_task_id": row["task_id"], "account_id": fields["account_id"],
                "target_type": fields["target_type"], "target_id": fields["target_id"],
                "conversation_id": fields["conversation_id"], "reply_text": fields["text"],
                "execution_generation": generation, "status": "ready_to_send",
                "evidence_json": json.dumps(evidence, ensure_ascii=False),
            }).lastrowid)

    @staticmethod
    def _native_wechat_delivery(db, delivery_id: int):
        from app.action_task_delivery_definitions import task_delivery_projection

        projection = task_delivery_projection("wechat_deliveries")
        return db.execute(
            f"select * from ({projection}) where id=?", (delivery_id,),
        ).fetchone()

    @staticmethod
    def _native_wechat_task(db, task_id: int):
        from app import task_entity_storage

        task = task_entity_storage.get_task_with_inputs(db, task_id)
        if task is None or task["kind"] != "reply" or task["current_input"] is None:
            return None
        current = {key: value for key, value in task["current_input"].items()
                   if key not in {"id", "task_id"}}
        return {**task, **current}

    def wechat_delivery_review_approved(self, delivery_id: int) -> bool:
        with self._connect() as db:
            delivery = self._native_wechat_delivery(db, delivery_id)
            if delivery is None:
                return False
            task = self._native_wechat_task(db, int(delivery["reply_task_id"]))
            return bool(task is not None
                        and task["execution_generation"] == delivery["execution_generation"]
                        and self._wechat_review_approved_in_connection(db, delivery, task))

    def set_wechat_delivery_status(
        self, delivery_id: int, status: str, *, error: str = "",
        action_started_at: str | None = None,
        pre_action_failure: bool = False,
    ) -> None:
        expected_statuses = self._wechat_delivery_source_statuses(status, error)
        placeholders = ",".join("?" for _ in expected_statuses)
        generation_guard = (
            f"and exists (select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks "
            "where reply_tasks.id=wechat_deliveries.td_reply_task_id "
            "and reply_tasks.execution_generation="
            "wechat_deliveries.td_execution_generation)"
        )
        with self._connect() as db:
            values = {"status": status, "error": error,
                      "pre_action_failure": int(pre_action_failure)}
            if action_started_at is not None:
                values["action_started_at"] = action_started_at
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries", values,
                update_sql={"updated_at": "current_timestamp"},
            )
            cursor = db.execute(
                f"update actions as wechat_deliveries set {assignments} "
                "where wechat_deliveries.record_type='wechat_deliveries' "
                "and cast(wechat_deliveries.legacy_key as integer)=? "
                f"and wechat_deliveries.td_status in ({placeholders}) {generation_guard}",
                (*set_args, delivery_id, *expected_statuses),
            )
            if cursor.rowcount != 1:
                raise AgentRunLeaseLostError(
                    f"WeChat delivery superseded or not in expected state: {delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status=status,
                error=error,
            )
            if status == "sent":
                self._supersede_failed_wechat_deliveries_with_newer_sent(
                    db,
                    sent_delivery_id=delivery_id,
                )

    def supersede_reconciled_wechat_delivery(
        self,
        delivery_id: int,
        *,
        expected_execution_generation: str,
        reason: str,
        inactive_before: str,
    ) -> None:
        """Close a stale unknown delivery after read-only reconciliation."""
        generation = expected_execution_generation.strip()
        explanation = reason.strip()
        inactivity_cutoff = inactive_before.strip()
        if not generation:
            raise ValueError("expected_execution_generation must be non-empty")
        if not explanation:
            raise ValueError("reason must be non-empty")
        if not inactivity_cutoff:
            raise ValueError("inactive_before must be non-empty")
        with self._connect() as db:
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries", {"status": "superseded", "error": explanation},
                update_sql={"updated_at": "current_timestamp"},
            )
            cursor = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and wechat_deliveries.td_status='send_unknown'
                  and wechat_deliveries.td_execution_generation=?
                  and datetime(
                    coalesce(nullif(wechat_deliveries.td_action_started_at, ''),
                             wechat_deliveries.td_created_at)
                  ) <= datetime(?)
                  and exists (
                    select 1 from ({REPLY_TASK_SQL}) as reply_tasks
                    where reply_tasks.id=wechat_deliveries.td_reply_task_id
                      and reply_tasks.execution_generation=?
                  )
                """,
                (
                    *set_args,
                    delivery_id,
                    generation,
                    inactivity_cutoff,
                    generation,
                ),
            )
            if cursor.rowcount != 1:
                raise AgentRunLeaseLostError(
                    f"WeChat delivery superseded or not in expected state: {delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="superseded",
                error=explanation,
            )

    def skip_exhausted_stale_wechat_delivery(
        self,
        delivery_id: int,
        *,
        expected_execution_generation: str,
        reason: str,
        inactive_before: str,
        max_retries: int = MAX_AUTOMATIC_RETRIES,
    ) -> None:
        generation = expected_execution_generation.strip()
        explanation = reason.strip()
        inactivity_cutoff = inactive_before.strip()
        if delivery_id < 1:
            raise ValueError("delivery_id must be positive")
        if not generation:
            raise ValueError("expected_execution_generation must be non-empty")
        if not explanation:
            raise ValueError("reason must be non-empty")
        if not inactivity_cutoff:
            raise ValueError("inactive_before must be non-empty")
        if max_retries < 1:
            raise ValueError("max_retries must be positive")
        with self._immediate_write_transaction() as db:
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries",
                {"status": "skipped", "error": explanation, "pre_action_failure": 0},
                update_sql={"updated_at": "current_timestamp"},
            )
            updated = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and wechat_deliveries.td_status='failed'
                  and wechat_deliveries.td_pre_action_failure=1
                  and trim(wechat_deliveries.td_action_started_at)<>''
                  and datetime(wechat_deliveries.td_action_started_at) <= datetime(?)
                  and wechat_deliveries.td_execution_generation=?
                  and exists (
                      select 1
                      from ({REPLY_TASK_SQL}) as tasks
                      where tasks.id=wechat_deliveries.td_reply_task_id
                        and tasks.execution_generation=?
                        and (
                            select attempts.retry_count
                            from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                            where attempts.channel='wechat'
                              and attempts.conversation_id=tasks.conversation_id
                              and attempts.trigger_message_id=tasks.trigger_message_id
                            order by attempts.id desc
                            limit 1
                        ) >= ?
                  )
                returning cast(legacy_key as integer) as id
                """,
                (
                    *set_args,
                    delivery_id,
                    inactivity_cutoff,
                    generation,
                    generation,
                    max_retries,
                ),
            ).fetchone()
            if updated is None:
                raise AgentRunLeaseLostError(
                    f"WeChat delivery superseded or not in expected state: {delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="skipped",
                error=explanation,
            )

    def supersede_stale_ready_wechat_delivery(
        self,
        delivery_id: int,
        *,
        expected_execution_generation: str,
        reason: str,
        inactive_before: str,
    ) -> None:
        """Close an expired, never-started delivery without sending it."""
        generation = expected_execution_generation.strip()
        explanation = reason.strip()
        inactivity_cutoff = inactive_before.strip()
        if not generation:
            raise ValueError("expected_execution_generation must be non-empty")
        if not explanation:
            raise ValueError("reason must be non-empty")
        if not inactivity_cutoff:
            raise ValueError("inactive_before must be non-empty")
        with self._connect() as db:
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries", {"status": "superseded", "error": explanation},
                update_sql={"updated_at": "current_timestamp"},
            )
            cursor = db.execute(
                f"""
                update actions as wechat_deliveries set {assignments}
                where wechat_deliveries.record_type='wechat_deliveries'
                  and cast(wechat_deliveries.legacy_key as integer)=?
                  and wechat_deliveries.td_status='ready_to_send'
                  and wechat_deliveries.td_execution_generation=?
                  and coalesce(wechat_deliveries.td_action_started_at, '')=''
                  and datetime(wechat_deliveries.td_created_at) <= datetime(?)
                  and exists (
                    select 1 from ({REPLY_TASK_SQL}) as reply_tasks
                    where reply_tasks.id=wechat_deliveries.td_reply_task_id
                      and reply_tasks.execution_generation=?
                  )
                """,
                (
                    *set_args,
                    delivery_id,
                    generation,
                    inactivity_cutoff,
                    generation,
                ),
            )
            if cursor.rowcount != 1:
                raise AgentRunLeaseLostError(
                    f"WeChat delivery superseded or not in expected state: {delivery_id}"
                )
            self._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="superseded",
                error=explanation,
            )

    @classmethod
    def _supersede_failed_wechat_deliveries_with_newer_sent(
        cls,
        db: sqlite3.Connection,
        *,
        sent_delivery_id: int,
    ) -> int:
        """Close old pre-action failures once a newer reply reached the chat.

        A later successful direct-chat reply makes earlier failed drafts stale.
        Replaying them would reverse the conversation and duplicate a response,
        so preserve the audit trail as ``superseded`` instead of retrying.
        """
        sent = db.execute(
            f"""
            select account_id, target_type, target_id, conversation_id, reply_task_id,
                   execution_generation
            from ({WECHAT_DELIVERY_SQL})
            where id=? and status='sent'
            """,
            (sent_delivery_id,),
        ).fetchone()
        if sent is None:
            return 0
        rows = db.execute(
            f"""
            select id
            from ({WECHAT_DELIVERY_SQL})
            where account_id=?
              and target_type=?
              and target_id=?
              and conversation_id=?
              and (reply_task_id < ? or (
                  reply_task_id=? and id < ? and execution_generation<>?
              ))
              and status='failed'
              and pre_action_failure=1
            """,
            (
                sent["account_id"],
                sent["target_type"],
                sent["target_id"],
                sent["conversation_id"],
                sent["reply_task_id"],
                sent["reply_task_id"],
                sent_delivery_id,
                sent["execution_generation"],
            ),
        ).fetchall()
        error = f"superseded_by_newer_wechat_delivery:{sent_delivery_id}"
        for row in rows:
            delivery_id = int(row["id"])
            assignments, set_args = task_delivery_set_parts(
                "wechat_deliveries",
                {"status": "superseded", "error": error, "pre_action_failure": 0},
                update_sql={"updated_at": "current_timestamp"},
            )
            db.execute(
                f"update actions set {assignments} "
                "where record_type='wechat_deliveries' and cast(legacy_key as integer)=? "
                "and td_status='failed' and td_pre_action_failure=1",
                (*set_args, delivery_id),
            )
            cls._sync_wechat_delivery_reply_attempt(
                db,
                delivery_id=delivery_id,
                delivery_status="superseded",
                error=error,
            )
        return len(rows)

    def supersede_failed_wechat_deliveries_with_newer_sent(self) -> int:
        """Reconcile historical failures after an interrupted sender restart."""
        with self._connect() as db:
            sent_rows = db.execute(
                f"select id from ({WECHAT_DELIVERY_SQL}) where status='sent' order by id"
            ).fetchall()
            total = 0
            for row in sent_rows:
                total += self._supersede_failed_wechat_deliveries_with_newer_sent(
                    db,
                    sent_delivery_id=int(row["id"]),
                )
            return total

    def normalize_user_rejected_wechat_deliveries(self) -> int:
        """Convert legacy user-rejected deliveries to terminal skipped state."""
        with self._connect() as db:
            rows = db.execute(
                f"""
                select id
                from ({WECHAT_DELIVERY_SQL})
                where status='failed' and error='user_rejected'
                order by id
                """
            ).fetchall()
            for row in rows:
                delivery_id = int(row["id"])
                assignments, set_args = task_delivery_set_parts(
                    "wechat_deliveries", {"status": "skipped"},
                    update_sql={"updated_at": "current_timestamp"},
                )
                db.execute(
                    f"update actions set {assignments} "
                    "where record_type='wechat_deliveries' and cast(legacy_key as integer)=? "
                    "and td_status='failed' and td_error='user_rejected'",
                    (*set_args, delivery_id),
                )
                self._sync_wechat_delivery_reply_attempt(
                    db,
                    delivery_id=delivery_id,
                    delivery_status="skipped",
                    error="user_rejected",
                )
            return len(rows)

    @staticmethod
    def _wechat_delivery_source_statuses(status: str, error: str) -> tuple[str, ...]:
        if status == "sending":
            return ("ready_to_send",)
        if status == "sent":
            return ("sending", "send_unknown")
        if status == "send_unknown":
            return ("sending", "send_unknown")
        if status == "failed" and error in {
            "user_rejected",
            "target_binding_unverified",
        }:
            return ("ready_to_send",)
        if status == "failed" and error == "recalled":
            return ("sent",)
        if status == "failed":
            return ("sending", "send_unknown")
        raise ValueError(f"Unsupported WeChat delivery transition target: {status}")

    @staticmethod
    def _wechat_delivery_reply_attempt_status(
        delivery_status: str,
        error: str,
    ) -> tuple[str, str] | None:
        status = delivery_status.strip().lower()
        reason = error.strip()
        if status in {"ready_to_send", "sending"}:
            return "pending", reason or f"wechat_delivery_{status}"
        if status == "sent":
            return "sent", reason
        if status == "superseded":
            return "skipped", reason or status
        if status == "skipped":
            return "skipped", reason or status
        if status == "failed" and reason == "user_rejected":
            return "skipped", reason
        if status in {"failed", "send_unknown"}:
            return "failed", reason or status
        return None

    @classmethod
    def _sync_wechat_delivery_reply_attempt(
        cls,
        db: sqlite3.Connection,
        *,
        delivery_id: int,
        delivery_status: str,
        error: str,
    ) -> None:
        next_status = cls._wechat_delivery_reply_attempt_status(
            delivery_status,
            error,
        )
        if next_status is None:
            return
        send_status, send_error = next_status
        delivery = cls._native_wechat_delivery(db, delivery_id)
        task = (None if delivery is None else
                cls._native_wechat_task(db, int(delivery["reply_task_id"])))
        if task is None:
            return
        if str(delivery["execution_generation"]) != str(task["execution_generation"]):
            # The Attempt stands for the task's current generation. A delivery
            # of an earlier generation (a failed draft that a rerun replaced)
            # being closed as superseded must not overwrite the status the
            # current generation's delivery just wrote (2026-10-28: attempt
            # 16295 showed "skipped" one second after its reply was sent).
            return
        attempt = db.execute(
            f"""
            select id
            from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
            where channel='wechat'
              and conversation_id=?
              and trigger_message_id=?
            order by id desc
            limit 1
            """,
            (task["conversation_id"], task["trigger_message_id"]),
        ).fetchone()
        if attempt is None:
            return
        db.execute("update sqlite_sequence set seq=seq where 0")
        update_action(db, "reply_attempts", attempt["id"], {
            "send_status": send_status, "send_error": send_error,
            "updated_at": db.execute("select current_timestamp").fetchone()[0],
        })

    # ---- WeChat channel: memory candidates ----
    def add_wechat_memory_candidate(self, *, import_run_id: str, account_id: str,
                                    candidate) -> int | None:
        with self._immediate_write_transaction() as db:
            canonical = " ".join(candidate.statement.split()).casefold()
            existing = db.execute(
                f"select * from ({candidate_projection('wechat_memory_candidate')}) where account_id=? "
                "and status in ('pending', 'approved') order by id",
                (account_id,),
            ).fetchall()
            for row in existing:
                if " ".join(row["statement"].split()).casefold() != canonical:
                    continue
                conversations = sorted(set(json.loads(row["source_conversation_ids_json"]))
                                       | set(candidate.source_conversation_ids))
                messages = sorted(set(json.loads(row["source_message_ids_json"]))
                                  | set(candidate.source_message_ids))
                starts = [value for value in (row["source_time_start"],
                          candidate.source_time_start) if value]
                ends = [value for value in (row["source_time_end"],
                        candidate.source_time_end) if value]
                update_business_candidate(db, "wechat_memory_candidate", row["id"], {
                    "source_conversation_ids_json": json.dumps(conversations, ensure_ascii=False),
                    "source_message_ids_json": json.dumps(messages, ensure_ascii=False),
                    "source_time_start": min(starts, default=""),
                    "source_time_end": max(ends, default=""),
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                })
                return None
            cur = insert_business_candidate(db, "wechat_memory_candidate", {
                "import_run_id": import_run_id, "account_id": account_id,
                "statement": candidate.statement, "category": candidate.category,
                "confidence": candidate.confidence, "sensitivity": candidate.sensitivity,
                "source_conversation_ids_json": json.dumps(candidate.source_conversation_ids, ensure_ascii=False),
                "source_message_ids_json": json.dumps(candidate.source_message_ids, ensure_ascii=False),
                "source_time_start": candidate.source_time_start,
                "source_time_end": candidate.source_time_end,
                "evidence_excerpt": candidate.evidence_excerpt,
                "cleanup_notes": candidate.cleanup_notes,
            }, ignore=True)
            if cur.rowcount != 1:
                return None
            return int(cur.lastrowid)

    def get_wechat_memory_candidate(self, candidate_id: int) -> dict | None:
        with self._connect() as db:
            row = db.execute(
                f"select * from ({candidate_projection('wechat_memory_candidate')}) where id=?", (candidate_id,)
            ).fetchone()
        return dict(row) if row is not None else None

    def list_wechat_memory_candidates(
        self, *, status: str | None = None, category: str | None = None,
        sensitivity: str | None = None,
    ) -> list[dict]:
        with self._connect() as db:
            clauses, values = [], []
            for column, value in (("status", status), ("category", category),
                                  ("sensitivity", sensitivity)):
                if value:
                    clauses.append(f"{column}=?")
                    values.append(value)
            where = " where " + " and ".join(clauses) if clauses else ""
            rows = db.execute(
                f"select * from ({candidate_projection('wechat_memory_candidate')}){where} order by id",
                values,
            ).fetchall()
        return [dict(row) for row in rows]

    def review_wechat_memory_candidate(
        self, candidate_id: int, action: str, *, reviewer: str = "",
        final_statement: str = "",
    ) -> dict:
        with self._immediate_write_transaction() as db:
            row = db.execute(
                f"select * from ({candidate_projection('wechat_memory_candidate')}) where id=?", (candidate_id,)
            ).fetchone()
            if row is None:
                raise ValueError("candidate not found")
            current = row["status"]
            write_status = row["memory_write_status"]
            reviewer = reviewer.strip()
            if not reviewer:
                raise ValueError("reviewer required")
            if write_status == "writing":
                raise ValueError("candidate is writing and cannot be reviewed")
            if action == "approve":
                from app.wechat.memory_import import validate_final_statement
                statement = validate_final_statement(final_statement)
                if current != "pending":
                    raise ValueError("only pending candidate can be approved")
                stamp = db.execute("select current_timestamp").fetchone()[0]
                update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                    "status": "approved", "reviewer": reviewer,
                    "edited_statement": statement, "reviewed_at": stamp,
                    "updated_at": stamp,
                }, expected={"status": "pending"})
            elif action == "reject":
                if current not in {"pending", "approved"} or write_status in {"writing", "written"}:
                    raise ValueError("candidate cannot be rejected")
                stamp = db.execute("select current_timestamp").fetchone()[0]
                update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                    "status": "rejected", "reviewer": reviewer,
                    "reviewed_at": stamp, "updated_at": stamp,
                })
            elif action == "revoke":
                if current != "approved":
                    raise ValueError("only approved candidate can be revoked")
                next_write_status = (
                    "revocation_unavailable" if write_status == "written" else write_status
                )
                stamp = db.execute("select current_timestamp").fetchone()[0]
                update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                    "status": "revoked", "reviewer": reviewer,
                    "memory_write_status": next_write_status,
                    "reviewed_at": stamp, "updated_at": stamp,
                })
            else:
                raise ValueError("invalid review action")
        result = self.get_wechat_memory_candidate(candidate_id)
        assert result is not None
        return result

    def claim_wechat_memory_candidate_write(self, candidate_id: int) -> dict:
        with self._immediate_write_transaction() as db:
            row = db.execute(
                f"select * from ({candidate_projection('wechat_memory_candidate')}) where id=?", (candidate_id,)
            ).fetchone()
            if row is None:
                return {"outcome": "rejected", "reason": "candidate not found"}
            candidate = dict(row)
            if candidate["status"] != "approved":
                return {"outcome": "rejected", "reason": "candidate must be approved before writing memory"}
            if candidate["memory_id"]:
                return {"outcome": "written", "memory_id": candidate["memory_id"]}
            if candidate["memory_write_status"] == "writing":
                return {"outcome": "writing"}
            if candidate["memory_write_status"] == "unknown":
                return {"outcome": "rejected", "reason": "unknown memory write outcome requires manual resolution"}
            if candidate["memory_write_status"] == "revocation_unavailable":
                return {"outcome": "rejected", "reason": "revoked candidate cannot be written"}
            changed = update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                "memory_write_status": "writing", "memory_write_error": "",
                "updated_at": db.execute("select current_timestamp").fetchone()[0],
            }, expected={"status": "approved", "memory_id": ""},
                expected_in={"memory_write_status": ("", "failed")})
            if changed != 1:
                return {"outcome": "writing"}
            candidate["edited_statement"] = (
                candidate["edited_statement"] or candidate["statement"]
            )
            return {"outcome": "claimed", "candidate": candidate}

    def finish_wechat_memory_candidate_write(
        self, candidate_id: int, *, status: str, memory_id: str = "",
        error: str = "",
    ) -> None:
        if status not in {"written", "failed", "unknown"}:
            raise ValueError("invalid memory write status")
        with self._immediate_write_transaction() as db:
            if status == "written":
                changed = update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                    "memory_write_status": "written", "memory_id": memory_id,
                    "memory_write_error": "",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                }, expected={"status": "approved", "memory_write_status": "writing"})
                if changed == 1:
                    return
                row = db.execute(
                    f"select status, memory_write_status from ({candidate_projection('wechat_memory_candidate')}) where id=?",
                    (candidate_id,),
                ).fetchone()
                if row is None or row["memory_write_status"] != "writing":
                    raise RuntimeError("memory write claim lost")
                fallback = "revocation_unavailable" if row["status"] == "revoked" else "unknown"
                update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                    "memory_write_status": fallback, "memory_id": memory_id,
                    "memory_write_error": "review state changed during write",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                }, expected={"memory_write_status": "writing"})
                return
            changed = update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                "memory_write_status": status, "memory_id": "",
                "memory_write_error": error[:500],
                "updated_at": db.execute("select current_timestamp").fetchone()[0],
            }, expected={"status": "approved", "memory_write_status": "writing"})
            if changed != 1:
                raise RuntimeError("memory write claim lost")

    def resolve_wechat_memory_candidate_write_unknown(
        self, candidate_id: int, *, reviewer: str, confirm: bool = False,
        stale_after_seconds: int = 900,
    ) -> None:
        if not confirm:
            raise ValueError("explicit stale write confirmation required")
        if stale_after_seconds < 900:
            raise ValueError("stale write threshold cannot be less than 900 seconds")
        if not reviewer.strip():
            raise ValueError("reviewer required")
        with self._immediate_write_transaction() as db:
            stamp = db.execute("select current_timestamp").fetchone()[0]
            changed = update_business_candidate(db, "wechat_memory_candidate", candidate_id, {
                "memory_write_status": "unknown",
                "memory_write_error": "manually resolved after interrupted write",
                "reviewer": reviewer.strip(), "reviewed_at": stamp,
                "updated_at": stamp,
            }, expected={"memory_write_status": "writing"},
                stale_seconds=int(stale_after_seconds))
            if changed != 1:
                raise ValueError("only confirmed stale writing candidate can be resolved to unknown")

    @staticmethod
    def _native_meeting_alignment_job(db: sqlite3.Connection, task_id: int) -> MeetingAlignmentJob | None:
        from app.task_entity_storage import get_task

        task = get_task(db, task_id)
        if task is None or task["kind"] != "meeting_alignment":
            return None
        parameters = task["parameters"]
        result = db.execute(
            "select * from task_results where task_id=? and result_kind='meeting_alignment'",
            (task_id,),
        ).fetchone()
        output = {} if result is None else dict(result)
        values = {
            "id": task_id, "meeting_id": parameters["meeting_id"],
            "title": parameters.get("title", ""), "source_json": parameters.get("source_json", "{}"),
            "participants_json": parameters.get("participants_json", "[]"),
            "ended_at": parameters.get("ended_at", ""), "eligible_at": parameters.get("eligible_at", ""),
            "status": task["status"], "attempts": task["attempts"] or 0,
            "locked_at": task["locked_at"], "available_at": task["available_at"] or "",
            "error": task["error"] or "", "created_at": task["created_at"],
            "updated_at": task["updated_at"],
            **{name: output.get(name) for name in (
                "decision_json", "target_kind", "target_id", "target_title", "mentions_json",
                "final_message", "send_result_json", "calendar_summary_status",
                "calendar_summary_result_json",
            )},
        }
        defaults = {"decision_json": "{}", "target_kind": "", "target_id": "", "target_title": "",
                    "mentions_json": "[]", "final_message": "", "send_result_json": "{}",
                    "calendar_summary_status": "not_started", "calendar_summary_result_json": "{}"}
        for name, default in defaults.items():
            if values[name] is None:
                values[name] = default
        return MeetingAlignmentJob.model_validate(values)

    @staticmethod
    def _meeting_alignment_run_from_row(
        row: sqlite3.Row,
        ref: object,
    ) -> MeetingAlignmentRun:
        from app.native_standalone import NativeStandaloneDecision, meeting_decision

        values = {key: row[key] for key in row.keys() if key in MeetingAlignmentRun.model_fields}
        if "task_id" in row.keys():
            values.setdefault("task_id", row["task_id"])
        if "completed_at" in row.keys():
            values.setdefault("finished_at", row["completed_at"] or "")
        if "session_id" in row.keys():
            values.setdefault("codex_session_id", row["session_id"] or "")
        if "transcript_start" in row.keys():
            values.setdefault("codex_transcript_start_line", row["transcript_start"] or 0)
        if "transcript_end" in row.keys():
            values.setdefault("codex_transcript_end_line", row["transcript_end"] or 0)
        native = (meeting_decision(ref) if ref is not None else
                  NativeStandaloneDecision(
                      False, "native_reference_unavailable",
                      tool_events_reason="native_reference_unavailable",
                  ))
        values.update(
            decision_json=native.decision_json,
            audit_summary=native.audit_summary,
            audit_tool_events_json=native.audit_tool_events_json,
            native_available=native.available,
            native_reason=native.reason,
            tool_events_available=native.tool_events_available,
            tool_events_reason=native.tool_events_reason,
        )
        return MeetingAlignmentRun.model_validate(values)

    @staticmethod
    def _validate_meeting_alignment_status(status: object) -> str:
        return TypeAdapter(MeetingAlignmentQueueStatus).validate_python(status)

    def attach_meeting_alignment_segment(
        self,
        job_id: int,
        *,
        segment_id: str,
        eligible_at: str,
        status: str,
    ) -> bool:
        """Record a later recording of a meeting and reopen its job to re-summarise.

        Returns False when this recording is already attached, so a repeated scan
        does not keep reopening a job that is already covering it.
        """
        with self._immediate_write_transaction() as db:
            from app.task_entity_storage import get_task, update_task_cas

            row = db.execute(
                "select id from tasks where kind='meeting_alignment' and id=?",
                (job_id,),
            ).fetchone()
            if row is None:
                return False
            task = get_task(db, job_id)
            assert task is not None
            source_json = task["parameters"].get("source_json", "{}")
            try:
                source = json.loads(source_json or "{}")
            except (TypeError, ValueError):
                source = {}
            segments = source.get("extra_segment_ids")
            segments = list(segments) if isinstance(segments, list) else []
            if segment_id in segments:
                return False
            segments.append(segment_id)
            source["extra_segment_ids"] = segments
            params = {**task["parameters"], "source_json": json.dumps(source, ensure_ascii=False, sort_keys=True),
                      "eligible_at": eligible_at}
            changed = update_task_cas(
                db, task_id=job_id, expected={"status": task["status"]},
                changes={"status": status, "attempts": 0, "locked_at": None,
                         "available_at": "", "error": "", "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                parameters=params,
            )
            return changed is not None

    def upsert_meeting_alignment_job(
        self,
        *,
        meeting_id: str,
        title: str,
        source_json: str,
        participants_json: str,
        ended_at: str,
        eligible_at: str,
        status: MeetingAlignmentQueueStatus,
    ) -> int:
        validated_status = self._validate_meeting_alignment_status(status)
        from app.task_entity_storage import associate_business_key, create_task, get_task

        with self._immediate_write_transaction() as db:
            existing = db.execute(
                "select id from tasks where kind='meeting_alignment' and json_extract(parameters_json,'$.meeting_id')=?",
                (meeting_id,),
            ).fetchone()
            if existing is None:
                task = create_task(db, values={"kind": "meeting_alignment", "status": validated_status,
                    "available_at": "", "attempts": 0, "error": "", "locked_at": None,
                    "created_at": db.execute("select current_timestamp").fetchone()[0],
                    "updated_at": db.execute("select current_timestamp").fetchone()[0]}, parameters={
                    "meeting_id": meeting_id, "title": title, "source_json": source_json,
                    "participants_json": participants_json, "ended_at": ended_at, "eligible_at": eligible_at})
                task_id = int(task["id"])
                associate_business_key(db, task_id=task_id,
                    business_key=f"meeting-alignment:{task_id}:{meeting_id}")
                db.execute(
                    "insert into task_results(task_id,result_kind,decision_json,target_kind,target_id,target_title,"
                    "mentions_json,final_message,send_result_json,calendar_summary_status,calendar_summary_result_json) "
                    "values(?,'meeting_alignment','{}','','','','[]','','{}','not_started','{}')",
                    (task_id,),
                )
                return task_id
            task_id = int(existing["id"])
            task = get_task(db, task_id)
            assert task is not None
            if task["status"] == "waiting":
                parameters = {**task["parameters"], "title": title, "source_json": source_json,
                    "participants_json": participants_json, "ended_at": ended_at, "eligible_at": eligible_at}
                from app.task_entity_storage import update_task_cas
                update_task_cas(db, task_id=task_id, expected={"status": "waiting"},
                    changes={"status": validated_status, "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                    parameters=parameters)
            return task_id

    def get_meeting_alignment_job(self, job_id: int) -> MeetingAlignmentJob:
        with self._connect() as db:
            job = self._native_meeting_alignment_job(db, job_id)
            if job is None:
                raise ValueError(f"meeting alignment job not found: {job_id}")
            return job

    def get_meeting_delivery_key(self, task_id: int) -> str:
        from app.task_entity_storage import get_meeting_delivery_key

        with self._connect() as db:
            return get_meeting_delivery_key(db, task_id)

    def find_meeting_alignment_job_for_segment(
        self,
        *,
        title: str,
        started_at: str,
        ended_at: str,
        max_gap: timedelta,
    ) -> MeetingAlignmentJob | None:
        """The job for the meeting this recording belongs to, if one exists.

        One meeting can be recorded in several parts, and each part arrives with
        its own provider id, so the id alone cannot tell two recordings of one
        meeting apart from two meetings. Same title within `max_gap` of an
        existing job's own span is the same meeting.
        """
        segment_start = datetime.fromisoformat(started_at)
        segment_end = datetime.fromisoformat(ended_at)
        with self._connect() as db:
            ids = [int(row[0]) for row in db.execute(
                "select id from tasks where kind='meeting_alignment' and json_extract(parameters_json,'$.title')=? "
                "order by datetime(json_extract(parameters_json,'$.ended_at')) desc,id desc limit 50", (title,))]
            jobs = [self._native_meeting_alignment_job(db, task_id) for task_id in ids]
        for job in jobs:
            if job is None:
                continue
            other_start, other_end = _meeting_alignment_job_span(job)
            if other_start is None or other_end is None:
                continue
            if segment_start - other_end <= max_gap and other_start - segment_end <= max_gap:
                return job
        return None

    def get_meeting_alignment_job_by_meeting_id(
        self,
        meeting_id: str,
    ) -> MeetingAlignmentJob | None:
        with self._connect() as db:
            row = db.execute("select id from tasks where kind='meeting_alignment' and json_extract(parameters_json,'$.meeting_id')=?", (meeting_id,)).fetchone()
            return None if row is None else self._native_meeting_alignment_job(db, int(row["id"]))

    def list_sent_meeting_alignment_jobs(self) -> list[MeetingAlignmentJob]:
        """Return delivered meeting conclusions in stable chronological order."""
        with self._connect() as db:
            ids = [int(row[0]) for row in db.execute(
                "select t.id from tasks t join task_results r on r.task_id=t.id and r.result_kind='meeting_alignment' "
                "where t.kind='meeting_alignment' and t.status='sent' and trim(r.final_message)<>'' "
                "order by datetime(json_extract(t.parameters_json,'$.ended_at')),t.id")]
            return [job for task_id in ids if (job := self._native_meeting_alignment_job(db, task_id)) is not None]

    def list_meeting_alignment_jobs_ended_between(
        self, start: str, end: str
    ) -> list[MeetingAlignmentJob]:
        """Every discovered meeting that ended in [start, end), oldest first."""
        with self._connect() as db:
            ids = [int(row[0]) for row in db.execute(
                "select id from tasks where kind='meeting_alignment' "
                "and datetime(json_extract(parameters_json,'$.ended_at'))>=datetime(?) "
                "and datetime(json_extract(parameters_json,'$.ended_at'))<datetime(?) "
                "order by datetime(json_extract(parameters_json,'$.ended_at')),id", (start, end))]
            return [job for task_id in ids if (job := self._native_meeting_alignment_job(db, task_id)) is not None]

    def recurring_meeting_group_targets(self, title: str) -> list[tuple[str, str, int]]:
        with self._connect() as db:
            rows = db.execute(
                "select r.target_id,max(r.target_title) as target_title,count(*) as sent_count "
                "from tasks t join task_results r on r.task_id=t.id and r.result_kind='meeting_alignment' "
                "where t.kind='meeting_alignment' and json_extract(t.parameters_json,'$.title')=? "
                "and t.status='sent' and r.target_kind='group' and trim(r.target_id)<>'' and trim(r.final_message)<>'' "
                "group by r.target_id having count(*)>=2 "
                "order by sent_count desc,max(t.id) desc limit 5",
                (title,),
            ).fetchall()
        return [
            (str(row["target_id"]), str(row["target_title"]), int(row["sent_count"]))
            for row in rows
        ]


    def claim_meeting_alignment_jobs(
        self,
        limit: int,
        now: str,
    ) -> list[MeetingAlignmentJob]:
        if limit <= 0:
            return []
        from app.task_entity_storage import update_task_cas
        with self._immediate_write_transaction() as db:
            rows = db.execute(
                "select id,status,locked_at,attempts,available_at,parameters_json from tasks "
                "where kind='meeting_alignment' and status in ('waiting','pending','retry') "
                "and datetime(json_extract(parameters_json,'$.eligible_at'))<=datetime(?) "
                "and (coalesce(available_at,'')='' or datetime(available_at)<=datetime(?)) "
                "order by max(datetime(json_extract(parameters_json,'$.eligible_at')) ,"
                "coalesce(datetime(nullif(available_at,'')),datetime(json_extract(parameters_json,'$.eligible_at')))),id limit ?",
                (now, now, limit),
            ).fetchall()
            jobs = []
            stamp = db.execute("select current_timestamp").fetchone()[0]
            for row in rows:
                task_id = int(row["id"])
                changed = update_task_cas(db, task_id=task_id,
                    expected={"status": row["status"], "locked_at": row["locked_at"]},
                    changes={"status": "processing", "attempts": (row["attempts"] or 0) + 1,
                             "locked_at": stamp, "updated_at": stamp})
                if changed is not None:
                    job = self._native_meeting_alignment_job(db, task_id)
                    if job is not None:
                        jobs.append(job)
            return sorted(jobs, key=lambda job: (
                max(self._parse_stored_timestamp(job.eligible_at),
                    self._parse_stored_timestamp(job.available_at or job.eligible_at)), job.id))

    def update_meeting_alignment_job(self, job_id: int, **values: object) -> None:
        if not values:
            return
        allowed_columns = {
            "title",
            "source_json",
            "participants_json",
            "ended_at",
            "eligible_at",
            "status",
            "locked_at",
            "available_at",
            "error",
            "decision_json",
            "target_kind",
            "target_id",
            "target_title",
            "mentions_json",
            "final_message",
            "send_result_json",
            "calendar_summary_status",
            "calendar_summary_result_json",
        }
        filtered = self._filter_allowed_values(values, allowed_columns)
        settled_status = filtered.get("status")
        release_ready_lock_on_transition = False
        if "status" in filtered:
            filtered["status"] = self._validate_meeting_alignment_status(
                filtered["status"]
            )
            if (
                filtered["status"] == "ready_to_send"
                and "locked_at" not in filtered
            ):
                release_ready_lock_on_transition = True
                filtered.setdefault("available_at", "")
            elif filtered["status"] in {
                "waiting",
                "pending",
                "no_action",
                "sent",
                "retry",
                "failed",
                "quarantined",
                "skipped",
                "needs_human",
            }:
                filtered.setdefault("locked_at", None)
        from app.task_entity_storage import get_task, update_task_cas
        lifecycle_fields = {name: filtered.pop(name) for name in tuple(filtered)
                            if name in {"status", "locked_at", "available_at", "error"}}
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            if task is None or task["kind"] != "meeting_alignment":
                return
            parameters = {name: filtered.pop(name) for name in tuple(filtered)
                          if name in {"title", "source_json", "participants_json", "ended_at", "eligible_at"}}
            results = filtered
            if lifecycle_fields.get("status") in {"waiting", "pending", "no_action", "sent", "retry", "failed", "quarantined", "skipped", "needs_human"}:
                lifecycle_fields.setdefault("locked_at", None)
            if release_ready_lock_on_transition and lifecycle_fields.get("status") == "ready_to_send":
                lifecycle_fields.setdefault("available_at", "")
                if task["status"] != "ready_to_send":
                    lifecycle_fields.setdefault("locked_at", None)
            if lifecycle_fields:
                lifecycle_fields["updated_at"] = db.execute("select current_timestamp").fetchone()[0]
                update_task_cas(db, task_id=job_id,
                    expected={"status": task["status"], "locked_at": task["locked_at"]},
                    changes=lifecycle_fields,
                    parameters={**task["parameters"], **parameters} if parameters else None)
            elif parameters:
                update_task_cas(db, task_id=job_id,
                    expected={"status": task["status"]}, changes={"updated_at": db.execute("select current_timestamp").fetchone()[0]},
                    parameters={**task["parameters"], **parameters})
            if results:
                inserted = {
                    "task_id": job_id, "result_kind": "meeting_alignment",
                    "decision_json": "{}", "target_kind": "", "target_id": "", "target_title": "",
                    "mentions_json": "[]", "final_message": "", "send_result_json": "{}",
                    "calendar_summary_status": "not_started", "calendar_summary_result_json": "{}",
                    **results,
                }
                columns = list(inserted)
                db.execute(
                    f"insert into task_results({','.join(columns)}) values({','.join('?' for _ in columns)}) "
                    f"on conflict(task_id,result_kind) do update set {','.join(f'{name}=excluded.{name}' for name in results)}",
                    tuple(inserted.values()),
                )
        if settled_status in {"sent", "skipped"}:
            self.compact_meeting_consumer_input(job_id)

    def compact_meeting_consumer_input(self, job_id: int) -> bool:
        """Retire nonreplayable input only after every field has an exact source."""
        from app.meeting_consumer_source import (
            compact_meeting_consumer, scheduled_consumer_source_fields,
        )

        job = self.get_meeting_alignment_job(job_id)
        if job.status not in {"sent", "skipped"}:
            return False
        if "scheduled_consumer" not in json.loads(job.source_json):
            return False
        with self._connect() as db:
            attempts = db.execute(
                "select a.runtime_kind,a.session_id,a.transcript_start,a.transcript_end "
                "from runtime_attempts a join runs r on a.parent_id=r.id "
                "join run_provenance p on p.run_id=r.id and p.source_type='meeting_alignment_runs' "
                "where r.task_id=? and a.status not in ('starting','running') order by a.id desc",
                (job_id,),
            ).fetchall()
        compact = compact_meeting_consumer(job.source_json, attempts,
            source_reader=lambda context: scheduled_consumer_source_fields(self, context))
        if compact is None:
            return False
        from app.task_entity_storage import get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            if task is None or task["kind"] != "meeting_alignment" or task["status"] not in {"sent", "skipped"}:
                return False
            if task["parameters"].get("source_json", "{}") != job.source_json:
                return False
            parameters = {**task["parameters"], "source_json": compact}
            changed = update_task_cas(db, task_id=job_id,
                expected={"status": task["status"], "updated_at": task["updated_at"]},
                changes={"updated_at": db.execute("select current_timestamp").fetchone()[0]},
                parameters=parameters)
            return changed is not None

    def compact_terminal_meeting_consumer_inputs(self) -> dict[str, int]:
        """One explicit migration batch; normal writes compact their own job."""
        with self._connect() as db:
            ids = [int(row[0]) for row in db.execute(
                "select id from tasks where kind='meeting_alignment' and status in ('sent','skipped')"
            )]
        compacted = sum(self.compact_meeting_consumer_input(job_id) for job_id in ids)
        return {"examined": len(ids), "compacted": compacted}


    def claim_ready_to_send_meeting_alignment_jobs(
        self,
        limit: int,
        now: str,
    ) -> list[MeetingAlignmentJob]:
        if limit <= 0:
            return []
        token = uuid4().hex
        from app.task_entity_storage import update_task_cas
        with self._connect() as db:
            candidate = db.execute(
                "select 1 from tasks where kind='meeting_alignment' and status='ready_to_send' and locked_at is null "
                "and (coalesce(available_at,'')='' or datetime(available_at)<=datetime(?)) "
                "limit 1",
                (now,),
            ).fetchone()
            if candidate is None:
                return []
        with claim_connection(self, immediate=True) as db:
            if db is None:
                return []
            ids = [int(row[0]) for row in db.execute(
                "select id from tasks where kind='meeting_alignment' and status='ready_to_send' "
                "and locked_at is null and (coalesce(available_at,'')='' or datetime(available_at)<=datetime(?)) "
                "order by id limit ?", (now, limit))]
            jobs = []
            stamp = db.execute("select current_timestamp").fetchone()[0]
            for task_id in ids:
                changed = update_task_cas(db, task_id=task_id,
                    expected={"status": "ready_to_send", "locked_at": None},
                    changes={"locked_at": stamp, "updated_at": stamp})
                if changed is None:
                    continue
                upsert_meeting_alignment_delivery_claim(
                    db, job_id=task_id, claim_token=token,
                )
                job = self._native_meeting_alignment_job(db, task_id)
                if job is not None:
                    jobs.append(job.model_copy(update={"delivery_claim_token": token}))
            return jobs

    def claim_ready_to_send_meeting_alignment_job(
        self, job_id: int, *, now: str
    ) -> MeetingAlignmentJob | None:
        if job_id <= 0:
            raise ValueError("meeting alignment job id must be positive")
        from app.task_entity_storage import update_task_cas
        with claim_connection(self, immediate=True) as db:
            if db is None:
                return None
            row = db.execute("select status,locked_at,available_at from tasks "
                "where id=? and kind='meeting_alignment'", (job_id,)).fetchone()
            if row is None or row["status"] != "ready_to_send" or row["locked_at"] is not None or (
                row["available_at"] and db.execute("select datetime(?)<=datetime(?)", (row["available_at"], now)).fetchone()[0] != 1
            ):
                return None
            stamp = db.execute("select current_timestamp").fetchone()[0]
            if update_task_cas(db, task_id=job_id, expected={"status": "ready_to_send", "locked_at": None},
                               changes={"locked_at": stamp, "updated_at": stamp}) is None:
                return None
            token = uuid4().hex
            upsert_meeting_alignment_delivery_claim(
                db, job_id=job_id, claim_token=token,
            )
            job = self._native_meeting_alignment_job(db, job_id)
            return None if job is None else job.model_copy(update={"delivery_claim_token": token})

    def release_ready_to_send_meeting_alignment_claims(
        self, jobs: list[MeetingAlignmentJob]
    ) -> None:
        if not jobs:
            return
        from app.task_entity_storage import update_task_cas
        with self._immediate_write_transaction() as db:
            stamp = db.execute("select current_timestamp").fetchone()[0]
            for job in jobs:
                claim = db.execute("select td_claim_token from actions where record_type='meeting_alignment_delivery_claims' "
                    "and td_claim_job_id=?", (job.id,)).fetchone()
                if claim is None or claim[0] != job.delivery_claim_token or not job.delivery_claim_token:
                    continue
                update_task_cas(db, task_id=job.id,
                    expected={"status": "ready_to_send", "locked_at": job.locked_at},
                    changes={"locked_at": None, "updated_at": stamp})
                db.execute("delete from actions where record_type='meeting_alignment_delivery_claims' "
                           "and td_claim_job_id=? and td_claim_token=?", (job.id, job.delivery_claim_token))

    def schedule_ready_to_send_meeting_alignment_retry(
        self,
        job_id: int,
        *,
        error: str,
        available_at: str,
    ) -> MeetingAlignmentJob:
        from app.task_entity_storage import get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            if task is None or task["kind"] != "meeting_alignment" or task["status"] != "ready_to_send" or task["locked_at"] is None:
                raise ValueError(
                    "ready meeting retry requires an exclusive claim"
                )
            updated = update_task_cas(db, task_id=job_id,
                expected={"status": "ready_to_send", "locked_at": task["locked_at"]},
                changes={"attempts": (task["attempts"] or 0) + 1, "available_at": available_at,
                         "error": error, "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]})
            assert updated is not None
            return self._native_meeting_alignment_job(db, job_id)

    def reset_ready_to_send_meeting_alignment_jobs(
        self,
    ) -> list[MeetingAlignmentJob]:
        from app.task_entity_storage import update_task_cas
        with self._immediate_write_transaction() as db:
            rows = db.execute("select id,locked_at from tasks where kind='meeting_alignment' "
                              "and status='ready_to_send' and locked_at is not null").fetchall()
            updated_ids = []
            stamp = db.execute("select current_timestamp").fetchone()[0]
            for row in rows:
                changed = update_task_cas(db, task_id=int(row["id"]),
                    expected={"status": "ready_to_send", "locked_at": row["locked_at"]},
                    changes={"locked_at": None, "updated_at": stamp})
                if changed is not None:
                    updated_ids.append(int(row["id"]))
            db.execute("delete from actions where record_type='meeting_alignment_delivery_claims'")
            jobs = [job for task_id in updated_ids if (job := self._native_meeting_alignment_job(db, task_id)) is not None]
            return sorted(jobs, key=lambda job: job.id)

    def reset_processing_meeting_alignment_jobs(
        self,
    ) -> list[MeetingAlignmentJob]:
        with self._agent_run_write_transaction(None) as (db, (_, now_text)):
            from app.task_entity_storage import update_task_cas
            from app.run_entity_storage import update_run_cas, update_runtime_attempt_cas

            task_rows = db.execute("select id,attempts,locked_at,lease_owner,lease_expires_at from tasks "
                "where kind='meeting_alignment' and status='processing' order by id").fetchall()
            recovered = []
            for task in task_rows:
                task_id = int(task["id"])
                changed = update_task_cas(db, task_id=task_id,
                    expected={"status": "processing", "locked_at": task["locked_at"]},
                    changes={"status": "retry", "attempts": max((task["attempts"] or 0) - 1, 0),
                             "locked_at": None, "lease_owner": "", "owner_pid": 0,
                             "lease_expires_at": "", "updated_at": now_text})
                if changed is not None:
                    job = self._native_meeting_alignment_job(db, task_id)
                    if job is not None:
                        recovered.append(job)
            task_ids = [int(task["id"]) for task in task_rows]
            if task_ids:
                placeholders = ",".join("?" for _ in task_ids)
                runs = db.execute("select r.id from runs r join run_provenance p on p.run_id=r.id "
                    f"where p.source_type='meeting_alignment_runs' and r.task_id in ({placeholders}) "
                    "and r.status='running' order by r.id", task_ids).fetchall()
                error = json.dumps({"kind": "meeting_alignment_service_startup_requeue",
                    "message": "service restarted while meeting work was claimed"}, ensure_ascii=False)
                for row in runs:
                    run_id = int(row["id"])
                    update_run_cas(db, run_id=run_id, expected={"status": "running"},
                        changes={"status": "retry", "error": error, "completed_at": now_text,
                                 "updated_at": now_text, "lease_owner": "", "lease_expires_at": ""})
                    attempts = db.execute("select id,status from runtime_attempts where parent_id=? "
                        "and workload_kind in ('meeting','meeting_audit') and status in ('starting','running')", (run_id,)).fetchall()
                    for attempt in attempts:
                        update_runtime_attempt_cas(db, attempt_id=int(attempt["id"]),
                            expected={"status": attempt["status"]},
                            changes={"status": "failed", "failure_class": "process",
                                     "failure_code": "runtime_parent_requeued", "failover_permitted": 1,
                                     "lease_owner": "", "lease_expires_at": "", "finished_at": now_text,
                                     "updated_at": now_text})
            return sorted(recovered, key=lambda job: job.id)

    def rerun_meeting_alignment_jobs(self, job_ids: list[int]) -> list[int]:
        """Reset selected unsent terminal meeting jobs for fresh analysis.

        Existing meeting alignment runs remain immutable. Only the queue
        projection and retry counter are reset; delivery must be reached again
        through the current analysis and target-selection path. A prepared
        delivery or live owner must use its existing recovery path instead.
        """
        ids = sorted({int(job_id) for job_id in job_ids if int(job_id) > 0})
        if not ids:
            return []
        with self._immediate_write_transaction() as db:
            from app.task_entity_storage import get_meeting_delivery_key, update_task_cas

            changed_ids = []
            for task_id in ids:
                task = db.execute("select * from tasks where id=? and kind='meeting_alignment'", (task_id,)).fetchone()
                if task is None or task["status"] not in {"failed", "no_action", "needs_human"} or task["locked_at"] is not None:
                    continue
                result = db.execute("select * from task_results where task_id=? and result_kind='meeting_alignment'", (task_id,)).fetchone()
                if result is None or result["send_result_json"] != "{}":
                    continue
                key = get_meeting_delivery_key(db, task_id)
                target_key_prefix = key + ":target:"
                if db.execute(
                    f"select 1 from ({OUTBOUND_POSTFIX_SQL}) where channel='dingtalk' "
                    "and (delivery_key in (?,?) or substr(delivery_key,1,length(?))=?) limit 1",
                    (key, key + ":sensitive", target_key_prefix, target_key_prefix),
                ).fetchone() or db.execute(
                    f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) where channel='dingtalk' "
                    "and (delivery_key in (?,?) or substr(delivery_key,1,length(?))=?) limit 1",
                    (key, key + ":sensitive", target_key_prefix, target_key_prefix),
                ).fetchone():
                    continue
                if db.execute("select 1 from actions where record_type='meeting_alignment_delivery_claims' and td_claim_job_id=? limit 1", (task_id,)).fetchone():
                    continue
                if task["lease_owner"] and db.execute("select julianday(?)>julianday('now')", (task["lease_expires_at"],)).fetchone()[0]:
                    continue
                if db.execute("select 1 from runs r join run_provenance p on p.run_id=r.id "
                    "where p.source_type='meeting_alignment_runs' and r.task_id=? and r.status='running' limit 1", (task_id,)).fetchone():
                    continue
                if db.execute("select 1 from runtime_attempts a join runs r on r.id=a.parent_id "
                    "join run_provenance p on p.run_id=r.id and p.source_type='meeting_alignment_runs' "
                    "where r.task_id=? and a.status in ('starting','running') limit 1", (task_id,)).fetchone():
                    continue
                changed = update_task_cas(db, task_id=task_id,
                    expected={"status": task["status"], "locked_at": task["locked_at"], "updated_at": task["updated_at"]},
                    changes={"status": "retry", "attempts": 0, "locked_at": None, "available_at": "", "error": "",
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]})
                if changed is None:
                    continue
                db.execute("update task_results set decision_json='{}',target_kind='',target_id='',target_title='',mentions_json='[]',final_message='',send_result_json='{}' "
                           "where task_id=? and result_kind='meeting_alignment'", (task_id,))
                changed_ids.append(task_id)
            return changed_ids

    def attach_asr_transcript_and_rerun_meeting_job(
        self, job_id: int, transcript: dict[str, Any]
    ) -> int | None:
        """Bind a complete, provenance-bearing ASR transcript to one failed job.

        This is a same-identity source recovery, not a delivery retry. It applies
        the ordinary meeting rerun effect guards and preserves prior runs.
        """
        from app.meeting_alignment_source import MeetingAsrTranscript

        if not isinstance(job_id, int) or isinstance(job_id, bool) or job_id <= 0:
            return None
        evidence = MeetingAsrTranscript.model_validate(transcript)
        transcript_json = evidence.model_dump(mode="json")
        with self._immediate_write_transaction() as db:
            from app.task_entity_storage import get_meeting_delivery_key, get_task, update_task_cas
            task = get_task(db, job_id)
            if task is None or task["kind"] != "meeting_alignment" or task["status"] != "failed" or task["locked_at"] is not None:
                return None
            try:
                source_json = task["parameters"].get("source_json", "{}")
                source = json.loads(source_json or "{}")
            except (TypeError, ValueError):
                return None
            if (
                not isinstance(source, dict)
                or source.get("meeting_id") != task["parameters"].get("meeting_id")
                or "asr_transcript" in source
                or not isinstance(source.get("calendar_evidence"), dict)
                or source["calendar_evidence"].get("source") != "calendar"
                or self._native_meeting_alignment_job(db, job_id).send_result_json != "{}"
            ):
                return None
            delivery_key = get_meeting_delivery_key(db, job_id)
            target_key_prefix = delivery_key + ":target:"
            if db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_SQL}) outbound where outbound.channel='dingtalk' "
                "and (outbound.delivery_key in (?,?) or substr(outbound.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone() or db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) outbound where outbound.channel='dingtalk' "
                "and (outbound.delivery_key in (?,?) or substr(outbound.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone():
                return None
            if db.execute(
                "select 1 from actions where record_type='meeting_alignment_delivery_claims' and td_claim_job_id=? limit 1", (job_id,),
            ).fetchone():
                return None
            if task["lease_owner"] and db.execute("select julianday(?)>julianday('now')", (task["lease_expires_at"],)).fetchone()[0]:
                return None
            if db.execute(
                "select 1 from runs r join run_provenance p on p.run_id=r.id "
                "where p.source_type='meeting_alignment_runs' and r.task_id=? and r.status='running' limit 1",
                (job_id,),
            ).fetchone():
                return None
            if db.execute(
                "select 1 from runtime_attempts a join runs r on r.id=a.parent_id "
                "join run_provenance p on p.run_id=r.id and p.source_type='meeting_alignment_runs' "
                "where a.workload_kind in ('meeting','meeting_audit') and r.task_id=? and a.status in ('starting','running') limit 1",
                (job_id,),
            ).fetchone():
                return None

            source["asr_transcript"] = transcript_json
            source_json = json.dumps(source, ensure_ascii=False, sort_keys=True)
            params = {**task["parameters"], "source_json": source_json}
            updated = update_task_cas(db, task_id=job_id,
                expected={"status": "failed", "locked_at": None, "updated_at": task["updated_at"]},
                changes={"status": "retry", "attempts": 0, "locked_at": None, "available_at": "", "error": "",
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]}, parameters=params)
            if updated is None:
                return None
            db.execute("update task_results set decision_json='{}',target_kind='',target_id='',target_title='',mentions_json='[]',final_message='',send_result_json='{}' "
                       "where task_id=? and result_kind='meeting_alignment'", (job_id,))
            return job_id

    def baseline_meeting_alignment_jobs_before(
        self,
        activated_at: str,
    ) -> list[MeetingAlignmentJob]:
        from app.task_entity_storage import update_task_cas
        with self._immediate_write_transaction() as db:
            rows = db.execute("select t.id,t.status,t.locked_at,t.updated_at from tasks t join task_results r "
                "on r.task_id=t.id and r.result_kind='meeting_alignment' where t.kind='meeting_alignment' "
                "and datetime(json_extract(t.parameters_json,'$.ended_at'))<datetime(?) "
                "and t.status in ('waiting','pending','processing','retry','ready_to_send','failed') "
                "and r.send_result_json='{}' order by t.id", (activated_at,)).fetchall()
            jobs = []
            for row in rows:
                task_id = int(row["id"])
                changed = update_task_cas(db, task_id=task_id,
                    expected={"status": row["status"], "locked_at": row["locked_at"], "updated_at": row["updated_at"]},
                    changes={"status": "no_action", "locked_at": None, "available_at": "", "error": "",
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]})
                if changed is None:
                    continue
                db.execute("update task_results set decision_json='{}',target_kind='',target_id='',target_title='',mentions_json='[]',final_message='',send_result_json='{}' "
                           "where task_id=? and result_kind='meeting_alignment'", (task_id,))
                job = self._native_meeting_alignment_job(db, task_id)
                if job is not None:
                    jobs.append(job)
            return jobs

    def reopen_meeting_alignment_job_for_replay(
        self,
        job_id: int,
        *,
        title: str,
        source_json: str,
        participants_json: str,
        ended_at: str,
        eligible_at: str,
    ) -> MeetingAlignmentJob | None:
        from app.task_entity_storage import get_meeting_delivery_key, get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            current = self._native_meeting_alignment_job(db, job_id)
            if (task is None or task["kind"] != "meeting_alignment" or current is None
                    or task["status"] not in {"no_action", "failed", "needs_human"}
                    or task["locked_at"] is not None or current.send_result_json != "{}"):
                return None
            if db.execute(
                "select 1 from actions where record_type='meeting_alignment_delivery_claims' "
                "and td_claim_job_id=? limit 1",
                (job_id,),
            ).fetchone():
                return None
            if task["lease_owner"] and db.execute(
                "select julianday(?)>julianday('now')", (task["lease_expires_at"],)
            ).fetchone()[0]:
                return None
            if db.execute(
                "select 1 from runs r join run_provenance p on p.run_id=r.id "
                "where p.source_type='meeting_alignment_runs' and r.task_id=? "
                "and r.status='running' limit 1",
                (job_id,),
            ).fetchone() or db.execute(
                "select 1 from runtime_attempts a join runs r on r.id=a.parent_id "
                "join run_provenance p on p.run_id=r.id "
                "and p.source_type='meeting_alignment_runs' "
                "where r.task_id=? and a.status in ('starting','running') limit 1",
                (job_id,),
            ).fetchone():
                return None
            delivery_key = get_meeting_delivery_key(db, job_id)
            target_key_prefix = delivery_key + ":target:"
            # Safety gate: a prepared outbound message (sent or not) for this Meeting's
            # delivery key, its ':sensitive' key or any ':target:' key blocks replay.
            if db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_SQL}) outbound "
                "where outbound.channel='dingtalk' and (outbound.delivery_key in (?,?) "
                "or substr(outbound.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone():
                return None
            if db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) receipt "
                "where receipt.channel='dingtalk' and (receipt.delivery_key in (?,?) "
                "or substr(receipt.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone():
                return None
            parameters = {**task["parameters"], "title": title, "source_json": source_json,
                          "participants_json": participants_json, "ended_at": ended_at, "eligible_at": eligible_at}
            changed = update_task_cas(db, task_id=job_id,
                expected={"status": task["status"], "updated_at": task["updated_at"]},
                changes={"status": "pending", "attempts": 0, "locked_at": None,
                         "available_at": "", "error": "",
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                parameters=parameters)
            if changed is None:
                return None
            db.execute("update task_results set decision_json='{}',target_kind='',target_id='',target_title='',mentions_json='[]',final_message='',send_result_json='{}' "
                       "where task_id=? and result_kind='meeting_alignment'", (job_id,))
            return self._native_meeting_alignment_job(db, job_id)

    def restore_confirmed_meeting_delivery(
        self, job: MeetingAlignmentJob, *, key: str, prepared: PreparedOutboundMessage,
        receipt: dict[str, object], result_json: str,
    ) -> bool:
        """CAS restore of an already-delivered primary; preserve its exact body."""
        from app.meeting_alignment_delivery import MeetingDeliveryResult
        from app.meeting_alignment_models import (
            load_persisted_meeting_alignment_decision,
            meeting_decision_audit_is_approved,
        )

        result = MeetingDeliveryResult.model_validate_json(result_json)
        if (result.message_text != prepared.final_body or result.send_result != receipt
                or result.target_kind != job.target_kind or result.target_id != job.target_id
                or result.sensitive_private_delivery is not None or result.sensitive_private_merged):
            return False
        try:
            stored_decision = json.loads(job.decision_json)
            if (
                isinstance(stored_decision, dict)
                and "_service_audit" in stored_decision
                and not meeting_decision_audit_is_approved(job.decision_json)
            ):
                return False
            decision, _ = load_persisted_meeting_alignment_decision(job.decision_json)
        except (TypeError, ValueError, json.JSONDecodeError):
            return False
        from app.task_entity_storage import get_meeting_delivery_key, get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            if get_meeting_delivery_key(db, job.id) != key:
                return False
            body = db.execute(f"select final_body from ({OUTBOUND_POSTFIX_SQL}) where channel='dingtalk' and delivery_key=?", (key,)).fetchone()
            saved = db.execute(f"select provider_result_json from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) where channel='dingtalk' and delivery_key=?", (key,)).fetchone()
            if body is None or saved is None or body["final_body"] != prepared.final_body or json.loads(saved["provider_result_json"]) != receipt:
                return False
            target = db.execute(f"select value from ({state_projection('service_state')}) where key=?",
                (f"meeting_delivery_target:v1:dingtalk:{key}",)).fetchone()
            if decision.target is None:
                return False
            binding_target_kind = (
                "group" if decision.target.kind == "group"
                else "user" if decision.target.direct_user_id
                else "open_user"
            )
            expected_target = {"kind": binding_target_kind, "id": job.target_id}
            if target is None or json.loads(target["value"]) != expected_target:
                return False
            if db.execute(f"select 1 from ({OUTBOUND_POSTFIX_SQL}) where channel='dingtalk' and delivery_key=?", (f"{key}:sensitive",)).fetchone():
                return False
            task = get_task(db, job.id)
            if task is None or task["kind"] != "meeting_alignment" or task["lease_owner"] and db.execute(
                "select julianday(?)>julianday('now')", (task["lease_expires_at"],)).fetchone()[0]:
                return False
            current = self._native_meeting_alignment_job(db, job.id)
            if (current is None or current.status != "failed" or current.locked_at is not None
                    or current.send_result_json != "{}" or current.decision_json != job.decision_json
                    or current.target_kind != job.target_kind or current.target_id != job.target_id
                    or current.updated_at != job.updated_at or current.source_json != job.source_json):
                return False
            result_update = db.execute(
                "update task_results set send_result_json=?,final_message=? where task_id=? "
                "and result_kind='meeting_alignment' and decision_json=? and target_kind=? and target_id=? "
                "and send_result_json='{}' and final_message=?",
                (result_json, prepared.final_body, job.id, job.decision_json, job.target_kind,
                 job.target_id, job.final_message),
            )
            if result_update.rowcount != 1:
                return False
            changed = update_task_cas(db, task_id=job.id,
                expected={"status": "failed", "locked_at": None, "updated_at": job.updated_at,
                          "lease_owner": task["lease_owner"], "lease_expires_at": task["lease_expires_at"]},
                changes={"status": "ready_to_send", "available_at": "", "error": "",
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]})
            if changed is None:
                raise RuntimeError("Meeting Task changed while restoring the confirmed delivery")
            return True

    def requeue_failed_meeting_delivery(self, job_id: int) -> MeetingAlignmentJob | None:
        """Resume a reviewed unsent delivery after independent provider readback."""
        from app.meeting_alignment_models import (
            load_persisted_meeting_alignment_decision,
            meeting_decision_audit_is_approved,
        )
        from app.task_entity_storage import get_task, update_task_cas

        current = self.get_meeting_alignment_job(job_id)
        if current is None or not meeting_decision_audit_is_approved(current.decision_json):
            return None
        decision, _ = load_persisted_meeting_alignment_decision(current.decision_json)
        if decision.target is None:
            return None
        target_kind = (
            "group" if decision.target.kind == "group"
            else "user" if decision.target.direct_user_id
            else "open_user"
        )
        target_id = (
            decision.target.conversation_id if target_kind == "group"
            else decision.target.direct_user_id or decision.target.open_dingtalk_id
        )
        if target_id != current.target_id:
            return None
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            latest = self._native_meeting_alignment_job(db, job_id)
            if (task is None or latest is None or task["kind"] != "meeting_alignment"
                    or task["status"] != "failed" or task["locked_at"] is not None
                    or latest.decision_json != current.decision_json
                    or latest.updated_at != current.updated_at
                    or latest.source_json != current.source_json
                    or latest.send_result_json != "{}"
                    or latest.target_kind != current.target_kind
                    or latest.target_id != current.target_id
                    or latest.final_message != current.final_message
                    or latest.error != current.error):
                return None
            from app.task_entity_storage import get_meeting_delivery_key
            delivery_key = get_meeting_delivery_key(db, job_id)
            target_key_prefix = delivery_key + ":target:"
            if db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) outbound "
                "where outbound.channel='dingtalk' and (outbound.delivery_key in (?,?) "
                "or substr(outbound.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone():
                return None
            if task["lease_owner"] and db.execute(
                "select julianday(?)>julianday('now')", (task["lease_expires_at"],),
            ).fetchone()[0]:
                return None
            changed = update_task_cas(
                db, task_id=job_id,
                expected={"status": "failed", "locked_at": None,
                          "updated_at": task["updated_at"]},
                changes={"status": "ready_to_send", "available_at": "", "error": "",
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            return self._native_meeting_alignment_job(db, job_id) if changed else None

    def request_failed_meeting_audit_recovery(
        self, job_id: int, *, expected_candidate_sha256: str,
    ) -> MeetingAlignmentJob | None:
        """Queue one independent Audit of an unchanged failed Meeting candidate."""
        import hmac
        from app.meeting_alignment_models import (
            load_persisted_meeting_alignment_decision,
            meeting_alignment_decision_digest,
            meeting_audit_result_from_record,
            meeting_decision_audit_is_approved,
        )

        current = self.get_meeting_alignment_job(job_id)
        if (
            current is None or current.status != "failed" or current.locked_at
            or current.send_result_json != "{}" or current.decision_json == "{}"
        ):
            return None
        try:
            error = json.loads(current.error)
            raw_decision = json.loads(current.decision_json)
            decision, _ = load_persisted_meeting_alignment_decision(
                current.decision_json
            )
            candidate_json = current.decision_json
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
        if not isinstance(error, dict) or not isinstance(raw_decision, dict):
            return None
        prior_audit = raw_decision.get("_service_audit")
        prior_result = (
            prior_audit.get("result") if isinstance(prior_audit, dict) else None
        )
        try:
            parsed_prior_result = meeting_audit_result_from_record(
                prior_result, digest=meeting_alignment_decision_digest(decision),
            )
        except (TypeError, ValueError):
            parsed_prior_result = None
        prior_return = (
            error.get("kind") == "meeting_audit_recovery_unapproved"
            and isinstance(prior_audit, dict)
            and parsed_prior_result is not None
            and parsed_prior_result.outcome == "return"
            and prior_audit.get("candidate_sha256")
            == meeting_alignment_decision_digest(decision)
        )
        if prior_return:
            candidate_json = json.dumps(
                decision.model_dump(mode="json"),
                ensure_ascii=False,
                separators=(",", ":"),
            )
        initial_target_failure = (
            error.get("kind") == "meeting_target"
            and not isinstance(prior_audit, dict)
        )
        if (
            not (initial_target_failure or prior_return)
            or meeting_decision_audit_is_approved(current.decision_json)
            or not expected_candidate_sha256
            or not hmac.compare_digest(
                meeting_alignment_decision_digest(decision),
                expected_candidate_sha256,
            )
            or decision.action != "send" or decision.target is None
            or decision.sensitive_private_message is not None
            or decision.final_message != current.final_message
        ):
            return None
        target_kind = (
            "group" if decision.target.kind == "group"
            else "user" if decision.target.direct_user_id
            else "open_user"
        )
        target_id = (
            decision.target.conversation_id if target_kind == "group"
            else decision.target.direct_user_id or decision.target.open_dingtalk_id
        )
        if not target_id or (decision.target.kind, target_id) != (
            current.target_kind, current.target_id,
        ):
            return None
        marker = json.dumps({
            "kind": "meeting_audit_recovery_requested",
            "message": "Audit the unchanged failed Meeting candidate only.",
            "candidate_sha256": expected_candidate_sha256,
        }, ensure_ascii=False, sort_keys=True)
        from app.task_entity_storage import get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            latest = self._native_meeting_alignment_job(db, job_id)
            if (task is None or latest is None or task["kind"] != "meeting_alignment"
                    or task["status"] != "failed" or task["locked_at"] is not None
                    or latest.decision_json != current.decision_json
                    or latest.source_json != current.source_json
                    or latest.target_kind != current.target_kind
                    or latest.target_id != current.target_id
                    or latest.final_message != current.final_message
                    or latest.error != current.error or latest.send_result_json != "{}"
                    or latest.updated_at != current.updated_at):
                return None
            from app.task_entity_storage import get_meeting_delivery_key
            delivery_key = get_meeting_delivery_key(db, job_id)
            target_key_prefix = delivery_key + ":target:"
            if db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) outbound "
                "where outbound.channel='dingtalk' and (outbound.delivery_key in (?,?) "
                "or substr(outbound.delivery_key,1,length(?))=?) limit 1",
                (delivery_key, delivery_key + ":sensitive", target_key_prefix, target_key_prefix),
            ).fetchone():
                return None
            changed = update_task_cas(
                db, task_id=job_id,
                expected={"status": "failed", "locked_at": None,
                          "updated_at": task["updated_at"]},
                changes={"status": "retry", "available_at": "", "error": marker,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if changed is None:
                return None
            candidate = db.execute(
                "update task_results set decision_json=? where task_id=? "
                "and result_kind='meeting_alignment' and decision_json=?",
                (candidate_json, job_id, current.decision_json),
            )
            if candidate.rowcount != 1:
                raise RuntimeError("Meeting candidate changed while queuing its frozen re-audit")
            return self._native_meeting_alignment_job(db, job_id)

    def complete_failed_meeting_audit_recovery(
        self, job: MeetingAlignmentJob, *, audited_decision_json: str | None,
        approved: bool, error: str = "",
    ) -> MeetingAlignmentJob | None:
        """CAS the exact audit-only result; approve alone re-enters delivery."""
        from app.meeting_alignment_models import (
            meeting_alignment_decision_digest,
            meeting_decision_audit_is_approved,
        )

        try:
            original = MeetingAlignmentDecision.model_validate_json(job.decision_json)
            audited_payload = (
                json.loads(audited_decision_json)
                if audited_decision_json is not None else None
            )
            if isinstance(audited_payload, dict):
                audited_payload = {
                    key: value for key, value in audited_payload.items()
                    if key != "_service_audit"
                }
            audited = (
                MeetingAlignmentDecision.model_validate(audited_payload)
                if audited_payload is not None else original
            )
        except (TypeError, ValueError):
            return None
        original_digest = meeting_alignment_decision_digest(original)
        if (
            meeting_alignment_decision_digest(audited) != original_digest
            or original.model_dump(mode="json") != audited.model_dump(mode="json")
            or (approved and (
                audited_decision_json is None
                or not meeting_decision_audit_is_approved(audited_decision_json)
            ))
            or (approved and error)
            or (not approved and not error)
            or job.status != "processing"
            or job.send_result_json != "{}"
        ):
            return None
        next_status = "ready_to_send" if approved else "failed"
        target_kind = "group" if original.target and original.target.kind == "group" else "user"
        target_id = (
            original.target.conversation_id if target_kind == "group"
            else (original.target.direct_user_id or original.target.open_dingtalk_id)
            if original.target else ""
        )
        binding_kind = (
            "group" if target_kind == "group"
            else "user" if original.target and original.target.direct_user_id
            else "open_user"
        )
        delivery_key = self.resolve_meeting_alignment_delivery_key(
            f"meeting-alignment:{job.id}:{job.meeting_id}",
            target_kind=binding_kind,
            target_id=target_id,
        )
        from app.task_entity_storage import get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job.id)
            current = self._native_meeting_alignment_job(db, job.id)
            if (task is None or current is None or task["kind"] != "meeting_alignment"
                    or task["status"] != "processing" or task["locked_at"] != job.locked_at
                    or current.decision_json != job.decision_json
                    or current.source_json != job.source_json
                    or current.target_kind != job.target_kind
                    or current.target_id != job.target_id
                    or current.final_message != job.final_message
                    or current.error != job.error or current.send_result_json != "{}"):
                return None
            if next_status == "ready_to_send" and db.execute(
                f"select 1 from ({OUTBOUND_POSTFIX_RECEIPT_SQL}) "
                "where channel='dingtalk' and delivery_key=?", (delivery_key,),
            ).fetchone():
                return None
            if task["lease_owner"] and db.execute(
                "select julianday(?)>julianday('now')", (task["lease_expires_at"],),
            ).fetchone()[0]:
                return None
            result = db.execute(
                "update task_results set decision_json=? where task_id=? "
                "and result_kind='meeting_alignment' and decision_json=? "
                "and target_kind=? and target_id=? and final_message=? "
                "and send_result_json='{}'",
                (audited_decision_json or job.decision_json, job.id,
                 job.decision_json, job.target_kind, job.target_id, job.final_message),
            )
            if result.rowcount != 1:
                return None
            changed = update_task_cas(
                db, task_id=job.id,
                expected={"status": "processing", "locked_at": job.locked_at,
                          "updated_at": task["updated_at"]},
                changes={"status": next_status, "locked_at": None, "available_at": "",
                         "error": error,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if changed is None:
                raise RuntimeError("Meeting Task changed while completing Audit recovery")
            return self._native_meeting_alignment_job(db, job.id)




    def list_meeting_alignment_runs(
        self,
        job_id: int,
    ) -> list[MeetingAlignmentRun]:
        from app.native_standalone import native_run_ref

        with self._connect() as db:
            rows = db.execute(
                """
                select r.*, p.job_id from runs r
                join run_provenance p on p.run_id=r.id and p.source_type='meeting_alignment_runs'
                where r.task_id=?
                order by r.id desc
                """,
                (job_id,),
            ).fetchall()
            runs = [(row, native_run_ref(db, row["id"], "meeting_alignment_runs")) for row in rows]
        return [self._meeting_alignment_run_from_row(row, provenance) for row, provenance in runs]

    def get_meeting_alignment_run(self, run_id: int) -> MeetingAlignmentRun | None:
        from app.native_standalone import native_run_ref
        with self._connect() as db:
            row = db.execute(
                "select r.*, p.job_id from runs r join run_provenance p on p.run_id=r.id "
                "where r.id=? and p.source_type='meeting_alignment_runs'", (run_id,),
            ).fetchone()
            if row is None:
                return None
            return self._meeting_alignment_run_from_row(row, native_run_ref(db, run_id, "meeting_alignment_runs"))



    def recovered_meeting_alignment_run_ids_since(
        self,
        created_since: str,
    ) -> set[int]:
        """Return retry runs superseded by a completed meeting outcome."""
        with self._connect() as db:
            rows = db.execute("select earlier.id from runs earlier "
                "join run_provenance ep on ep.run_id=earlier.id and ep.source_type='meeting_alignment_runs' "
                "join tasks jobs on jobs.id=earlier.task_id and jobs.kind='meeting_alignment' "
                "where earlier.created_at>=? and earlier.status in ('retry','failed') and jobs.status in ('sent','no_action') "
                "and exists (select 1 from runs later join run_provenance lp on lp.run_id=later.id "
                "and lp.source_type='meeting_alignment_runs' where later.task_id=earlier.task_id "
                "and later.id>earlier.id and later.status in ('ready_to_send','sent','no_action'))", (created_since,)).fetchall()
        return {int(row["id"]) for row in rows}

    def has_later_meeting_alignment_run(self, job_id: int, run_id: int) -> bool:
        with self._connect() as db:
            row = db.execute("select 1 from runs r join run_provenance p on p.run_id=r.id "
                "where p.source_type='meeting_alignment_runs' and r.task_id=? and r.id>? limit 1",
                (job_id, run_id)).fetchone()
        return row is not None

    def list_meeting_alignment_runs_for_codex_session(
        self,
        codex_session_id: str,
    ) -> list[MeetingAlignmentRun]:
        from app.native_standalone import native_run_ref

        with self._connect() as db:
            rows = db.execute(
                """
                select r.*, r.task_id as job_id from runs r
                join run_provenance p on p.run_id=r.id and p.source_type='meeting_alignment_runs'
                where r.session_id=? order by r.id desc
                """,
                (codex_session_id,),
            ).fetchall()
            runs = [(row, native_run_ref(db, row["id"], "meeting_alignment_runs")) for row in rows]
        return [self._meeting_alignment_run_from_row(row, provenance) for row, provenance in runs]

    def create_okr_review_request(
        self,
        *,
        conversation_id: str,
        conversation_title: str,
        trigger_message_id: str,
        trigger_sender: str,
        trigger_sender_user_id: str,
        trigger_text: str,
        period_label: str,
        period_start: str,
        period_end: str,
        okr_source_json: str,
    ) -> int:
        from app.task_entity_storage import create_task, get_task, update_task_cas

        with self._immediate_write_transaction() as db:
            row = db.execute(
                "select id from tasks where kind='okr_review' "
                "and json_extract(parameters_json,'$.conversation_id')=? "
                "and json_extract(parameters_json,'$.trigger_message_id')=?",
                (conversation_id, trigger_message_id),
            ).fetchone()
            if row is not None:
                task_id = int(row["id"])
                task = get_task(db, task_id)
                assert task is not None
                if task["status"] == "failed":
                    parameters = {**task["parameters"], "okr_source_json": okr_source_json, "codex_session_id": ""}
                    update_task_cas(
                        db, task_id=task_id, expected={"status": "failed"},
                        changes={"status": "pending", "error": "", "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                        parameters=parameters,
                    )
                return task_id
            now = db.execute("select current_timestamp").fetchone()[0]
            task = create_task(db, values={
                "kind": "okr_review", "status": "pending", "error": "",
                "created_at": now, "updated_at": now,
            }, parameters={
                "conversation_id": conversation_id, "conversation_title": conversation_title,
                "trigger_message_id": trigger_message_id, "trigger_sender": trigger_sender,
                "trigger_sender_user_id": trigger_sender_user_id, "trigger_text": trigger_text,
                "period_label": period_label, "period_start": period_start,
                "period_end": period_end, "okr_source_json": okr_source_json,
                "codex_session_id": "",
            })
            return int(task["id"])

    @staticmethod
    def _okr_review_request_from_task(task: Mapping[str, object]) -> OkrReviewRequest:
        parameters = task["parameters"]
        return OkrReviewRequest.model_validate({
            "id": task["id"], **parameters, "status": task["status"],
            "error": task["error"] or "", "created_at": task["created_at"],
            "updated_at": task["updated_at"],
        })

    def claim_okr_review_requests(self, limit: int) -> list[OkrReviewRequest]:
        if limit <= 0:
            return []
        from app.task_entity_storage import update_task_cas

        with self._immediate_write_transaction() as db:
            rows = db.execute(
                "select id,status,error from tasks where kind='okr_review' "
                "and status='pending' order by id limit ?", (limit,),
            ).fetchall()
            claimed = []
            stamp = db.execute("select current_timestamp").fetchone()[0]
            for row in rows:
                task_id = int(row["id"])
                updated = update_task_cas(db, task_id=task_id,
                    expected={"status": row["status"]},
                    changes={"status": "processing", "error": "", "updated_at": stamp})
                if updated is not None:
                    claimed.append(self._okr_review_request_from_task(updated))
            return claimed

    def reset_recoverable_okr_review_requests(
        self, *, processing_max_age_seconds: int | None = None
    ) -> list[OkrReviewRequest]:
        from app.task_entity_storage import get_task, update_task_cas

        with self._immediate_write_transaction() as db:
            lock_projection = "(" + state_projection("codex_session_locks") + ")"
            processing_clause = (
                "task.status='processing' and not (task.adapter_name='okr_review' "
                "and coalesce(task.lease_owner,'')<>'' "
                "and task.lease_expires_at>current_timestamp)"
            )
            params: list[object] = []
            if processing_max_age_seconds is not None:
                if processing_max_age_seconds <= 0:
                    return []
                processing_clause += " and datetime(task.updated_at)<=datetime('now', ?)"
                params.append(f"-{int(processing_max_age_seconds)} seconds")
            rows = db.execute(
                f"""
                select task.id from tasks task
                where task.kind='okr_review' and (
                    ({processing_clause}) or (
                        task.status='failed'
                        and task.error like 'codex session locked:%'
                        and not exists (
                            select 1 from {lock_projection} locks
                            where locks.conversation_id=json_extract(task.parameters_json,'$.conversation_id')
                              and datetime(locks.locked_at)>datetime('now', ?)
                        )
                    )
                ) order by task.updated_at,task.id
                """,
                (*params, f"-{CODEX_SESSION_LOCK_STALE_SECONDS} seconds"),
            ).fetchall()
            tasks = [get_task(db, int(row["id"])) for row in rows]
            tasks = [task for task in tasks if task is not None]
            if not tasks:
                return []
            owners = [f"okr_review:{task['id']}" for task in tasks]
            placeholders = ",".join("?" for _ in owners)
            db.execute(
                f"delete from state where record_type='codex_session_locks' and owner in ({placeholders})",
                owners,
            )
            stamp = db.execute("select current_timestamp").fetchone()[0]
            reset = []
            for task in tasks:
                parameters = dict(task["parameters"])
                parameters["codex_session_id"] = ""
                update_task_cas(
                    db, task_id=int(task["id"]),
                    expected={"status": task["status"], "updated_at": task["updated_at"]},
                    changes={"status": "pending", "error": "", "updated_at": stamp},
                    parameters=parameters,
                )
                reset.append(self._okr_review_request_from_task(task))
            return reset

    def get_okr_review_request(self, request_id: int) -> OkrReviewRequest:
        from app.task_entity_storage import get_task

        with self._connect() as db:
            task = get_task(db, request_id)
            if task is None or task["kind"] != "okr_review":
                raise ValueError(f"okr review request not found: {request_id}")
            return self._okr_review_request_from_task(task)

    def mark_okr_review_request_done(
        self, request_id: int, *, codex_session_id: str
    ) -> None:
        from app.task_entity_storage import get_task, update_task_cas

        with self._connect() as db:
            task = get_task(db, request_id)
            if task is None or task["kind"] != "okr_review":
                raise ValueError(f"okr review request not found: {request_id}")
            update_task_cas(
                db, task_id=request_id, expected={"status": task["status"]},
                changes={"status": "done", "error": "", "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                parameters={**task["parameters"], "codex_session_id": codex_session_id},
            )

    def mark_okr_review_request_failed(self, request_id: int, error: str) -> None:
        from app.task_entity_storage import get_task, update_task_cas

        with self._connect() as db:
            task = get_task(db, request_id)
            if task is None or task["kind"] != "okr_review":
                raise ValueError(f"okr review request not found: {request_id}")
            update_task_cas(
                db, task_id=request_id, expected={"status": task["status"]},
                changes={"status": "failed", "error": error, "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )

    def record_okr_review_item(
        self, *, request_id: int, objective_title: str, objective_weight: float,
        kr_title: str, kr_weight: float, item_json: str,
    ) -> int:
        with self._connect() as db:
            owner = db.execute("select kind from tasks where id=?", (request_id,)).fetchone()
            if owner is None or owner["kind"] != "okr_review":
                raise ValueError(f"okr review request not found: {request_id}")
            row = db.execute(
                "insert into okr_review_items(request_id,objective_title,objective_weight,kr_title,kr_weight,item_json) "
                "values(?,?,?,?,?,?) returning id",
                (request_id, objective_title, objective_weight, kr_title, kr_weight, item_json),
            ).fetchone()
            return int(row["id"])

    def bind_okr_review_runtime_attempt(self, *, task_id: int, run_id: int, attempt_id: int) -> None:
        """Bind the returned structured attempt to the validated review's new Run."""
        from app.run_entity_storage import (
            get_run, get_run_provenance, get_runtime_attempt,
            update_runtime_attempt_cas,
        )
        from app.task_entity_storage import get_task

        with self._agent_run_write_transaction(None) as (db, _):
            task = get_task(db, task_id)
            run = get_run(db, run_id)
            provenance = get_run_provenance(db, run_id)
            attempt = get_runtime_attempt(db, attempt_id)
            if task is None or task["kind"] != "okr_review":
                raise ValueError("OKR RuntimeAttempt owner Task is invalid")
            if run is None or run["task_id"] != task_id or provenance is None or provenance["source_type"] != "okr_review_runs":
                raise ValueError("OKR RuntimeAttempt owner Run is invalid")
            if attempt is None or attempt["workload_kind"] != "structured" or attempt["workload_key"] != str(task_id) or attempt["status"] != "completed":
                raise ValueError("OKR RuntimeAttempt does not match the completed structured request")
            if attempt["parent_id"] == run_id:
                return
            if attempt["parent_id"] is not None:
                raise ValueError("structured RuntimeAttempt already has a different Run owner")
            if update_runtime_attempt_cas(
                db, attempt_id=attempt_id,
                expected={"parent_id": None, "workload_kind": "structured",
                          "workload_key": str(task_id), "status": "completed"},
                changes={"parent_id": run_id},
            ) is None:
                raise ValueError("structured RuntimeAttempt changed before OKR Run binding")

    def upsert_conversation(
        self, conversation_id: str, title: str, single_chat: bool,
    ) -> None:
        with self._connect() as db:
            db.execute("begin")
            upsert_state(
                db, "conversations",
                {"conversation_id": conversation_id, "title": title,
                 "single_chat": int(single_chat)},
                {"title": state_json_field("title"),
                 "single_chat": state_json_field("single_chat")},
            )

    def upsert_conversation_runtime_session(
        self,
        conversation_id: str,
        route_name: str,
        session_id: str,
        contract_hash: str = "",
    ) -> None:
        conversation_id = self._require_runtime_attempt_text(
            conversation_id, field="conversation_id"
        )
        route_name = self._require_runtime_attempt_text(route_name, field="route_name")
        session_id = self._require_runtime_attempt_text(session_id, field="session_id")
        contract_hash = contract_hash.strip()
        with self._agent_run_write_transaction(None) as (db, (_, now_text)):
            self._upsert_conversation_runtime_session_in_connection(
                db, conversation_id, route_name, session_id, contract_hash, now_text
            )

    @staticmethod
    def _upsert_conversation_runtime_session_in_connection(
        db: sqlite3.Connection,
        conversation_id: str,
        route_name: str,
        session_id: str,
        contract_hash: str,
        now_text: str,
    ) -> None:
        upsert_state(
            db, "conversation_runtime_sessions",
            {"conversation_id": conversation_id, "route_name": route_name,
             "session_id": session_id, "contract_hash": contract_hash,
             "updated_at": now_text},
            {field: state_json_field(field) for field in
             ("session_id", "contract_hash", "updated_at")},
        )

    def get_conversation_runtime_session(
        self,
        conversation_id: str,
        route_name: str,
        *,
        required_contract_hash: str | None = None,
    ) -> str | None:
        projection = "(" + state_projection("conversation_runtime_sessions") + ")"
        with self._connect() as db:
            if required_contract_hash is None:
                row = db.execute(
                    f"""
                    select session_id from {projection}
                    where conversation_id=? and route_name=?
                    """,
                    (conversation_id, route_name),
                ).fetchone()
            else:
                row = db.execute(
                    f"""
                    select session_id from {projection}
                    where conversation_id=? and route_name=? and contract_hash=?
                    """,
                    (conversation_id, route_name, required_contract_hash.strip()),
                ).fetchone()
            return None if row is None else str(row["session_id"])

    def get_conversation_runtime_session_contract_hash(
        self,
        conversation_id: str,
        route_name: str,
    ) -> str | None:
        projection = "(" + state_projection("conversation_runtime_sessions") + ")"
        with self._connect() as db:
            row = db.execute(
                f"""
                select contract_hash from {projection}
                where conversation_id=? and route_name=?
                """,
                (conversation_id, route_name),
            ).fetchone()
            return None if row is None else str(row["contract_hash"])

    def clear_conversation_runtime_sessions(self, conversation_id: str) -> int:
        """Drop every route's session for a conversation, so the next turn is new.

        Some work is a fresh look at external state rather than a continuing
        conversation: resuming there lets a turn answer from its own previous
        transcript instead of reading the source again. Every route slot is
        cleared so none can resume.
        """
        conversation_id = self._require_runtime_attempt_text(
            conversation_id, field="conversation_id"
        )
        with self._agent_run_write_transaction(None) as (db, _):
            cursor = db.execute(
                "delete from state where record_type='conversation_runtime_sessions' and conversation_id=?",
                (conversation_id,),
            )
            return cursor.rowcount

    def clear_conversation_runtime_session_if_matches(
        self,
        conversation_id: str,
        route_name: str,
        expected_session_id: str,
        *,
        additional_expected_session_ids: tuple[str, ...] = (),
    ) -> int:
        """Clear one Consumer route slot without deleting attempt/Audit evidence.

        Other route slots are never affected.
        """
        conversation_id = self._require_runtime_attempt_text(
            conversation_id, field="conversation_id"
        )
        route_name = self._require_runtime_attempt_text(route_name, field="route_name")
        expected_session_id = self._require_runtime_attempt_text(
            expected_session_id, field="expected_session_id"
        )
        expected_session_ids = (expected_session_id,) + tuple(
            self._require_runtime_attempt_text(value, field="expected_session_id")
            for value in additional_expected_session_ids
        )
        placeholders = ",".join("?" for _ in expected_session_ids)
        with self._agent_run_write_transaction(None) as (db, _):
            cursor = db.execute(
                f"""
                delete from state
                where record_type='conversation_runtime_sessions' and conversation_id=? and route_name=?
                  and session_id in ({placeholders})
                """,
                (conversation_id, route_name, *expected_session_ids),
            )
            return cursor.rowcount

    def open_runtime_route_pause(
        self,
        route_name: str,
        failure_code: str,
        retry_at: str | datetime,
    ) -> bool:
        route_name = self._require_runtime_attempt_text(route_name, field="route_name")
        failure_code = self._require_runtime_attempt_text(
            failure_code, field="failure_code"
        )
        if not failure_code.replace("_", "").isalnum():
            raise ValueError("failure_code must be a typed code")
        _, retry_at_text = _utc_store_time(retry_at)
        projection = "(" + state_projection("runtime_route_pauses") + ")"
        with self._agent_run_write_transaction(None) as (db, (_, now_text)):
            existing = db.execute(
                f"select retry_at from {projection} where route_name=?",
                (route_name,),
            ).fetchone()
            if existing is not None and str(existing["retry_at"]) > now_text:
                return False
            if existing is not None:
                db.execute(
                    "delete from state where record_type='runtime_route_pauses' and route_name=? and retry_at<=?",
                    (route_name, now_text),
                )
            inserted = insert_state(
                db, "runtime_route_pauses",
                {"route_name": route_name, "failure_code": failure_code,
                 "retry_at": retry_at_text, "opened_at": now_text,
                 "updated_at": now_text},
            )
            return inserted.rowcount == 1

    def active_runtime_route_pause(
        self,
        route_name: str,
        now: str | datetime | None = None,
    ) -> str | None:
        route_name = self._require_runtime_attempt_text(route_name, field="route_name")
        _, now_text = _utc_store_time(now)
        projection = "(" + state_projection("runtime_route_pauses") + ")"
        with self._agent_run_write_transaction(now) as (db, _):
            row = db.execute(
                f"""
                select failure_code, retry_at from {projection}
                where route_name=?
                """,
                (route_name,),
            ).fetchone()
            if row is None:
                return None
            if str(row["retry_at"]) <= now_text:
                db.execute(
                    "delete from state where record_type='runtime_route_pauses' and route_name=? and retry_at<=?",
                    (route_name, now_text),
                )
                return None
            return str(row["failure_code"])

    def close_runtime_route_pause(self, route_name: str) -> bool:
        route_name = self._require_runtime_attempt_text(route_name, field="route_name")
        with self._agent_run_write_transaction(None) as (db, _):
            cursor = db.execute(
                "delete from state where record_type='runtime_route_pauses' and route_name=?", (route_name,)
            )
            return cursor.rowcount == 1

    def rename_runtime_route(self, old_name: str, new_name: str) -> dict[str, int]:
        """Carry every persisted reference to a route over to its new name.

        One write transaction moves what decides later work: scheduled tasks'
        preferred route, the route named by every scheduled task run that can
        still be dispatched or rebuilt (pending and dispatched; skipped and
        failed runs are final), resumable conversation sessions, the route
        pause and the capability snapshot. A row already stored under the new
        name belongs to a route that no longer exists and is replaced.
        Attempt history (``agent_runtime_attempts.route_name``) keeps the name
        that was in use. Once committed, running it again moves nothing, so a
        caller may retry after a later step failed.
        """

        from app.scheduled_config_storage import intern_scheduled_config

        old_name = self._require_runtime_attempt_text(old_name, field="route_name")
        new_name = self._require_runtime_attempt_text(new_name, field="route_name")
        if old_name == new_name:
            raise ValueError("a route rename needs a different name")
        now_value, now_text = _utc_store_time(None)
        task_time = self._scheduled_task_time_text(now_value, field="rename time")
        old_key = self._runtime_capability_state_key(old_name)
        new_key = self._runtime_capability_state_key(new_name)
        with self._immediate_write_transaction() as db:
            tasks = rename_schedule_runtime(db, old_name, new_name, task_time)
            runs = 0
            for row in db.execute(
                f"""
                select runs.id, configs.snapshot_json from schedule_occurrences as runs
                 join ({config_projection('scheduled_task_config_versions')}) as configs on configs.id=runs.snapshot_id
                 where dispatch_status in ('pending', 'dispatched')
                   and json_valid(snapshot_json)
                   and json_extract(snapshot_json, '$.runtime_id')=?
                """,
                (old_name,),
            ).fetchall():
                snapshot = ScheduledTaskSnapshot.from_json(str(row["snapshot_json"]))
                db.execute(
                    "update schedule_occurrences set snapshot_id=? where id=?",
                    (
                        intern_scheduled_config(db, dataclass_replace(snapshot, runtime_id=new_name).to_json()),
                        int(row["id"]),
                    ),
                )
                runs += 1
            sessions = update_state_rows(
                db, "conversation_runtime_sessions", {"route_name": new_name},
                where_sql="route_name=?", parameters=(old_name,), replace=True,
            )
            pauses = update_state_rows(
                db, "runtime_route_pauses",
                {"route_name": new_name, "updated_at": now_text},
                where_sql="route_name=?", parameters=(old_name,), replace=True,
            )
            capability = db.execute(
                f"select value from ({state_projection('service_state')}) where key=?",
                (old_key,),
            ).fetchone()
            snapshots = 0
            if capability is not None:
                payload = json.loads(str(capability["value"]))
                payload["snapshot"] = RuntimeCapabilitySnapshot.model_validate(
                    payload["snapshot"]
                ).model_copy(update={"route_name": new_name}).model_dump(mode="json")
                upsert_state(
                    db, "service_state",
                    {"key": new_key,
                     "value": json.dumps(payload, ensure_ascii=False, sort_keys=True)},
                    {"value": state_json_field("value"),
                     "updated_at": "json_quote(current_timestamp)"},
                    insert_json={"updated_at": "json_quote(current_timestamp)"},
                )
                db.execute(
                    "delete from state where record_type='service_state' and key=?",
                    (old_key,),
                )
                snapshots = 1
        return {
            "scheduled_tasks": tasks,
            "scheduled_task_runs": runs,
            "conversation_sessions": sessions,
            "route_pauses": pauses,
            "capability_snapshots": snapshots,
        }

    def acquire_codex_session_lock(self, conversation_id: str, owner: str) -> bool:
        if not conversation_id.strip():
            raise ValueError("missing conversation_id")
        if not owner.strip():
            raise ValueError("missing lock owner")
        def acquire() -> bool:
            with self._connect() as db:
                db.execute(
                    """
                    delete from state
                    where record_type='codex_session_locks' and conversation_id=?
                      and datetime(locked_at) <= datetime('now', ?)
                    """,
                    (
                        conversation_id,
                        f"-{CODEX_SESSION_LOCK_STALE_SECONDS} seconds",
                    ),
                )
                inserted = insert_state(
                    db, "codex_session_locks",
                    {"conversation_id": conversation_id, "owner": owner},
                    ignore=True,
                )
                if inserted.rowcount == 1:
                    return True
                row = db.execute(
                    f"select owner from ({state_projection('codex_session_locks')}) "
                    "where conversation_id=?",
                    (conversation_id,),
                ).fetchone()
                return row is not None and str(row["owner"]) == owner

        return self._retry_codex_session_lock_operation(acquire)

    def release_codex_session_lock(self, conversation_id: str, owner: str) -> bool:
        if not conversation_id.strip():
            raise ValueError("missing conversation_id")
        if not owner.strip():
            raise ValueError("missing lock owner")
        def release() -> bool:
            with self._connect() as db:
                cursor = db.execute(
                    """
                    delete from state
                    where record_type='codex_session_locks' and conversation_id=? and owner=?
                    """,
                    (conversation_id, owner),
                )
                if cursor.rowcount == 1:
                    return True
                row = db.execute(
                    f"select 1 from ({state_projection('codex_session_locks')}) where conversation_id=?",
                    (conversation_id,),
                ).fetchone()
                return row is None

        return self._retry_codex_session_lock_operation(release)

    def renew_codex_session_lock(
        self,
        conversation_id: str,
        owner: str,
        *,
        now: str | datetime | None = None,
    ) -> bool:
        if not conversation_id.strip():
            raise ValueError("missing conversation_id")
        if not owner.strip():
            raise ValueError("missing lock owner")
        now_value, now_text = _utc_store_time(now)
        stale_before = (
            now_value - timedelta(seconds=CODEX_SESSION_LOCK_STALE_SECONDS)
        ).strftime("%Y-%m-%d %H:%M:%S")
        def renew() -> bool:
            with self._connect() as db:
                db.execute("begin")
                changed = update_state_rows(
                    db, "codex_session_locks", {"locked_at": now_text},
                    where_sql="conversation_id=? and owner=? and locked_at>?",
                    parameters=(conversation_id, owner, stale_before),
                )
                return changed == 1

        return self._retry_codex_session_lock_operation(renew)

    @staticmethod
    def _retry_codex_session_lock_operation(operation: Callable[[], bool]) -> bool:
        for attempt in range(CODEX_SESSION_LOCK_RETRY_ATTEMPTS):
            try:
                return operation()
            except OSError as exc:
                if exc.errno != errno.EDEADLK or attempt + 1 == CODEX_SESSION_LOCK_RETRY_ATTEMPTS:
                    raise
                time.sleep(CODEX_SESSION_LOCK_RETRY_DELAY_SECONDS * (attempt + 1))
        raise AssertionError("unreachable codex session lock retry state")

    def codex_session_lock(self, conversation_id: str, owner: str) -> CodexSessionLock:
        return CodexSessionLock(self, conversation_id, owner)

    def update_reply_task_trigger(
        self, task_id: int, *, trigger_text: str, trigger_message_json: str
    ) -> int:
        from app import task_entity_storage

        with self._immediate_write_transaction() as db:
            task = task_entity_storage.get_task_with_inputs(db, task_id)
            if (
                task is None or task["kind"] != "reply"
                or task["status"] != "pending" or task["attempts"] != 0
                or task["current_input"] is None
            ):
                return 0
            self._refresh_reply_input_in_transaction(
                db, task, trigger_text, trigger_message_json
            )
            return 1

    @classmethod
    def _refresh_reply_input_in_transaction(
        cls,
        db: sqlite3.Connection,
        row: Mapping[str, object],
        trigger_text: str,
        trigger_message_json: str,
    ) -> int:
        from app import task_entity_storage

        snapshot = dict(row)
        current_input = row["current_input"]
        if not isinstance(current_input, Mapping):
            raise RuntimeError("reply task has no bound current input")
        snapshot.update(current_input)
        snapshot.update(
            trigger_text=trigger_text, trigger_message_json=trigger_message_json
        )
        digest = hashlib.sha256(
            json.dumps(
                [trigger_text, trigger_message_json],
                ensure_ascii=False,
                separators=(",", ":"),
            ).encode()
        ).hexdigest()
        new_input, _inserted = task_entity_storage.append_task_input(
            db, task_id=int(row["id"]), values={
                field: snapshot[field] for field in (
                    "channel", "conversation_id", "conversation_title", "single_chat",
                    "trigger_message_id", "trigger_create_time", "trigger_sender",
                    "trigger_text", "trigger_message_json", "oa_url",
                    "business_object_key",
                )
            } | {
                "input_revision_key": f"refresh:{row['input_version'] + 1}:{digest}",
                "input_provenance_json": cls._reply_input_provenance(
                    trigger_text, trigger_message_json,
                ),
                "input_compacted": 0,
            },
        )
        updated = task_entity_storage.bind_current_input(
            db, task_id=int(row["id"]), input_id=int(new_input["id"]),
            expected_input_version=int(row["input_version"]),
            input_version=int(row["input_version"]) + 1,
        )
        if updated is None:
            raise RuntimeError("reply task input refresh lost its owner")
        return int(new_input["id"])

    def update_pending_reply_task_trigger_for_message(
        self,
        conversation_id: str,
        trigger_message_id: str,
        *,
        trigger_text: str,
        trigger_message_json: str,
        channel: str = "dingtalk",
    ) -> int:
        from app import task_entity_storage

        with self._immediate_write_transaction() as db:
            rows = db.execute(
                "select tasks.id from tasks join task_inputs on task_inputs.id=tasks.current_input_id "
                "where tasks.kind='reply' and tasks.status='pending' and tasks.attempts=0 "
                "and task_inputs.channel=? and task_inputs.conversation_id=? "
                "and task_inputs.trigger_message_id=? order by tasks.id limit 1",
                (channel, conversation_id, trigger_message_id),
            ).fetchone()
            if rows is None:
                return 0
            task = task_entity_storage.get_task_with_inputs(db, int(rows["id"]))
            if task is None:
                return 0
            current_input = task["current_input"]
            if current_input is None or (
                current_input["trigger_text"] == trigger_text
                and current_input["trigger_message_json"] == trigger_message_json
            ):
                return 0
            self._refresh_reply_input_in_transaction(
                db, task, trigger_text, trigger_message_json
            )
            return 1

    def requeue_terminal_reply_task_for_revised_trigger(
        self,
        *,
        conversation_id: str,
        conversation_title: str,
        single_chat: bool,
        trigger_message_id: str,
        trigger_create_time: str,
        trigger_sender: str,
        trigger_text: str,
        trigger_message_json: str,
        channel: str = "dingtalk",
    ) -> bool:
        """Requeue one terminal provider object when its rendered input changed.

        Some providers update an existing interactive card without issuing a new
        message id. The original id remains the business identity, while the
        changed text is a new input version that needs a fresh Agent decision.
        Unchanged, active, or missing tasks remain untouched.
        """
        from app import task_entity_storage

        with self._immediate_write_transaction() as db:
            row = db.execute(
                "select tasks.id from tasks join task_inputs current_input "
                "on current_input.id=tasks.current_input_id and current_input.task_id=tasks.id "
                "where tasks.kind='reply' and current_input.channel=? "
                "and current_input.conversation_id=? and current_input.trigger_message_id=? "
                "order by tasks.id limit 1",
                (channel, conversation_id, trigger_message_id),
            ).fetchone()
            if row is None:
                return False
            task = task_entity_storage.get_task_with_inputs(db, int(row["id"]))
            current_input = None if task is None else task["current_input"]
            if (task is None or current_input is None
                    or task["status"] not in {"done", "failed"}):
                return False
            same_rendered_text = (
                json.loads(str(current_input["input_provenance_json"]))["trigger_text"]["sha256"]
                == hashlib.sha256(trigger_text.encode("utf-8")).hexdigest()
                if current_input["input_compacted"]
                else str(current_input["trigger_text"]) == trigger_text
            )
            if same_rendered_text:
                return False
            next_input_version = int(task["input_version"]) + 1
            revision_digest = hashlib.sha256(
                json.dumps(
                    {
                        "trigger_text": trigger_text,
                        "trigger_message_json": trigger_message_json,
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            input_revision_key = f"v{next_input_version}:{revision_digest}"
            new_input, inserted = task_entity_storage.append_task_input(
                db, task_id=int(task["id"]), values={
                    "channel": channel, "conversation_id": conversation_id,
                    "conversation_title": conversation_title,
                    "single_chat": int(single_chat),
                    "trigger_message_id": trigger_message_id,
                    "trigger_create_time": trigger_create_time,
                    "trigger_sender": trigger_sender, "trigger_text": trigger_text,
                    "trigger_message_json": trigger_message_json,
                    "oa_url": str(current_input["oa_url"] or ""),
                    "business_object_key": str(current_input["business_object_key"]),
                    "input_revision_key": input_revision_key,
                    "created_at": db.execute("select current_timestamp").fetchone()[0],
                    "input_provenance_json": "{}", "input_compacted": 0,
                },
            )
            if not inserted:
                raise RuntimeError("revised reply task input was not persisted")
            execution_generation = uuid4().hex
            parameters = dict(task["parameters"])
            parameters.update(force_new_decision=1, manual_rerun_attempt_id=0,
                              manual_rerun_revision_key="", recovery_code="")
            updated = task_entity_storage.update_task_cas(
                db, task_id=int(task["id"]),
                expected={"status": task["status"],
                          "execution_generation": task["execution_generation"]},
                changes={
                    "execution_generation": execution_generation, "status": "pending",
                    "attempts": 0, "claimed_input_version": next_input_version,
                    "claimed_input_id": int(new_input["id"]),
                    "current_input_id": int(new_input["id"]),
                    "input_version": next_input_version, "locked_at": None,
                    "available_at": "", "error": "",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                },
                parameters=parameters,
            )
            return updated is not None

    def replace_pending_single_chat_reply_task_trigger(
        self,
        *,
        conversation_id: str,
        trigger_message_id: str,
        trigger_create_time: str,
        trigger_sender: str,
        trigger_text: str,
        trigger_message_json: str,
        available_at: str = "",
        error: str = "",
        channel: str = "dingtalk",
    ) -> int:
        from app import task_entity_storage

        with self._immediate_write_transaction() as db:
            target_row = db.execute(
                "select tasks.id from tasks join task_inputs on task_inputs.id=tasks.current_input_id "
                "and task_inputs.task_id=tasks.id where tasks.kind='reply' and tasks.status='pending' "
                "and tasks.attempts=0 and task_inputs.channel=? and task_inputs.conversation_id=? "
                "and task_inputs.single_chat=1 and task_inputs.trigger_create_time<=? "
                "order by task_inputs.trigger_create_time desc,tasks.id desc limit 1",
                (channel, conversation_id, trigger_create_time),
            ).fetchone()
            if target_row is None:
                return 0
            target = task_entity_storage.get_task_with_inputs(db, int(target_row["id"]))
            if target is None or target["current_input"] is None:
                return 0
            current_input = target["current_input"]
            task_id = int(target["id"])
            current_generation = str(target["execution_generation"])
            unchanged = all(
                str(current_input[field]) == value
                for field, value in (
                    ("trigger_message_id", trigger_message_id),
                    ("trigger_create_time", trigger_create_time),
                    ("trigger_sender", trigger_sender),
                    ("trigger_text", trigger_text),
                    ("trigger_message_json", trigger_message_json),
                )
            ) and str(target["available_at"]) == available_at and str(target["error"]) == error
            if unchanged:
                return 0
            from app import run_entity_storage

            superseded_at = db.execute("select current_timestamp").fetchone()[0]
            running_runs = db.execute(
                "select id,status from runs where task_id=? and execution_generation=? and status='running'",
                (task_id, current_generation),
            ).fetchall()
            for run in running_runs:
                run_entity_storage.update_run_cas(
                    db, run_id=int(run["id"]), expected={"status": "running"},
                    changes={"status": "failed",
                             "structured_error_json": json.dumps(
                                 {"code": "superseded_by_new_generation", "retryable": False},
                                 separators=(",", ":")),
                             "lease_owner": "", "lease_expires_at": "",
                             "completed_at": superseded_at, "updated_at": superseded_at},
                )
            execution_generation = uuid4().hex
            now_text = db.execute("select current_timestamp").fetchone()[0]
            updated = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                expected={"status": "pending", "attempts": 0,
                          "execution_generation": current_generation,
                          "current_input_id": int(current_input["id"])},
                changes={"execution_generation": execution_generation,
                         "available_at": available_at, "error": error,
                         "updated_at": now_text},
            )
            if updated is None:
                return 0
            duplicate_rows = db.execute(
                "select tasks.id from tasks join task_inputs on task_inputs.id=tasks.current_input_id "
                "and task_inputs.task_id=tasks.id where tasks.kind='reply' and tasks.status='pending' "
                "and tasks.attempts=0 and task_inputs.channel=? and task_inputs.conversation_id=? "
                "and task_inputs.single_chat=1 and tasks.id<>?",
                (channel, conversation_id, task_id),
            ).fetchall()
            duplicate_ids = [int(row["id"]) for row in duplicate_rows]
            for duplicate_id in duplicate_ids:
                # Retained TaskInput identities and all keys are reassigned before
                # the duplicate Task is removed; native FKs reject unrepresentable
                # references and the enclosing transaction rolls back.
                db.execute("update task_inputs set task_id=? where task_id=?", (task_id, duplicate_id))
                for key in task_entity_storage.list_task_business_keys(db, duplicate_id):
                    exists = db.execute(
                        "select 1 from task_business_keys where task_id=? and business_key=?",
                        (task_id, key["business_key"]),
                    ).fetchone()
                    if exists:
                        db.execute("delete from task_business_keys where id=?", (key["id"],))
                    else:
                        db.execute("update task_business_keys set task_id=? where id=?",
                                   (task_id, key["id"]))
            target_key = str(current_input["business_object_key"] or "").strip()
            if not target_key:
                target_key = reply_business_object_key(
                    channel=channel,
                    conversation_id=conversation_id,
                    trigger_message_id=str(current_input["trigger_message_id"]),
                )
            now_text = db.execute("select current_timestamp").fetchone()[0]
            for business_key in (
                target_key,
                reply_business_object_key(
                    channel=channel, conversation_id=conversation_id,
                    trigger_message_id=trigger_message_id,
                ),
            ):
                if db.execute(
                    "select 1 from task_business_keys where task_id=? and business_key=?",
                    (task_id, business_key),
                ).fetchone() is None:
                    task_entity_storage.associate_business_key(
                        db, task_id=task_id, business_key=business_key,
                        created_at=now_text, updated_at=now_text,
                    )
            merged_input, inserted = task_entity_storage.append_task_input(
                db, task_id=task_id, values={
                    "channel": channel, "conversation_id": conversation_id,
                    "conversation_title": current_input["conversation_title"],
                    "single_chat": 1, "trigger_message_id": trigger_message_id,
                    "trigger_create_time": trigger_create_time,
                    "trigger_sender": trigger_sender, "trigger_text": trigger_text,
                    "trigger_message_json": trigger_message_json,
                    "oa_url": current_input["oa_url"], "business_object_key": target_key,
                    "input_revision_key": f"merge:{execution_generation}",
                    "created_at": now_text, "input_provenance_json": "{}",
                    "input_compacted": 0,
                },
            )
            if not inserted:
                raise RuntimeError("merged reply input was not persisted")
            advanced = task_entity_storage.bind_current_input(
                db, task_id=task_id, input_id=int(merged_input["id"]),
                expected_input_version=int(target["input_version"]),
                input_version=int(target["input_version"]) + 1,
            )
            if advanced is None:
                raise RuntimeError("merged reply input lost its Task owner")
            # Preserve the explicit source runtime count assignment after moving
            # duplicate inputs and appending this merge snapshot.
            new_version = int(db.execute(
                "select count(*) from task_inputs where task_id=?", (task_id,)
            ).fetchone()[0])
            db.execute("update tasks set input_version=? where id=?", (new_version, task_id))
            for duplicate_id in duplicate_ids:
                db.execute("delete from tasks where id=? and kind='reply'", (duplicate_id,))
            return 1

    def reset_codex_oauth_sessions(self) -> int:
        with self._connect() as db:
            cursor = db.execute(
                "delete from state where record_type='conversation_runtime_sessions' and route_name='codex_oauth'"
            )
            return cursor.rowcount

    def list_codex_conversations(self) -> list[ConversationSessionRecord]:
        conversations = "(" + state_projection("conversations") + ")"
        sessions = "(" + state_projection("conversation_runtime_sessions") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"""select c.conversation_id, c.title, c.single_chat, s.session_id
                from {conversations} c join {sessions} s
                  on s.conversation_id=c.conversation_id and s.route_name='codex_oauth'
                order by c.title, c.conversation_id"""
            ).fetchall()
            return [ConversationSessionRecord(
                conversation_id=row["conversation_id"], title=row["title"],
                single_chat=bool(row["single_chat"]), session_id=row["session_id"],
            ) for row in rows]

    def list_recent_single_chat_conversations(
        self,
        since_utc: str,
        limit: int,
    ) -> list[ConversationRecord]:
        seen_projection = "(" + state_projection("seen_messages") + ")"
        conversation_projection = "(" + state_projection("conversations") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"""
                with recent_activity as (
                    select conversation_id, max(activity_at) as latest_activity_at
                    from (
                        select conversation_id, seen_at as activity_at
                        from {seen_projection}
                        union all
                        select conversation_id, created_at as activity_at
                        from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks
                        where single_chat=1 and input_compacted=0
                    )
                    group by conversation_id
                )
                select
                    c.conversation_id,
                    c.title,
                    c.single_chat,
                    coalesce((
                        select json_extract(t.trigger_message_json, '$.sender_user_id')
                        from ({NATIVE_REPLY_TASK_CURRENT_SQL}) t
                        where t.conversation_id=c.conversation_id
                          and t.single_chat=1
                          and t.input_compacted=0
                        order by t.id desc
                        limit 1
                    ), '') as direct_user_id,
                    coalesce((
                        select json_extract(
                            t.trigger_message_json,
                            '$.sender_open_dingtalk_id'
                        )
                        from ({NATIVE_REPLY_TASK_CURRENT_SQL}) t
                        where t.conversation_id=c.conversation_id
                          and t.single_chat=1
                          and t.input_compacted=0
                        order by t.id desc
                        limit 1
                    ), '') as direct_open_dingtalk_id,
                    a.latest_activity_at
                from {conversation_projection} c
                join recent_activity a on a.conversation_id=c.conversation_id
                where c.single_chat=1 and a.latest_activity_at >= ?
                order by a.latest_activity_at desc
                limit ?
                """,
                (since_utc, limit),
            ).fetchall()
            return [
                ConversationRecord(
                    conversation_id=row["conversation_id"],
                    title=row["title"],
                    single_chat=bool(row["single_chat"]),
                    direct_user_id=row["direct_user_id"],
                    direct_open_dingtalk_id=row["direct_open_dingtalk_id"],
                )
                for row in rows
            ]

    def get_conversation(self, conversation_id: str) -> ConversationRecord | None:
        projection = "(" + state_projection("conversations") + ")"
        with self._connect() as db:
            row = db.execute(
                f"""
                select conversation_id, title, single_chat
                from {projection}
                where conversation_id=?
                """,
                (conversation_id,),
            ).fetchone()
            if row is None:
                return None
            return ConversationRecord(
                conversation_id=row["conversation_id"],
                title=row["title"],
                single_chat=bool(row["single_chat"]),
            )

