    def has_seen(self, message_id: str) -> bool:
        projection = "(" + state_projection("seen_messages") + ")"
        with self._connect() as db:
            row = db.execute(
                f"select 1 from {projection} where message_id=?",
                (message_id,),
            ).fetchone()
            return row is not None

    def mark_seen(self, message_id: str, conversation_id: str) -> bool:
        with self._connect() as db:
            db.execute("begin")
            result = insert_state(
                db, "seen_messages",
                {"message_id": message_id, "conversation_id": conversation_id},
                ignore=True,
            )
            return result.rowcount == 1

    def record_sent_reply(
        self,
        conversation_id: str,
        trigger_message_id: str,
        reply_text: str,
        *,
        send_result_json: str = "",
        recall_key: str = "",
        feedback_token: str = "",
    ) -> None:
        if not feedback_token:
            feedback_context = extract_configured_feedback_link_context(
                reply_text,
                vercel_base_url=feedback_spike_vercel_base_url(),
            )
            feedback_token = (
                feedback_context.feedback_token
                if feedback_context is not None
                else ""
            )
        with self._connect() as db:
            db.execute("begin immediate")
            shared_action_lifecycle.record_sent_action(
                db, operation=None, target_json=None,
                provider_json=send_result_json or None,
                result_digest=None, external_action_key="",
                business_object_key=None, action_identity=None,
                channel="dingtalk", conversation_id=conversation_id,
                trigger_message_id=trigger_message_id, reply_text=reply_text,
                feedback_token=feedback_token, recall_key=recall_key,
                agent_run_id=None, task_id=None,
            )

    def record_completed_agent_message_delivery(
        self,
        *,
        agent_run_id: int,
        external_action_key: str,
        business_object_key: str,
        action_identity: str,
        operation: str,
        target_identifiers: dict[str, object],
        conversation_id: str,
        trigger_message_id: str,
        reply_text: str,
        provider_result: dict[str, object],
    ) -> SentReply:
        """Persist one completed provider action and its History projection."""
        values = tuple(
            value.strip()
            for value in (
                external_action_key,
                business_object_key,
                action_identity,
                operation,
                conversation_id,
                trigger_message_id,
                reply_text,
            )
        )
        if any(not value for value in values):
            raise ValueError("completed message delivery identity is incomplete")
        target_json = _json_object_text(
            target_identifiers, field="target_identifiers"
        )
        provider_json = _json_object_text(provider_result, field="provider_result")
        result_digest = _canonical_json_sha256(provider_result)
        feedback_context = extract_configured_feedback_link_context(
            reply_text,
            vercel_base_url=feedback_spike_vercel_base_url(),
        )
        feedback_token = (
            feedback_context.feedback_token if feedback_context is not None else ""
        )
        with self._immediate_write_transaction() as db:
            # Audit is the only role allowed to execute a delivery, and the
            # normal path always arrives here with an Audit run.  A Consumer
            # turn with plain shell access can still reach a provider and be
            # accepted, though, and that effect is just as real: leaving it out
            # of the ledger is precisely what lets the next attempt send the
            # same message a second time.  This ledger records what a provider
            # did, so it accepts whichever completed run on the task produced
            # the receipt.  Who is allowed to deliver is enforced before the
            # call, not by declining to remember a delivery that happened.
            run = db.execute(
                f"select agent_runs.reply_task_id, reply_tasks.business_object_key from ({NATIVE_AGENT_RUN_SQL}) as agent_runs join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks on reply_tasks.id=agent_runs.reply_task_id where agent_runs.id=? and agent_runs.role in ('audit', 'consumer') and agent_runs.status='completed'",
                (agent_run_id,),
            ).fetchone()
            if run is None or run["business_object_key"] != business_object_key:
                raise ValueError("completed message delivery run identity mismatch")
            common = shared_action_lifecycle.record_sent_action(
                db, operation=operation, target_json=target_json,
                provider_json=provider_json, result_digest=result_digest,
                external_action_key=external_action_key,
                business_object_key=business_object_key,
                action_identity=action_identity, channel="dingtalk",
                conversation_id=conversation_id,
                trigger_message_id=trigger_message_id, reply_text=reply_text,
                feedback_token=feedback_token, agent_run_id=agent_run_id,
                task_id=int(run["reply_task_id"]),
            )
            sent = db.execute(
                f"select * from ({SENT_REPLY_SQL}) where id=?",
                (common["action"]["id"],),
            ).fetchone()
            if sent is None or sent["reply_text"] != reply_text:
                raise ValueError("conflicting message delivery projection")
            return SentReply.model_validate(dict(sent))

    def resolve_reconciled_failed_reply_task(
        self,
        task_id: int,
        *,
        external_action_key: str,
    ) -> bool:
        """Close a failed task whose delivery has since been recorded.

        A task can fail after its message was already delivered: the effect
        escaped the ledger, so nothing downstream knew to stop, and the run
        that produced it ended in an error anyway.  Once that delivery is
        recorded, rerunning the task would send the message a second time, so
        ``done`` is the only terminal state that matches what the recipient
        actually received.  The row only moves when the ledger really holds
        that delivery for this task's business object, which is what keeps this
        from becoming a way to close a task nobody ever answered.
        """
        key = external_action_key.strip()
        if not key:
            raise ValueError("external_action_key must be non-empty")
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select business_object_key from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks "
                "where id=? and status='failed'",
                (task_id,),
            ).fetchone()
            if task is None:
                return False
            business_object_key = str(task["business_object_key"] or "").strip()
            if not business_object_key:
                raise ValueError("reconciled task has no business object key")
            recorded = db.execute(
                f"select 1 from ({EXTERNAL_ACTION_RESULT_SQL}) "
                "where external_action_key=? and business_object_key=? "
                "and coalesce(json_extract(provider_result_json, '$.verification.state'), 'sent')='sent'",
                (key, business_object_key),
            ).fetchone()
            projected = db.execute(
                f"select 1 from ({SENT_REPLY_SQL}) where external_action_key=? and external_action_key<>''",
                (key,),
            ).fetchone()
            if recorded is None or projected is None:
                raise ValueError("reconciled delivery is not recorded for this task")
            from app import task_entity_storage
            updated = task_entity_storage.update_task_cas(
                db, task_id=task_id, expected={"status": "failed"},
                changes={"status": "done", "error": "", "available_at": "",
                         "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if updated is not None:
                self._compact_settled_reply_task_input(db, task_id)
            return updated is not None

    def reconcile_failed_agent_message_delivery(
        self,
        *,
        send_run_id: int,
        readback_run_id: int,
        external_action_key: str,
        readback_message_id: str,
    ) -> SentReply:
        """Record a delivered shell send only when persisted send/readback agree."""
        from app.agent_effect_guard import provider_receipts
        from app.outbound_text_authority import (
            delivered_shell_send_commands,
            provider_send_texts,
            unprepared_send_texts,
        )

        send_run = self.get_agent_run(send_run_id)
        readback_run = self.get_agent_run(readback_run_id)
        if send_run is None or readback_run is None:
            raise ValueError("send and readback runs must exist")
        if (
            send_run.reply_task_id != readback_run.reply_task_id
            or send_run.execution_generation != readback_run.execution_generation
            or send_run.status != "failed"
            or readback_run.status != "failed"
        ):
            raise ValueError("reconciliation runs do not identify one failed generation")
        if not delivered_shell_send_commands(send_run.tool_events):
            raise ValueError("send run has no provider-accepted shell send")
        receipts = provider_receipts(send_run.tool_events)
        if not receipts:
            raise ValueError("send run has no provider receipt")
        if send_run.parent_agent_run_id is None:
            raise ValueError("send run has no accepted proposal")
        consumer = self.get_agent_run(send_run.parent_agent_run_id)
        if consumer is None or consumer.status != "completed":
            raise ValueError("accepted consumer proposal is unavailable")
        adopted = self.adopted_candidate_for_consumer_run(consumer.id)
        try:
            proposal = json.loads(adopted["candidate_json"] if adopted else "")["proposal"]
            actions = proposal["actions"]
        except (json.JSONDecodeError, KeyError, TypeError):
            raise ValueError("accepted consumer proposal is invalid") from None
        sent_texts = {text.strip() for text in provider_send_texts(send_run.tool_events)}
        matches: list[tuple[dict[str, object], list[str]]] = []
        for action in actions if isinstance(actions, list) else []:
            if not isinstance(action, dict):
                continue
            payload = action.get("payload")
            content = None
            if isinstance(payload, dict):
                content = payload.get("content") or payload.get("text")
            if not isinstance(content, str) or not content.strip():
                continue
            prepared_body = message_body_without_feedback_callbacks(content.strip())
            matching_sent = [
                sent_text
                for sent_text in sent_texts
                if not unprepared_send_texts(
                    [message_body_without_feedback_callbacks(sent_text)],
                    [prepared_body],
                )
            ]
            if matching_sent:
                matches.append((action, matching_sent))
        if len(matches) != 1:
            raise ValueError("provider send does not match exactly one proposed action")
        action, matching_sent_texts = matches[0]
        action_identity = str(action.get("action_identity") or "").strip()
        operation = str(action.get("operation") or "").strip()
        target = action.get("target")
        if not action_identity or not operation or not isinstance(target, dict):
            raise ValueError("proposed action identity is incomplete")
        action_key = external_action_key.strip()
        message_id = readback_message_id.strip()
        if not action_key or not message_id:
            raise ValueError("external action key and readback message id are required")
        readback_evidence = json.dumps(
            readback_run.tool_events, ensure_ascii=False, separators=(",", ":")
        )
        readback_texts: list[str] = []

        def collect_message_texts(value: object) -> None:
            if isinstance(value, dict):
                if str(value.get("messageId") or "") == message_id:
                    text = value.get("text")
                    if isinstance(text, str) and text.strip():
                        readback_texts.append(text)
                for child in value.values():
                    collect_message_texts(child)
            elif isinstance(value, list):
                for child in value:
                    collect_message_texts(child)

        for event in readback_run.tool_events:
            collect_message_texts(event)
            item = event.get("item") if isinstance(event, dict) else None
            output = item.get("aggregated_output") if isinstance(item, dict) else None
            if not isinstance(output, str) or not output.strip():
                continue
            try:
                collect_message_texts(json.loads(output))
            except json.JSONDecodeError:
                continue
        unique_readback_texts = set(readback_texts)
        exact_readback_matches = {
            sent_text
            for sent_text in matching_sent_texts
            if not unprepared_send_texts([sent_text], unique_readback_texts)
        }
        if action_key not in readback_evidence or len(unique_readback_texts) != 1:
            raise ValueError("readback run does not contain the reconciled delivery")
        if message_id in receipts:
            reply_text = unique_readback_texts.pop()
        elif len(exact_readback_matches) == 1:
            reply_text = exact_readback_matches.pop()
        else:
            raise ValueError("readback run does not contain the reconciled delivery")
        provider_result = {
            "reconciled_from_failed_run": True,
            "provider_receipt": receipts[0],
            "readback_message_id": message_id,
        }
        provider_json = _json_object_text(provider_result, field="provider_result")
        target_json = _json_object_text(target, field="target_identifiers")
        feedback_context = extract_configured_feedback_link_context(
            reply_text,
            vercel_base_url=feedback_spike_vercel_base_url(),
        )
        feedback_token = feedback_context.feedback_token if feedback_context else ""
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select * from ({REPLY_TASK_CURRENT_SQL}) as reply_tasks where id=? and status='failed'",
                (send_run.reply_task_id,),
            ).fetchone()
            if (
                task is None
                or task["execution_generation"] != send_run.execution_generation
            ):
                raise AgentRunLeaseLostError(
                    f"reply task superseded: {send_run.reply_task_id}"
                )
            business_object_key = str(task["business_object_key"] or "").strip()
            if not business_object_key:
                raise ValueError("reconciled task has no business object key")
            common = shared_action_lifecycle.record_sent_action(
                db, operation=operation, target_json=target_json,
                provider_json=provider_json,
                result_digest=_canonical_json_sha256(provider_result),
                external_action_key=action_key,
                business_object_key=business_object_key,
                action_identity=action_identity, channel=str(task["channel"]),
                conversation_id=task["conversation_id"],
                trigger_message_id=task["trigger_message_id"],
                reply_text=reply_text, feedback_token=feedback_token,
                agent_run_id=send_run_id, task_id=send_run.reply_task_id,
            )
            from app.action_entity_storage import add_action_observer
            observed_at = db.execute("select current_timestamp").fetchone()[0]
            add_action_observer(
                db, common["action"]["id"], agent_run_id=readback_run_id,
                task_id=send_run.reply_task_id, created_at=observed_at,
            )
            sent = db.execute(
                f"select * from ({SENT_REPLY_SQL}) where id=?",
                (common["action"]["id"],),
            ).fetchone()
            if sent is None or sent["reply_text"] != reply_text:
                raise ValueError("conflicting reconciled message delivery")
            latest = db.execute(
                f"select max(id) from ({REPLY_ATTEMPT_COMMON_SQL}) "
                "where channel=? and conversation_id=? and trigger_message_id=?",
                (task["channel"], task["conversation_id"], task["trigger_message_id"]),
            ).fetchone()[0]
            if latest is not None:
                update_action(db, "reply_attempts", latest, {
                    "send_status": "completed", "send_error": "",
                    "final_reply_text": reply_text,
                    "human_decision_options_json": "[]",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                })
            from app import task_entity_storage
            current_task = self._native_current_reply_task(db, send_run.reply_task_id)
            if (current_task is None
                    or current_task["execution_generation"] != send_run.execution_generation):
                raise AgentRunLeaseLostError(
                    f"reply task superseded: {send_run.reply_task_id}"
                )
            updated_task = task_entity_storage.update_task_cas(
                db, task_id=send_run.reply_task_id,
                expected={"status": "failed",
                          "execution_generation": send_run.execution_generation},
                changes={"status": "done", "error": "", "available_at": "",
                         "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if updated_task is None:
                raise AgentRunLeaseLostError(
                    f"reply task superseded: {send_run.reply_task_id}"
                )
            self._compact_settled_reply_task_input(db, send_run.reply_task_id)
            return SentReply.model_validate(dict(sent))

    def reconcile_failed_audit_with_verified_delivery(self, task_id: int, run_id: int) -> bool:
        """Recover result-format failure after every proposed effect was accepted."""
        from app.dingtalk_send_evidence import DingTalkSendEvidenceDriver
        from app.business_identity import external_action_key

        task = self.get_reply_task(task_id)
        run = self.get_agent_run(run_id)
        if (
            task is None or run is None or task.status != "failed"
            or task.error != "codex_result_invalid"
            or run.role is not AgentRole.AUDIT or run.status != "failed"
            or run.reply_task_id != task_id
            or run.execution_generation != task.execution_generation
            or not run.operation_id or run.parent_agent_run_id is None
        ):
            raise ValueError("not a failed result-format Audit on the current task")
        # Metadata discovery and evidence classification must not hold a writer lock.
        if not DingTalkSendEvidenceDriver(self).audit_run_has_execution_evidence(
            task, audit_run_id=run_id,
        ):
            raise ValueError("not all proposed effects have execution evidence")
        consumer = self.get_agent_run(run.parent_agent_run_id) if run.parent_agent_run_id else None
        if consumer is None or consumer.role is not AgentRole.CONSUMER or consumer.status != "completed":
            raise ValueError("accepted Consumer proposal is unavailable")
        adopted = self.adopted_candidate_for_consumer_run(consumer.id)
        if adopted is None:
            raise ValueError("accepted Consumer proposal is unavailable")
        actions = json.loads(adopted["candidate_json"])["proposal"]["actions"]
        expected = {
            external_action_key(
                business_object_key=task.business_object_key,
                action_identity=action["action_identity"], operation=action["operation"],
                target_identifiers=action["target"],
            ): action for action in actions
        }
        with self._immediate_write_transaction() as db:
            receipt = db.execute(
                f"""
                select replies.* from ({SENT_REPLY_SQL}) replies
                join ({AGENT_RUN_SQL}) sender on sender.id=replies.agent_run_id
                where sender.reply_task_id=? and sender.execution_generation=?
                  and sender.role='audit' and sender.id<=?
                  and sender.parent_agent_run_id is ?
                  and sender.proposal_revision=? and sender.operation_id=?
                  and trim(replies.external_action_key)<>''
                  and json_valid(replies.send_result_json)
                  and json_extract(replies.send_result_json, '$.verification.state')='sent'
                """,
                (task_id, run.execution_generation, run_id, run.parent_agent_run_id,
                 run.proposal_revision, run.operation_id),
            ).fetchall()
            matched = [row for row in receipt if row["external_action_key"] in expected]
            if not matched:
                raise ValueError("current reviewed operation has no verified send receipt")
            for row in matched:
                action = expected[row["external_action_key"]]
                target_json = _json_object_text(action["target"], field="target_identifiers")
                shared_action_lifecycle.adopt_verified_sent_action(
                    db, external_action_key=row["external_action_key"],
                    business_object_key=task.business_object_key,
                    action_identity=action["action_identity"],
                    operation=action["operation"], target_json=target_json,
                    provider_json=row["send_result_json"],
                    result_digest=_canonical_json_sha256(json.loads(row["send_result_json"])),
                    agent_run_id=row["agent_run_id"], observed_at=row["sent_at"],
                )
            latest = db.execute(
                f"select max(id) from ({NATIVE_AGENT_RUN_SQL}) where reply_task_id=? "
                "and execution_generation=?",
                (task_id, run.execution_generation),
            ).fetchone()[0]
            from app import task_entity_storage
            updated = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                expected={"status": "failed", "error": "codex_result_invalid",
                          "execution_generation": run.execution_generation},
                changes={"status": "done", "error": "", "available_at": "",
                         "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            ) if latest == run_id else None
            if updated is None:
                raise AgentRunLeaseLostError(f"failed Audit superseded: {run_id}")
            self._compact_settled_reply_task_input(db, task_id)
            return True

    def reconcile_failed_reply_tasks_with_recorded_deliveries(self) -> int:
        """Close failed tasks whose completed provider action is in the ledger.

        A process can fail after a provider has accepted the action.  The
        external-action result and its History projection are both required to
        prove that outcome.  Reprocessing such a task would duplicate a real
        message, so the task's current lifecycle state is ``done`` even when a
        subsequent Audit run failed to serialize its own result.
        """
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            from app.action_storage import NATIVE_EXTERNAL_ACTION_RESULT_SQL
            candidates = db.execute(
                f"""select tasks.id,tasks.status,tasks.execution_generation
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) tasks
                where tasks.status in ('failed','needs_human') and exists(
                  select 1 from ({NATIVE_EXTERNAL_ACTION_RESULT_SQL}) actions
                  join ({SENT_REPLY_SQL}) replies
                    on replies.external_action_key=actions.external_action_key
                  where actions.business_object_key=tasks.business_object_key
                    and coalesce(json_extract(actions.provider_result_json,
                      '$.verification.state'),'sent')='sent')
                order by tasks.id"""
            ).fetchall()
            settled = 0
            for row in candidates:
                changed = task_entity_storage.update_task_cas(
                    db, task_id=int(row["id"]),
                    expected={"status": row["status"],
                              "execution_generation": row["execution_generation"]},
                    changes={"status": "done", "error": "", "available_at": "",
                             "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if changed is not None:
                    self._compact_settled_reply_task_input(db, int(row["id"]))
                    settled += 1
            return settled

    @staticmethod
    def _email_unsubscribe_outcomes_by_task_status() -> dict[str, list[str]]:
        """Derive task projections from the unsubscribe outcome contract."""
        from app.email_unsubscribe import (
            UnsubscribeOutcome,
            disposition_for_unsubscribe_outcome,
        )

        outcomes_by_status: dict[str, list[str]] = {"done": [], "skipped": []}
        for outcome in UnsubscribeOutcome:
            status = disposition_for_unsubscribe_outcome(outcome).task_status
            if status in outcomes_by_status:
                outcomes_by_status[status].append(outcome.value)
        return outcomes_by_status

    @staticmethod
    def _email_unsubscribe_receipts_table_exists(db: sqlite3.Connection) -> bool:
        """Whether the independently initialized Email receipt ledger exists."""
        return current_email_actions_available(db)

    def reconcile_failed_email_unsubscribe_tasks_with_terminal_receipts(self) -> int:
        """Project durable email unsubscribe receipts onto their failed tasks.

        The direct unsubscribe operation persists one terminal receipt before
        its worker finalizes the reply task.  A worker interruption after that
        write used to leave the task failed even though the receipt already
        says the operation completed or was safely skipped.  The receipt is
        keyed by the immutable email action identity, which is also the task's
        trigger id, so this reconciliation neither guesses nor replays an
        external operation.
        """
        outcomes_by_status = self._email_unsubscribe_outcomes_by_task_status()
        done_outcomes = outcomes_by_status["done"]
        skipped_outcomes = outcomes_by_status["skipped"]
        terminal_outcomes = [*done_outcomes, *skipped_outcomes]
        if not terminal_outcomes:
            return 0
        terminal_placeholders = ", ".join("?" for _ in terminal_outcomes)
        with self._immediate_write_transaction() as db:
            if not self._email_unsubscribe_receipts_table_exists(db):
                return 0
            compact_rows = db.execute(
                f"""
                select current_tasks.id,current_tasks.status,current_tasks.execution_generation,
                       current_receipts.outcome
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_tasks
                    join ({email_action_projection('email_unsubscribe_receipts')}) as current_receipts
                      on current_receipts.action_identity=current_tasks.trigger_message_id
                where current_tasks.channel='email'
                  and current_tasks.status='failed'
                  and current_receipts.outcome in ({terminal_placeholders})
                """,
                terminal_outcomes,
            ).fetchall()
            from app import task_entity_storage
            compact_ids = []
            for row in compact_rows:
                task_id = int(row["id"])
                status = "done" if row["outcome"] in done_outcomes else "skipped"
                updated = task_entity_storage.update_task_cas(
                    db, task_id=task_id,
                    expected={"status": row["status"],
                              "execution_generation": row["execution_generation"]},
                    changes={"status": status, "error": "", "available_at": "",
                             "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if updated is not None:
                    compact_ids.append(task_id)
                    self._compact_settled_reply_task_input(db, task_id)
            return len(compact_ids)

    def resolve_failed_reply_attempt_already_settled(
        self,
        attempt_id: int,
        *,
        resolution: str,
    ) -> bool:
        """Record that a failed attempt's work was settled outside the service.

        `errors` has kept `resolved_at`/`resolution` for a long time, so a
        service error that later recovered stops reading as active. A failed
        `reply_attempts` row had no such pair, and the only way it could stop
        reading as failed was for a *later attempt on the same trigger* to
        reach a terminal state. When the principal simply does the work
        himself in DingTalk, no later attempt on that trigger ever exists, so
        the row reads as an open failure forever even though nothing is open.

        Nothing is rewritten: `send_status` and `send_error` are untouched and
        the history detail keeps the original error with the resolution
        appended, exactly as a resolved `errors` row does. The live evidence
        is required, because this is the one closure that is not derived from
        anything the service itself did.
        """

        evidence = resolution.strip()
        if not evidence:
            raise ValueError("resolution evidence must be non-empty")
        with self._immediate_write_transaction() as db:
            row = db.execute(
                "select send_status, coalesce(resolved_at, '') as resolved_at "
                f"from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?",
                (attempt_id,),
            ).fetchone()
            if row is None or row["send_status"] != "failed" or row["resolved_at"]:
                return False
            update_action(db, "reply_attempts", attempt_id, {
                "resolved_at": db.execute("select current_timestamp").fetchone()[0],
                "resolution": evidence,
            })
            return True

    def resolve_completed_oa_needs_human_attempt(
        self,
        attempt_id: int,
        *,
        process_instance_id: str,
        process_result: str,
    ) -> bool:
        """Close an OA task only after terminal state or confirmed return.

        The OA scanner creates a terminal ``needs_human`` attempt when a
        decision really requires Derek. Derek may then complete that approval
        directly in DingTalk, or explicitly return that exact task while the
        wider process continues. Merely disappearing from Derek's pending list
        does not prove either outcome. A later projection repair can also turn an
        invalid technical ``needs_human`` Attempt into ``failed`` while its
        owning task still has the old status. Once the external process is
        terminal or that exact OA task has a verified return receipt, there is
        no action left for that attempt, so the local attempt is ``skipped``
        and the owning task is ``done``.
        """

        process_id = process_instance_id.strip()
        if not process_id:
            raise ValueError("process_instance_id must be non-empty")
        result = process_result.strip() or "completed"
        resolution = (
            "Live DingTalk OA process has a verified return receipt for this task."
            if result == "OA_RETURNED"
            else f"Live DingTalk OA task reached terminal state {result}."
        )
        with self._immediate_write_transaction() as db:
            attempt = db.execute(
                "select channel, conversation_id, trigger_message_id "
                f"from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?",
                (attempt_id,),
            ).fetchone()
            if attempt is None:
                return False
            now = db.execute("select current_timestamp").fetchone()[0]
            cursor = update_action(db, "reply_attempts", attempt_id, {
                "send_status": "skipped", "send_error": "",
                "resolved_at": now, "resolution": resolution,
                "updated_at": now,
            }, where_sql="send_status in ('needs_human', 'failed') "
                         "and oa_process_instance_id=? "
                         "and trim(coalesce(resolved_at, ''))=''",
               parameters=(process_id,))
            if cursor.rowcount != 1:
                return False
            task = db.execute(
                f"select id,status,execution_generation from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks where channel=? and conversation_id=? "
                "and trigger_message_id=?",
                (attempt["channel"], attempt["conversation_id"], attempt["trigger_message_id"]),
            ).fetchone()
            if task is not None:
                from app import task_entity_storage
                updated = task_entity_storage.update_task_cas(
                    db, task_id=int(task["id"]),
                    expected={"status": task["status"],
                              "execution_generation": task["execution_generation"]},
                    changes={"status": "done", "error": "", "available_at": "",
                             "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                ) if task["status"] in {"needs_human", "failed"} else None
                if updated is not None:
                    self._compact_settled_reply_task_input(db, int(task["id"]))
            return True

    def close_unresolved_reply_task_already_settled(
        self,
        task_id: int,
        *,
        expected_execution_generation: str,
        settled_evidence: str,
    ) -> bool:
        """Close an unresolved task whose business object reached its end state.

        A task can remain failed or needs-human after the work was already
        done by the principal directly or by an earlier run. Rerunning cannot
        help and can repeat an irreversible action.

        This is the one closure not derived from anything the service itself
        did, so the live evidence that settles it is required and is written
        beside the task rather than left in an operator's console.
        """
        evidence = settled_evidence.strip()
        if not evidence:
            raise ValueError("settled evidence must be non-empty")
        generation = expected_execution_generation.strip()
        if not generation:
            raise ValueError("execution generation is required")
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select conversation_id, trigger_message_id from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks "
                "where id=? and status in ('failed', 'needs_human') and execution_generation=?",
                (task_id, generation),
            ).fetchone()
            if task is None:
                return False
            cursor = db.execute(
                "update tasks set status='done',error='',available_at='',locked_at=null,"
                "updated_at=current_timestamp where id=? and kind='reply' "
                "and status in ('failed','needs_human') and execution_generation=?",
                (task_id, generation),
            )
            if cursor.rowcount == 1:
                insert_error_action(db, {
                    "conversation_id": task["conversation_id"],
                    "message_id": task["trigger_message_id"],
                    "kind": "reply_task_already_settled", "detail": evidence,
                    "resolution": evidence,
                }, resolved_at_now=True)
                self._compact_settled_reply_task_input(db, task_id)
            return cursor.rowcount == 1

    def settle_failed_wechat_task_from_delivery(
        self,
        task_id: int,
        *,
        expected_execution_generation: str,
        delivery_id: int,
        task_status: str,
        evidence: dict[str, Any],
        successor_task_id: int = 0,
    ) -> bool:
        """Settle a failed WeChat Task from a generation-bound native readback.

        ``done`` requires the exact sent delivery's outbound message. ``skipped``
        requires a supersession chain that reaches a sent successor, an exact
        readback of that successor, and a complete bounded readback with no
        match for the obsolete body's delivery window. The failed Attempt and
        its action history are left intact.
        """
        if task_status not in {"done", "skipped"} or not expected_execution_generation.strip():
            raise ValueError("invalid WeChat settlement")
        if not isinstance(evidence, dict) or evidence.get("delivery_id") != delivery_id:
            raise ValueError("WeChat settlement evidence does not match delivery")
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select id,status,error,execution_generation,channel,conversation_id,trigger_message_id "
                f"from ({NATIVE_REPLY_TASK_CURRENT_SQL}) where id=?",
                (task_id,),
            ).fetchone()
            delivery = db.execute(
                f"select * from ({WECHAT_DELIVERY_SQL}) where id=?",
                (delivery_id,),
            ).fetchone()
            if (task is None or task["status"] != "failed"
                    or task["error"] != "external_action_failed"
                    or task["execution_generation"] != expected_execution_generation
                    or task["channel"] != "wechat"
                    or delivery is None or int(delivery["reply_task_id"]) != task_id
                    or delivery["execution_generation"] != expected_execution_generation):
                return False
            if task_status == "done":
                readback = evidence.get("readback")
                readback_time = None
                action_time = None
                if isinstance(readback, dict):
                    try:
                        readback_time = datetime.fromisoformat(
                            str(readback.get("sent_at", "")).replace("Z", "+00:00")
                        )
                        action_time = datetime.fromisoformat(
                            str(delivery["action_started_at"]).replace("Z", "+00:00")
                        )
                    except ValueError:
                        readback_time = action_time = None
                    if readback_time is not None and readback_time.tzinfo is None:
                        readback_time = readback_time.replace(tzinfo=timezone.utc)
                    if action_time is not None and action_time.tzinfo is None:
                        action_time = action_time.replace(tzinfo=timezone.utc)
                if (delivery["status"] != "sent" or not isinstance(readback, dict)
                        or not readback.get("message_id")
                        or readback.get("account_id") != delivery["account_id"]
                        or readback.get("conversation_id") != delivery["conversation_id"]
                        or readback.get("direction") != "outbound"
                        or readback.get("text") != delivery["reply_text"]
                        or readback_time is None or action_time is None
                        or readback_time.astimezone(timezone.utc) < action_time.astimezone(timezone.utc)):
                    raise ValueError("sent WeChat delivery lacks an exact outbound readback")
                settlement_reason = "verified_wechat_delivery_readback"
            else:
                prefix = "superseded_by_newer_wechat_trigger:"
                try:
                    immediate_successor = int(str(delivery["error"])[len(prefix):])
                except ValueError:
                    raise ValueError("superseded WeChat delivery link is invalid") from None
                if delivery["status"] != "superseded" or not str(delivery["error"]).startswith(prefix):
                    raise ValueError("WeChat delivery is not superseded by a newer trigger")
                old_readback = evidence.get("old_delivery_readback")
                successor_readback = evidence.get("successor_readback")
                chain = evidence.get("successor_delivery_chain")
                if (not successor_task_id or not isinstance(old_readback, dict)
                        or old_readback.get("delivery_id") != delivery_id
                        or old_readback.get("match_count") != 0
                        or old_readback.get("window_complete") is not True
                        or not isinstance(successor_readback, dict)
                        or not isinstance(successor_readback.get("readback"), dict)
                        or not successor_readback["readback"].get("message_id")
                        or not isinstance(chain, list)):
                    raise ValueError("superseded WeChat settlement lacks complete readback evidence")
                target_task_id = immediate_successor
                visited = {task_id}
                observed_chain = [delivery_id]
                target_delivery = None
                for _ in range(10):
                    if target_task_id in visited:
                        raise ValueError("superseded WeChat chain contains a cycle")
                    visited.add(target_task_id)
                    target_delivery = db.execute(
                        f"select * from ({WECHAT_DELIVERY_SQL}) where reply_task_id=? "
                        "order by id desc limit 1", (target_task_id,),
                    ).fetchone()
                    if target_delivery is None:
                        raise ValueError("superseded WeChat successor delivery is missing")
                    observed_chain.append(int(target_delivery["id"]))
                    if target_delivery["status"] == "sent":
                        break
                    next_error = str(target_delivery["error"] or "")
                    if target_delivery["status"] != "superseded" or not next_error.startswith(prefix):
                        raise ValueError("superseded WeChat chain has no sent successor")
                    try:
                        target_task_id = int(next_error[len(prefix):])
                    except ValueError:
                        raise ValueError("superseded WeChat successor link is invalid") from None
                if (target_delivery is None or target_delivery["status"] != "sent"
                        or int(target_delivery["reply_task_id"]) != successor_task_id
                        or observed_chain != chain
                        or successor_readback.get("delivery_id") != int(target_delivery["id"])
                        or successor_readback["readback"].get("conversation_id") != delivery["conversation_id"]
                        or successor_readback["readback"].get("account_id") != delivery["account_id"]
                        or successor_readback["readback"].get("direction") != "outbound"
                        or successor_readback["readback"].get("text") != target_delivery["reply_text"]
                        or delivery["account_id"] != target_delivery["account_id"]
                        or delivery["target_type"] != target_delivery["target_type"]
                        or delivery["target_id"] != target_delivery["target_id"]
                        or delivery["conversation_id"] != target_delivery["conversation_id"]
                        or int(target_delivery["id"]) not in chain):
                    raise ValueError("superseded WeChat successor readback does not match")
                successor_time = datetime.fromisoformat(
                    successor_readback["readback"]["sent_at"].replace("Z", "+00:00")
                )
                successor_action_time = datetime.fromisoformat(
                    str(target_delivery["action_started_at"]).replace("Z", "+00:00")
                )
                if successor_time.tzinfo is None:
                    successor_time = successor_time.replace(tzinfo=timezone.utc)
                if successor_action_time.tzinfo is None:
                    successor_action_time = successor_action_time.replace(tzinfo=timezone.utc)
                if successor_time.astimezone(timezone.utc) < successor_action_time.astimezone(timezone.utc):
                    raise ValueError("successor WeChat readback predates its send action")
                settlement_reason = "superseded_by_verified_wechat_delivery"

            from app import task_entity_storage
            changed = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                expected={"status": "failed", "error": "external_action_failed",
                          "execution_generation": expected_execution_generation},
                changes={"status": task_status,
                         "error": "" if task_status == "done" else settlement_reason,
                         "available_at": "", "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if changed is None:
                return False
            detail = json.dumps(evidence, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            insert_error_action(db, {
                "conversation_id": task["conversation_id"],
                "message_id": task["trigger_message_id"],
                "kind": f"wechat_reply_task_{task_status}_reconciled",
                "detail": detail,
                "resolution": settlement_reason,
            }, resolved_at_now=True)
            self._compact_settled_reply_task_input(db, task_id)
            return True

    def skip_unresolved_reply_task(
        self,
        task_id: int,
        *,
        expected_execution_generation: str,
        reason: str,
    ) -> bool:
        """Stop an uncertain failed Reply task by an explicit operator decision.

        This does not assert that the external action succeeded. The original
        task error and immutable Agent run history remain intact; the separate
        error row records why the operator chose not to continue the action.
        """
        evidence = reason.strip()
        generation = expected_execution_generation.strip()
        if not evidence:
            raise ValueError("skip reason must be non-empty")
        if not generation:
            raise ValueError("execution generation is required")
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select conversation_id, trigger_message_id, error "
                f"from ({REPLY_TASK_SQL}) as reply_tasks "
                "where id=? and status='failed' and execution_generation=?",
                (task_id, generation),
            ).fetchone()
            if task is None or str(task["error"] or "") != "external_action_uncertain":
                return False
            cursor = db.execute(
                "update tasks set status='skipped',available_at='',locked_at=null,"
                "updated_at=current_timestamp where id=? and kind='reply' and status='failed' "
                "and error='external_action_uncertain' and execution_generation=?",
                (task_id, generation),
            )
            if cursor.rowcount != 1:
                return False
            insert_error_action(db, {
                "conversation_id": task["conversation_id"],
                "message_id": task["trigger_message_id"],
                "kind": "reply_task_skipped_by_operator", "detail": evidence,
                "resolution": evidence,
            }, resolved_at_now=True)
            self._compact_settled_reply_task_input(db, task_id)
            return True

    def skip_unresolved_reply_task_for_terminal_oa_source(
        self,
        task_id: int,
        *,
        expected_execution_generation: str,
        process_instance_id: str,
        oa_task_id: str,
        settled_evidence: str,
    ) -> bool:
        """Skip an uncertain OA follow-up once its exact source task is terminal.

        This records that no action remains applicable. It does not claim the
        earlier external action was delivered and does not rewrite its receipt.
        """
        generation = expected_execution_generation.strip()
        process_id = process_instance_id.strip()
        source_task_id = oa_task_id.strip()
        evidence = settled_evidence.strip()
        if not generation or not process_id or not source_task_id or not evidence:
            raise ValueError("terminal OA skip requires generation, source identity and evidence")
        business_object_key = f"oa:{process_id}:{source_task_id}"
        with self._immediate_write_transaction() as db:
            task = db.execute(
                f"select conversation_id, trigger_message_id, status, error, execution_generation from ({NATIVE_REPLY_TASK_CURRENT_SQL}) "
                "where id=? and status='failed' and error='external_action_uncertain' "
                "and execution_generation=? and business_object_key=?",
                (task_id, generation, business_object_key),
            ).fetchone()
            if task is None:
                return False
            from app import task_entity_storage
            updated = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                # The business object key was matched above, inside this immediate
                # transaction; it is a TaskInput field, not a Task compare field.
                expected={"status": "failed", "error": "external_action_uncertain",
                          "execution_generation": generation},
                changes={"status": "skipped", "available_at": "", "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if updated is None:
                return False
            insert_error_action(db, {
                "conversation_id": task["conversation_id"],
                "message_id": task["trigger_message_id"],
                "kind": "reply_task_skipped_terminal_oa", "detail": evidence,
                "resolution": evidence,
            }, resolved_at_now=True)
            self._compact_settled_reply_task_input(db, task_id)
            return True

    def reconcile_unresolved_reply_tasks_with_settlement_evidence(self) -> int:
        """Close stale tasks with exact settlement evidence in bounded writes."""
        candidate_sql = f"""
            select tasks.id, tasks.execution_generation
            from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
            where tasks.status in ('failed', 'needs_human')
              and tasks.error not in ('external_action_uncertain', 'external_action_failed')
              and exists (
                  select 1
                  from ({ERROR_SQL}) as settled
                  where settled.conversation_id=tasks.conversation_id
                    and settled.message_id=tasks.trigger_message_id
                    and settled.kind='reply_task_already_settled'
                    and trim(coalesce(settled.resolved_at, ''))<>''
                    and trim(coalesce(settled.resolution, ''))<>''
              )
        """
        with self._connect() as db:
            candidates = db.execute(candidate_sql + " order by tasks.id").fetchall()

        reconciled = 0
        for offset in range(0, len(candidates), SETTLED_REPLY_RECONCILE_BATCH_SIZE):
            batch = candidates[offset:offset + SETTLED_REPLY_RECONCILE_BATCH_SIZE]
            predicates = " or ".join(
                "(tasks.id=? and tasks.execution_generation=?)" for _ in batch
            )
            parameters = [
                value
                for row in batch
                for value in (row["id"], row["execution_generation"])
            ]
            with self._immediate_write_transaction() as db:
                rows = db.execute(
                    candidate_sql
                    + f" and ({predicates}) order by tasks.id",
                    parameters,
                ).fetchall()
                for row in rows:
                    cursor = db.execute(
                        f"""update tasks set status='done',error='',available_at='',
                            locked_at=null,updated_at=current_timestamp
                        where kind='reply' and id=? and status in ('failed','needs_human')
                          and error not in ('external_action_uncertain','external_action_failed')
                          and execution_generation=? and exists(
                            select 1 from ({ERROR_SQL}) settled
                            join task_inputs current_input on current_input.id=tasks.current_input_id
                              and current_input.task_id=tasks.id
                            where settled.conversation_id=current_input.conversation_id
                              and settled.message_id=current_input.trigger_message_id
                              and settled.kind='reply_task_already_settled'
                              and trim(coalesce(settled.resolved_at,''))<>''
                              and trim(coalesce(settled.resolution,''))<>'')
                        returning id""",
                        (row["id"], row["execution_generation"]),
                    ).fetchone()
                    if cursor is not None:
                        self._compact_settled_reply_task_input(db, int(cursor["id"]))
                        reconciled += 1
        return reconciled

    def has_sent_reply_for_trigger(
        self,
        conversation_id: str,
        trigger_message_id: str,
    ) -> bool:
        with self._connect() as db:
            row = db.execute(
                f"""
                select 1
                from ({SENT_REPLY_SQL})
                where conversation_id=? and trigger_message_id=?
                limit 1
                """,
                (conversation_id, trigger_message_id),
            ).fetchone()
            return row is not None


    def get_sent_reply(
        self, conversation_id: str, trigger_message_id: str
    ) -> SentReply | None:
        with self._connect() as db:
            row = db.execute(
                f"""
                select *
                from ({SENT_REPLY_SQL})
                where conversation_id=? and trigger_message_id=?
                order by id desc
                limit 1
                """,
                (conversation_id, trigger_message_id),
            ).fetchone()
            if row is None:
                return None
            return SentReply.model_validate(dict(row))

    def is_verified_agent_authored_message(
        self,
        conversation_id: str,
        message_id: str,
        *,
        channel: str = "dingtalk",
    ) -> bool:
        """Match a provider message ID to a successfully read-back agent send."""
        conversation_id = conversation_id.strip()
        message_id = message_id.strip()
        channel = channel.strip()
        if not conversation_id or not message_id or not channel:
            return False
        with self._connect() as db:
            return db.execute(
                f"""
                select 1
                from ({SENT_REPLY_SQL}) as sent
                where sent.channel=?
                  and sent.conversation_id=?
                  and json_valid(sent.send_result_json)
                  and json_extract(sent.send_result_json, '$.verification.state')='sent'
                  and json_extract(
                      sent.send_result_json,
                      '$.verification.status_result.result.sendStatus'
                  )='SUCCESS'
                  and json_extract(
                      sent.send_result_json,
                      '$.verification.status_result.result.openMessageId'
                  )=?
                limit 1
                """,
                (channel, conversation_id, message_id),
            ).fetchone() is not None

    def list_sent_replies_after(self, sent_reply_id: int) -> list[SentReply]:
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({SENT_REPLY_SQL})
                where id > ?
                order by id asc
                """,
                (sent_reply_id,),
            ).fetchall()
            return [SentReply.model_validate(dict(row)) for row in rows]

    def list_sent_replies_for_attempts(
        self, attempts: list[ReplyAttempt]
    ) -> dict[tuple[str, str], SentReply]:
        keys = [
            (attempt.conversation_id, attempt.trigger_message_id)
            for attempt in attempts
        ]
        if not keys:
            return {}
        placeholders = ",".join(["(?, ?)"] * len(keys))
        args = [value for key in keys for value in key]
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({SENT_REPLY_SQL})
                where (conversation_id, trigger_message_id) in ({placeholders})
                order by id desc
                """,
                args,
            ).fetchall()
            result: dict[tuple[str, str], SentReply] = {}
            for row in rows:
                reply = SentReply.model_validate(dict(row))
                key = (reply.conversation_id, reply.trigger_message_id)
                if key not in result:
                    result[key] = reply
            return result

