    def feedback_pressure_stats(
        self,
        conversation_id: str,
        *,
        now_utc: str | None = None,
    ) -> FeedbackPressureStats:
        now_expression = "current_timestamp" if now_utc is None else "?"
        args = [conversation_id]
        if now_utc is not None:
            args.extend([now_utc, now_utc])
        with self._connect() as db:
            row = db.execute(
                f"""
                with latest_feedback as (
                    select max(datetime(coalesce(
                        nullif(fe.received_at, ''),
                        fe.updated_at,
                        fe.created_at
                    ))) as latest_feedback_at
                    from ({SENT_REPLY_SQL}) sr
                    join ({FEEDBACK_EVENT_SQL}) fe
                        on fe.feedback_token = sr.feedback_token
                    where sr.conversation_id=?
                      and trim(sr.feedback_token) <> ''
                ),
                unanswered as (
                    select sr.*
                    from ({SENT_REPLY_SQL}) sr
                    left join latest_feedback lf
                    where sr.conversation_id=?
                      and trim(sr.feedback_token) <> ''
                      and not exists (
                          select 1
                          from ({FEEDBACK_EVENT_SQL}) fe
                          where fe.feedback_token = sr.feedback_token
                      )
                      and (
                          lf.latest_feedback_at is null
                          or datetime(sr.sent_at) > lf.latest_feedback_at
                      )
                )
                select
                    count(*) as unanswered_since_last_feedback,
                    sum(
                        case
                            when datetime(sent_at)
                                <= datetime({now_expression}, '-7 days')
                            then 1
                            else 0
                        end
                    ) as unanswered_older_than_7_days,
                    sum(
                        case
                            when datetime(sent_at)
                                <= datetime({now_expression}, '-10 days')
                            then 1
                            else 0
                        end
                    ) as unanswered_older_than_10_days
                from unanswered
                """,
                [conversation_id, *args],
            ).fetchone()
        if row is None:
            return FeedbackPressureStats()
        return FeedbackPressureStats(
            unanswered_since_last_feedback=int(
                row["unanswered_since_last_feedback"] or 0
            ),
            unanswered_older_than_7_days=int(
                row["unanswered_older_than_7_days"] or 0
            ),
            unanswered_older_than_10_days=int(
                row["unanswered_older_than_10_days"] or 0
            ),
        )

    def upsert_feedback_event(
        self,
        *,
        key: str,
        feedback_token: str,
        rating: str = "",
        rating_label: str = "",
        comment: str = "",
        original_text: str = "",
        reply_text: str = "",
        source: str = "",
        received_at: str = "",
        raw_json: str = "{}",
    ) -> None:
        with self._connect() as db:
            upsert_feedback_event(db, {
                "key": key, "feedback_token": feedback_token, "rating": rating,
                "rating_label": rating_label, "comment": comment,
                "original_text": original_text, "reply_text": reply_text,
                "source": source, "received_at": received_at, "raw_json": raw_json,
            })
            existing = db.execute(
                "select task_id from feedback_processing_items where feedback_key=?",
                (key,),
            ).fetchone()
            if existing is None:
                event = db.execute(
                    f"select resolved_at,trim(resolved_at)<>'' as is_resolved "
                    f"from ({FEEDBACK_EVENT_SQL}) where key=?",
                    (key,),
                ).fetchone()
                status = "resolved" if event and event["is_resolved"] else "pending"
                task_timestamp = str(db.execute("select current_timestamp").fetchone()[0])
                task = task_entity_storage.create_task(
                    db,
                    values={
                        "kind": "feedback_processing",
                        "status": status,
                        "created_at": task_timestamp,
                        "updated_at": task_timestamp,
                    },
                )
                db.execute(
                    "insert into feedback_processing_items(task_id,feedback_key,batch_id,current_round_id) values(?,?,?,0)",
                    (task["id"], key, ""),
                )
            else:
                event = db.execute(
                    f"select resolved_at,trim(resolved_at)<>'' as is_resolved "
                    f"from ({FEEDBACK_EVENT_SQL}) where key=?",
                    (key,),
                ).fetchone()
                if event and event["is_resolved"]:
                    db.execute(
                        "update tasks set status='resolved',updated_at=current_timestamp "
                        "where id=? and kind='feedback_processing'",
                        (existing["task_id"],),
                    )
                else:
                    db.execute(
                        "update tasks set updated_at=current_timestamp "
                        "where id=? and kind='feedback_processing'",
                        (existing["task_id"],),
                    )

    @staticmethod
    def _feedback_processing_round_pointer(
        row: sqlite3.Row,
        *,
        require_positive: bool,
    ) -> int:
        raw = row["current_round_id"]
        if (
            type(raw) is not int
            or raw < 0
            or (require_positive and raw <= 0)
        ):
            raise ValueError(FEEDBACK_PROCESSING_CURRENT_ROUND_ID_INVALID)
        return raw

    @staticmethod
    def _feedback_backlog_receipt_is_complete(raw: object) -> bool:
        try:
            parsed = json.loads(raw or "{}")
        except (TypeError, ValueError):
            return False
        required = ("processing", "failed", "retryable")
        return isinstance(parsed, dict) and all(
            type(parsed.get(name)) is int and parsed[name] == 0 for name in required
        )

    @staticmethod
    def _feedback_processing_receipt_version(row: sqlite3.Row) -> int:
        raw = row["receipt_version"]
        if type(raw) is not int or raw not in (1, 2):
            raise ValueError("feedback processing receipt version is invalid")
        return raw

    @staticmethod
    def _feedback_processing_item_from_row(row: sqlite3.Row) -> FeedbackProcessingItem:
        values = dict(row)
        values["current_round_id"] = AutoReplyStore._feedback_processing_round_pointer(
            row,
            require_positive=False,
        )
        for field in ("attempt_id", "agent_run_id"):
            raw = values.get(field, 0)
            if raw in (None, ""):
                values[field] = 0
            else:
                try:
                    values[field] = int(raw)
                except (TypeError, ValueError):
                    values[field] = 0
        for field in ("test_evidence", "restart_evidence", "health_evidence"):
            raw = values.pop(f"{field}_json", "{}")
            try:
                parsed = json.loads(raw or "{}")
            except (TypeError, ValueError):
                parsed = {}
            values[field] = parsed if isinstance(parsed, dict) else {}
        return FeedbackProcessingItem.model_validate(values)

    @staticmethod
    def _feedback_processing_round_from_row(
        row: sqlite3.Row,
    ) -> FeedbackProcessingRound:
        values = dict(row)
        values["receipt_version"] = AutoReplyStore._feedback_processing_receipt_version(
            row
        )
        for field in (
            "test_evidence",
            "restart_evidence",
            "health_evidence",
            "backlog_evidence",
            "scope_receipt",
        ):
            raw = values.pop(f"{field}_json", "{}")
            parsed = json.loads(raw or "{}")
            if not isinstance(parsed, dict):
                raise ValueError(f"feedback processing round {field} must be an object")
            values[field] = parsed
        return FeedbackProcessingRound.model_validate(values)

    @staticmethod
    def _feedback_processing_transition_from_row(
        row: sqlite3.Row,
    ) -> FeedbackProcessingTransition:
        return FeedbackProcessingTransition.model_validate(dict(row))

    @staticmethod
    def _validate_resolved_feedback_processing_round(
        item: sqlite3.Row,
        current_round: sqlite3.Row,
    ) -> None:
        AutoReplyStore._resolved_feedback_processing_round_evidence(current_round)
        if (
            not str(current_round["resolved_at"] or "").strip()
            or str(item["resolved_at"] or "") != str(current_round["resolved_at"] or "")
            or not str(current_round["workbench_task_id"] or "").strip()
            or not str(current_round["workbench_turn_id"] or "").strip()
            or type(current_round["attempt_id"]) is not int
            or int(current_round["attempt_id"]) <= 0
            or type(current_round["agent_run_id"]) is not int
            or int(current_round["agent_run_id"]) <= 0
        ):
            raise ValueError("resolved feedback processing round is incomplete")
    @staticmethod
    def _resolved_feedback_processing_round_evidence(
        current_round: sqlite3.Row,
    ) -> ResolutionEvidence:
        if (
            not str(current_round["resolved_at"] or "").strip()
            or not str(current_round["workbench_task_id"] or "").strip()
            or not str(current_round["workbench_turn_id"] or "").strip()
            or type(current_round["attempt_id"]) is not int
            or current_round["attempt_id"] <= 0
            or type(current_round["agent_run_id"]) is not int
            or current_round["agent_run_id"] <= 0
        ):
            raise ValueError("resolved feedback processing round is incomplete")
        evidence_by_name: dict[str, dict[str, object]] = {}
        for name in (
            "test_evidence",
            "restart_evidence",
            "health_evidence",
            "backlog_evidence",
        ):
            parsed = json.loads(current_round[f"{name}_json"] or "{}")
            if not isinstance(parsed, dict):
                raise ValueError("resolved feedback processing evidence is invalid")
            evidence_by_name[name] = parsed
        evidence = ResolutionEvidence(
            commit_sha=str(current_round["commit_sha"] or ""),
            test_evidence=evidence_by_name["test_evidence"],
            restart_evidence=evidence_by_name["restart_evidence"],
            health_evidence=evidence_by_name["health_evidence"],
            backlog_evidence=evidence_by_name["backlog_evidence"],
        )
        return evidence

    @staticmethod
    def _feedback_processing_batch_from_row(
        row: sqlite3.Row,
    ) -> FeedbackProcessingBatch:
        return FeedbackProcessingBatch.model_validate(dict(row))

    @staticmethod
    def _feedback_iteration_decision_from_row(
        row: sqlite3.Row,
    ) -> FeedbackIterationDecisionRecord:
        values = dict(row)
        values["feedback_keys"] = json.loads(values.pop("feedback_keys_json"))
        values["round_ids"] = json.loads(values.pop("round_ids_json"))
        values["decision"] = json.loads(values.pop("decision_json"))
        return FeedbackIterationDecisionRecord.model_validate(values)

    def record_feedback_iteration_decision(
        self,
        batch_id: str,
        decision: FeedbackIterationDecision,
        *,
        workbench_task_id: str,
        workbench_turn_id: str,
    ) -> FeedbackIterationDecisionRecord:
        """Append one typed classification tied to the current rounds in a batch."""
        if not isinstance(decision, FeedbackIterationDecision):
            raise ValueError("feedback iteration decision is invalid")
        if (
            not isinstance(workbench_task_id, str)
            or not isinstance(workbench_turn_id, str)
            or not workbench_task_id.strip()
            or not workbench_turn_id.strip()
        ):
            raise ValueError(
                "feedback iteration decision requires non-empty Workbench task and turn strings"
            )
        cleaned_batch_id = batch_id.strip()
        task_id = workbench_task_id.strip()
        turn_id = workbench_turn_id.strip()
        if not cleaned_batch_id or not task_id or not turn_id:
            raise ValueError("feedback iteration decision requires batch and Workbench identity")
        keys = tuple(decision.feedback_keys)
        with self._immediate_write_transaction() as db:
            batch = db.execute(
                f"""select status from ({_native_feedback_batch_projection()}) as feedback_processing_batches where batch_id=?""",
                (cleaned_batch_id,),
            ).fetchone()
            if batch is None or str(batch["status"]) != "processing":
                raise ValueError("feedback iteration decision requires a processing batch")
            placeholders = ",".join("?" for _ in keys)
            rows = db.execute(
                f"""select item.feedback_key, item.current_round_id, item.batch_id,
                           item.status, round.workbench_task_id,
                           round.workbench_turn_id
                    from ({_native_feedback_item_projection()}) as item
                    join ({_native_feedback_round_projection()}) as round
                      on round.id=item.current_round_id
                     and round.feedback_key=item.feedback_key
                     and round.batch_id=item.batch_id
                     and round.status='processing'
                   where item.feedback_key in ({placeholders})""",
                keys,
            ).fetchall()
            if len(rows) != len(keys) or any(
                str(row["batch_id"]) != cleaned_batch_id
                or str(row["status"]) != "processing"
                or type(row["current_round_id"]) is not int
                or row["current_round_id"] <= 0
                for row in rows
            ):
                raise FeedbackIterationAssociationMismatchError(
                    "feedback iteration decision keys must belong to the current processing round association"
                )
            round_ids_by_key = {str(row["feedback_key"]): int(row["current_round_id"]) for row in rows}
            identities = {
                (
                    str(row["workbench_task_id"] or "").strip(),
                    str(row["workbench_turn_id"] or "").strip(),
                )
                for row in rows
            }
            if len(identities) != 1:
                raise FeedbackIterationAssociationMismatchError(
                    "feedback iteration decision requires one current processing round association"
                )
            canonical_task_id, canonical_turn_id = identities.pop()
            if (
                not canonical_task_id
                or not canonical_turn_id
                or (task_id, turn_id) != (canonical_task_id, canonical_turn_id)
            ):
                raise FeedbackIterationAssociationMismatchError(
                    "feedback iteration decision must match the current processing round association"
                )
            cursor = db.execute(
                "insert into feedback_iteration_decisions"
                "(batch_id,workbench_task_id,workbench_turn_id,decision_json)"
                " values(?,?,?,?)",
                (cleaned_batch_id, canonical_task_id, canonical_turn_id,
                 decision.model_dump_json()),
            )
            decision_id = int(cursor.lastrowid)
            insert_feedback_decision_items(db, [
                {"decision_id": decision_id, "feedback_key": key,
                 "round_id": round_ids_by_key[key]} for key in keys
            ])
            row = db.execute(
                f"""select decision.id, decision.batch_id, decision.workbench_task_id,
                          decision.workbench_turn_id, decision.decision_json,
                          decision.created_at,
                          json_group_array(item.feedback_key) as feedback_keys_json,
                          json_group_array(item.round_id) as round_ids_json
                     from feedback_iteration_decisions as decision
                     join ({FEEDBACK_DECISION_ITEM_SQL}) item on item.decision_id=decision.id
                    where decision.id=?
                    group by decision.id""",
                (decision_id,),
            ).fetchone()
        assert row is not None
        return self._feedback_iteration_decision_from_row(row)

    def list_feedback_iteration_decisions(
        self, batch_id: str
    ) -> tuple[FeedbackIterationDecisionRecord, ...]:
        with self._connect() as db:
            rows = db.execute(
                f"""select decision.id, decision.batch_id, decision.workbench_task_id,
                          decision.workbench_turn_id, decision.decision_json,
                          decision.created_at,
                          json_group_array(item.feedback_key) as feedback_keys_json,
                          json_group_array(item.round_id) as round_ids_json
                     from feedback_iteration_decisions as decision
                     join ({FEEDBACK_DECISION_ITEM_SQL}) item on item.decision_id=decision.id
                    where decision.batch_id=?
                    group by decision.id
                    order by decision.id""",
                (batch_id.strip(),),
            ).fetchall()
        return tuple(self._feedback_iteration_decision_from_row(row) for row in rows)

    def create_feedback_processing_batch(
        self,
        feedback_keys: Sequence[str] = (),
        *,
        batch_id: str | None = None,
    ) -> FeedbackProcessingBatch:
        """Create or reuse one native Feedback batch and its Task/detail items."""
        cleaned_batch_id = (batch_id or uuid4().hex).strip()
        if not cleaned_batch_id:
            raise ValueError("batch_id must not be empty")
        keys = list(dict.fromkeys(key.strip() for key in feedback_keys if key.strip()))
        with self._immediate_write_transaction() as db:
            existing_batch = db.execute(
                "select batch_id,status,requested_count,created_at,updated_at,resolved_at "
                "from feedback_processing_batches where batch_id=?",
                (cleaned_batch_id,),
            ).fetchone()
            if existing_batch is not None:
                existing_keys = {
                    str(row[0]) for row in db.execute(
                        "select feedback_key from feedback_processing_items where batch_id=?",
                        (cleaned_batch_id,),
                    )
                }
                if existing_keys != set(keys):
                    raise FeedbackProcessingBatchError(FEEDBACK_PROCESSING_BATCH_ERROR)
                return self._feedback_processing_batch_from_row(existing_batch)
            if keys:
                placeholders = ",".join("?" for _ in keys)
                source_rows = db.execute(
                    f"select key,resolved_at from ({FEEDBACK_EVENT_SQL}) where key in ({placeholders})",
                    keys,
                ).fetchall()
                source_by_key = {str(row["key"]): row for row in source_rows}
                if len(source_by_key) != len(keys) or any(
                    str(source_by_key[key]["resolved_at"] or "").strip() for key in keys
                ):
                    raise FeedbackProcessingBatchError(FEEDBACK_PROCESSING_BATCH_ERROR)
                conflicting = db.execute(
                    f"select item.feedback_key from feedback_processing_items item "
                    f"join tasks task on task.id=item.task_id where item.feedback_key in ({placeholders}) "
                    "and (trim(item.batch_id)<>'' or task.status='resolved')",
                    keys,
                ).fetchall()
                if conflicting:
                    raise FeedbackProcessingBatchError(FEEDBACK_PROCESSING_BATCH_ERROR)
            db.execute(
                "insert into feedback_processing_batches(batch_id,requested_count) values(?,?)",
                (cleaned_batch_id, len(keys)),
            )
            item_timestamp = str(db.execute("select current_timestamp").fetchone()[0])
            for key in keys:
                existing_item = db.execute(
                    "select item.task_id,task.status from feedback_processing_items item "
                    "join tasks task on task.id=item.task_id where item.feedback_key=?",
                    (key,),
                ).fetchone()
                if existing_item is None:
                    task = task_entity_storage.create_task(
                        db, values={"kind": "feedback_processing", "status": "pending",
                                    "created_at": item_timestamp, "updated_at": item_timestamp},
                    )
                    db.execute(
                        "insert into feedback_processing_items(task_id,feedback_key,batch_id,current_round_id) "
                        "values(?,?,?,0)",
                        (task["id"], key, cleaned_batch_id),
                    )
                else:
                    db.execute(
                        "update feedback_processing_items set batch_id=? where task_id=?",
                        (cleaned_batch_id, existing_item["task_id"]),
                    )
                    db.execute(
                        "update tasks set updated_at=current_timestamp where id=? and kind='feedback_processing'",
                        (existing_item["task_id"],),
                    )
            row = db.execute(
                "select batch_id,status,requested_count,created_at,updated_at,resolved_at "
                "from feedback_processing_batches where batch_id=?",
                (cleaned_batch_id,),
            ).fetchone()
        assert row is not None
        return self._feedback_processing_batch_from_row(row)

    def claim_feedback_processing_items(
        self,
        batch_id: str,
        feedback_keys: Sequence[str],
    ) -> list[FeedbackProcessingItem]:
        """Atomically claim native Feedback items and append their round facts."""
        cleaned_batch_id = batch_id.strip()
        keys = list(dict.fromkeys(key.strip() for key in feedback_keys if key.strip()))
        if not cleaned_batch_id or not keys:
            return []
        if not self.feedback_iteration_enabled():
            raise FeedbackIterationDisabledError("feedback iteration is disabled")
        with self._immediate_write_transaction() as db:
            batch = db.execute(
                "select status,requested_count from feedback_processing_batches where batch_id=?",
                (cleaned_batch_id,),
            ).fetchone()
            if batch is not None:
                if type(batch["requested_count"]) is not int or batch["requested_count"] != len(keys):
                    raise FeedbackProcessingBatchError(FEEDBACK_PROCESSING_BATCH_ERROR)
                members = {str(row[0]) for row in db.execute(
                    "select feedback_key from feedback_processing_items where batch_id=?",
                    (cleaned_batch_id,),
                )}
                if members != set(keys):
                    raise FeedbackProcessingBatchError(FEEDBACK_PROCESSING_BATCH_ERROR)
            placeholders = ",".join("?" for _ in keys)
            existing = db.execute(
                f"select event.key as feedback_key,event.resolved_at as event_resolved_at, "
                "coalesce(task.status,'pending') as item_status,coalesce(item.batch_id,'') as item_batch_id, "
                "coalesce(item.current_round_id,0) as current_round_id "
                f"from ({FEEDBACK_EVENT_SQL}) event left join feedback_processing_items item "
                "on item.feedback_key=event.key left join tasks task on task.id=item.task_id "
                f"where event.key in ({placeholders})", keys,
            ).fetchall()
            by_key = {str(row["feedback_key"]): row for row in existing}
            try:
                pointers = {
                    key: self._feedback_processing_round_pointer(
                        row, require_positive=False
                    )
                    for key, row in by_key.items()
                }
            except ValueError as exc:
                raise FeedbackProcessingClaimError(
                    FEEDBACK_PROCESSING_CLAIM_ERROR
                ) from exc
            same_batch_processing = (len(existing) == len(keys) and all(
                key in by_key and not str(by_key[key]["event_resolved_at"] or "").strip()
                and by_key[key]["item_status"] == "processing"
                and str(by_key[key]["item_batch_id"] or "").strip() == cleaned_batch_id
                and pointers[key] > 0 for key in keys))
            if same_batch_processing:
                try:
                    self._validate_current_feedback_processing_batch_lineage(
                        db, batch_id=cleaned_batch_id, expected_status="processing")
                except ValueError as exc:
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR) from exc
                rows = db.execute(
                    f"select * from ({_native_feedback_item_projection()}) "
                    f"where feedback_key in ({placeholders}) and batch_id=? "
                    "order by created_at asc,feedback_key asc",
                    [*keys, cleaned_batch_id],
                ).fetchall()
                if len(rows) != len(keys):
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
                return [self._feedback_processing_item_from_row(row) for row in rows]
            if batch is not None and str(batch["status"] or "") != "pending":
                raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
            if len(existing) != len(keys) or any(
                key not in by_key or str(by_key[key]["event_resolved_at"] or "").strip()
                or by_key[key]["item_status"] != "pending"
                or (str(by_key[key]["item_batch_id"] or "").strip()
                    and str(by_key[key]["item_batch_id"]).strip() != cleaned_batch_id)
                for key in keys
            ):
                raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
            for key in keys:
                if pointers[key] != 0:
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
                history = db.execute(
                    "select status,reopened_at,reopen_reason from feedback_processing_rounds "
                    "where feedback_key=? order by round_number desc,id desc", (key,),
                ).fetchall()
                if history and (history[0]["status"] != "resolved"
                    or not str(history[0]["reopened_at"] or "").strip()
                    or not str(history[0]["reopen_reason"] or "").strip()
                    or any(row["status"] != "resolved" for row in history)):
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
            if batch is None:
                db.execute("insert into feedback_processing_batches(batch_id,requested_count) values(?,?)",
                           (cleaned_batch_id, len(keys)))
            claim_timestamp = str(db.execute("select current_timestamp").fetchone()[0])
            for key in keys:
                next_round = db.execute(
                    "select coalesce(max(round_number),0)+1 from feedback_processing_rounds where feedback_key=?",
                    (key,),
                ).fetchone()[0]
                cursor = db.execute(
                    "insert into feedback_processing_rounds(feedback_key,round_number,batch_id,status,receipt_version,started_at) "
                    "values(?,?,?,'processing',2,?)",
                    (key, next_round, cleaned_batch_id, claim_timestamp),
                )
                round_id = int(cursor.lastrowid)
                update = db.execute(
                    "update tasks set status='processing',updated_at=current_timestamp "
                    "where id=(select task_id from feedback_processing_items where feedback_key=?) "
                    "and kind='feedback_processing' and status='pending'", (key,),
                )
                if update.rowcount != 1:
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
                update = db.execute(
                    "update feedback_processing_items set current_round_id=?,batch_id=? "
                    "where feedback_key=? and current_round_id=0",
                    (round_id, cleaned_batch_id, key),
                )
                if update.rowcount != 1:
                    raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
                insert_feedback_action(db, "feedback_processing_transitions", {
                    "feedback_key": key, "round_id": round_id, "batch_id": cleaned_batch_id,
                    "from_status": "pending", "to_status": "processing",
                    "created_at": claim_timestamp,
                })
            db.execute(
                "update feedback_processing_batches set status='processing',updated_at=current_timestamp where batch_id=?",
                (cleaned_batch_id,),
            )
            rows = db.execute(
                f"select * from ({_native_feedback_item_projection()}) "
                f"where feedback_key in ({placeholders}) and batch_id=? and status='processing' "
                "order by created_at asc,feedback_key asc",
                [*keys, cleaned_batch_id],
            ).fetchall()
            if len(rows) != len(keys):
                raise FeedbackProcessingClaimError(FEEDBACK_PROCESSING_CLAIM_ERROR)
        return [self._feedback_processing_item_from_row(row) for row in rows]

    def reopen_feedback_processing_item(
        self, feedback_key: str, *, reason: str
    ) -> FeedbackProcessingItem | None:
        """Return one resolved item to pending without changing its old receipt."""
        cleaned_key = feedback_key.strip()
        if not reason.strip():
            raise FeedbackProcessingReopenError(
                "feedback reopen reason must not be blank",
                error_code=FEEDBACK_REOPEN_INVALID,
            )
        if not cleaned_key:
            return None
        with self._immediate_write_transaction() as db:
            item = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
            if item is None:
                return None
            status = str(item["status"] or "")
            if status == "pending":
                return self._feedback_processing_item_from_row(item)
            if status == "processing":
                raise FeedbackProcessingReopenError(
                    "feedback is currently processing",
                    error_code=FEEDBACK_REOPEN_PROCESSING,
                )
            if status != "resolved":
                raise FeedbackProcessingReopenError(
                    "feedback reopen state is invalid",
                    error_code=FEEDBACK_REOPEN_INVALID,
                )
            try:
                round_id = self._feedback_processing_round_pointer(
                    item,
                    require_positive=True,
                )
            except ValueError as exc:
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                ) from exc
            current_round = db.execute(
                f"""
                select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where id=? and feedback_key=? and batch_id=? and status='resolved'
                   and round_number=(
                       select max(latest_round.round_number)
                         from ({_native_feedback_round_projection()}) as latest_round
                        where latest_round.feedback_key=?
                   )
                """,
                (
                    round_id,
                    cleaned_key,
                    str(item["batch_id"] or ""),
                    cleaned_key,
                ),
            ).fetchone()
            source = db.execute(
                f"select resolved_at from ({FEEDBACK_EVENT_SQL}) where key=?",
                (cleaned_key,),
            ).fetchone()
            batch = db.execute(
                f"""select status, requested_count, resolved_at, updated_at from ({_native_feedback_batch_projection()}) as feedback_processing_batches where batch_id=?""",
                (str(item["batch_id"] or ""),),
            ).fetchone()
            if (
                current_round is None
                or source is None
                or not str(source["resolved_at"] or "").strip()
                or batch is None
                or str(batch["status"] or "") != "resolved"
                or str(current_round["reopened_at"] or "").strip()
                or str(current_round["reopen_reason"] or "").strip()
            ):
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                )
            try:
                self._validate_resolved_feedback_processing_batch(
                    db,
                    batch_id=str(item["batch_id"] or ""),
                    requested_count=batch["requested_count"],
                    batch_resolved_at=str(batch["resolved_at"] or ""),
                    batch_updated_at=str(batch["updated_at"] or ""),
                    evidence=None,
                )
                self._validate_resolved_feedback_processing_round(item, current_round)
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                ) from exc
            reopen_timestamp_row = db.execute(
                "select current_timestamp as reopen_timestamp"
            ).fetchone()
            reopen_timestamp = str(reopen_timestamp_row["reopen_timestamp"])
            cursor = db.execute(
                "update feedback_processing_rounds set reopened_at=?,reopen_reason=? "
                "where id=? and feedback_key=? and batch_id=? and status='resolved' "
                "and trim(reopened_at)='' and trim(reopen_reason)=''",
                (
                    reopen_timestamp,
                    reason,
                    round_id,
                    cleaned_key,
                    str(item["batch_id"] or ""),
                ),
            )
            if cursor.rowcount != 1:
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                )
            insert_feedback_action(db, "feedback_processing_transitions", {
                "feedback_key": cleaned_key, "round_id": round_id,
                "batch_id": str(current_round["batch_id"] or ""),
                "from_status": "resolved", "to_status": "pending",
                "reason": reason,
                "workbench_task_id": str(current_round["workbench_task_id"] or ""),
                "workbench_turn_id": str(current_round["workbench_turn_id"] or ""),
                "created_at": reopen_timestamp,
            })
            cursor = db.execute(
                "update feedback_processing_items set current_round_id=0,batch_id='' "
                "where feedback_key=? and current_round_id=? and task_id in "
                "(select id from tasks where kind='feedback_processing' and status='resolved')",
                (cleaned_key, round_id),
            )
            if cursor.rowcount != 1:
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                )
            db.execute(
                "update tasks set status='pending',updated_at=current_timestamp "
                "where kind='feedback_processing' and id=(select task_id "
                "from feedback_processing_items where feedback_key=?)",
                (cleaned_key,),
            )
            if reopen_feedback_event(db, cleaned_key) != 1:
                raise FeedbackProcessingReopenError(
                    "feedback processing history is incomplete",
                    error_code=FEEDBACK_REOPEN_HISTORY_INCOMPLETE,
                )
            refreshed = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
        assert refreshed is not None
        return self._feedback_processing_item_from_row(refreshed)

    def list_feedback_processing_rounds(
        self, feedback_key: str
    ) -> list[FeedbackProcessingRound]:
        cleaned_key = feedback_key.strip()
        if not cleaned_key:
            return []
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({_native_feedback_round_projection()}) where feedback_key=? "
                "order by round_number desc,id desc",
                (cleaned_key,),
            ).fetchall()
        return [self._feedback_processing_round_from_row(row) for row in rows]

    def list_feedback_processing_rounds_for_batch(
        self, batch_id: str
    ) -> list[FeedbackProcessingRound]:
        """Read the exact round rows owned by one batch through its index."""

        cleaned_batch_id = batch_id.strip()
        if not cleaned_batch_id:
            return []
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({_native_feedback_round_projection()}) where batch_id=? "
                "order by feedback_key asc,id asc",
                (cleaned_batch_id,),
            ).fetchall()
        return [self._feedback_processing_round_from_row(row) for row in rows]

    def list_feedback_processing_transitions(
        self, feedback_key: str
    ) -> list[FeedbackProcessingTransition]:
        cleaned_key = feedback_key.strip()
        if not cleaned_key:
            return []
        with self._connect() as db:
            rows = db.execute(
                f"""
                select * from ({FEEDBACK_TRANSITION_SQL})
                 where feedback_key=?
                 order by id desc
                """,
                (cleaned_key,),
            ).fetchall()
        return [self._feedback_processing_transition_from_row(row) for row in rows]

    def associate_feedback_processing_turn(
        self,
        feedback_key: str,
        *,
        expected_batch_id: str | None = None,
        workbench_task_id: str = "",
        workbench_turn_id: str = "",
        attempt_id: int = 0,
        agent_run_id: int = 0,
    ) -> FeedbackProcessingItem | None:
        cleaned_key = feedback_key.strip()
        if not cleaned_key:
            return None
        with self._immediate_write_transaction() as db:
            current = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
            if current is None:
                return None
            round_id = self._feedback_processing_round_pointer(
                current,
                require_positive=True,
            )
            batch_id = str(current["batch_id"] or "")
            if expected_batch_id is not None and (
                not expected_batch_id.strip() or expected_batch_id.strip() != batch_id
            ):
                raise ValueError(
                    "feedback association requires the exact current processing batch"
                )
            current_round = db.execute(
                f"""
                select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where id=? and feedback_key=? and batch_id=? and status='processing'
                """,
                (round_id, cleaned_key, batch_id),
            ).fetchone()
            if (
                str(current["status"] or "") != "processing"
                or round_id <= 0
                or not batch_id.strip()
                or current_round is None
            ):
                raise ValueError("feedback association requires the exact current processing round")
            round_cursor = db.execute(
                "update feedback_processing_rounds set workbench_task_id=?,"
                "workbench_turn_id=?,attempt_id=?,agent_run_id=?,"
                "updated_at=current_timestamp "
                "where id=? and feedback_key=? and batch_id=? and status='processing'",
                (
                    workbench_task_id,
                    workbench_turn_id,
                    attempt_id,
                    agent_run_id,
                    round_id,
                    cleaned_key,
                    batch_id,
                ),
            )
            item_current = db.execute(
                "select 1 from feedback_processing_items "
                "where feedback_key=? and current_round_id=? and batch_id=? "
                "and task_id in (select id from tasks where kind='feedback_processing' and status='processing')",
                (cleaned_key, round_id, batch_id),
            ).fetchone()
            if round_cursor.rowcount != 1 or item_current is None:
                raise ValueError("feedback association requires the exact current processing round")
            db.execute(
                "update tasks set updated_at=current_timestamp where kind='feedback_processing' "
                "and id=(select task_id from feedback_processing_items where feedback_key=?)",
                (cleaned_key,),
            )
            row = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
        return self._feedback_processing_item_from_row(row) if row else None

    def get_feedback_processing_batch(
        self, batch_id: str
    ) -> FeedbackProcessingBatch | None:
        with self._connect() as db:
            row = db.execute(
                "select batch_id,status,requested_count,created_at,updated_at,resolved_at "
                "from feedback_processing_batches where batch_id=?",
                (batch_id.strip(),),
            ).fetchone()
        return self._feedback_processing_batch_from_row(row) if row else None

    def get_feedback_processing_item(
        self, feedback_key: str
    ) -> FeedbackProcessingItem | None:
        with self._connect() as db:
            row = db.execute(
                f"select * from ({_native_feedback_item_projection()}) where feedback_key=?",
                (feedback_key.strip(),),
            ).fetchone()
        return self._feedback_processing_item_from_row(row) if row else None

    def patch_feedback_processing_item_evidence(
        self,
        feedback_key: str,
        *,
        test_evidence: dict[str, object] | None = None,
        restart_evidence: dict[str, object] | None = None,
        health_evidence: dict[str, object] | None = None,
        commit_sha: str | None = None,
        note: str | None = None,
        status: str | None = None,
    ) -> FeedbackProcessingItem | None:
        cleaned_key = feedback_key.strip()
        if not cleaned_key:
            return None
        allowed_statuses = {"pending", "processing", "resolved"}
        if status is not None and status not in allowed_statuses:
            raise ValueError(f"unsupported feedback processing status: {status}")
        if status == "resolved":
            raise ValueError("only batch resolution may mark feedback resolved")
        if status == "processing":
            raise ValueError("only atomic batch claim may mark feedback processing")
        if status is not None:
            raise ValueError("evidence patch cannot change feedback processing status")
        assignments: dict[str, str] = {"updated_at": "current_timestamp"}
        args: list[object] = []
        for field, value in (
            ("test_evidence_json", test_evidence),
            ("restart_evidence_json", restart_evidence),
            ("health_evidence_json", health_evidence),
        ):
            if value is not None:
                if not isinstance(value, dict):
                    raise TypeError(f"{field} must be a JSON object")
                assignments[field] = "?"
                args.append(json.dumps(value, ensure_ascii=False, sort_keys=True))
        for field, value in (("commit_sha", commit_sha), ("note", note), ("status", status)):
            if value is not None:
                assignments[field] = "?"
                args.append(value)
        with self._immediate_write_transaction() as db:
            current = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
            if current is None:
                return None
            round_id = self._feedback_processing_round_pointer(
                current,
                require_positive=True,
            )
            batch_id = str(current["batch_id"] or "")
            current_round = db.execute(
                f"""
                select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where id=? and feedback_key=? and batch_id=? and status='processing'
                """,
                (round_id, cleaned_key, batch_id),
            ).fetchone()
            if (
                str(current["status"] or "") != "processing"
                or round_id <= 0
                or not batch_id.strip()
                or current_round is None
            ):
                raise ValueError("evidence patch requires the exact current processing round")
            changed = False
            for field, value in (
                ("test_evidence_json", test_evidence),
                ("restart_evidence_json", restart_evidence),
                ("health_evidence_json", health_evidence),
            ):
                if value is not None:
                    round_old = json.loads(current_round[field] or "{}")
                    serialized = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
                    if (
                        json.dumps(round_old, ensure_ascii=False, sort_keys=True, separators=(",", ":")) != serialized
                    ):
                        changed = True
            for field, value in (("commit_sha", commit_sha), ("note", note), ("status", status)):
                if value is not None and (
                    (field == "status" and str(current[field] or "") != str(value))
                    or str(current_round[field] or "") != str(value)
                ):
                    changed = True
            if not changed:
                return self._feedback_processing_item_from_row(current)
            round_sql = ",".join(f"{field}={expression}"
                                  for field, expression in assignments.items())
            round_cursor = db.execute(
                f"update feedback_processing_rounds set {round_sql} "
                "where id=? and feedback_key=? and batch_id=? and status='processing'",
                [*args, round_id, cleaned_key, batch_id],
            )
            item_current = db.execute(
                "select 1 from feedback_processing_items "
                "where feedback_key=? and current_round_id=? and batch_id=? "
                "and task_id in (select id from tasks where kind='feedback_processing' and status='processing')",
                (cleaned_key, round_id, batch_id),
            ).fetchone()
            if round_cursor.rowcount != 1 or item_current is None:
                raise ValueError("evidence patch requires the exact current processing round")
            db.execute(
                "update tasks set updated_at=current_timestamp where kind='feedback_processing' "
                "and id=(select task_id from feedback_processing_items where feedback_key=?)",
                (cleaned_key,),
            )
            row = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (cleaned_key,),
            ).fetchone()
        return self._feedback_processing_item_from_row(row) if row else None

    @classmethod
    def _validate_feedback_processing_transition_multiset(
        cls,
        db: sqlite3.Connection,
        current_round: sqlite3.Row,
        transitions: Sequence[sqlite3.Row] | None = None,
    ) -> None:
        receipt_version = cls._feedback_processing_receipt_version(current_round)
        status = str(current_round["status"] or "")
        reopened_at = str(current_round["reopened_at"] or "").strip()
        reopen_reason = str(current_round["reopen_reason"] or "").strip()
        if (
            status not in {"processing", "resolved"}
            or bool(reopened_at) != bool(reopen_reason)
            or (status == "processing" and reopened_at)
        ):
            raise ValueError("feedback processing transition history is incomplete")
        if transitions is None:
            transitions = db.execute(
                f"select * from ({FEEDBACK_TRANSITION_SQL}) "
                "where round_id=? order by id",
                (int(current_round["id"]),),
            ).fetchall()
        by_pair: dict[tuple[str, str], list[sqlite3.Row]] = {}
        for transition in transitions:
            if (
                str(transition["feedback_key"]) != str(current_round["feedback_key"])
                or str(transition["batch_id"] or "")
                != str(current_round["batch_id"] or "")
            ):
                raise ValueError("feedback processing transition history is incomplete")
            pair = (
                str(transition["from_status"] or ""),
                str(transition["to_status"] or ""),
            )
            by_pair.setdefault(pair, []).append(transition)

        claim = by_pair.pop(("pending", "processing"), [])
        completion = by_pair.pop(("processing", "resolved"), [])
        reopen = by_pair.pop(("resolved", "pending"), [])
        if by_pair:
            raise ValueError("feedback processing transition history is incomplete")
        if receipt_version == 2:
            expected_counts = (
                1,
                1 if status == "resolved" else 0,
                1 if reopened_at else 0,
            )
        else:
            expected_counts = (
                0,
                len(completion) if status == "resolved" and len(completion) <= 1 else 0,
                1 if reopened_at else 0,
            )
        if (len(claim), len(completion), len(reopen)) != expected_counts:
            raise ValueError("feedback processing transition history is incomplete")
        if claim and (
            not str(current_round["started_at"] or "").strip()
            or str(claim[0]["reason"] or "")
            or str(claim[0]["workbench_task_id"] or "")
            or str(claim[0]["workbench_turn_id"] or "")
            or str(claim[0]["created_at"] or "")
            != str(current_round["started_at"] or "")
        ):
            raise ValueError("feedback processing claim transition is incomplete")
        if completion and (
            not str(current_round["resolved_at"] or "").strip()
            or str(completion[0]["reason"] or "")
            or str(completion[0]["workbench_task_id"] or "")
            != str(current_round["workbench_task_id"] or "")
            or str(completion[0]["workbench_turn_id"] or "")
            != str(current_round["workbench_turn_id"] or "")
            or str(completion[0]["created_at"] or "")
            != str(current_round["resolved_at"] or "")
        ):
            raise ValueError("feedback processing completion transition is incomplete")
        if reopen and (
            str(reopen[0]["reason"] or "") != reopen_reason
            or str(reopen[0]["workbench_task_id"] or "")
            != str(current_round["workbench_task_id"] or "")
            or str(reopen[0]["workbench_turn_id"] or "")
            != str(current_round["workbench_turn_id"] or "")
            or str(reopen[0]["created_at"] or "") != reopened_at
        ):
            raise ValueError("feedback processing reopen transition is incomplete")

    @classmethod
    def _validate_current_processing_round_projection(
        cls,
        item: sqlite3.Row,
        current_round: sqlite3.Row,
    ) -> None:
        receipt_version = cls._feedback_processing_receipt_version(current_round)
        if (
            str(item["status"] or "") != "processing"
            or str(current_round["status"] or "") != "processing"
            or str(item["batch_id"] or "") != str(current_round["batch_id"] or "")
            or type(current_round["attempt_id"]) is not int
            or current_round["attempt_id"] < 0
            or type(current_round["agent_run_id"]) is not int
            or current_round["agent_run_id"] < 0
            or str(item["resolved_at"] or "")
            or str(current_round["resolved_at"] or "")
        ):
            raise ValueError("resolved batch current processing lineage is incomplete")
        for field in (
            "test_evidence_json",
            "restart_evidence_json",
            "health_evidence_json",
        ):
            round_evidence = json.loads(current_round[field] or "{}")
            if not isinstance(round_evidence, dict):
                raise ValueError(
                    "resolved batch current processing evidence is incomplete"
                )
        backlog_evidence = json.loads(current_round["backlog_evidence_json"] or "{}")
        if not isinstance(backlog_evidence, dict) or (
            receipt_version == 2 and backlog_evidence
        ):
            raise ValueError("resolved batch current processing backlog is incomplete")

    @classmethod
    def _validate_feedback_processing_batch_transition_ownership(
        cls,
        db: sqlite3.Connection,
        batch_id: str,
        batch_rounds: Sequence[sqlite3.Row],
    ) -> dict[int, list[sqlite3.Row]]:
        round_by_id: dict[int, sqlite3.Row] = {}
        for round_row in batch_rounds:
            round_id = round_row["id"]
            if (
                type(round_id) is not int
                or round_id <= 0
                or str(round_row["batch_id"] or "") != batch_id
                or round_id in round_by_id
            ):
                raise ValueError(
                    "feedback processing batch transition ownership is incomplete"
                )
            round_by_id[round_id] = round_row
        if not round_by_id:
            raise ValueError(
                "feedback processing batch transition ownership is incomplete"
            )
        batch_transitions = db.execute(
            f"select * from ({FEEDBACK_TRANSITION_SQL}) "
            "where batch_id=? order by round_id, id",
            (batch_id,),
        ).fetchall()
        for transition in batch_transitions:
            transition_round_id = transition["round_id"]
            owned_round = (
                round_by_id.get(transition_round_id)
                if type(transition_round_id) is int
                else None
            )
            if owned_round is None or str(transition["feedback_key"]) != str(
                owned_round["feedback_key"]
            ):
                raise ValueError(
                    "feedback processing batch transition ownership is incomplete"
                )
        placeholders = ",".join("?" for _ in round_by_id)
        round_transitions = db.execute(
            f"select * from ({FEEDBACK_TRANSITION_SQL}) "
            f"where round_id in ({placeholders}) order by round_id, id",
            list(round_by_id),
        ).fetchall()
        transitions_by_round = {
            round_id: [] for round_id in round_by_id
        }
        for transition in round_transitions:
            transition_round_id = transition["round_id"]
            if (
                type(transition_round_id) is not int
                or transition_round_id not in transitions_by_round
            ):
                raise ValueError(
                    "feedback processing batch transition ownership is incomplete"
                )
            transitions_by_round[transition_round_id].append(transition)
        return transitions_by_round

    @classmethod
    def _validate_current_feedback_processing_batch_lineage(
        cls,
        db: sqlite3.Connection,
        *,
        batch_id: str,
        expected_status: str,
    ) -> None:
        stable_error = "resolved batch newer lineage is incomplete"
        try:
            if expected_status not in {"processing", "resolved"}:
                raise ValueError(stable_error)
            batch = db.execute(
                f"""select status, requested_count, resolved_at, updated_at from ({_native_feedback_batch_projection()}) as feedback_processing_batches where batch_id=?""",
                (batch_id,),
            ).fetchone()
            if (
                batch is None
                or str(batch["status"] or "") != expected_status
                or type(batch["requested_count"]) is not int
                or batch["requested_count"] <= 0
            ):
                raise ValueError(stable_error)
            requested_count = batch["requested_count"]
            items = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where batch_id=? order by feedback_key""",
                (batch_id,),
            ).fetchall()
            rounds = db.execute(
                f"""select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where batch_id=? order by feedback_key, id""",
                (batch_id,),
            ).fetchall()
            item_keys = [str(item["feedback_key"]) for item in items]
            round_keys = [str(round_row["feedback_key"]) for round_row in rounds]
            if (
                len(items) != requested_count
                or len(rounds) != requested_count
                or len(set(item_keys)) != requested_count
                or len(set(round_keys)) != requested_count
                or set(item_keys) != set(round_keys)
            ):
                raise ValueError(stable_error)
            placeholders = ",".join("?" for _ in item_keys)
            sources = db.execute(
                f"select key, resolved_at, updated_at from ({FEEDBACK_EVENT_SQL}) "
                f"where key in ({placeholders})",
                item_keys,
            ).fetchall()
            source_by_key = {str(source["key"]): source for source in sources}
            if len(source_by_key) != requested_count:
                raise ValueError(stable_error)
            round_by_id = {int(round_row["id"]): round_row for round_row in rounds}
            if len(round_by_id) != requested_count:
                raise ValueError(stable_error)
            transitions_by_round = (
                cls._validate_feedback_processing_batch_transition_ownership(
                    db,
                    batch_id,
                    rounds,
                )
            )

            version_two_rounds: list[sqlite3.Row] = []
            version_two_claim_timestamps: set[str] = set()
            receipt_versions: set[int] = set()
            common_resolved_receipt: ResolutionEvidence | None = None
            for item in items:
                round_id = cls._feedback_processing_round_pointer(
                    item,
                    require_positive=True,
                )
                current_round = round_by_id.get(round_id)
                feedback_key = str(item["feedback_key"])
                source = source_by_key[feedback_key]
                item_status = str(item["status"] or "")
                round_status = str(current_round["status"] or "") if current_round else ""
                allowed_statuses = {expected_status}
                if expected_status == "processing":
                    allowed_statuses.add("resolved")
                if (
                    item_status not in allowed_statuses
                    or current_round is None
                    or str(current_round["feedback_key"]) != feedback_key
                    or str(current_round["batch_id"] or "") != batch_id
                    or round_status != item_status
                    or int(current_round["round_number"])
                    != db.execute(
                        f"""select max(round_number) from ({_native_feedback_round_projection()}) as feedback_processing_rounds where feedback_key=?""",
                        (feedback_key,),
                    ).fetchone()[0]
                ):
                    raise ValueError(stable_error)
                receipt_version = cls._feedback_processing_receipt_version(
                    current_round
                )
                receipt_versions.add(receipt_version)
                cls._validate_feedback_processing_transition_multiset(
                    db,
                    current_round,
                    transitions_by_round[round_id],
                )
                if receipt_version == 2:
                    version_two_claim_timestamps.add(
                        str(current_round["started_at"] or "")
                    )
                if round_status == "processing":
                    if str(source["resolved_at"] or "").strip():
                        raise ValueError(stable_error)
                    cls._validate_current_processing_round_projection(
                        item,
                        current_round,
                    )
                    continue

                member_receipt = cls._resolved_feedback_processing_round_evidence(
                    current_round
                )
                cls._validate_resolved_feedback_processing_round(item, current_round)
                if common_resolved_receipt is None:
                    common_resolved_receipt = member_receipt
                elif (
                    member_receipt.commit_sha != common_resolved_receipt.commit_sha
                    or member_receipt.test_evidence
                    != common_resolved_receipt.test_evidence
                    or member_receipt.restart_evidence
                    != common_resolved_receipt.restart_evidence
                    or member_receipt.health_evidence
                    != common_resolved_receipt.health_evidence
                    or member_receipt.backlog_evidence
                    != common_resolved_receipt.backlog_evidence
                ):
                    raise ValueError(stable_error)
                if str(source["resolved_at"] or "") != str(
                    current_round["resolved_at"] or ""
                ):
                    raise ValueError(stable_error)
                if receipt_version == 2:
                    version_two_rounds.append(current_round)
                    if (
                        str(item["updated_at"] or "")
                        != str(current_round["resolved_at"] or "")
                        or str(source["updated_at"] or "")
                        != str(current_round["resolved_at"] or "")
                    ):
                        raise ValueError(stable_error)

            if len(receipt_versions) != 1:
                raise ValueError(stable_error)
            if version_two_claim_timestamps and (
                len(version_two_claim_timestamps) != 1
                or not next(iter(version_two_claim_timestamps)).strip()
            ):
                raise ValueError(stable_error)
            if expected_status == "processing":
                if str(batch["resolved_at"] or "").strip():
                    raise ValueError(stable_error)
                return
            if (
                not str(batch["resolved_at"] or "").strip()
                or not str(batch["updated_at"] or "").strip()
            ):
                raise ValueError(stable_error)
            if version_two_rounds:
                timestamps = {
                    str(round_row["resolved_at"] or "")
                    for round_row in version_two_rounds
                }
                if (
                    len(timestamps) != 1
                    or str(batch["resolved_at"] or "") not in timestamps
                    or str(batch["updated_at"] or "") not in timestamps
                    or any(
                        str(round_row["updated_at"] or "") not in timestamps
                        for round_row in version_two_rounds
                    )
                ):
                    raise ValueError(stable_error)
        except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
            if str(exc) == FEEDBACK_PROCESSING_CURRENT_ROUND_ID_INVALID:
                raise
            raise ValueError(stable_error) from exc

    @classmethod
    def _validate_resolved_feedback_processing_batch(
        cls,
        db: sqlite3.Connection,
        *,
        batch_id: str,
        requested_count: int,
        batch_resolved_at: str,
        batch_updated_at: str,
        evidence: ResolutionEvidence | None,
    ) -> None:
        if type(requested_count) is not int or requested_count <= 0:
            raise ValueError("resolution requires valid batch membership")
        if not batch_resolved_at.strip() or not batch_updated_at.strip():
            raise ValueError("resolved batch completion timestamp is incomplete")
        rounds = db.execute(
            f"""select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where batch_id=? order by feedback_key, id""",
            (batch_id,),
        ).fetchall()
        round_keys = [str(round_row["feedback_key"]) for round_row in rounds]
        if (
            len(rounds) != requested_count
            or len(set(round_keys)) != requested_count
            or any(str(round_row["status"] or "") != "resolved" for round_row in rounds)
        ):
            raise ValueError("resolved batch history is incomplete")
        decision_record = cls._resolution_feedback_iteration_decision(
            db,
            batch_id=batch_id,
            feedback_keys=round_keys,
            round_by_key={str(round_row["feedback_key"]): int(round_row["id"]) for round_row in rounds},
        )
        persisted_scope_receipts = [
            cls._scope_resolution_receipt(round_row) for round_row in rounds
        ]
        if decision_record is None:
            if any(receipt is not None for receipt in persisted_scope_receipts):
                raise ValueError("resolved feedback scope receipt has no matching decision")
        else:
            if any(receipt is None for receipt in persisted_scope_receipts):
                raise ValueError("resolved feedback scope receipt is missing")
            first_scope_receipt = persisted_scope_receipts[0]
            assert first_scope_receipt is not None
            if any(receipt != first_scope_receipt for receipt in persisted_scope_receipts):
                raise ValueError("resolved feedback scope receipt is inconsistent")
            decision_id, scope, persisted_scope_evidence = first_scope_receipt
            if decision_id != decision_record.id or scope != decision_record.decision.scope:
                raise ValueError("resolved feedback scope receipt does not match decision")
            validate_resolution_receipt(
                decision_record.decision,
                persisted_scope_evidence,
                commit_is_ancestor=True,
            )
            cls._validate_decision_resolution_receipt(
                db, decision_record.decision, persisted_scope_evidence
            )
            if evidence is not None and persisted_scope_evidence != evidence:
                raise ValueError("resolution scope receipt does not match batch history")
        transitions_by_round = (
            cls._validate_feedback_processing_batch_transition_ownership(
                db,
                batch_id,
                rounds,
            )
        )
        if evidence is not None and evidence.associations and set(
            evidence.associations
        ) != set(round_keys):
            raise ValueError("resolution receipt associations do not match batch")

        version_two_rounds = [
            round_row
            for round_row in rounds
            if cls._feedback_processing_receipt_version(round_row) == 2
        ]
        if len(
            {
                cls._feedback_processing_receipt_version(round_row)
                for round_row in rounds
            }
        ) != 1:
            raise ValueError("resolved batch receipt versions are inconsistent")
        if version_two_rounds:
            resolution_timestamps = {
                str(round_row["resolved_at"] or "")
                for round_row in version_two_rounds
            }
            if (
                any(not timestamp.strip() for timestamp in resolution_timestamps)
                or batch_resolved_at != max(resolution_timestamps)
                or batch_updated_at != batch_resolved_at
                or any(
                    str(round_row["updated_at"] or "")
                    != str(round_row["resolved_at"] or "")
                    for round_row in version_two_rounds
                )
            ):
                raise ValueError("resolved batch completion timestamp is incomplete")
            claim_timestamps = {
                str(round_row["started_at"] or "")
                for round_row in version_two_rounds
            }
            if (
                len(claim_timestamps) != 1
                or not next(iter(claim_timestamps)).strip()
            ):
                raise ValueError("resolved batch claim timestamp is incomplete")

        association_fields = (
            "workbench_task_id",
            "workbench_turn_id",
            "attempt_id",
            "agent_run_id",
        )
        validated_newer_batches: set[tuple[str, str]] = set()
        common_persisted_receipt: ResolutionEvidence | None = None
        for resolved_round in rounds:
            persisted_evidence = cls._resolved_feedback_processing_round_evidence(
                resolved_round
            )
            feedback_key = str(resolved_round["feedback_key"])
            receipt_version = cls._feedback_processing_receipt_version(resolved_round)
            cls._validate_feedback_processing_transition_multiset(
                db,
                resolved_round,
                transitions_by_round[int(resolved_round["id"])],
            )
            if common_persisted_receipt is None:
                common_persisted_receipt = persisted_evidence
            elif (
                persisted_evidence.commit_sha
                != common_persisted_receipt.commit_sha
                or persisted_evidence.test_evidence
                != common_persisted_receipt.test_evidence
                or persisted_evidence.restart_evidence
                != common_persisted_receipt.restart_evidence
                or persisted_evidence.health_evidence
                != common_persisted_receipt.health_evidence
                or persisted_evidence.backlog_evidence
                != common_persisted_receipt.backlog_evidence
            ):
                raise ValueError("resolved batch persisted receipt is inconsistent")
            if decision_record is None:
                if receipt_version == 1:
                    validate_legacy_resolution_evidence(
                        persisted_evidence, commit_is_ancestor=True
                    )
                else:
                    validate_resolution_evidence(
                        persisted_evidence, commit_is_ancestor=True
                    )
            if evidence is not None:
                if (
                    (decision_record is None or decision_record.decision.scope in {"code", "mixed"})
                    and persisted_evidence.commit_sha != evidence.commit_sha
                ) or persisted_evidence.test_evidence != evidence.test_evidence or (
                    persisted_evidence.restart_evidence != evidence.restart_evidence
                ) or persisted_evidence.health_evidence != evidence.health_evidence or (
                    persisted_evidence.backlog_evidence != evidence.backlog_evidence
                ):
                    raise ValueError("resolution receipt does not match batch history")
                if evidence.associations:
                    association = evidence.associations[feedback_key]
                    if any(
                        getattr(association, field) != resolved_round[field]
                        for field in association_fields
                    ):
                        raise ValueError(
                            "resolution receipt association does not match batch history"
                        )

            reopened_at = str(resolved_round["reopened_at"] or "").strip()
            reopen_reason = str(resolved_round["reopen_reason"] or "").strip()
            if bool(reopened_at) != bool(reopen_reason):
                raise ValueError("resolved batch reopen history is incomplete")
            item = db.execute(
                f"""select * from ({_native_feedback_item_projection()}) as feedback_processing_items where feedback_key=?""",
                (feedback_key,),
            ).fetchone()
            source = db.execute(
                f"select resolved_at, updated_at from ({FEEDBACK_EVENT_SQL}) where key=?",
                (feedback_key,),
            ).fetchone()
            if item is None or source is None:
                raise ValueError("resolved batch source history is incomplete")
            if not reopened_at:
                if (
                    str(item["status"] or "") != "resolved"
                    or cls._feedback_processing_round_pointer(
                        item, require_positive=True
                    )
                    != int(resolved_round["id"])
                    or str(item["batch_id"] or "") != batch_id
                    or str(source["resolved_at"] or "")
                    != str(resolved_round["resolved_at"] or "")
                ):
                    raise ValueError("resolved batch current projection is incomplete")
                cls._validate_resolved_feedback_processing_round(item, resolved_round)
                if receipt_version == 2 and (
                    str(item["updated_at"] or "")
                    != str(resolved_round["resolved_at"] or "")
                    or str(source["updated_at"] or "")
                    != str(resolved_round["resolved_at"] or "")
                ):
                    raise ValueError("resolved batch terminal timestamp is incomplete")
                continue

            current_round_id = cls._feedback_processing_round_pointer(
                item,
                require_positive=False,
            )
            if current_round_id == 0:
                if (
                    str(item["status"] or "") != "pending"
                    or str(item["batch_id"] or "")
                    or str(item["workbench_task_id"] or "")
                    or str(item["workbench_turn_id"] or "")
                    or type(item["attempt_id"]) is not int
                    or item["attempt_id"] != 0
                    or type(item["agent_run_id"]) is not int
                    or item["agent_run_id"] != 0
                    or str(item["commit_sha"] or "")
                    or json.loads(item["test_evidence_json"] or "{}") != {}
                    or json.loads(item["restart_evidence_json"] or "{}") != {}
                    or json.loads(item["health_evidence_json"] or "{}") != {}
                    or str(item["note"] or "")
                    or str(item["resolved_at"] or "")
                    or str(source["resolved_at"] or "").strip()
                ):
                    raise ValueError("resolved batch reopened projection is incomplete")
                continue
            current_round = db.execute(
                f"""
                select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where id=? and feedback_key=? and batch_id=? and status=?
                   and round_number>?
                   and round_number=(
                       select max(latest_round.round_number)
                         from ({_native_feedback_round_projection()}) as latest_round
                        where latest_round.feedback_key=?
                   )
                """,
                (
                    current_round_id,
                    feedback_key,
                    str(item["batch_id"] or ""),
                    str(item["status"] or ""),
                    int(resolved_round["round_number"]),
                    feedback_key,
                ),
            ).fetchone()
            if current_round is None:
                raise ValueError("resolved batch current lineage is incomplete")
            newer_batch_key = (
                str(item["batch_id"] or ""),
                str(item["status"] or ""),
            )
            if newer_batch_key not in validated_newer_batches:
                cls._validate_current_feedback_processing_batch_lineage(
                    db,
                    batch_id=newer_batch_key[0],
                    expected_status=newer_batch_key[1],
                )
                validated_newer_batches.add(newer_batch_key)
            if str(item["status"] or "") == "resolved":
                if str(source["resolved_at"] or "") != str(
                    current_round["resolved_at"] or ""
                ):
                    raise ValueError("resolved batch source lineage is incomplete")
                cls._validate_resolved_feedback_processing_round(item, current_round)
                if cls._feedback_processing_receipt_version(current_round) == 2 and (
                    str(current_round["updated_at"] or "")
                    != str(current_round["resolved_at"] or "")
                    or str(item["updated_at"] or "")
                    != str(current_round["resolved_at"] or "")
                    or str(source["updated_at"] or "")
                    != str(current_round["resolved_at"] or "")
                ):
                    raise ValueError("resolved batch current lineage timestamp is incomplete")
            else:
                if str(source["resolved_at"] or "").strip():
                    raise ValueError("resolved batch current lineage is incomplete")
                cls._validate_current_processing_round_projection(
                    item,
                    current_round,
                )

    @classmethod
    def _resolution_feedback_iteration_decision(
        cls,
        db: sqlite3.Connection,
        *,
        batch_id: str,
        feedback_keys: Sequence[str],
        round_by_key: Mapping[str, int],
    ) -> FeedbackIterationDecisionRecord | None:
        """Return the latest decision bound to these exact current rounds.

        Batches created before iteration decisions remain on the historic
        receipt contract. A decision for an earlier/reopened round is not
        reusable for the current round.
        """

        rows = db.execute(
            f"""select decision.id, decision.batch_id, decision.workbench_task_id,
                      decision.workbench_turn_id, decision.decision_json,
                      decision.created_at,
                      json_group_array(item.feedback_key) as feedback_keys_json,
                      json_group_array(item.round_id) as round_ids_json
                 from feedback_iteration_decisions as decision
                 join ({FEEDBACK_DECISION_ITEM_SQL}) item on item.decision_id=decision.id
                where decision.batch_id=?
                group by decision.id
                order by decision.id desc""",
            (batch_id,),
        ).fetchall()
        expected_keys = set(feedback_keys)
        for row in rows:
            record = cls._feedback_iteration_decision_from_row(row)
            if set(record.feedback_keys) != expected_keys or len(record.feedback_keys) != len(expected_keys):
                continue
            if {key: round_id for key, round_id in zip(record.feedback_keys, record.round_ids, strict=True)} != dict(round_by_key):
                continue
            return record
        return None

    @staticmethod
    def _validate_runtime_load_receipt(
        db: sqlite3.Connection,
        *,
        config_id: int,
        load_receipt_id: int,
    ) -> dict[int, str]:
        if not db.in_transaction:
            db.execute("begin")
        config = db.execute(
            f"select status from ({config_projection('runtime_skill_configs')}) where id=?", (config_id,)
        ).fetchone()
        action = db.execute(
            "select id from actions where record_type='runtime_skill_load_receipts' and legacy_key=?",
            (str(load_receipt_id),),
        ).fetchone()
        receipt = load_receipt_projection(db, action[0]) if action is not None else None
        if (
            config is None
            or str(config["status"] or "") != "active"
            or receipt is None
            or receipt.config_id != config_id
            or receipt.error
        ):
            raise ValueError("resolution requires a successful active runtime load receipt")
        try:
            loaded = json.loads(receipt.loaded_json or "{}")
            if not isinstance(loaded, dict) or any(
                not isinstance(skill_id, str) or not isinstance(sha256, str)
                for skill_id, sha256 in loaded.items()
            ):
                raise ValueError
            normalized = {int(skill_id): str(sha256) for skill_id, sha256 in loaded.items()}
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError("resolution runtime load receipt is invalid") from exc
        return normalized

    @classmethod
    def _validate_decision_resolution_receipt(
        cls,
        db: sqlite3.Connection,
        decision: FeedbackIterationDecision,
        evidence: ResolutionEvidence,
    ) -> None:
        """Bind a typed receipt to immutable runtime records selected by a decision."""

        if decision.scope == "needs_human":
            raise ValueError("needs_human feedback iteration decisions cannot resolve")
        if decision.scope in {"skill_only", "runtime_config", "mixed"}:
            loaded = cls._validate_runtime_load_receipt(
                db,
                config_id=evidence.runtime_config_id,
                load_receipt_id=evidence.load_receipt_id,
            )
        else:
            loaded = {}
        if decision.scope in {"runtime_config", "mixed"}:
            config = db.execute(
                f"select parent_id from ({config_projection('runtime_skill_configs')}) where id=?",
                (evidence.runtime_config_id,),
            ).fetchone()
            if (
                decision.target_runtime_config_id != evidence.runtime_config_id
                or config is None
                or config["parent_id"] != evidence.previous_runtime_config_id
            ):
                raise ValueError("resolution runtime configuration does not match decision")
        if decision.scope in {"skill_only", "mixed"}:
            expected = {
                target.skill_id: target.to_revision
                for target in decision.target_skill_revisions
            }
            actual = {revision.skill_id: revision for revision in evidence.skill_revisions}
            if set(actual) != set(expected):
                raise ValueError("resolution managed Skill revisions do not match decision")
            for skill_id, revision_id in expected.items():
                revision = actual[skill_id]
                row = db.execute(
                    f"select sha256 from ({config_projection('managed_skill_revisions')}) where id=? and skill_id=?",
                    (revision.revision_id, revision.skill_id),
                ).fetchone()
                if (
                    revision.revision_id != revision_id
                    or row is None
                    or str(row["sha256"]) != revision.sha256
                    or loaded.get(skill_id) != revision.sha256
                ):
                    raise ValueError("resolution managed Skill revision is not loaded")

    @staticmethod
    def _scope_resolution_receipt(
        current_round: sqlite3.Row,
    ) -> tuple[int, str, ResolutionEvidence] | None:
        """Read one scope receipt durably bound to a resolved feedback round."""

        try:
            raw = json.loads(current_round["scope_receipt_json"] or "{}")
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError("resolved feedback scope receipt is invalid") from exc
        if raw == {}:
            return None
        if not isinstance(raw, dict):
            raise ValueError("resolved feedback scope receipt is invalid")
        decision_id = raw.get("decision_id")
        scope = raw.get("scope")
        evidence = raw.get("evidence")
        if type(decision_id) is not int or not isinstance(scope, str) or not isinstance(evidence, dict):
            raise ValueError("resolved feedback scope receipt is invalid")
        return decision_id, scope, ResolutionEvidence.model_validate(evidence)

    def resolve_feedback_processing_batch(
        self,
        batch_id: str,
        evidence: ResolutionEvidence | dict[str, object] | None = None,
        *,
        commit_is_ancestor: bool,
        feedback_keys: Sequence[str] | None = None,
    ) -> bool:
        """Resolve selected items after validating completion evidence.

        The no-evidence form preserves the original internal transition used
        by older callers (all item rows must already be ``resolved``). New
        callers provide a receipt and get one atomic transaction for the
        selected items. The parent batch stays processing until every member
        is resolved.
        """
        cleaned_batch_id = batch_id.strip()
        if not cleaned_batch_id:
            return False
        normalized_evidence = (
            evidence
            if isinstance(evidence, ResolutionEvidence)
            else ResolutionEvidence.model_validate(evidence)
            if evidence is not None
            else None
        )
        with self._immediate_write_transaction() as db:
            batch = db.execute(
                f"""select status, requested_count, resolved_at, updated_at from ({_native_feedback_batch_projection()}) as feedback_processing_batches where batch_id=?""",
                (cleaned_batch_id,),
            ).fetchone()
            if batch is None:
                return False
            if str(batch["status"] or "") == "resolved":
                self._validate_resolved_feedback_processing_batch(
                    db,
                    batch_id=cleaned_batch_id,
                    requested_count=batch["requested_count"],
                    batch_resolved_at=str(batch["resolved_at"] or ""),
                    batch_updated_at=str(batch["updated_at"] or ""),
                    evidence=normalized_evidence,
                )
                return True
            if normalized_evidence is None:
                return False
            if str(batch["status"] or "") != "processing":
                raise ValueError("resolution requires a processing batch")
            self._validate_current_feedback_processing_batch_lineage(
                db,
                batch_id=cleaned_batch_id,
                expected_status="processing",
            )
            requested_count = batch["requested_count"]
            if type(requested_count) is not int or requested_count <= 0:
                raise ValueError("resolution requires valid batch membership")
            rows = db.execute(
                f"""
                select * from ({_native_feedback_item_projection()}) as feedback_processing_items where batch_id=? order by feedback_key
                """,
                (cleaned_batch_id,),
            ).fetchall()
            round_rows = db.execute(
                f"""
                select * from ({_native_feedback_round_projection()}) as feedback_processing_rounds where batch_id=? order by feedback_key, id
                """,
                (cleaned_batch_id,),
            ).fetchall()
            item_keys = [str(item["feedback_key"]) for item in rows]
            round_keys = [str(round_row["feedback_key"]) for round_row in round_rows]
            if (
                len(rows) != requested_count
                or len(round_rows) != requested_count
                or len(set(item_keys)) != requested_count
                or len(set(round_keys)) != requested_count
                or set(item_keys) != set(round_keys)
            ):
                raise ValueError("resolution requires complete batch round membership")
            if feedback_keys is None:
                selected_keys = item_keys
            else:
                if isinstance(feedback_keys, (str, bytes)):
                    raise ValueError("resolution feedback keys must be a list")
                selected_keys = [
                    key.strip() if isinstance(key, str) else ""
                    for key in feedback_keys
                ]
                if (
                    not selected_keys
                    or any(not key for key in selected_keys)
                    or len(set(selected_keys)) != len(selected_keys)
                    or not set(selected_keys) <= set(item_keys)
                ):
                    raise ValueError("resolution feedback keys do not match batch")
            selected_key_set = set(selected_keys)
            selected_rows = [
                item for item in rows if str(item["feedback_key"]) in selected_key_set
            ]
            if normalized_evidence.associations and set(
                normalized_evidence.associations
            ) != set(item_keys):
                raise ValueError("resolution receipt associations do not match batch")
            round_by_id = {int(round_row["id"]): round_row for round_row in round_rows}
            decision_record = self._resolution_feedback_iteration_decision(
                db,
                batch_id=cleaned_batch_id,
                feedback_keys=item_keys,
                round_by_key={
                    str(item["feedback_key"]): self._feedback_processing_round_pointer(
                        item, require_positive=True
                    )
                    for item in rows
                },
            )
            if decision_record is None:
                validate_resolution_evidence(
                    normalized_evidence,
                    commit_is_ancestor=commit_is_ancestor,
                )
                requires_commit = True
            else:
                validate_resolution_receipt(
                    decision_record.decision,
                    normalized_evidence,
                    commit_is_ancestor=commit_is_ancestor,
                )
                self._validate_decision_resolution_receipt(
                    db,
                    decision_record.decision,
                    normalized_evidence,
                )
                requires_commit = decision_record.decision.scope in {"code", "mixed"}
            verified: list[tuple[sqlite3.Row, sqlite3.Row]] = []
            for item in selected_rows:
                round_id = self._feedback_processing_round_pointer(
                    item,
                    require_positive=True,
                )
                current_round = round_by_id.get(round_id)
                if (
                    str(item["status"] or "") != "processing"
                    or current_round is None
                    or str(current_round["feedback_key"]) != str(item["feedback_key"])
                    or str(current_round["batch_id"] or "") != cleaned_batch_id
                    or str(current_round["status"] or "") != "processing"
                ):
                    raise ValueError("resolution requires every item to be processing")
                association_fields = (
                    "workbench_task_id",
                    "workbench_turn_id",
                    "attempt_id",
                    "agent_run_id",
                )
                if (
                    not str(current_round["workbench_task_id"] or "").strip()
                    or not str(current_round["workbench_turn_id"] or "").strip()
                    or int(current_round["attempt_id"] or 0) <= 0
                    or int(current_round["agent_run_id"] or 0) <= 0
                ):
                    raise ValueError("resolution requires complete item associations")
                feedback_key = str(item["feedback_key"])
                if normalized_evidence.associations:
                    association = normalized_evidence.associations.get(feedback_key)
                    if association is None or any(
                        getattr(association, field) != current_round[field]
                        for field in association_fields
                    ):
                        raise ValueError(
                            "resolution receipt association does not match current round"
                        )
                item_commit = str(current_round["commit_sha"] or "").strip()
                if requires_commit and (
                    item_commit.lower() != normalized_evidence.commit_sha.strip().lower()
                ):
                    raise ValueError("resolution item commit does not match receipt")
                test_json = json.loads(current_round["test_evidence_json"] or "{}")
                restart_json = json.loads(
                    current_round["restart_evidence_json"] or "{}"
                )
                health_json = json.loads(current_round["health_evidence_json"] or "{}")
                for parsed, receipt_value in (
                    (test_json, normalized_evidence.test_evidence),
                    (
                        restart_json,
                        normalized_evidence.restart_evidence,
                    ),
                    (
                        health_json,
                        normalized_evidence.health_evidence,
                    ),
                ):
                    if parsed != receipt_value:
                        raise ValueError(
                            "resolution item evidence does not match current round receipt"
                        )
                if requires_commit:
                    validate_resolution_evidence(
                        ResolutionEvidence(
                            commit_sha=item_commit,
                            test_evidence=test_json,
                            restart_evidence=restart_json,
                            health_evidence=health_json,
                            backlog_evidence=normalized_evidence.backlog_evidence,
                        ),
                        commit_is_ancestor=commit_is_ancestor,
                    )
                else:
                    validate_resolution_receipt(
                        decision_record.decision,
                        ResolutionEvidence(
                            test_evidence=test_json,
                            restart_evidence=restart_json,
                            health_evidence=health_json,
                            backlog_evidence=normalized_evidence.backlog_evidence,
                            runtime_config_id=normalized_evidence.runtime_config_id,
                            previous_runtime_config_id=normalized_evidence.previous_runtime_config_id,
                            load_receipt_id=normalized_evidence.load_receipt_id,
                            skill_revisions=normalized_evidence.skill_revisions,
                        ),
                        commit_is_ancestor=commit_is_ancestor,
                    )
                verified.append((item, current_round))
            placeholders = ",".join("?" for _ in selected_keys)
            source_rows = db.execute(
                f"""
                select key, resolved_at from ({FEEDBACK_EVENT_SQL})
                 where key in ({placeholders})
                """,
                selected_keys,
            ).fetchall()
            if (
                len(source_rows) != len(selected_keys)
                or {str(source["key"]) for source in source_rows} != set(selected_keys)
                or any(str(source["resolved_at"] or "").strip() for source in source_rows)
            ):
                raise ValueError("resolution requires complete source feedback membership")
            backlog_json = json.dumps(
                normalized_evidence.backlog_evidence,
                ensure_ascii=False,
                sort_keys=True,
            )
            scope_receipt_json = json.dumps(
                {
                    "decision_id": decision_record.id,
                    "scope": decision_record.decision.scope,
                    "evidence": normalized_evidence.model_dump(mode="json"),
                }
                if decision_record is not None
                else {},
                ensure_ascii=False,
                sort_keys=True,
            )
            resolution_timestamp_row = db.execute(
                "select current_timestamp as resolution_timestamp"
            ).fetchone()
            resolution_timestamp = str(
                resolution_timestamp_row["resolution_timestamp"]
            )
            for item, current_round in verified:
                round_cursor = db.execute(
                    "update feedback_processing_rounds set status='resolved',resolved_at=?,"
                    "backlog_evidence_json=?,scope_receipt_json=?,updated_at=? "
                    "where id=? and feedback_key=? and batch_id=? and status='processing'",
                    (
                        resolution_timestamp,
                        backlog_json,
                        scope_receipt_json,
                        resolution_timestamp,
                        int(current_round["id"]),
                        str(item["feedback_key"]),
                        cleaned_batch_id,
                    ),
                )
                if round_cursor.rowcount != 1:
                    raise ValueError("resolution current round changed during update")
                task_cursor = db.execute(
                    "update tasks set status='resolved',updated_at=? where kind='feedback_processing' "
                    "and status='processing' and id=(select task_id from feedback_processing_items "
                    "where feedback_key=? and current_round_id=? and batch_id=?)",
                    (resolution_timestamp, str(item["feedback_key"]),
                     int(current_round["id"]), cleaned_batch_id),
                )
                if task_cursor.rowcount != 1:
                    raise ValueError("resolution current round changed during update")
                insert_feedback_action(db, "feedback_processing_transitions", {
                    "feedback_key": str(item["feedback_key"]),
                    "round_id": int(current_round["id"]),
                    "batch_id": cleaned_batch_id,
                    "from_status": "processing", "to_status": "resolved",
                    "workbench_task_id": str(current_round["workbench_task_id"] or ""),
                    "workbench_turn_id": str(current_round["workbench_turn_id"] or ""),
                    "created_at": resolution_timestamp,
                })
            if resolve_feedback_events(db, selected_keys, resolution_timestamp) != len(selected_keys):
                raise ValueError("resolution source feedback changed during update")
            remaining = db.execute(
                f"select count(*) from ({_native_feedback_round_projection()}) "
                "where batch_id=? and status!='resolved'",
                (cleaned_batch_id,),
            ).fetchone()[0]
            if remaining == 0:
                cursor = db.execute(
                    "update feedback_processing_batches set status='resolved',resolved_at=?,"
                    "updated_at=? where batch_id=? and status='processing'",
                    (resolution_timestamp, resolution_timestamp, cleaned_batch_id),
                )
            else:
                cursor = db.execute(
                    "update feedback_processing_batches set updated_at=? "
                    "where batch_id=? and status='processing'",
                    (resolution_timestamp, cleaned_batch_id),
                )
            if cursor.rowcount != 1:
                raise ValueError("resolution batch changed during update")
            return True
        return False

    def list_feedback_events_for_token(self, feedback_token: str) -> list[FeedbackEvent]:
        if not feedback_token.strip():
            return []
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({FEEDBACK_EVENT_SQL})
                where feedback_token=?
                order by received_at desc, updated_at desc
                """,
                (feedback_token,),
            ).fetchall()
            return [FeedbackEvent.model_validate(dict(row)) for row in rows]

    def get_feedback_event(self, key: str) -> FeedbackEvent | None:
        """Return one original feedback event by its stable key."""
        cleaned_key = key.strip()
        if not cleaned_key:
            return None
        with self._connect() as db:
            row = db.execute(
                f"select * from ({FEEDBACK_EVENT_SQL}) where key=?",
                (cleaned_key,),
            ).fetchone()
        return FeedbackEvent.model_validate(dict(row)) if row else None

    def list_feedback_events_for_tokens(
        self, feedback_tokens: list[str]
    ) -> dict[str, list[FeedbackEvent]]:
        tokens = sorted({token for token in feedback_tokens if token.strip()})
        if not tokens:
            return {}
        placeholders = ",".join(["?"] * len(tokens))
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({FEEDBACK_EVENT_SQL})
                where feedback_token in ({placeholders})
                order by received_at desc, updated_at desc
                """,
                tokens,
            ).fetchall()
            result: dict[str, list[FeedbackEvent]] = {}
            for row in rows:
                event = FeedbackEvent.model_validate(dict(row))
                result.setdefault(event.feedback_token, []).append(event)
            return result

    def create_service_bugfix_candidate(
        self,
        *,
        feedback_event_key: str,
        feedback_token: str = "",
        attempt_id: int = 0,
        title: str,
        reason: str,
        feedback_comment: str,
        conversation_title: str = "",
        trigger_text: str = "",
    ) -> ServiceBugfixCandidate | None:
        cleaned_key = feedback_event_key.strip()
        if not cleaned_key:
            return None
        with self._immediate_write_transaction() as db:
            result = insert_business(db, "service_bugfix_candidate", {
                "feedback_event_key": cleaned_key,
                "feedback_token": feedback_token,
                "attempt_id": max(0, int(attempt_id)),
                "title": title,
                "reason": reason,
                "feedback_comment": feedback_comment,
                "conversation_title": conversation_title,
                "trigger_text": trigger_text,
            }, ignore=True)
            if result.rowcount != 1 or result.lastrowid is None:
                return None
            row = db.execute(
                f"select * from ({BUSINESS_PROJECTIONS['service_bugfix_candidate']}) "
                "where id=?",
                (result.lastrowid,),
            ).fetchone()
            return ServiceBugfixCandidate.model_validate(dict(row)) if row else None

    def create_service_bugfix_candidate_for_feedback_event(
        self,
        event: FeedbackEvent,
        *,
        title: str,
        reason: str,
    ) -> ServiceBugfixCandidate | None:
        with self._connect() as db:
            row = db.execute(
                f"""
                select
                    coalesce(ra.id, 0) as attempt_id,
                    coalesce(ra.conversation_title, '') as conversation_title,
                    coalesce(ra.trigger_text, '') as trigger_text
                from ({FEEDBACK_EVENT_SQL}) fe
                left join ({SENT_REPLY_SQL}) sr
                    on sr.feedback_token = fe.feedback_token
                left join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                    on ra.conversation_id = sr.conversation_id
                   and ra.trigger_message_id = sr.trigger_message_id
                where fe.key=?
                order by ra.id desc
                limit 1
                """,
                (event.key,),
            ).fetchone()
        return self.create_service_bugfix_candidate(
            feedback_event_key=event.key,
            feedback_token=event.feedback_token,
            attempt_id=int(row["attempt_id"] or 0) if row else 0,
            title=title,
            reason=reason,
            feedback_comment=event.comment,
            conversation_title=str(row["conversation_title"] or "") if row else "",
            trigger_text=str(row["trigger_text"] or "") if row else "",
        )

    def list_service_bugfix_candidates(
        self,
        *,
        status: str | None = None,
        limit: int = 50,
    ) -> list[ServiceBugfixCandidate]:
        filters: list[str] = []
        args: list[object] = []
        if status is not None:
            filters.append("status=?")
            args.append(status)
        query = f"select * from ({BUSINESS_PROJECTIONS['service_bugfix_candidate']})"
        if filters:
            query = f"{query} where {' and '.join(filters)}"
        query = f"{query} order by created_at desc, id desc limit ?"
        args.append(max(1, limit))
        with self._connect() as db:
            rows = db.execute(query, args).fetchall()
            return [ServiceBugfixCandidate.model_validate(dict(row)) for row in rows]

    def count_service_bugfix_candidates(self, *, status: str | None = None) -> int:
        filters: list[str] = []
        args: list[object] = []
        if status is not None:
            filters.append("status=?")
            args.append(status)
        query = (
            "select count(*) as count from business "
            "where record_type='service_bugfix_candidate'"
        )
        if filters:
            query = f"{query} and {' and '.join(filters)}"
        with self._connect() as db:
            row = db.execute(query, args).fetchone()
            return int(row["count"] if row else 0)

    def list_user_feedback_items(
        self, limit: int = 200, offset: int = 0
    ) -> list[UserFeedbackItem]:
        with self._connect() as db:
            rows = db.execute(
                f"""
                with latest_attempt_by_token as (
                    select
                        sr.feedback_token as feedback_token,
                        max(ra.id) as attempt_id
                    from ({SENT_REPLY_SQL}) sr
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                        on ra.conversation_id = sr.conversation_id
                       and ra.trigger_message_id = sr.trigger_message_id
                    where trim(sr.feedback_token) <> ''
                    group by sr.feedback_token
                ), manual_attempt_by_key as (
                    select
                        fe.key as feedback_key,
                        max(ra.id) as attempt_id
                    from ({FEEDBACK_EVENT_SQL}) fe
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                        on ra.id = cast(substr(fe.key, 8) as integer)
                    where fe.key like 'manual:%'
                    group by fe.key
                )
                select
                    fe.key,
                    fe.feedback_token,
                    fe.rating,
                    fe.rating_label,
                    fe.comment,
                    fe.source,
                    fe.received_at,
                    coalesce(ra.id, 0) as attempt_id,
                    coalesce(ra.agent_run_id, 0) as agent_run_id,
                    coalesce(ra.codex_session_id, '') as codex_session_id,
                    coalesce(ar.role, '') as attempt_role,
                    coalesce(ra.conversation_title, '') as conversation_title,
                    coalesce(ra.trigger_sender, '') as trigger_sender,
                    coalesce(ra.trigger_text, '') as trigger_text,
                    coalesce(ra.final_reply_text, '') as final_reply_text,
                    coalesce(ra.draft_reply_text, '') as draft_reply_text,
                    coalesce(ra.codex_reason, '') as codex_reason,
                    coalesce(ra.audit_summary, '') as audit_summary,
                    case when latest.attempt_id is not null
                         then coalesce(ra.reviewer_feedback, '') else '' end as reviewer_feedback,
                    case when latest.attempt_id is not null
                         then coalesce(ra.corrected_reply_text, '') else '' end as corrected_reply_text,
                    coalesce(pi.status, case when trim(fe.resolved_at) <> '' then 'resolved' else 'pending' end) as processing_status,
                    fe.resolved_at,
                    fe.updated_at
                from ({FEEDBACK_EVENT_SQL}) fe
                left join latest_attempt_by_token latest
                    on latest.feedback_token = fe.feedback_token
                left join manual_attempt_by_key manual
                    on manual.feedback_key = fe.key
                left join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                    on ra.id = coalesce(latest.attempt_id, manual.attempt_id)
                left join (select id,role,session_id from runs) ar
                    on ar.id = ra.agent_run_id
                left join ({_native_feedback_item_projection()}) as pi
                    on pi.feedback_key = fe.key
                order by fe.received_at desc, fe.updated_at desc
                limit ?
                offset ?
                """,
                (limit, max(0, offset)),
            ).fetchall()
            return [UserFeedbackItem.model_validate(dict(row)) for row in rows]

    def list_user_feedback_items_by_keys(
        self, feedback_keys: Sequence[str]
    ) -> list[UserFeedbackItem]:
        """Bulk-load source projections for exact feedback identities."""

        keys = list(
            dict.fromkeys(key.strip() for key in feedback_keys if key.strip())
        )
        if not keys:
            return []
        placeholders = ",".join("?" for _ in keys)
        with self._connect() as db:
            rows = db.execute(
                f"""
                with requested_feedback as (
                    select * from ({FEEDBACK_EVENT_SQL})
                     where key in ({placeholders})
                ), latest_attempt_by_token as (
                    select
                        sr.feedback_token as feedback_token,
                        max(ra.id) as attempt_id
                    from ({SENT_REPLY_SQL}) sr
                    join requested_feedback requested
                        on requested.feedback_token = sr.feedback_token
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                        on ra.conversation_id = sr.conversation_id
                       and ra.trigger_message_id = sr.trigger_message_id
                    where trim(sr.feedback_token) <> ''
                    group by sr.feedback_token
                ), manual_attempt_by_key as (
                    select
                        fe.key as feedback_key,
                        max(ra.id) as attempt_id
                    from requested_feedback fe
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                        on ra.id = cast(substr(fe.key, 8) as integer)
                    where fe.key like 'manual:%'
                    group by fe.key
                )
                select
                    fe.key,
                    fe.feedback_token,
                    fe.rating,
                    fe.rating_label,
                    fe.comment,
                    fe.source,
                    fe.received_at,
                    coalesce(ra.id, 0) as attempt_id,
                    coalesce(ra.agent_run_id, 0) as agent_run_id,
                    coalesce(ra.codex_session_id, '') as codex_session_id,
                    coalesce(ar.role, '') as attempt_role,
                    coalesce(ra.conversation_title, '') as conversation_title,
                    coalesce(ra.trigger_sender, '') as trigger_sender,
                    coalesce(ra.trigger_text, '') as trigger_text,
                    coalesce(ra.final_reply_text, '') as final_reply_text,
                    coalesce(ra.draft_reply_text, '') as draft_reply_text,
                    coalesce(ra.codex_reason, '') as codex_reason,
                    coalesce(ra.audit_summary, '') as audit_summary,
                    case when latest.attempt_id is not null
                         then coalesce(ra.reviewer_feedback, '') else '' end as reviewer_feedback,
                    case when latest.attempt_id is not null
                         then coalesce(ra.corrected_reply_text, '') else '' end as corrected_reply_text,
                    coalesce(pi.status, case when trim(fe.resolved_at) <> '' then 'resolved' else 'pending' end) as processing_status,
                    fe.resolved_at,
                    fe.updated_at
                from requested_feedback fe
                left join latest_attempt_by_token latest
                    on latest.feedback_token = fe.feedback_token
                left join manual_attempt_by_key manual
                    on manual.feedback_key = fe.key
                left join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                    on ra.id = coalesce(latest.attempt_id, manual.attempt_id)
                left join (select id,role,session_id from runs) ar
                    on ar.id = ra.agent_run_id
                left join ({_native_feedback_item_projection()}) as pi
                    on pi.feedback_key = fe.key
                order by fe.key asc
                """,
                keys,
            ).fetchall()
        return [UserFeedbackItem.model_validate(dict(row)) for row in rows]

    def count_user_feedback_items(self) -> int:
        with self._connect() as db:
            row = db.execute(
                f"select count(*) as count from ({FEEDBACK_EVENT_SQL})"
            ).fetchone()
            return int(row["count"])

    def list_feedback_import_items(
        self, limit: int = 200, offset: int = 0
    ) -> list[FeedbackImportItem]:
        """Project feedback rows into the deterministic startup payload."""
        return [
            FeedbackImportItem(
                feedback_key=item.key,
                summary=persisted_feedback_summary(item),
                references=detail_references(item),
            )
            for item in self.list_user_feedback_items(limit=limit, offset=offset)
        ]

    def count_pending_user_feedback_items(self) -> int:
        with self._connect() as db:
            row = db.execute(
                f"""
                with latest_attempt_by_token as (
                    select
                        sr.feedback_token as feedback_token,
                        max(ra.id) as attempt_id
                    from ({SENT_REPLY_SQL}) sr
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                        on ra.conversation_id = sr.conversation_id
                       and ra.trigger_message_id = sr.trigger_message_id
                    where trim(sr.feedback_token) <> ''
                    group by sr.feedback_token
                )
                select count(*) as pending_count
                from ({FEEDBACK_EVENT_SQL}) fe
                left join ({_native_feedback_item_projection()}) as pi
                    on pi.feedback_key = fe.key
                left join latest_attempt_by_token latest
                    on latest.feedback_token = fe.feedback_token
                left join ({REPLY_ATTEMPT_COMMON_SQL}) as ra
                    on ra.id = latest.attempt_id
                where trim(fe.resolved_at) = ''
                  and coalesce(pi.status, 'pending') = 'pending'
                  and trim(coalesce(ra.reviewer_feedback, '')) = ''
                  and trim(coalesce(ra.corrected_reply_text, '')) = ''
                """
            ).fetchone()
            return int(row["pending_count"] if row else 0)


    def update_sent_reply_recall(
        self,
        sent_reply_id: int,
        *,
        recall_status: str,
        recall_error: str,
    ) -> None:
        with self._connect() as db:
            db.execute("begin immediate")
            from app.action_entity_storage import get_action, record_action_result

            sent = db.execute(
                f"select 1 from ({SENT_REPLY_SQL}) where id=?", (sent_reply_id,),
            ).fetchone()
            owner = get_action(db, sent_reply_id)
            if sent is None or owner is None:
                raise ValueError(f"unknown sent Action {sent_reply_id}")
            values = {"recall_status": recall_status, "recall_error": recall_error}
            if recall_status == "recalled":
                values["recalled_at"] = db.execute("select current_timestamp").fetchone()[0]
            expected = {"recall_status": owner["recall_status"], "recall_error": owner["recall_error"]}
            if record_action_result(db, sent_reply_id, expected=expected, changes=values) is None:
                raise ValueError(f"sent Action changed during recall update {sent_reply_id}")

