    def finalize_orchestrated_reply_task(
        self,
        *,
        task_id: int,
        expected_execution_generation: str,
        run_id: int,
        task_status: str,
        task_error: str,
        available_at: str,
        conversation_id: str,
        conversation_title: str,
        trigger_message_id: str,
        trigger_sender: str,
        trigger_text: str,
        audit_tool_events_json: str,
        audit_summary: str,
        human_decision_options_json: str = "[]",
        send_status: str,
        send_error: str,
        channel: str,
        preserve_attempt_budget: bool = False,
        oa_process_instance_id: str = "",
        oa_task_id: str = "",
        oa_url: str = "",
        oa_action: str = "",
        oa_remark: str = "",
        oa_action_result_json: str = "",
        oa_action_receipt_id: int | None = None,
    ) -> int:
        """Persist one orchestration result and its task transition atomically.

        A task that ends ``done`` also queues the durable memories its final
        Consumer result named, in the same transaction.
        """
        if task_status not in {"done", "failed", "pending", "unchanged", "needs_human", "skipped"}:
            raise ValueError("invalid reply task terminal status")
        if not expected_execution_generation.strip():
            raise ValueError("expected_execution_generation must be non-empty")
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            task = self._native_current_reply_task(db, task_id)
            run = db.execute(
                "select status, execution_generation, session_id, transcript_start, transcript_end from runs "
                "where id=? and task_id=? and role in ('consumer','audit')",
                (run_id, task_id),
            ).fetchone()
            if (
                task is None or run is None
                or run["execution_generation"] != expected_execution_generation
                or task["execution_generation"] != expected_execution_generation
                or run["status"] not in {"completed", "failed"}
            ):
                raise AgentRunLeaseLostError(f"agent run superseded: {run_id}")
            if (
                task_status == "done"
                and run["status"] == "failed"
            ):
                failed_run = db.execute(
                    "select structured_error_json from runs where id=? and task_id=? "
                    "and role in ('consumer','audit')", (run_id, task_id),
                ).fetchone()
                task_status = "failed"
                task_error = self._agent_run_failure_code(
                    failed_run["structured_error_json"] if failed_run is not None else ""
                )
                send_status = "failed"
                send_error = task_error
            persisted_oa_url = oa_url.strip() or str(task["current_input"]["oa_url"] or "").strip()
            task_process_id, task_oa_task_id = self._oa_identifiers_from_url(
                persisted_oa_url
            )
            persisted_process_id = oa_process_instance_id.strip() or task_process_id
            persisted_task_id = oa_task_id.strip() or task_oa_task_id
            persisted_oa_action = oa_action.strip() or (
                "review" if persisted_process_id else ""
            )
            task_parameters = task["parameters"]
            manual_rerun_attempt_id = (
                task_parameters.get("manual_rerun_attempt_id")
                if isinstance(task_parameters, Mapping) else None
            )
            current_attempt = db.execute(
                f"""
                select attempts.id
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                left join runs on runs.id=attempts.agent_run_id
                  and runs.role in ('consumer','audit')
                where attempts.channel=?
                  and attempts.conversation_id=?
                  and attempts.trigger_message_id=?
                  and (
                      runs.task_id=?
                      or attempts.id=?
                      or attempts.id=(
                          select max(latest.id)
                          from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                          where latest.channel=attempts.channel
                            and latest.conversation_id=attempts.conversation_id
                            and latest.trigger_message_id=attempts.trigger_message_id
                      )
                  )
                order by attempts.id desc
                limit 1
                """,
                (
                    channel,
                    conversation_id,
                    trigger_message_id,
                    task_id,
                    manual_rerun_attempt_id,
                ),
            ).fetchone()
            projection_values = {
                "conversation_id": conversation_id,
                "conversation_title": conversation_title,
                "trigger_message_id": trigger_message_id,
                "trigger_sender": trigger_sender,
                "trigger_text": trigger_text,
                "action": "agent_run", "sensitivity_kind": "general",
                "agent_run_id": run_id, "codex_reason": audit_summary,
                "codex_session_id": run["session_id"],
                "codex_transcript_start_line": run["transcript_start"],
                "codex_transcript_end_line": run["transcript_end"],
                "audit_tool_events_json": _audit_event_metadata_json(audit_tool_events_json),
                "audit_summary": audit_summary,
                "human_decision_options_json": human_decision_options_json,
                "oa_process_instance_id": persisted_process_id,
                "oa_task_id": persisted_task_id,
                "oa_url": persisted_oa_url, "oa_action": persisted_oa_action,
                "oa_remark": oa_remark,
                "oa_action_result_json": oa_action_result_json,
                "send_status": send_status, "send_error": send_error,
                "final_reply_text": "",
            }
            if current_attempt is None:
                result = insert_action(db, "reply_attempts", {
                    **projection_values, "channel": channel,
                })
                attempt_id = int(result.lastrowid)
            else:
                attempt_id = int(current_attempt["id"])
                update_action(db, "reply_attempts", attempt_id, {
                    **projection_values, "permission_action": "",
                    "permission_reason": "", "retry_count": 0,
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                })
            from app.reply_receipt_reference import delete_reference
            delete_reference(db, attempt_id=attempt_id)
            if oa_action_receipt_id is not None:
                from app.reply_receipt_reference import add_reference
                add_reference(db, attempt_id=attempt_id, receipt_id=oa_action_receipt_id,
                              expected_body=oa_action_result_json)
                from app.oa_history_storage import record_current_oa_facts
                record_current_oa_facts(
                    db, attempt_id=attempt_id, receipt_id=oa_action_receipt_id,
                    expected_body=oa_action_result_json,
                    process_instance_id=persisted_process_id, task_id=persisted_task_id,
                )
                update_action(db, "reply_attempts", attempt_id, {"oa_action_result_json": ""})
            self._record_memory_write_events_in_connection(
                db,
                attempt_id,
                audit_tool_events_json,
            )
            if task_status != "unchanged":
                if task["status"] not in {"processing", "pending"}:
                    raise AgentRunLeaseLostError(f"reply task superseded: {task_id}")
                changes = {
                    "status": task_status,
                    "attempts": max(int(task["attempts"]) - 1, 0)
                    if preserve_attempt_budget else int(task["attempts"]),
                    "locked_at": None,
                    "available_at": available_at if task_status == "pending" else "",
                    "error": task_error if task_status != "done" else "",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                }
                if task_entity_storage.update_task_cas(
                    db, task_id=task_id,
                    expected={"execution_generation": expected_execution_generation,
                              "status": task["status"]},
                    changes=changes,
                ) is None:
                    raise AgentRunLeaseLostError(f"reply task superseded: {task_id}")
            if task_status in {"done", "skipped"}:
                self._compact_settled_reply_task_input(db, task_id)
            return attempt_id

    @staticmethod
    def _agent_run_failure_code(structured_error_json: str) -> str:
        """Return a concise failure code suitable for the task projection."""
        try:
            payload = json.loads(structured_error_json)
        except (TypeError, json.JSONDecodeError):
            return "agent_run_failed"
        if not isinstance(payload, dict):
            return "agent_run_failed"
        code = payload.get("code")
        return code.strip() if isinstance(code, str) and code.strip() else "agent_run_failed"

    def reconcile_done_reply_tasks_with_failed_current_run(self) -> int:
        """Restore truthful current state when a failed final run was projected done.

        ``agent_runs`` is immutable execution history.  The latest terminal run
        in a task's current execution generation is the authoritative current
        result, so a stale ``reply_tasks.status='done'`` must not hide a failed
        run from Attention or History.
        """
        unsubscribe_outcomes = self._email_unsubscribe_outcomes_by_task_status()
        terminal_unsubscribe_outcomes = [
            *unsubscribe_outcomes["done"],
            *unsubscribe_outcomes["skipped"],
        ]
        receipt_placeholders = ", ".join(
            "?" for _ in terminal_unsubscribe_outcomes
        )
        receipt_exclusion = ""
        native_receipt_exclusion = ""
        receipt_parameters: list[str] = []
        with self._connect() as db:
            from app.action_storage import NATIVE_EXTERNAL_ACTION_RESULT_SQL
            if self._email_unsubscribe_receipts_table_exists(db):
                receipt_exclusion = f"""
                  and not exists (
                      select 1
                      from ({email_action_projection('email_unsubscribe_receipts')}) as receipts
                      where tasks.channel='email'
                        and receipts.action_identity=tasks.trigger_message_id
                        and receipts.outcome in ({receipt_placeholders})
                  )
                """
                native_receipt_exclusion = f"""
                  and not exists (
                      select 1
                      from ({email_action_projection('email_unsubscribe_receipts')}) as receipts
                      where tasks.channel='email'
                        and receipts.action_identity=tasks.trigger_message_id
                        and receipts.outcome in ({receipt_placeholders})
                  )
                """
                receipt_parameters = terminal_unsubscribe_outcomes
            shared_exclusions = f"""
                and not exists (
                    select 1
                    from ({NATIVE_EXTERNAL_ACTION_RESULT_SQL}) as actions
                    where actions.business_object_key=tasks.business_object_key
                      and coalesce(json_extract(actions.provider_result_json, '$.verification.state'), 'sent')='sent'
                      and exists (
                          select 1
                          from ({SENT_REPLY_SQL}) as replies
                          where replies.external_action_key<>''
                            and replies.external_action_key=actions.external_action_key
                      )
                )
                and not exists (
                    select 1
                    from ({ERROR_SQL}) as settled
                    where settled.conversation_id=tasks.conversation_id
                      and settled.message_id=tasks.trigger_message_id
                      and settled.kind='reply_task_already_settled'
                      and trim(coalesce(settled.resolved_at, ''))<>''
                      and trim(coalesce(settled.resolution, ''))<>''
                )
                {receipt_exclusion}
            """
            native_shared_exclusions = f"""
                and not exists (
                    select 1
                    from ({NATIVE_EXTERNAL_ACTION_RESULT_SQL}) as actions
                    where actions.business_object_key=tasks.business_object_key
                      and coalesce(json_extract(actions.provider_result_json, '$.verification.state'), 'sent')='sent'
                      and exists (
                          select 1
                          from ({SENT_REPLY_SQL}) as replies
                          where replies.external_action_key<>''
                            and replies.external_action_key=actions.external_action_key
                      )
                )
                and not exists (
                    select 1
                    from ({ERROR_SQL}) as settled
                    where settled.conversation_id=tasks.conversation_id
                      and settled.message_id=tasks.trigger_message_id
                      and settled.kind='reply_task_already_settled'
                      and trim(coalesce(settled.resolved_at, ''))<>''
                      and trim(coalesce(settled.resolution, ''))<>''
                )
                {native_receipt_exclusion}
            """
            candidates = db.execute(
                f"""
                select tasks.id, tasks.execution_generation, runs.id as run_id,
                       runs.structured_error_json
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                join runs on runs.id=(
                    select latest.id
                    from runs as latest
                    where latest.task_id=tasks.id and latest.role in ('consumer','audit')
                      and latest.execution_generation=tasks.execution_generation
                    order by latest.id desc
                    limit 1
                )
                where tasks.status='done' and runs.status='failed'
                  {shared_exclusions}
                order by tasks.id
                """,
                receipt_parameters,
            ).fetchall()

        repaired = 0
        for offset in range(0, len(candidates), DONE_FAILED_RUN_RECONCILE_BATCH_SIZE):
            batch = candidates[offset:offset + DONE_FAILED_RUN_RECONCILE_BATCH_SIZE]
            batch_values = ", ".join("(?, ?, ?)" for _ in batch)
            batch_parameters = [
                value
                for row in batch
                for value in (row["id"], row["execution_generation"], row["run_id"])
            ]
            with self._immediate_write_transaction() as db:
                rows = db.execute(
                    f"""
                    with batch_candidates(task_id, execution_generation, run_id) as (
                        values {batch_values}
                    )
                    select tasks.id, tasks.execution_generation,
                           runs.id as run_id, runs.structured_error_json
                    from batch_candidates
                    join ({NATIVE_REPLY_TASK_CURRENT_SQL}) tasks
                      on tasks.id=batch_candidates.task_id
                    join runs on runs.id=batch_candidates.run_id
                    where tasks.status='done'
                      and tasks.execution_generation=batch_candidates.execution_generation
                      and runs.task_id=tasks.id
                      and runs.role in ('consumer','audit')
                      and runs.execution_generation=tasks.execution_generation
                      and runs.status='failed'
                      and runs.id=(
                          select latest.id
                          from runs as latest
                          where latest.task_id=tasks.id and latest.role in ('consumer','audit')
                            and latest.execution_generation=tasks.execution_generation
                          order by latest.id desc
                          limit 1
                      )
                      {native_shared_exclusions}
                    order by tasks.id
                    """,
                    [*batch_parameters, *receipt_parameters],
                ).fetchall()
                for row in rows:
                    from app import task_entity_storage
                    updated = task_entity_storage.update_task_cas(
                        db, task_id=int(row["id"]),
                        expected={"status": "done", "execution_generation": row["execution_generation"]},
                        changes={"status": "failed",
                                 "error": self._agent_run_failure_code(row["structured_error_json"]),
                                 "available_at": "", "locked_at": None,
                                 "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                    )
                    repaired += int(updated is not None)
        return repaired

    def reconcile_failed_reply_tasks_with_confirmation_required_runs(self) -> int:
        """Repair old confirmation projections as truthful technical failures.

        A provider-side confirmation refusal is not a business decision. It
        must remain a failed run and must never be turned into generic human
        choice buttons during service startup.
        """
        with self._immediate_write_transaction() as db:
            rows = db.execute(
                f"""
                select tasks.id, tasks.execution_generation, runs.id as run_id,
                       runs.structured_error_json
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                join runs on runs.id=(
                    select latest.id
                    from runs as latest
                    where latest.task_id=tasks.id and latest.role in ('consumer','audit')
                      and latest.execution_generation=tasks.execution_generation
                    order by latest.id desc
                    limit 1
                )
                where tasks.status='failed' and runs.status='failed'
                order by tasks.id
                """
            ).fetchall()
            reconciled = 0
            for row in rows:
                try:
                    payload = json.loads(str(row["structured_error_json"] or ""))
                except (TypeError, json.JSONDecodeError):
                    payload = {}
                if not isinstance(payload, dict) or not (
                    payload.get("authorization_required") is True
                    and payload.get("code") == "confirmation_required"
                ):
                    continue
                attempt_ids = [item[0] for item in db.execute(
                    f"select id from ({REPLY_ATTEMPT_COMMON_SQL}) "
                    "where agent_run_id=? and send_status='needs_human' "
                    "and send_error='confirmation_required'",
                    (row["run_id"],),
                )]
                now = db.execute("select current_timestamp").fetchone()[0]
                for attempt_id in attempt_ids:
                    cursor = update_action(db, "reply_attempts", attempt_id, {
                        "send_status": "failed", "send_error": "confirmation_required",
                        "codex_reason": "外部提供方拒绝执行：需要运行时确认；这不是业务决策，Agent 不会将其升级为 needs_human。",
                        "audit_summary": "外部提供方拒绝执行：需要运行时确认；这不是业务决策，未执行外部动作。",
                        "human_decision_options_json": "[]", "updated_at": now,
                    }, where_sql="agent_run_id=? and send_status='needs_human' "
                                 "and send_error='confirmation_required'",
                       parameters=(row["run_id"],))
                    reconciled += cursor.rowcount
                db.execute(
                    "update tasks set status='failed',error='confirmation_required',available_at='',"
                    "locked_at=null,updated_at=current_timestamp where kind='reply' and id=? "
                    "and execution_generation=? and status<>'failed'",
                    (row["id"], row["execution_generation"]),
                )
            return reconciled

    def reconcile_invalid_needs_human_projections(self) -> int:
        """Close current human projections whose approved candidate is invalid.

        A legacy input-only question can remain readable as historical evidence,
        but it is not a valid current needs-human result. Retain the candidate,
        review and run unchanged; only close the current task/Attempt projection
        so startup recovery cannot revive the question.
        """
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            rows = db.execute(f"""
                select t.id as task_id, t.execution_generation,
                       a.id as attempt_id, a.agent_run_id,
                       c.id as candidate_id, c.candidate_json,
                       r.audit_run_id
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) t
                join ({REVIEW_CANDIDATE_SQL}) c on c.task_id=t.id
                  and c.execution_generation=t.execution_generation
                  and c.invalidated_at=''
                join ({CANDIDATE_REVIEW_SQL}) r on r.candidate_id=c.id
                  and r.decision='approve' and r.candidate_digest=c.candidate_digest
                join ({REPLY_ATTEMPT_COMMON_SQL}) a on a.channel=t.channel
                  and a.conversation_id=t.conversation_id
                  and a.trigger_message_id=t.trigger_message_id
                left join ({CANDIDATE_SELECTION_SQL}) choice on choice.candidate_id=c.id
                where t.status='needs_human' and a.send_status='needs_human'
                  and a.reviewed_at is null and trim(coalesce(a.resolved_at,''))=''
                  and choice.id is null
                  and a.agent_run_id=r.audit_run_id
                  and c.id=(select max(newest.id) from ({REVIEW_CANDIDATE_SQL}) newest
                      where newest.task_id=t.id and newest.execution_generation=t.execution_generation)
                  and a.id=(select max(newest.id) from ({REPLY_ATTEMPT_COMMON_SQL}) newest
                      where newest.channel=t.channel and newest.conversation_id=t.conversation_id
                        and newest.trigger_message_id=t.trigger_message_id)
                  and exists(select 1 from task_business_keys current_object
                      where current_object.business_key=t.business_object_key
                        and current_object.task_id=t.id)
                order by t.id
            """).fetchall()
            reconciled = 0
            for row in rows:
                if self._is_actionable_needs_human_candidate(row["candidate_json"]):
                    continue

                task_cursor = task_entity_storage.update_task_cas(
                    db, task_id=int(row["task_id"]),
                    expected={"status": "needs_human",
                              "execution_generation": row["execution_generation"]},
                    changes={"status": "failed", "error": "invalid_needs_human_projection",
                             "available_at": "", "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if task_cursor is None:
                    continue
                attempt_cursor = update_action(
                    db,
                    "reply_attempts",
                    row["attempt_id"],
                    {
                        "send_status": "failed",
                        "send_error": "invalid_needs_human_projection",
                        "human_decision_options_json": "[]",
                        "updated_at": db.execute(
                            "select current_timestamp"
                        ).fetchone()[0],
                    },
                    where_sql="agent_run_id=? and send_status='needs_human' "
                    "and reviewed_at is null and trim(coalesce(resolved_at,''))=''",
                    parameters=(row["audit_run_id"],),
                )
                reconciled += attempt_cursor.rowcount
            return reconciled

    @staticmethod
    def _is_actionable_needs_human_candidate(candidate_json: object) -> bool:
        """Recognize only a current reusable task-class rule question."""
        from app.agent_contracts import ConsumerOutcome, parse_persisted_consumer_result

        try:
            candidate = parse_persisted_consumer_result(
                str(candidate_json or "")
            )
        except ValueError:
            return False
        return (
            candidate.outcome is ConsumerOutcome.NEEDS_HUMAN
            and candidate.requested_input is None
            and 2 <= len(candidate.decision_options) <= 4
            and all(
                option.applies_to == "task_class"
                for option in candidate.decision_options
            )
        )

    def reconcile_valid_needs_human_projections(self) -> int:
        """Restore only a current, unselected, Audit-approved persisted question.

        A raw Consumer or Audit result is never sufficient authority, and old
        generations and previously resolved attempts are left untouched.
        """
        with self._immediate_write_transaction() as db:
            rows = db.execute(f"""
                select t.id as task_id, t.execution_generation, t.status as task_status,
                       a.id as attempt_id, a.send_status, a.agent_run_id,
                       c.id as candidate_id, c.candidate_json, c.candidate_digest,
                       r.id as review_id, r.audit_run_id
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) t
                join ({REVIEW_CANDIDATE_SQL}) c on c.task_id=t.id
                  and c.execution_generation=t.execution_generation
                  and c.invalidated_at=''
                join ({CANDIDATE_REVIEW_SQL}) r on r.candidate_id=c.id
                  and r.decision='approve' and r.candidate_digest=c.candidate_digest
                join ({REPLY_ATTEMPT_COMMON_SQL}) as a on a.channel=t.channel
                  and a.conversation_id=t.conversation_id
                  and a.trigger_message_id=t.trigger_message_id
                left join ({CANDIDATE_SELECTION_SQL}) choice on choice.candidate_id=c.id
                where t.status in ('failed','needs_human')
                  and a.send_status in ('failed','needs_human')
                  and a.reviewed_at is null and trim(coalesce(a.resolved_at,''))=''
                  and choice.id is null
                  and c.id=(select max(newest.id) from ({REVIEW_CANDIDATE_SQL}) newest
                      where newest.task_id=t.id and newest.execution_generation=t.execution_generation)
                  and a.id=(select max(newest.id) from ({REPLY_ATTEMPT_COMMON_SQL}) as newest
                      where newest.channel=t.channel and newest.conversation_id=t.conversation_id
                        and newest.trigger_message_id=t.trigger_message_id)
                  and exists(select 1 from task_business_keys current_object
                      where current_object.business_key=t.business_object_key
                        and current_object.task_id=t.id)
            """).fetchall()
            from app import task_entity_storage
            reconciled = 0
            for row in rows:
                try:
                    candidate = json.loads(row["candidate_json"])
                except (TypeError, json.JSONDecodeError):
                    continue

                if not self._is_actionable_needs_human_candidate(
                    json.dumps(candidate, ensure_ascii=False)
                ):
                    continue
                # A completed Audit run identifies the exact reviewed question.
                # Never bind a failed projection to a different run.
                if row["agent_run_id"] != row["audit_run_id"]:
                    continue
                if row["send_status"] == "needs_human" and row["task_status"] == "needs_human":
                    continue
                update_action(db, "reply_attempts", row["attempt_id"], {
                    "send_status": "needs_human", "send_error": "",
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                }, where_sql="agent_run_id=? and send_status='failed'",
                   parameters=(row["audit_run_id"],))
                updated = task_entity_storage.update_task_cas(
                    db, task_id=int(row["task_id"]),
                    expected={"status": "failed",
                              "execution_generation": row["execution_generation"]},
                    changes={"status": "needs_human", "error": "",
                             "available_at": "", "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                reconciled += int(updated is not None)
            return reconciled

    @staticmethod
    def _authorization_plan_matches_attempt(
        decision: object,
        *,
        oa_process_instance_id: str,
        oa_task_id: str,
    ) -> bool:
        plan = getattr(decision, "authorization_plan", None)
        if plan is None:
            return True
        target = plan.primary_action.target
        for field, value in (
            ("oa_process_instance_id", oa_process_instance_id),
            ("oa_task_id", oa_task_id),
        ):
            if value and str(target.get(field) or "") != value:
                return False
        return True


    def skip_failed_reply_tasks_superseded_by_terminal_business_object(self) -> int:
        """Close obsolete local projections once another task owns the business object.

        OA scans can create a new trigger for the same process/task pair.  Once
        the canonical business-object mapping points at a different terminal
        task, retaining the earlier failed task or human-decision Attempt as
        current attention is false: the newer task is the current lifecycle
        owner.  This never closes a decision belonging to that current task;
        it only retires an Attempt whose own Agent run belongs to an older task.
        """
        terminal_attempt_statuses = tuple(
            SUPERSEDED_HUMAN_ATTEMPT_SUCCESSOR_STATUSES
        )
        terminal_attempt_placeholders = ", ".join(
            "?" for _ in terminal_attempt_statuses
        )
        with self._immediate_write_transaction() as db:
            skipped_tasks = db.execute(
                f"""
                select historical.id,historical.execution_generation
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) historical
                where historical.status='failed' and exists (
                    select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) current_task
                    where current_task.business_object_key=historical.business_object_key
                      and current_task.id<>historical.id
                      and current_task.status in ('done','skipped','needs_human'))
                order by historical.id
                """
            ).fetchall()
            skipped_task_ids: list[int] = []
            for task in skipped_tasks:
                updated = task_entity_storage.update_task_cas(
                    db, task_id=int(task["id"]),
                    expected={"status": "failed", "execution_generation": task["execution_generation"]},
                    changes={"status": "skipped", "error": "superseded_by_terminal_business_object_task",
                             "available_at": "", "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if updated is not None:
                    skipped_task_ids.append(int(task["id"]))
            superseded_attempts = db.execute(
                f"""
                select historical_attempt.id
                from ({REPLY_ATTEMPT_COMMON_SQL}) as historical_attempt
                where historical_attempt.send_status='needs_human'
                  and trim(coalesce(historical_attempt.resolved_at, ''))=''
                  and exists (
                      select 1
                      from runs as source_run
                      join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as source_task
                        on source_task.id=source_run.task_id
                       and source_run.role in ('consumer','audit')
                      join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                        on current_task.business_object_key=source_task.business_object_key
                      where source_run.id=historical_attempt.agent_run_id
                        and source_run.status in ('completed', 'failed')
                        and current_task.id<>source_task.id
                        and current_task.status in ('done', 'skipped', 'needs_human')
                  )
                """
            ).fetchall()
            now = db.execute("select current_timestamp").fetchone()[0]
            attempt_count = 0
            for attempt in superseded_attempts:
                attempt_count += update_action(db, "reply_attempts", attempt["id"], {
                    "send_status": "skipped", "send_error": "",
                    "resolved_at": now,
                    "resolution": "同一业务对象已由新的终态任务接管；原人工决策不再有效。",
                    "updated_at": now,
                }).rowcount
            trigger_attempts = db.execute(
                f"""
                select historical_attempt.id
                from ({REPLY_ATTEMPT_COMMON_SQL}) as historical_attempt
                where historical_attempt.send_status='needs_human'
                  and trim(coalesce(historical_attempt.resolved_at, ''))=''
                  and exists (
                      select 1
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest_attempt
                      where latest_attempt.channel=historical_attempt.channel
                        and latest_attempt.conversation_id=
                            historical_attempt.conversation_id
                        and latest_attempt.trigger_message_id=
                            historical_attempt.trigger_message_id
                        and latest_attempt.id<>(historical_attempt.id)
                        and latest_attempt.id=(
                            select newest.id
                            from ({REPLY_ATTEMPT_COMMON_SQL}) as newest
                            where newest.channel=historical_attempt.channel
                              and newest.conversation_id=
                                  historical_attempt.conversation_id
                              and newest.trigger_message_id=
                                  historical_attempt.trigger_message_id
                            order by datetime(newest.updated_at) desc, newest.id desc
                            limit 1
                        )
                        and latest_attempt.send_status in
                            ({terminal_attempt_placeholders})
                  )
                """,
                terminal_attempt_statuses,
            ).fetchall()
            trigger_attempt_count = 0
            for attempt in trigger_attempts:
                trigger_attempt_count += update_action(db, "reply_attempts", attempt["id"], {
                    "send_status": "skipped", "send_error": "",
                    "resolved_at": now,
                    "resolution": "同一触发的后续处理已终态；原人工决策不再有效。",
                    "updated_at": now,
                }).rowcount
            for task_id in skipped_task_ids:
                self._compact_settled_reply_task_input(db, task_id)
            return (
                len(skipped_task_ids)
                + attempt_count
                + trigger_attempt_count
            )

    def reconcile_unresolved_reply_tasks_with_terminal_attempts(self) -> int:
        """Project the latest terminal trigger attempt onto a stale task.

        A reply attempt records the business outcome for one exact channel,
        conversation, and trigger message.  If its latest state is terminal,
        a stale failed or needs-human reply-task projection cannot remain
        current: it would show the same work both as settled in History and as
        unresolved. A failed attempt with persisted resolution evidence is
        also settled. This only changes the local projection; it never invokes
        a provider or replays the original action.
        """
        statuses = tuple(TERMINAL_REPLY_ATTEMPT_TASK_STATUSES)
        placeholders = ", ".join("?" for _ in statuses)
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            rows = db.execute(
                f"""
                select tasks.id, tasks.status, tasks.execution_generation,
                       attempts.send_status, attempts.resolved_at
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                join ({REPLY_ATTEMPT_COMMON_SQL}) as attempts on attempts.id=(
                    select latest.id
                    from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                    where latest.channel=tasks.channel
                      and latest.conversation_id=tasks.conversation_id
                      and latest.trigger_message_id=tasks.trigger_message_id
                    order by latest.id desc
                    limit 1
                )
                where tasks.status in ('failed', 'needs_human')
                  and tasks.error not in ('external_action_uncertain', 'external_action_failed')
                  and (
                      attempts.send_status in ({placeholders})
                      or (
                          attempts.send_status='failed'
                          and trim(coalesce(attempts.resolved_at, ''))<>''
                      )
                  )
                order by tasks.id
                """,
                statuses,
            ).fetchall()
            reconciled = 0
            for row in rows:
                attempt_status = str(row["send_status"])
                task_status = (
                    "done"
                    if attempt_status == "failed"
                    else TERMINAL_REPLY_ATTEMPT_TASK_STATUSES[attempt_status]
                )
                current_status = str(row["status"])
                if task_status == current_status:
                    continue
                # Keep why it failed. Clearing the error here is what made
                # the weekly report's lost week unreadable: the task ended
                # `skipped` with an empty error, and nothing in its record
                # said a provider overload had cut it short. The outcome is
                # settled either way; the reason is the only thing that tells
                # anyone whether it settled the way it should have.
                current = task_entity_storage.get_task(db, int(row["id"]))
                if current is None:
                    continue
                error = str(current["error"] or "")
                changed = task_entity_storage.update_task_cas(
                    db, task_id=int(row["id"]),
                    expected={"status": current_status,
                              "execution_generation": row["execution_generation"]},
                    changes={"status": task_status, "available_at": "", "locked_at": None,
                             "error": (f"reconciled_from_{current_status}:" + error) if error else "",
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if changed is not None:
                    reconciled += 1
                    self._compact_settled_reply_task_input(db, int(row["id"]))
            return reconciled

    def skip_failed_reply_tasks_with_terminal_no_action_run(self) -> int:
        """Close failures whose final run already proves no action remains."""
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            rows = db.execute(
                f"""select tasks.id,tasks.execution_generation,runs.structured_error_json
                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) tasks
                join runs on runs.id=(select latest.id from runs latest
                  where latest.task_id=tasks.id and latest.role in ('consumer','audit')
                    and latest.execution_generation=tasks.execution_generation
                  order by latest.id desc limit 1)
                where tasks.status='failed' and runs.status='failed'
                order by tasks.id"""
            ).fetchall()
            skipped = 0
            for row in rows:
                code = self._agent_run_failure_code(row["structured_error_json"])
                if code not in TERMINAL_NO_ACTION_RUN_FAILURE_CODES:
                    continue
                updated = task_entity_storage.update_task_cas(
                    db, task_id=int(row["id"]),
                    expected={"status": "failed", "execution_generation": row["execution_generation"]},
                    changes={"status": "skipped", "error": f"skipped_terminal_no_action:{code}",
                             "available_at": "", "locked_at": None,
                             "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                )
                if updated is not None:
                    skipped += 1
                    self._compact_settled_reply_task_input(db, int(row["id"]))
            return skipped

    def finalize_reply_task_without_run(
        self,
        *,
        task_id: int,
        expected_execution_generation: str,
        task_status: str,
        task_error: str,
        available_at: str,
        conversation_id: str,
        conversation_title: str,
        trigger_message_id: str,
        trigger_sender: str,
        trigger_text: str,
        codex_reason: str,
        audit_summary: str,
        send_status: str,
        send_error: str,
        channel: str,
    ) -> int:
        """Persist a pre-run failure and its generation-bound task transition."""
        if task_status not in {"failed", "pending"}:
            raise ValueError("invalid pre-run reply task status")
        if not expected_execution_generation.strip():
            raise ValueError("expected_execution_generation must be non-empty")
        with self._immediate_write_transaction() as db:
            task = self._native_current_reply_task(db, task_id)
            if (
                task is None
                or task["status"] != "processing"
                or task["execution_generation"] != expected_execution_generation
            ):
                raise AgentRunLeaseLostError(f"reply task superseded: {task_id}")
            persisted_oa_url = str(task["current_input"]["oa_url"] or "").strip()
            process_instance_id, oa_task_id = self._oa_identifiers_from_url(
                persisted_oa_url
            )
            current_attempt = db.execute(
                f"""
                select id
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where channel=? and conversation_id=? and trigger_message_id=?
                order by id desc
                limit 1
                """,
                (channel, conversation_id, trigger_message_id),
            ).fetchone()
            projection_values = {
                "conversation_id": conversation_id,
                "conversation_title": conversation_title,
                "trigger_message_id": trigger_message_id,
                "trigger_sender": trigger_sender,
                "trigger_text": trigger_text,
                "action": "agent_run", "sensitivity_kind": "general",
                "codex_reason": codex_reason, "audit_summary": audit_summary,
                "oa_process_instance_id": process_instance_id,
                "oa_task_id": oa_task_id, "oa_url": persisted_oa_url,
                "oa_action": "review" if process_instance_id else "",
                "send_status": send_status, "send_error": send_error,
            }
            if current_attempt is None:
                result = insert_action(db, "reply_attempts", {
                    **projection_values, "channel": channel,
                })
                attempt_id = int(result.lastrowid)
            else:
                attempt_id = int(current_attempt["id"])
                update_action(db, "reply_attempts", attempt_id, {
                    **projection_values, "final_reply_text": "",
                    "permission_action": "", "permission_reason": "",
                    "retry_count": 0,
                    "updated_at": db.execute("select current_timestamp").fetchone()[0],
                })
            from app import task_entity_storage
            task_cursor = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                expected={"status": "processing", "execution_generation": expected_execution_generation},
                changes={"status": task_status, "locked_at": None,
                         "available_at": available_at if task_status == "pending" else "",
                         "error": task_error,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
            )
            if task_cursor is None:
                raise AgentRunLeaseLostError(f"reply task superseded: {task_id}")
            return attempt_id

    def reply_task_is_done(self, task_id: int) -> bool:
        with self._connect() as db:
            row = db.execute(
                "select status from tasks where id=? and kind='reply'",
                (task_id,),
            ).fetchone()
        return bool(row and row["status"] == "done")

    def list_memory_write_events_for_attempt(
        self,
        attempt_id: int,
    ) -> list[MemoryWriteEvent]:
        with self._connect() as db:
            memory_sql = current_reply_action_projection("memory_write_events")
            rows = db.execute(
                f"""
                select *
                from ({memory_sql}) as memory_write_events
                where attempt_id=?
                order by id
                """,
                (attempt_id,),
            ).fetchall()
        return [MemoryWriteEvent.model_validate(dict(row)) for row in rows]

    @staticmethod
    def _record_memory_write_events_in_connection(
        db: sqlite3.Connection,
        attempt_id: int,
        audit_tool_events_json: str,
    ) -> None:
        try:
            audit_events = json.loads(audit_tool_events_json or "[]")
        except json.JSONDecodeError:
            audit_events = []
        if not isinstance(audit_events, list):
            audit_events = []
        tool_outputs_by_call_id = {
            str(event.get("call_id") or ""): str(event.get("output") or "")
            for event in audit_events
            if isinstance(event, dict)
            and str(event.get("tool") or "") == "tool_output"
            and str(event.get("call_id") or "")
            and str(event.get("output") or "")
        }
        memory_events = [
            AutoReplyStore._memory_write_event_from_audit_event(
                event,
                tool_outputs_by_call_id=tool_outputs_by_call_id,
            )
            for event in audit_events
            if isinstance(event, dict)
        ]
        memory_events = [event for event in memory_events if event is not None]
        memory_sql = current_reply_action_projection("memory_write_events")
        previous_ids = [row[0] for row in db.execute(
            f"select id from ({memory_sql}) as memory_write_events where attempt_id=?",
            (attempt_id,),
        )]
        for event_id in previous_ids:
            delete_action(db, "memory_write_events", event_id)
        event_type_counts: dict[str, int] = {}
        for event in memory_events:
            base_event_type = event["event_type"]
            count = event_type_counts.get(base_event_type, 0) + 1
            event_type_counts[base_event_type] = count
            event_type = base_event_type if count == 1 else f"{base_event_type}_{count}"
            insert_action(db, "memory_write_events", {
                "attempt_id": attempt_id,
                "event_type": event_type,
                "status": event["status"],
                "attempts": 1,
                "last_error": event["last_error"],
                "memory_episode_id": event["memory_episode_id"],
            })

    @staticmethod
    def _memory_write_event_from_audit_event(
        event: dict[str, object],
        *,
        tool_outputs_by_call_id: dict[str, str] | None = None,
    ) -> dict[str, str] | None:
        tool = str(event.get("tool") or "")
        if not AutoReplyStore._is_memory_write_tool_name(tool):
            return None
        output = str(event.get("output") or "")
        call_id = str(event.get("call_id") or "")
        if not output and call_id and tool_outputs_by_call_id:
            output = tool_outputs_by_call_id.get(call_id, "")
        parsed_output = AutoReplyStore._parse_memory_write_output(
            output
        )
        status = parsed_output.get("status") or "pending"
        return {
            "event_type": "memory_write",
            "status": status,
            "last_error": parsed_output.get("last_error") or "",
            "memory_episode_id": parsed_output.get("memory_episode_id") or "",
        }

    @staticmethod
    def _is_memory_write_tool_name(tool: str) -> bool:
        normalized = tool.strip()
        return normalized == "memory_write" or normalized.endswith(
            (".memory_write", "__memory_write", " memory_write")
        )

    @staticmethod
    def _parse_memory_write_output(output: str) -> dict[str, str]:
        if not output.strip():
            return {}
        payload = AutoReplyStore._load_memory_json(output)
        if not isinstance(payload, dict):
            return {}
        result = payload.get("structured_content")
        if isinstance(result, dict):
            nested = AutoReplyStore._load_memory_json(str(result.get("result") or ""))
            if isinstance(nested, dict):
                payload = nested
        elif isinstance(payload.get("result"), str):
            nested = AutoReplyStore._load_memory_json(str(payload.get("result") or ""))
            if isinstance(nested, dict):
                payload = nested
        elif isinstance(payload.get("content"), list):
            for item in payload["content"]:
                if not isinstance(item, dict):
                    continue
                nested = AutoReplyStore._load_memory_json(str(item.get("text") or ""))
                if isinstance(nested, dict):
                    payload = nested
                    break
        processing_status = str(payload.get("processing_status") or "").casefold()
        ok = payload.get("ok") is True
        if processing_status == "failed" or payload.get("ok") is False:
            status = "failed"
        else:
            status = "pending"
        memory_episode_id = str(
            payload.get("episode_uuid")
            or payload.get("uuid")
            or payload.get("memory_episode_id")
            or payload.get("duplicate_of_episode_uuid")
            or ""
        )
        if memory_episode_id and (
            ok
            or payload.get("failure_kind") == "duplicate_memory_write"
            or processing_status in {"completed", "success", "done", "ready"}
        ):
            status = "written"
        last_error = str(payload.get("last_error") or payload.get("error") or "")
        processing_statuses = payload.get("processing_statuses")
        if not last_error and isinstance(processing_statuses, list):
            for item in processing_statuses:
                if not isinstance(item, dict):
                    continue
                last_error = str(item.get("last_error") or item.get("error") or "")
                if last_error:
                    break
        return {
            "status": status,
            "memory_episode_id": memory_episode_id,
            "last_error": last_error,
        }

    @staticmethod
    def _load_memory_json(raw: str) -> object | None:
        text = raw.strip()
        if not text:
            return None
        if "\nOutput:\n" in text:
            text = text.rsplit("\nOutput:\n", 1)[1].strip()
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            return None

    @staticmethod
    def _reply_attempt_update_values(**updates: object) -> dict[str, object]:
        allowed_columns = {
            "action",
            "final_reply_text",
            "permission_action",
            "permission_reason",
            "direct_user_id",
            "direct_open_dingtalk_id",
            "oa_process_instance_id",
            "oa_task_id",
            "oa_url",
            "oa_action",
            "oa_remark",
            "oa_action_result_json",
            "calendar_event_id",
            "calendar_response_status",
            "calendar_response_result_json",
            "mail_mailbox",
            "mail_message_id",
            "mail_subject",
            "mail_reply_text",
            "mail_action_result_json",
            "reaction_action_result_json",
            "document_action_result_json",
            "audit_tool_events_json",
            "audit_summary",
            "human_decision_options_json",
            "send_status",
            "send_error",
            "retry_count",
            "feedback_scope",
            "skill_update_requested",
            "skill_update_receipts_json",
        }
        unknown = set(updates) - allowed_columns
        if unknown:
            raise ValueError(
                "unknown reply_attempt update column: "
                + ", ".join(sorted(unknown))
            )
        return {column: (_audit_event_metadata_json(str(value)) if column == "audit_tool_events_json" else value)
                for column, value in updates.items() if value is not None}

    @staticmethod
    def _update_reply_attempt_in_connection(
        db: sqlite3.Connection,
        attempt_id: int,
        updates: dict[str, object],
    ) -> None:
        db.execute("update sqlite_sequence set seq=seq where 0")
        updated_at = db.execute("select current_timestamp").fetchone()[0]
        update_action(db, "reply_attempts", attempt_id,
                      {**updates, "updated_at": updated_at})

    def record_reply_feedback(
        self,
        attempt_id: int,
        *,
        feedback: str,
        corrected_reply_text: str = "",
    ) -> bool:
        with self._connect() as db:
            db.execute("update sqlite_sequence set seq=seq where 0")
            now = db.execute("select current_timestamp").fetchone()[0]
            cursor = update_action(db, "reply_attempts", attempt_id, {
                "reviewer_feedback": feedback,
                "corrected_reply_text": corrected_reply_text,
                "reviewed_at": now, "updated_at": now,
            })
            return cursor.rowcount == 1

    def resolve_needs_human_attempt(
        self,
        attempt_id: int,
        *,
        reviewer_feedback: str,
    ) -> bool:
        with self._connect() as db:
            db.execute("update sqlite_sequence set seq=seq where 0")
            now = db.execute("select current_timestamp").fetchone()[0]
            cursor = update_action(db, "reply_attempts", attempt_id, {
                "send_status": "decision_selected", "send_error": "",
                "reviewer_feedback": reviewer_feedback,
                "reviewed_at": now, "updated_at": now,
            }, where_sql="send_status='needs_human'")
            return cursor.rowcount == 1

    def close_needs_human_task_with_decision(
        self, task_id: int, *, decision: str
    ) -> bool:
        """Record that a person answered the question and close the task.

        A `needs_human` task has no way back to a terminal state on its own:
        the retry path refuses it, which is right -- re-running something
        handed to a person can repeat an irreversible action. But an answered
        question has to be able to close, or the page fills with questions
        that were settled in conversation and nowhere else.
        """
        decision = decision.strip()
        if not decision:
            raise ValueError("decision must be non-empty")
        with self._immediate_write_transaction() as db:
            from app import task_entity_storage
            task = task_entity_storage.get_task(db, task_id)
            if task is None:
                return False
            updated = task_entity_storage.update_task_cas(
                db, task_id=task_id,
                expected={"kind": task["kind"], "status": "needs_human"},
                changes={"status": "done", "error": f"human_decision:{decision}"[:500],
                         "available_at": "", "locked_at": None,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]},
                parameters=task["parameters"],
            )
            if updated is None:
                return False
            # The attempt has to leave `failed` too. A reconciliation sweep
            # projects the task from its attempt, so a task closed here with
            # the attempt still reading `failed` was put straight back to
            # failed by the next pass -- 384446 and 384447 reopened one minute
            # after they were answered.
            attempts = db.execute(
                f"select id,send_status from ({REPLY_ATTEMPT_COMMON_SQL}) "
                f"where agent_run_id in (select id from ({AGENT_RUN_SQL}) "
                "where reply_task_id=?)", (task_id,),
            ).fetchall()
            now = db.execute("select current_timestamp").fetchone()[0]
            for attempt in attempts:
                update_action(db, "reply_attempts", attempt["id"], {
                    "send_status": ("decision_selected" if attempt["send_status"]
                                    in ("failed", "needs_human") else attempt["send_status"]),
                    "send_error": "", "reviewer_feedback": decision,
                    "reviewed_at": now, "resolved_at": now, "updated_at": now,
                })
            self._compact_settled_reply_task_input(db, task_id)
            return True

    def record_reviewed_reply_rerun(
        self,
        *,
        conversation_id: str,
        conversation_title: str,
        single_chat: bool,
        trigger_message_id: str,
        trigger_create_time: str,
        trigger_sender: str,
        trigger_text: str,
        trigger_message_json: str,
        suggested_reply_text: str,
        reviewer_feedback: str = "",
        channel: str = "dingtalk",
        oa_url: str = "",
        source_attempt_id: int = 0,
        review_candidate_id: int = 0,
        supplement_instruction: str = "",
    ) -> tuple[int, ReplyTask]:
        """Atomically persist one reviewed instruction and queue its generation."""
        feedback = reviewer_feedback.strip()
        suggestion = suggested_reply_text.strip()
        task: ReplyTask | None = None
        attempt_id = 0
        with self._immediate_write_transaction() as db:
            if review_candidate_id > 0:
                candidate = self._candidate_context(db, review_candidate_id)
                source_review = db.execute(f"""select r.id from ({CANDIDATE_REVIEW_SQL}) r
                    where r.candidate_id=? and r.decision='approve'
                      and r.candidate_digest=? and r.audit_run_id=(
                        select agent_run_id from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?)""",
                    (review_candidate_id, candidate["candidate_digest"], source_attempt_id)).fetchone()
                if (not supplement_instruction.strip() or source_review is None
                    or candidate["invalidated_at"] or not source_attempt_id
                    or db.execute(f"select 1 from ({CANDIDATE_SELECTION_SQL}) where candidate_id=?",
                                  (review_candidate_id,)).fetchone()):
                    raise ValueError("reviewed candidate supplement mismatch")
                self._persist_candidate_supplement(db, candidate, supplement_instruction)
            source_row = None
            if source_attempt_id > 0:
                source_row = db.execute(
                    f"select * from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?",
                    (source_attempt_id,),
                ).fetchone()
                if source_row is None:
                    raise ValueError("actionable attempt does not exist")
                source_status = str(source_row["send_status"] or "")
                if source_status == "decision_selected":
                    if str(source_row["reviewer_feedback"] or "") != feedback:
                        raise ValueError("attempt decision was already selected")
                elif source_status not in {"failed", "needs_human", "pending"}:
                    raise ValueError("attempt no longer requires a decision")
                # A reviewed decision rewrites the source attempt in place.
                # The execution generation changes on the task, but the
                # business attempt id and Codex conversation session remain
                # stable; do not create a second reply_attempt row.
                audit_summary = (
                    "Reviewer feedback: "
                    + feedback
                    + "\nSuggested response: "
                    + suggestion
                ).strip()
                # The attempt row is the current projection, but its audit
                # events are historical evidence.  Keep the prior events and
                # append the review enqueue marker instead of replacing the
                # evidence captured by the original run.
                try:
                    prior_events = json.loads(
                        str(source_row["audit_tool_events_json"] or "[]")
                    )
                except (TypeError, json.JSONDecodeError):
                    prior_events = []
                if not isinstance(prior_events, list):
                    prior_events = []
                queued_events = [*prior_events, {"tool": "audit_review", "result": "queued"}]
                now = db.execute("select current_timestamp").fetchone()[0]
                update_action(db, "reply_attempts", source_attempt_id, {
                    "action": "send_reply",
                    "codex_reason": "reviewed_message_reply",
                    "draft_reply_text": suggestion,
                    "audit_tool_events_json": json.dumps(
                        queued_events, ensure_ascii=False, separators=(",", ":")),
                    "audit_summary": audit_summary,
                    "reviewer_feedback": feedback,
                    "corrected_reply_text": suggestion,
                    "reviewed_at": now, "send_status": "pending",
                    "send_error": "", "updated_at": now,
                })
                revision_key = self._manual_rerun_revision_key(
                    db, source_attempt_id
                )
                task = self._enqueue_manual_rerun_reply_task_in_connection(
                    db,
                    conversation_id=conversation_id,
                    conversation_title=conversation_title,
                    single_chat=single_chat,
                    trigger_message_id=trigger_message_id,
                    trigger_create_time=trigger_create_time,
                    trigger_sender=trigger_sender,
                    trigger_text=trigger_text,
                    trigger_message_json=trigger_message_json,
                    oa_url=oa_url,
                    attempt_id=source_attempt_id,
                    revision_key=revision_key,
                    channel=channel,
                )
                return source_attempt_id, task
            existing = db.execute(
                f"""
                select attempts.id as attempt_id, tasks.*
                from ({REPLY_TASK_CURRENT_SQL}) as tasks
                join ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                  on attempts.id=tasks.manual_rerun_attempt_id
                where tasks.channel=?
                  and tasks.conversation_id=?
                  and tasks.trigger_message_id=?
                  and tasks.status in ('pending', 'processing')
                  and attempts.codex_reason='reviewed_message_reply'
                  and attempts.reviewer_feedback=?
                  and attempts.corrected_reply_text=?
                limit 1
                """,
                (
                    channel,
                    conversation_id,
                    trigger_message_id,
                    feedback,
                    suggestion,
                ),
            ).fetchone()
            if existing is not None:
                if source_attempt_id > 0:
                    self._resolve_actionable_attempt_in_connection(
                        db,
                        source_attempt_id,
                        reviewer_feedback=feedback,
                    )
                return int(existing["attempt_id"]), self._reply_task_from_row(existing)

            current_task = db.execute(
                f"""
                select * from ({REPLY_TASK_CURRENT_SQL}) as reply_tasks
                where channel=? and conversation_id=? and trigger_message_id=?
                """,
                (channel, conversation_id, trigger_message_id),
            ).fetchone()
            if current_task is not None:
                task = self._reply_task_from_row(current_task)

            audit_summary = (
                "Reviewer feedback: "
                + feedback
                + "\nSuggested response: "
                + suggestion
            ).strip()
            result = insert_action(db, "reply_attempts", {
                "conversation_id": conversation_id,
                "conversation_title": conversation_title,
                "trigger_message_id": trigger_message_id,
                "trigger_sender": trigger_sender,
                "trigger_text": trigger_text,
                "action": "send_reply", "sensitivity_kind": "general",
                "codex_reason": "reviewed_message_reply",
                "draft_reply_text": suggestion,
                "audit_tool_events_json": json.dumps(
                    [{"tool": "audit_review", "result": "queued"}], ensure_ascii=False),
                "audit_summary": audit_summary,
                "reviewer_feedback": feedback,
                "corrected_reply_text": suggestion,
                "reviewed_at": db.execute("select current_timestamp").fetchone()[0],
                "send_status": "pending", "channel": channel,
            })
            attempt_id = int(result.lastrowid)
            revision_key = self._manual_rerun_revision_key(db, attempt_id)
            task = self._enqueue_manual_rerun_reply_task_in_connection(
                db,
                conversation_id=conversation_id,
                conversation_title=conversation_title,
                single_chat=single_chat,
                trigger_message_id=trigger_message_id,
                trigger_create_time=trigger_create_time,
                trigger_sender=trigger_sender,
                trigger_text=trigger_text,
                trigger_message_json=trigger_message_json,
                oa_url=oa_url,
                attempt_id=attempt_id,
                revision_key=revision_key,
                channel=channel,
            )
            if source_attempt_id > 0:
                self._resolve_actionable_attempt_in_connection(
                    db,
                    source_attempt_id,
                    reviewer_feedback=feedback,
                )
        return attempt_id, task

    @staticmethod
    def _resolve_actionable_attempt_in_connection(
        db: sqlite3.Connection,
        attempt_id: int,
        *,
        reviewer_feedback: str,
    ) -> None:
        now = db.execute("select current_timestamp").fetchone()[0]
        cursor = update_action(db, "reply_attempts", attempt_id, {
            "send_status": "decision_selected", "send_error": "",
            "reviewer_feedback": reviewer_feedback,
            "reviewed_at": now, "updated_at": now,
        }, where_sql="send_status in ('failed', 'needs_human')")
        if cursor.rowcount == 1:
            return
        row = db.execute(
            f"select send_status, reviewer_feedback from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?",
            (attempt_id,),
        ).fetchone()
        if (
            row is not None
            and row["send_status"] == "decision_selected"
            and str(row["reviewer_feedback"] or "") == reviewer_feedback
        ):
            return
        raise ValueError("attempt no longer requires a decision")

    def record_actionable_attempt_decision(
        self,
        source_attempt_id: int,
        *,
        reviewer_feedback: str,
        conversation_title: str,
        single_chat: bool,
        trigger_create_time: str,
        trigger_message_json: str,
        trigger_text: str | None = None,
        review_candidate_id: int = 0,
        supplement_instruction: str = "",
    ) -> tuple[int, ReplyTask]:
        feedback = reviewer_feedback.strip()
        if not feedback:
            raise ValueError("reviewer feedback must be non-empty")
        source = self.get_reply_attempt(source_attempt_id)
        if source is None:
            raise ValueError("actionable attempt does not exist")
        if trigger_text is None and source.trigger_text_provenance_json != "{}":
            raise ValueError("original reply task input is unavailable")
        return self.record_reviewed_reply_rerun(
            conversation_id=source.conversation_id,
            conversation_title=conversation_title,
            single_chat=single_chat,
            trigger_message_id=source.trigger_message_id,
            trigger_create_time=trigger_create_time,
            trigger_sender=source.trigger_sender,
            trigger_text=source.trigger_text if trigger_text is None else trigger_text,
            trigger_message_json=trigger_message_json,
            suggested_reply_text="",
            reviewer_feedback=feedback,
            channel=source.channel or "dingtalk",
            oa_url=source.oa_url,
            source_attempt_id=source_attempt_id,
            review_candidate_id=review_candidate_id,
            supplement_instruction=supplement_instruction,
        )

    def list_recorded_oa_results(
        self, attempt_ids: Sequence[int]
    ) -> list[dict[str, object]]:
        """Read factual receipt metadata through each exact Attempt reference."""
        from app.oa_history_storage import list_recorded_oa_results
        with self._connect() as db:
            return list_recorded_oa_results(db, attempt_ids)

    def get_reply_attempt(self, attempt_id: int) -> ReplyAttempt | None:
        with self._connect() as db:
            row = db.execute(
                f"select * from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id=?",
                (attempt_id,),
            ).fetchone()
            if row is None:
                return None
            return ReplyAttempt.model_validate(dict(row))

    def get_latest_reply_attempt_for_trigger(
        self, conversation_id: str, trigger_message_id: str
    ) -> ReplyAttempt | None:
        with self._connect() as db:
            row = db.execute(
                f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where conversation_id=? and trigger_message_id=?
                order by id desc
                limit 1
                """,
                (conversation_id, trigger_message_id),
            ).fetchone()
            if row is None:
                return None
            return ReplyAttempt.model_validate(dict(row))

    @staticmethod
    def _not_external_failure_sql() -> str:
        """SQL: this Attempt's task did not fail for a reason outside the service.

        Derek, 2026-09-25: such a failure stays failed, and History lists it,
        but it is not an Attention item (see app/external_failures.py).
        """
        from app.external_failures import external_task_error_sql

        return (
            f"not exists (select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as external_task "
            "where external_task.channel=attempts.channel "
            "and external_task.conversation_id=attempts.conversation_id "
            "and external_task.trigger_message_id=attempts.trigger_message_id "
            f"and {external_task_error_sql('external_task.error')})"
        )

    def list_current_unresolved_problem_attempts(
        self, *, limit: int = 50
    ) -> list[ReplyAttempt]:
        """Return the latest unresolved problem state for each message trigger."""
        with self._connect() as db:
            rows = db.execute(
                f"""
                select attempts.*
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                where attempts.send_status in ('needs_human', 'blocked', 'failed')
                  and __NOT_EXTERNAL__
                  and not exists (
                      select 1 from ({NATIVE_AGENT_RUN_SQL}) as attempt_run
                      join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                        on current_task.id=attempt_run.reply_task_id
                      where attempt_run.id=attempts.agent_run_id
                        and (
                            attempt_run.execution_generation<>current_task.execution_generation
                            or current_task.status in ('done', 'skipped')
                        )
                  )
                  and not exists (
                      select 1
                      from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as historical_task
                      join ({NATIVE_REPLY_BUSINESS_KEY_SQL}) as current_business_object
                        on current_business_object.business_object_key=historical_task.business_object_key
                      where historical_task.channel=attempts.channel
                        and historical_task.conversation_id=attempts.conversation_id
                        and historical_task.trigger_message_id=attempts.trigger_message_id
                        and current_business_object.reply_task_id<>historical_task.id
                  )
                  and not exists (
                      select 1
                      from ({NATIVE_REPLY_BUSINESS_KEY_SQL}) as current_business_object
                      join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                        on current_task.id=current_business_object.reply_task_id
                      where current_business_object.business_object_key=(
                          'message:' || attempts.channel || ':' ||
                          attempts.conversation_id || ':' ||
                          attempts.trigger_message_id
                      )
                        and current_task.status in (
                            'done', 'skipped', 'needs_human', 'processing'
                        )
                  )
                  and (
                      (
                          attempts.send_status = 'needs_human'
                          and attempts.reviewed_at is null
                          and not exists (
                              select 1
                              from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                              where tasks.channel=attempts.channel
                                and tasks.conversation_id=attempts.conversation_id
                                and tasks.trigger_message_id=attempts.trigger_message_id
                                and tasks.status in ('pending', 'processing')
                          )
                      )
                      or (
                          attempts.send_status != 'needs_human'
                          and not exists (
                              select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as pending_task
                              where pending_task.channel=attempts.channel
                                and pending_task.conversation_id=attempts.conversation_id
                                and pending_task.trigger_message_id=attempts.trigger_message_id
                                and pending_task.status='pending'
                                and not exists (
                                    select 1 from ({NATIVE_AGENT_RUN_SQL}) as failed_run
                                    where failed_run.id=attempts.agent_run_id
                                      and failed_run.reply_task_id=pending_task.id
                                      and failed_run.execution_generation=pending_task.execution_generation
                                      and failed_run.status='failed'
                                )
                          )
                          and not exists (
                              select 1
                              from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                              where tasks.channel=attempts.channel
                                and tasks.conversation_id=attempts.conversation_id
                                and tasks.trigger_message_id=attempts.trigger_message_id
                                and (
                                    tasks.status in (
                                        'done', 'skipped', 'needs_human', 'processing'
                                    )
                                )
                          )
                      )
                  )
                  and attempts.id=(
                      select max(latest.id)
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                      where latest.conversation_id=attempts.conversation_id
                        and latest.trigger_message_id=attempts.trigger_message_id
                  )
                order by attempts.id desc
                limit ?
                """.replace(
                    "__NOT_EXTERNAL__", self._not_external_failure_sql()
                ),
                (max(1, limit),),
            ).fetchall()
            attempts: list[ReplyAttempt] = []
            for row in rows:
                values = dict(row)
                attempt = ReplyAttempt.model_validate(values)
                if (
                    attempt.send_status == "needs_human"
                    and not db.execute(f"""select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) t
                        join ({NATIVE_REVIEW_CANDIDATE_SQL}) c on c.task_id=t.id
                          and c.execution_generation=t.execution_generation and c.invalidated_at=''
                        join ({NATIVE_CANDIDATE_REVIEW_SQL}) r on r.candidate_id=c.id
                          and r.decision='approve' and r.candidate_digest=c.candidate_digest
                        left join ({NATIVE_CANDIDATE_SELECTION_SQL}) choice on choice.candidate_id=c.id
                        where t.channel=? and t.conversation_id=? and t.trigger_message_id=?
                          and t.status='needs_human' and r.audit_run_id=? and choice.id is null
                          and c.id=(select max(id) from ({NATIVE_REVIEW_CANDIDATE_SQL})
                            where task_id=t.id and execution_generation=t.execution_generation)
                          and json_extract(c.candidate_json,'$.outcome')='needs_human'
                        limit 1""", (
                            attempt.channel, attempt.conversation_id,
                            attempt.trigger_message_id, attempt.agent_run_id,
                        )).fetchone()
                ):
                    continue
                attempts.append(attempt)
            return attempts

