    def list_history_items(
        self,
        limit: int | None = None,
        offset: int = 0,
        *,
        send_statuses: tuple[str, ...] | None = None,
        query_text: str = "",
        kinds: tuple[str, ...] | None = None,
        reply_channels: tuple[str, ...] | None = None,
        object_types: tuple[str, ...] | None = None,
        created_since: str = "",
    ) -> list[HistoryItem]:
        query, args = self._history_items_query(
            send_statuses=send_statuses,
            query_text=query_text,
            kinds=kinds,
            reply_channels=reply_channels,
            object_types=object_types,
            created_since=created_since,
        )
        query = f"{query} order by created_at desc, source_id desc, kind desc"
        if limit is not None:
            query = f"{query} limit ? offset ?"
            args.extend([limit, max(0, offset)])
        with self._connect() as db:
            rows = db.execute(query, args).fetchall()
        return [HistoryItem.model_validate(dict(row)) for row in rows]

    def count_history_items(
        self,
        *,
        send_statuses: tuple[str, ...] | None = None,
        query_text: str = "",
        kinds: tuple[str, ...] | None = None,
        reply_channels: tuple[str, ...] | None = None,
        object_types: tuple[str, ...] | None = None,
        created_since: str = "",
    ) -> int:
        query, args = self._history_items_query(
            send_statuses=send_statuses,
            query_text=query_text,
            kinds=kinds,
            reply_channels=reply_channels,
            object_types=object_types,
            created_since=created_since,
        )
        with self._connect() as db:
            row = db.execute(f"select count(*) as count from ({query})", args).fetchone()
        return int(row["count"])

    @staticmethod
    def _history_items_query(
        *,
        send_statuses: tuple[str, ...] | None,
        query_text: str,
        kinds: tuple[str, ...] | None,
        reply_channels: tuple[str, ...] | None,
        object_types: tuple[str, ...] | None,
        created_since: str,
    ) -> tuple[str, list[object]]:
        query = f"""
            with history_items as (
                select
                    'reply' as kind,
                    case
                        when action='oa_approval' or oa_process_instance_id<>'' then 'approval'
                        when channel='wechat' then 'wechat'
                        when channel='email' and (
                            action='direct_unsubscribe'
                            or (
                                conversation_title='Email unsubscribe'
                                and trigger_text='Immutable ActionPlan authorizes unsubscribe.'
                            )
                        ) then 'email_unsubscribe'
                        else 'replay'
                    end as object_type,
                    id as source_id,
                    conversation_title as source_title,
                    trigger_sender as source_actor,
                    '问' as input_label,
                    trigger_text as input_text,
                    '答' as output_label,
                    case
                        when final_reply_text != '' then final_reply_text
                        else draft_reply_text
                    end as output_text,
                    action,
                    case
                        when {TERMINAL_OA_SOURCE_SKIP_SQL} then 'skipped'
                        when send_status='needs_human' and trim(coalesce(resolved_at, ''))<>'' then 'skipped'
                        when channel = 'wechat' then coalesce((
                            select case deliveries.status
                                when 'ready_to_send' then 'pending'
                                when 'sending' then 'processing'
                                when 'failed' then case
                                    when deliveries.error='user_rejected' then 'skipped'
                                    else 'failed'
                                end
                                else deliveries.status
                            end
                            from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                            join ({WECHAT_DELIVERY_SQL}) as deliveries
                                on deliveries.reply_task_id=tasks.id
                            where tasks.channel='wechat'
                              and tasks.conversation_id=reply_attempts.conversation_id
                              and tasks.trigger_message_id=reply_attempts.trigger_message_id
                            limit 1
                        ), send_status)
                        when send_status in ('failed', 'blocked', 'pending', 'dry_run', 'needs_human')
                             and exists (
                                select 1
                                from ({NATIVE_AGENT_RUN_SQL}) as attempt_run
                                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                                  on current_task.id=attempt_run.reply_task_id
                                join ({NATIVE_AGENT_RUN_SQL}) as latest_run
                                  on latest_run.reply_task_id=current_task.id
                                 and latest_run.execution_generation=current_task.execution_generation
                                where attempt_run.id=reply_attempts.agent_run_id
                                  and current_task.status='processing'
                                  and latest_run.id>attempt_run.id
                                  and latest_run.status in ('pending', 'running', 'completed')
                                  and latest_run.id=(
                                      select max(candidate.id)
                                      from ({NATIVE_AGENT_RUN_SQL}) as candidate
                                      where candidate.reply_task_id=current_task.id
                                        and candidate.execution_generation=current_task.execution_generation
                                  )
                             )
                        then 'processing'
                        when action in ('memory_write', 'oa_approval')
                             and send_status in ('failed', 'blocked', 'pending', 'dry_run', 'needs_human')
                             and exists (
                                select 1
                                from ({REPLY_ATTEMPT_COMMON_SQL}) as newer_side_effects
                                where newer_side_effects.conversation_id=reply_attempts.conversation_id
                                  and newer_side_effects.trigger_message_id=reply_attempts.trigger_message_id
                                  and newer_side_effects.action=reply_attempts.action
                                  and newer_side_effects.id>reply_attempts.id
                                  and newer_side_effects.send_status in (
                                      'sent', 'skipped', 'commented', 'reacted',
                                      'calendar', 'document', 'blocked'
                                  )
                             )
                        then 'skipped'
                        when send_status in ('failed', 'blocked', 'pending', 'dry_run', 'needs_human')
                             and action not in ('memory_write', 'oa_approval')
                             and exists (
                                select 1
                                from ({REPLY_ATTEMPT_COMMON_SQL}) as newer_attempts
                                where newer_attempts.conversation_id=reply_attempts.conversation_id
                                  and newer_attempts.trigger_message_id=reply_attempts.trigger_message_id
                                  and newer_attempts.id>reply_attempts.id
                                  and newer_attempts.send_status in (
                                      'sent', 'skipped', 'commented', 'reacted',
                                      'calendar', 'document', 'blocked'
                                  )
                             )
                        then 'skipped'
                        when send_status in ('failed', 'blocked', 'pending', 'dry_run', 'needs_human')
                             and action not in ('memory_write', 'oa_approval')
                             and exists (
                                select 1
                                from ({SENT_REPLY_SQL}) as sent
                                where sent.conversation_id=reply_attempts.conversation_id
                                  and sent.trigger_message_id=reply_attempts.trigger_message_id
                                  and datetime(sent.sent_at)>=datetime(reply_attempts.created_at)
                             )
                        then 'skipped'
                        else send_status
                    end as status,
                    conversation_title as target_title,
                    codex_session_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id,
                    channel,
                    created_at,
                    iif(?1, conversation_id || ' ' || conversation_title || ' ' ||
                    trigger_message_id || ' ' || trigger_sender || ' ' ||
                    trigger_text || ' ' || action || ' ' || sensitivity_kind || ' ' ||
                    codex_reason || ' ' || draft_reply_text || ' ' || final_reply_text || ' ' ||
                    permission_action || ' ' || permission_reason || ' ' || send_status || ' ' ||
                    send_error || ' ' || reviewer_feedback || ' ' || corrected_reply_text
                    , '') as search_text
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where (
                    oa_process_instance_id = ''
                    or id = (
                        select process_attempts.id
                        from ({REPLY_ATTEMPT_COMMON_SQL}) as process_attempts
                        where process_attempts.oa_process_instance_id = reply_attempts.oa_process_instance_id
                          and process_attempts.oa_process_instance_id <> ''
                        order by process_attempts.created_at desc,
                            process_attempts.id desc
                        limit 1
                    )
                )
                  and not exists (
                    select 1 from ({NATIVE_AGENT_RUN_SQL}) as attempt_run
                    join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                      on current_task.id=attempt_run.reply_task_id
                    where attempt_run.id=reply_attempts.agent_run_id
                      and attempt_run.execution_generation<>current_task.execution_generation
                )
                  -- Legacy retries can have distinct physical projections for
                  -- one reply task. Keep their immutable runs, but show only
                  -- the task's newest business-result projection in History.
                  and not exists (
                    select 1
                    from ({NATIVE_AGENT_RUN_SQL}) as historical_run
                    join ({REPLY_ATTEMPT_COMMON_SQL}) as newer_attempt
                      on newer_attempt.id > reply_attempts.id
                    join ({NATIVE_AGENT_RUN_SQL}) as newer_run
                      on newer_run.id = newer_attempt.agent_run_id
                    where historical_run.id = reply_attempts.agent_run_id
                      and newer_run.reply_task_id = historical_run.reply_task_id
                  )
                union all
                select
                    'meeting' as kind,
                    'meeting' as object_type,
                    runs.id as source_id,
                    jobs.title as source_title,
                    'Meeting Alignment Agent' as source_actor,
                    '会议' as input_label,
                    jobs.title as input_text,
                    '对齐' as output_label,
                    case
                        when jobs.final_message != '' and jobs.calendar_summary_status='updated'
                            then jobs.final_message || '\n\n日历备注：已写入原日程。'
                        when jobs.final_message != '' and jobs.calendar_summary_status='failed'
                            then jobs.final_message || '\n\n日历备注：等待补写。'
                        when jobs.final_message != '' then jobs.final_message
                        else '会议任务尚无已采用的最终消息。'
                    end as output_text,
                    case
                        when jobs.status='no_action' then 'no_action'
                        else 'meeting_alignment'
                    end as action,
                    case
                        when runs.status='no_action' then 'skipped'
                        when runs.status in ('retry', 'failed') then 'failed'
                        when runs.status='ready_to_send' and jobs.status='sent' then 'sent'
                        when runs.status='ready_to_send' and exists (
                            select 1 from ({NATIVE_MEETING_RUN_SQL}) as later_runs
                            where later_runs.job_id=runs.job_id and later_runs.id>runs.id
                        ) then 'skipped'
                        when runs.status='ready_to_send' and jobs.status in ('retry', 'failed') then 'failed'
                        else runs.status
                    end as status,
                    jobs.target_title,
                    runs.codex_session_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id,
                    'dingtalk' as channel,
                    runs.created_at,
                    iif(?1, jobs.meeting_id || ' ' || jobs.title || ' ' || jobs.source_json || ' ' ||
                    jobs.participants_json || ' ' || jobs.error || ' ' || jobs.decision_json || ' ' ||
                    jobs.target_kind || ' ' || jobs.target_id || ' ' || jobs.target_title || ' ' ||
                    jobs.mentions_json || ' ' || jobs.final_message || ' ' || jobs.send_result_json || ' ' ||
                    jobs.calendar_summary_status || ' ' || jobs.calendar_summary_result_json || ' ' ||
                    runs.error || ' ' ||
                    runs.codex_session_id || ' ' || runs.status
                    , '') as search_text
                from ({NATIVE_MEETING_RUN_SQL}) as runs
                join ({NATIVE_MEETING_TASK_SQL}) as jobs on jobs.id=runs.job_id
                union all
                select
                    'task' as kind,
                    'task' as object_type,
                    updates.id as source_id,
                    projects.title as source_title,
                    'Task Agent' as source_actor,
                    '来源' as input_label,
                    updates.source_type || ':' || updates.source_ref as input_text,
                    '更新' as output_label,
                    updates.summary as output_text,
                    'task_update' as action,
                    'done' as status,
                    projects.title as target_title,
                    '' as codex_session_id,
                    updates.project_id as project_id,
                    0 as todo_id,
                    0 as follow_up_id,
                    'dingtalk' as channel,
                    updates.created_at,
                    iif(?1, projects.title || ' ' || projects.category || ' ' ||
                    projects.owner_name || ' ' || projects.goal || ' ' ||
                    projects.background || ' ' || projects.current_state || ' ' ||
                    projects.next_step || ' ' || updates.source_type || ' ' ||
                    updates.source_ref || ' ' || updates.summary || ' ' ||
                    updates.changes_json
                    , '') as search_text
                from ({SYNC_ACTION_PROJECTIONS['work_updates']}) as updates
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=updates.project_id
                union all
                select
                    'task' as kind,
                    'todo_completion_evidence_candidate' as object_type,
                    candidates.id as source_id,
                    projects.title as source_title,
                    'Task Agent' as source_actor,
                    '证据' as input_label,
                    candidates.source_type || ':' || candidates.source_ref as input_text,
                    '判断' as output_label,
                    coalesce(nullif(candidates.decision_json, '{{}}'), candidates.reason) as output_text,
                    'todo_completion_evidence_candidate' as action,
                    case
                        when candidates.status='accepted' then 'done'
                        when candidates.status in ('candidate', 'enqueued') then 'pending'
                        else candidates.status
                    end as status,
                    coalesce(nullif(todos.title, ''), projects.title) as target_title,
                    '' as codex_session_id,
                    candidates.project_id as project_id,
                    candidates.todo_id as todo_id,
                    0 as follow_up_id,
                    'dingtalk' as channel,
                    candidates.updated_at as created_at,
                    iif(?1, projects.title || ' ' || projects.category || ' ' ||
                    projects.owner_name || ' ' || projects.goal || ' ' ||
                    projects.background || ' ' || projects.current_state || ' ' ||
                    projects.next_step || ' ' || coalesce(todos.title, '') || ' ' ||
                    coalesce(todos.description, '') || ' ' || candidates.source_type || ' ' ||
                    candidates.source_ref || ' ' || candidates.evidence_text || ' ' ||
                    candidates.reason || ' ' || candidates.status || ' ' ||
                    candidates.decision_json
                    , '') as search_text
                from ({BUSINESS_PROJECTIONS['todo_evidence_candidate']}) as candidates
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=candidates.project_id
                left join ({BUSINESS_PROJECTIONS['work_todo']}) as todos on todos.id=candidates.todo_id
                union all
                select
                    'task' as kind,
                    'task' as object_type,
                    drafts.id as source_id,
                    projects.title as source_title,
                    'Follow-up' as source_actor,
                    '跟进' as input_label,
                    drafts.question_text as input_text,
                    '结果' as output_label,
                    case
                        when drafts.status='sent' then coalesce(nullif(drafts.reaction_summary, ''), '已发送跟进')
                        when drafts.status='completed' then coalesce(nullif(drafts.suppressed_reason, ''), '已完成跟进')
                        when drafts.status in ('skipped', 'cancelled') then coalesce(nullif(drafts.suppressed_reason, ''), '已跳过跟进')
                        when drafts.status='failed' then coalesce(nullif(drafts.send_result_json, '{{}}'), '发送失败')
                        else drafts.scheduled_at
                    end as output_text,
                    'follow_up_' || drafts.status as action,
                    case
                        when drafts.status='sent' then 'sent'
                        when drafts.status='completed' then 'done'
                        when drafts.status in ('draft', 'approved') then 'pending'
                        when drafts.status in ('skipped', 'cancelled') then 'skipped'
                        when drafts.status='failed' then 'failed'
                        else drafts.status
                    end as status,
                    coalesce(nullif(todos.title, ''), drafts.owner_name, projects.title) as target_title,
                    '' as codex_session_id,
                    drafts.project_id as project_id,
                    drafts.todo_id as todo_id,
                    drafts.id as follow_up_id,
                    'dingtalk' as channel,
                    case
                        when drafts.status in ('draft', 'approved')
                             and nullif(drafts.scheduled_at, '') is not null
                        then drafts.scheduled_at
                        else coalesce(nullif(drafts.sent_at, ''), nullif(drafts.updated_at, ''), drafts.created_at)
                    end as created_at,
                    iif(?1, projects.title || ' ' || projects.category || ' ' ||
                    projects.owner_name || ' ' || projects.goal || ' ' ||
                    projects.background || ' ' || projects.current_state || ' ' ||
                    projects.next_step || ' ' || coalesce(todos.title, '') || ' ' ||
                    coalesce(todos.description, '') || ' ' || drafts.owner_name || ' ' ||
                    drafts.target_conversation_id || ' ' || drafts.target_kind || ' ' ||
                    drafts.question_text || ' ' || drafts.status || ' ' ||
                    drafts.send_result_json || ' ' || drafts.evidence_check_json || ' ' ||
                    drafts.reaction_status || ' ' || drafts.reaction_summary || ' ' ||
                    drafts.suppressed_reason
                    , '') as search_text
                from ({SYNC_ACTION_PROJECTIONS['follow_up_drafts']}) as drafts
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=drafts.project_id
                left join ({BUSINESS_PROJECTIONS['work_todo']}) as todos on todos.id=drafts.todo_id
            )
            select * from history_items
        """
        filters: list[str] = []
        args: list[object] = [bool(query_text.strip())]
        if send_statuses:
            placeholders = ",".join("?" for _ in send_statuses)
            filters.append(f"status in ({placeholders})")
            args.extend(send_statuses)
        if kinds:
            placeholders = ",".join("?" for _ in kinds)
            filters.append(f"kind in ({placeholders})")
            args.extend(kinds)
        if reply_channels:
            placeholders = ",".join("?" for _ in reply_channels)
            filters.append(f"(kind != 'reply' or channel in ({placeholders}))")
            args.extend(reply_channels)
        if object_types:
            placeholders = ",".join("?" for _ in object_types)
            filters.append(f"object_type in ({placeholders})")
            args.extend(object_types)
        if created_since.strip():
            filters.append("created_at >= ?")
            args.append(created_since)
        if query_text.strip():
            needle = f"%{query_text.strip().lower()}%"
            filters.append("lower(search_text) like ?")
            args.append(needle)
        if filters:
            query = f"{query} where {' and '.join(filters)}"
        return query, args

    def list_reply_attempts_by_ids(self, attempt_ids: list[int]) -> list[ReplyAttempt]:
        if not attempt_ids:
            return []
        placeholders = ",".join("?" for _ in attempt_ids)
        with self._connect() as db:
            rows = db.execute(
                f"select * from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts where id in ({placeholders})",
                attempt_ids,
            ).fetchall()
        return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_reply_attempts_after(self, attempt_id: int) -> list[ReplyAttempt]:
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where id > ?
                order by id asc
                """,
                (attempt_id,),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_reply_attempts_since(self, since_utc: str) -> list[ReplyAttempt]:
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where created_at >= ?
                order by created_at asc, id asc
                """,
                (since_utc,),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_reply_attempts_for_conversation(
        self, conversation_id: str, limit: int | None = None
    ) -> list[ReplyAttempt]:
        with self._connect() as db:
            query = f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where conversation_id=?
                order by id desc
            """
            args: tuple[object, ...] = (conversation_id,)
            if limit is not None:
                query = f"{query} limit ?"
                args = (conversation_id, limit)
            rows = db.execute(query, args).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_oa_attempt_history(
        self, process_instance_id: str, limit: int = 50
    ) -> list[ReplyAttempt]:
        process_id = process_instance_id.strip()
        if not process_id:
            return []
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where oa_process_instance_id=?
                order by created_at desc, id desc
                limit ?
                """,
                (process_id, max(1, limit)),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_unbound_failed_oa_attempts(self, *, limit: int = 20) -> list[ReplyAttempt]:
        """Return one oldest unresolved failed OA Attempt per process/task."""
        with self._connect() as db:
            rows = db.execute(
                f"""
                select attempts.*
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                where attempts.channel='dingtalk'
                  and attempts.send_status='failed'
                  and trim(coalesce(attempts.resolved_at, ''))=''
                  and trim(coalesce(attempts.oa_process_instance_id, ''))<>''
                  and trim(coalesce(attempts.oa_task_id, ''))<>''
                  and attempts.id=(
                      select max(latest.id)
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                      where latest.oa_process_instance_id=attempts.oa_process_instance_id
                        and latest.oa_task_id=attempts.oa_task_id
                        and latest.send_status='failed'
                        and trim(coalesce(latest.resolved_at, ''))=''
                  )
                  and not exists (
                      select 1
                      from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as tasks
                      where tasks.channel=attempts.channel
                        and tasks.status in ('pending', 'processing', 'needs_human', 'failed')
                        and ((tasks.conversation_id=attempts.conversation_id
                              and tasks.trigger_message_id=attempts.trigger_message_id)
                             or tasks.business_object_key='oa:' || attempts.oa_process_instance_id
                                 || ':' || attempts.oa_task_id)
                  )
                order by case when exists (
                    select 1
                    from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as terminal_tasks
                    where terminal_tasks.channel=attempts.channel
                      and terminal_tasks.business_object_key='oa:'
                          || attempts.oa_process_instance_id || ':' || attempts.oa_task_id
                      and terminal_tasks.status in ('done', 'skipped')
                ) then 0 else 1 end, attempts.id asc
                limit ?
                """,
                (max(1, limit),),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def skip_unbound_failed_oa_attempt(
        self,
        attempt_id: int,
        *,
        process_instance_id: str,
        oa_task_id: str,
        terminal_evidence: str,
    ) -> bool:
        """Close one orphaned failed Attempt after exact terminal source readback."""
        process_id = process_instance_id.strip()
        task_id = oa_task_id.strip()
        evidence = terminal_evidence.strip()
        if not process_id or not task_id or not evidence:
            raise ValueError("exact OA identity and terminal evidence are required")
        with self._immediate_write_transaction() as db:
            current = db.execute(
                f"select * from ({REPLY_ATTEMPT_COMMON_SQL}) where id=?",
                (attempt_id,),
            ).fetchone()
            if (
                current is None
                or current["send_status"] != "failed"
                or current["channel"] != "dingtalk"
                or current["oa_process_instance_id"] != process_id
                or current["oa_task_id"] != task_id
                or str(current["resolved_at"] or "").strip()
            ):
                return False
            latest = db.execute(
                f"select max(id) from ({REPLY_ATTEMPT_COMMON_SQL}) "
                "where oa_process_instance_id=? and oa_task_id=? "
                "and send_status='failed' and trim(coalesce(resolved_at, ''))=''",
                (process_id, task_id),
            ).fetchone()[0]
            if int(latest or 0) != attempt_id:
                return False
            owner = db.execute(
                f"""select 1 from ({NATIVE_REPLY_TASK_CURRENT_SQL}) tasks
                    where tasks.channel=?
                      and tasks.status in ('pending', 'processing', 'needs_human', 'failed')
                      and ((tasks.conversation_id=? and tasks.trigger_message_id=?)
                           or tasks.business_object_key=?)
                    limit 1""",
                (
                    current["channel"],
                    current["conversation_id"],
                    current["trigger_message_id"],
                    f"oa:{process_id}:{task_id}",
                ),
            ).fetchone()
            if owner is not None:
                return False
            unresolved = db.execute(
                f"""select id from ({REPLY_ATTEMPT_COMMON_SQL})
                    where channel='dingtalk' and send_status='failed'
                      and oa_process_instance_id=? and oa_task_id=?
                      and trim(coalesce(resolved_at, ''))=''
                    order by id desc""",
                (process_id, task_id),
            ).fetchall()
            closed = 0
            for row in unresolved:
                now = db.execute("select current_timestamp").fetchone()[0]
                cursor = update_action(
                    db,
                    "reply_attempts",
                    int(row["id"]),
                    {
                        "send_status": "skipped",
                        "resolved_at": now,
                        "resolution": evidence,
                        "updated_at": now,
                    },
                    where_sql=(
                        "send_status='failed' and channel='dingtalk' "
                        "and oa_process_instance_id=? and oa_task_id=? "
                        "and trim(coalesce(resolved_at, ''))=''"
                    ),
                    parameters=(process_id, task_id),
                )
                closed += cursor.rowcount
            return closed > 0

    def list_open_oa_needs_human_attempts(
        self, *, limit: int = 100
    ) -> list[ReplyAttempt]:
        """Return latest unresolved OA decisions with no active local rerun."""

        with self._connect() as db:
            rows = db.execute(
                f"""
                select attempts.*
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                where (
                        attempts.send_status='needs_human'
                        or (
                            attempts.send_status='failed'
                            and exists (
                                select 1
                                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) stale_tasks
                                where stale_tasks.channel=attempts.channel
                                  and stale_tasks.conversation_id=attempts.conversation_id
                                  and stale_tasks.trigger_message_id=attempts.trigger_message_id
                                  and stale_tasks.status in ('needs_human', 'failed')
                            )
                        )
                      )
                  and trim(coalesce(attempts.resolved_at, ''))=''
                  and trim(attempts.oa_process_instance_id)<>''
                  and trim(attempts.oa_task_id)<>''
                  and attempts.id=(
                      select max(latest.id)
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                      where latest.oa_process_instance_id=
                            attempts.oa_process_instance_id
                  )
                  and not exists (
                      select 1
                      from ({NATIVE_REPLY_TASK_CURRENT_SQL}) tasks
                      where tasks.channel=attempts.channel
                        and tasks.conversation_id=attempts.conversation_id
                        and tasks.trigger_message_id=attempts.trigger_message_id
                        and tasks.status in ('pending', 'processing')
                  )
                order by attempts.id desc
                limit ?
                """,
                (max(1, limit),),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_oa_task_not_pending_attempts(
        self, *, limit: int = 500
    ) -> list[ReplyAttempt]:
        """Return latest attempts falsely settled by the old pending-list rule."""
        with self._connect() as db:
            rows = db.execute(
                f"""
                select attempts.*
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                where attempts.send_status='skipped'
                  and attempts.resolution like '%OA_TASK_NOT_PENDING%'
                  and attempts.resolution not like 'Live DingTalk readback corrected%'
                  and trim(attempts.oa_process_instance_id)<>''
                  and attempts.id=(
                      select max(latest.id)
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                      where latest.oa_process_instance_id=
                            attempts.oa_process_instance_id
                  )
                order by attempts.id desc
                limit ?
                """,
                (max(1, limit),),
            ).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def correct_legacy_oa_task_not_pending_resolution(
        self,
        attempt_id: int,
        *,
        process_instance_id: str,
        task_id: str,
        process_result: str,
    ) -> bool:
        """Append live terminal/return evidence to a falsely closed OA attempt."""
        process_id = process_instance_id.strip()
        original_task_id = task_id.strip()
        if not process_id or not original_task_id:
            raise ValueError("process_instance_id and task_id must be non-empty")
        result = process_result.strip()
        if not result:
            raise ValueError("process_result must be non-empty")
        verified = (
            "the exact task has a verified return receipt"
            if result == "OA_RETURNED"
            else f"the process has a verified terminal result {result}"
        )
        with self._immediate_write_transaction() as db:
            row = db.execute(
                f"""
                select resolution
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where id=?
                  and send_status='skipped'
                  and oa_process_instance_id=?
                  and oa_task_id=?
                  and resolution not like 'Live DingTalk readback corrected%'
                  and id=(
                      select max(latest.id)
                      from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                      where latest.oa_process_instance_id=?
                  )
                """,
                (attempt_id, process_id, original_task_id, process_id),
            ).fetchone()
            if row is None:
                return False
            previous = str(row["resolution"] or "").strip()
            if "OA_TASK_NOT_PENDING" not in previous:
                return False
            corrected = (
                f"Live DingTalk readback corrected the earlier OA_TASK_NOT_PENDING "
                f"closure: {verified}. Previous resolution retained: {previous}"
            )
            cursor = update_action(db, "reply_attempts", attempt_id, {
                "resolution": corrected,
                "updated_at": db.execute("select current_timestamp").fetchone()[0],
            }, where_sql="send_status='skipped' and oa_process_instance_id=? "
                         "and oa_task_id=? and resolution=? "
                         "and resolution not like 'Live DingTalk readback corrected%' "
                         f"and id=(select max(latest.id) from ({REPLY_ATTEMPT_COMMON_SQL}) "
                         "as latest where latest.oa_process_instance_id=?)",
               parameters=(process_id, original_task_id, previous, process_id))
            return cursor.rowcount == 1

    def list_oa_attempt_histories(
        self, process_instance_ids: Sequence[str]
    ) -> dict[str, list[ReplyAttempt]]:
        """Load every attempt for several approval processes in one query."""
        process_ids = list(
            dict.fromkeys(
                process_id.strip()
                for process_id in process_instance_ids
                if process_id.strip()
            )
        )
        histories: dict[str, list[ReplyAttempt]] = {
            process_id: [] for process_id in process_ids
        }
        if not process_ids:
            return histories
        placeholders = ", ".join("?" for _ in process_ids)
        with self._connect() as db:
            rows = db.execute(
                f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where oa_process_instance_id in ({placeholders})
                order by oa_process_instance_id, created_at desc, id desc
                """,
                process_ids,
            ).fetchall()
        for row in rows:
            attempt = ReplyAttempt.model_validate(dict(row))
            histories[attempt.oa_process_instance_id].append(attempt)
        return histories

    def backfill_oa_audit_metadata(self) -> int:
        """Recover OA identity for historical agent attempts by exact task key."""
        with self._connect() as db:
            rows = db.execute(
                f"""
                select reply_attempts.id, reply_attempts.oa_action, reply_tasks.oa_url,
                       reply_tasks.business_object_key
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as reply_tasks on reply_tasks.conversation_id=reply_attempts.conversation_id
                    and reply_tasks.trigger_message_id=reply_attempts.trigger_message_id
                where reply_attempts.action='agent_run'
                    and reply_attempts.oa_process_instance_id=''
                    and (
                        reply_tasks.oa_url<>''
                        or reply_tasks.business_object_key like 'oa:%'
                    )
                order by reply_attempts.id
                """
            ).fetchall()

        candidates = []
        for row in rows:
            process_instance_id, task_id = self._oa_identifiers_from_url(
                str(row["oa_url"] or "")
            )
            if not process_instance_id:
                business_key = str(row["business_object_key"] or "").strip()
                if business_key.startswith("oa:") and ":" in business_key[3:]:
                    process_instance_id, task_id = business_key[3:].rsplit(":", 1)
            if not process_instance_id:
                continue
            oa_url = str(row["oa_url"] or "").strip()
            if not oa_url:
                oa_url = (
                    "https://aflow.dingtalk.com/detail?"
                    f"procInstId={quote(process_instance_id)}&taskId={quote(task_id)}"
                )
            candidates.append((
                int(row["id"]),
                process_instance_id,
                task_id,
                oa_url,
                "review" if row["oa_action"] == "" else row["oa_action"],
            ))

        repaired = 0
        for offset in range(0, len(candidates), OA_AUDIT_METADATA_BACKFILL_BATCH_SIZE):
            batch = candidates[offset:offset + OA_AUDIT_METADATA_BACKFILL_BATCH_SIZE]
            with self._immediate_write_transaction() as db:
                for attempt_id, process_instance_id, task_id, oa_url, oa_action in batch:
                    cursor = update_action(db, "reply_attempts", attempt_id, {
                        "oa_process_instance_id": process_instance_id,
                        "oa_task_id": task_id,
                        "oa_url": oa_url,
                        "oa_action": oa_action,
                        "updated_at": db.execute(
                            "select current_timestamp"
                        ).fetchone()[0],
                    }, where_sql="oa_process_instance_id=''")
                    repaired += cursor.rowcount
        return repaired

    @staticmethod
    def _oa_identifiers_from_url(url: str) -> tuple[str, str]:
        return oa_identifiers_from_url(url)

    def list_reply_attempts_for_codex_session(
        self, codex_session_id: str, limit: int | None = None
    ) -> list[ReplyAttempt]:
        with self._connect() as db:
            query = f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where codex_session_id=?
                order by id desc
            """
            args: tuple[object, ...] = (codex_session_id,)
            if limit is not None:
                query = f"{query} limit ?"
                args = (codex_session_id, limit)
            rows = db.execute(query, args).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]

    def list_codex_session_attempt_roles(
        self, codex_session_id: str
    ) -> list[dict[str, object]]:
        """Return the Attempts this Codex session ran for, and the role it ran as.

        An Attempt row stores one session id, the last role that ran, so a
        Consumer transcript matched nothing and its page could not say which
        business record it belonged to. The agent run that owns the session
        names its task, execution generation, and role. Only the Attempt
        projection for that same generation belongs on this session page;
        older generations of the task remain History, not session records.
        """
        with self._connect() as db:
            runs = db.execute(
                f"""
                select reply_task_id, execution_generation, role
                from ({NATIVE_AGENT_RUN_SQL}) as agent_runs
                where codex_session_id=?
                order by id desc
                """,
                (codex_session_id,),
            ).fetchall()
            results: list[dict[str, object]] = []
            seen: set[tuple[int, str]] = set()
            for run in runs:
                role = str(run["role"] or "")
                for row in db.execute(
                    f"""
                    select attempt.id as id, attempt.send_status as send_status
                    from ({REPLY_ATTEMPT_COMMON_SQL}) as attempt
                    join ({NATIVE_AGENT_RUN_SQL}) run on run.id = attempt.agent_run_id
                    where run.reply_task_id = ?
                      and run.execution_generation = ?
                    order by attempt.id desc
                    """,
                    (run["reply_task_id"], run["execution_generation"]),
                ).fetchall():
                    key = (int(row["id"]), role)
                    if key in seen:
                        continue
                    seen.add(key)
                    results.append(
                        {
                            "id": int(row["id"]),
                            "status": str(row["send_status"] or ""),
                            "role": role,
                        }
                    )
        return results

    def search_codex_sessions(
        self,
        *,
        fts_query: str,
        query_embedding: list[float] | None = None,
        embedding_client: Callable[[list[str]], list[list[float]]] | None = None,
        limit: int = 3,
        meeting_native_only: bool = False,
    ) -> list[CodexSessionSearchResult]:
        from app.native_standalone import native_run_ref

        with self._connect() as db:
            if meeting_native_only:
                rows = db.execute(
                    "select r.id,r.session_id,'meeting_alignment' as source_type,cast(r.id as text) as source_id,"
                    "json_extract(t.parameters_json,'$.title') as title,"
                    "json_extract(t.parameters_json,'$.meeting_id') as meeting_id,r.updated_at "
                    "from runs r join run_provenance p on p.run_id=r.id "
                    "join tasks t on t.id=r.task_id and t.kind='meeting_alignment' "
                    "where p.source_type='meeting_alignment_runs' and r.session_id<>'' "
                    "order by r.updated_at desc,r.id asc"
                ).fetchall()
                references = {str(row["source_id"]): native_run_ref(db, int(row["id"]), "meeting_alignment_runs")
                              for row in rows}
                runs = {}
                for row in rows:
                    runs[str(row["source_id"])] = {
                        "id": row["id"], "codex_session_id": row["session_id"],
                        "meeting_id": row["meeting_id"], "title": row["title"],
                    }
            else:
                rows = db.execute(
                    "select * from codex_session_search_index "
                    "order by updated_at desc,id asc"
                ).fetchall()
                source_ids = [str(row["source_id"]) for row in rows
                              if row["source_type"] == "meeting_alignment"]
                runs = {}
                if source_ids:
                    placeholders = ",".join("?" for _ in source_ids)
                    runs = {str(run["id"]): run for run in db.execute(
                        "select run.id,run.session_id as codex_session_id,"
                        "json_extract(task.parameters_json,'$.meeting_id') as meeting_id,"
                        "json_extract(task.parameters_json,'$.title') as title "
                        "from runs run join run_provenance provenance on provenance.run_id=run.id "
                        "join tasks task on task.id=run.task_id and task.kind='meeting_alignment' "
                        f"where provenance.source_type='meeting_alignment_runs' and run.id in ({placeholders})",
                        source_ids,
                    ).fetchall()}
                references = {
                    source_id: native_run_ref(db, run["id"], "meeting_alignment_runs")
                    for source_id, run in runs.items()
                }
        corpus = [self._native_meeting_search_corpus(
            row, runs.get(str(row["source_id"])), references.get(str(row["source_id"]))
        ) for row in rows]
        fts_scores: dict[int, float] = {}
        with sqlite3.connect(":memory:") as search_db:
            search_db.execute(
                "create virtual table corpus using fts5(title, summary_text, fts_text)"
            )
            search_db.executemany(
                "insert into corpus(rowid, title, summary_text, fts_text) "
                "values (?, ?, ?, ?)",
                (
                    (int(row["id"]), row["title"], summary, fts)
                    for row, summary, fts, _, _ in corpus
                ),
            )
            if fts_query.strip():
                try:
                    matches = search_db.execute(
                        "select rowid, bm25(corpus) from corpus where corpus match ? "
                        "order by bm25(corpus) limit ?",
                        (fts_query, max(limit * 5, 10)),
                    ).fetchall()
                    fts_scores = {int(row_id): float(score) for row_id, score in matches}
                except sqlite3.OperationalError:
                    pass
        embeddings: dict[int, list[float]] = {}
        if embedding_client is not None:
            model = getattr(embedding_client, "model", None)
            base_url = getattr(embedding_client, "base_url", None)
            model_identity = (
                (type(embedding_client), model, base_url)
                if isinstance(model, str) and isinstance(base_url, str)
                else (type(embedding_client), embedding_client)
            )
        else:
            model_identity = ()
        uncached: list[tuple[int, str, tuple]] = []
        if query_embedding and embedding_client is not None:
            for index, (_, summary, _, corpus_key, _) in enumerate(corpus):
                if not summary:
                    continue
                vector_key = (corpus_key, model_identity)
                cached = _meeting_search_cache_get(_MEETING_SEARCH_VECTOR_CACHE, vector_key)
                if cached is None:
                    uncached.append((index, summary, vector_key))
                else:
                    embeddings[index] = cached
        if uncached and embedding_client is not None:
            try:
                vectors = embedding_client([summary for _, summary, _ in uncached])
                for (index, _, vector_key), vector in zip(uncached, vectors):
                    embeddings[index] = vector
                    _meeting_search_cache_put(
                        _MEETING_SEARCH_VECTOR_CACHE, vector_key, vector
                    )
            except Exception:
                pass
        results = []
        for index, (row, summary_text, fts_text, _, native_reason) in enumerate(corpus):
            row_id = int(row["id"])
            stored_embedding = embeddings.get(index, [])
            embedding_score = _embedding_score(
                query_embedding,
                stored_embedding,
            )
            bm25_score = fts_scores.get(row_id)
            has_embedding_candidate = bool(query_embedding and stored_embedding)
            if bm25_score is None and not has_embedding_candidate:
                continue
            bm25_normalized = (
                1.0 / (1.0 + max(0.0, bm25_score))
                if bm25_score is not None
                else 0.0
            )
            score = 0.55 * embedding_score + 0.30 * bm25_normalized
            results.append(
                CodexSessionSearchResult(
                    session_id=row["session_id"],
                    source_type=row["source_type"],
                    source_id=row["source_id"],
                    title=row["title"],
                    summary_text=summary_text,
                    fts_text=fts_text,
                    embedding_score=embedding_score,
                    bm25_score=bm25_score,
                    score=score,
                    updated_at=row["updated_at"],
                    native_available=not native_reason,
                    native_reason=native_reason,
                )
            )
        results.sort(key=lambda result: result.score, reverse=True)
        return results[:limit]

    def _native_meeting_search_corpus(
        self, row: sqlite3.Row, run: sqlite3.Row | None, ref: object
    ) -> tuple[sqlite3.Row, str, str, tuple, str]:
        from app.meeting_alignment import _meeting_fts_text, _meeting_session_index_text
        from app.meeting_alignment_models import MeetingAlignmentDecision
        from app.native_standalone import meeting_decision, meeting_source
        from app.native_trajectory import claude_session_path, find_codex_session_path

        title_fts = _meeting_fts_text(str(row["title"]))
        if row["source_type"] != "meeting_alignment" or run is None or ref is None:
            return row, "", title_fts, (), "native_reference_unavailable"
        if run["codex_session_id"] != row["session_id"]:
            return row, "", title_fts, (), "native_reference_unavailable"
        path = (find_codex_session_path(ref.session_id) if ref.kind == "codex_cli"
                else claude_session_path(ref.session_id) if ref.kind == "claude_cli"
                else None)
        if path is not None and path.is_file():
            stat = path.stat()
            native_ref = (str(path), stat.st_mtime_ns, stat.st_size)
        else:
            native_ref = ("", 0, 0)
        cache_key = (
            str(self.path), int(row["id"]), str(row["source_id"]),
            ref.kind, ref.session_id, ref.start, ref.end,
            native_ref, row["title"], run["title"], run["meeting_id"],
        )
        cached = _meeting_search_cache_get(_MEETING_SEARCH_CORPUS_CACHE, cache_key)
        if cached is not None:
            return row, *cached, cache_key, ""
        native = meeting_decision(ref)
        if not native.available:
            return row, "", title_fts, cache_key, native.reason
        source = meeting_source(ref, meeting_id=str(run["meeting_id"]))
        if source is None:
            return row, "", title_fts, cache_key, "native_input_unavailable"
        decision = MeetingAlignmentDecision.model_validate_json(native.decision_json)
        text = _meeting_session_index_text(source, decision)
        fts = _meeting_fts_text(text)
        _meeting_search_cache_put(_MEETING_SEARCH_CORPUS_CACHE, cache_key, (text, fts))
        return row, text, fts, cache_key, ""

    def list_reviewed_reply_attempts(
        self, limit: int | None = None
    ) -> list[ReplyAttempt]:
        with self._connect() as db:
            query = f"""
                select *
                from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts
                where reviewer_feedback != '' or corrected_reply_text != ''
                order by id desc
            """
            args: tuple[int, ...] = ()
            if limit is not None:
                query = f"{query} limit ?"
                args = (limit,)
            rows = db.execute(query, args).fetchall()
            return [ReplyAttempt.model_validate(dict(row)) for row in rows]


    def count_recoverable_blocked_reply_attempts(self) -> int:
        with self._connect() as db:
            row = db.execute(
                f"""
                select count(*) as count
                from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                where attempts.send_status='blocked'
                  and (
                      (
                          attempts.action in ('memory_write', 'oa_approval')
                          and attempts.id = (
                              select max(latest.id)
                              from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                              where latest.conversation_id=attempts.conversation_id
                                and latest.trigger_message_id=attempts.trigger_message_id
                                and latest.action=attempts.action
                          )
                      )
                      or (
                          attempts.action not in ('memory_write', 'oa_approval')
                          and attempts.id = (
                              select max(latest.id)
                              from ({REPLY_ATTEMPT_COMMON_SQL}) as latest
                              where latest.conversation_id=attempts.conversation_id
                                and latest.trigger_message_id=attempts.trigger_message_id
                          )
                          and not exists (
                              select 1
                              from ({SENT_REPLY_SQL}) as sent
                              where sent.conversation_id=attempts.conversation_id
                                and sent.trigger_message_id=attempts.trigger_message_id
                          )
                      )
                  )
                """,
            ).fetchone()
            return int(row["count"])

    def _reply_attempt_filters(
        self,
        *,
        send_status: str | None = None,
        send_statuses: tuple[str, ...] | None = None,
        query_text: str = "",
    ) -> tuple[list[str], list[object]]:
        filters: list[str] = []
        args: list[object] = []
        statuses = send_statuses or ((send_status,) if send_status else ())
        if statuses:
            placeholders = ",".join("?" for _ in statuses)
            filters.append(f"send_status in ({placeholders})")
            args.extend(statuses)
        if query_text.strip():
            needle = f"%{query_text.strip().lower()}%"
            filters.append(
                """(
                    lower(coalesce(conversation_id, '')) like ?
                    or lower(coalesce(conversation_title, '')) like ?
                    or lower(coalesce(trigger_message_id, '')) like ?
                    or lower(coalesce(trigger_sender, '')) like ?
                    or lower(coalesce(trigger_text, '')) like ?
                    or lower(coalesce(draft_reply_text, '')) like ?
                    or lower(coalesce(final_reply_text, '')) like ?
                    or lower(coalesce(corrected_reply_text, '')) like ?
                    or lower(coalesce(action, '')) like ?
                    or lower(coalesce(send_status, '')) like ?
                    or lower(coalesce(send_error, '')) like ?
                )"""
            )
            args.extend([needle] * 11)
        return filters, args

    def enqueue_work_summary_input(
        self,
        source_type: str,
        source_ref: str,
        payload_json: str,
    ) -> int:
        source_created_at, body_sha256, body_bytes = self._work_summary_input_provenance(payload_json)
        with self._immediate_write_transaction() as db:
            from app.task_entity_storage import create_task
            row = db.execute(
                "select task_id from work_summary_inputs where source_type=? and source_ref=?",
                (source_type, source_ref),
            ).fetchone()
            if row is None:
                created_at = db.execute("select current_timestamp").fetchone()[0]
                task = create_task(db, values={
                    "kind": "work_summary", "status": "pending", "available_at": "",
                    "attempts": 0, "error": "", "created_at": created_at,
                    "updated_at": created_at,
                })
                db.execute(
                    "insert into work_summary_inputs(task_id,source_type,source_ref,payload_json,source_created_at,body_sha256,body_bytes,body_compacted) values(?,?,?,?,?,?,?,0)",
                    (task["id"], source_type, source_ref, encode_work_summary_payload(payload_json), source_created_at, body_sha256, body_bytes),
                )
                return int(task["id"])
            task_id = int(row["task_id"])
            status = db.execute("select status from tasks where id=?", (task_id,)).fetchone()[0]
            if status not in {"processing", "done", "skipped"}:
                db.execute(
                    "update work_summary_inputs set payload_json=?,source_created_at=?,body_sha256=?,body_bytes=? where task_id=? and body_compacted=0",
                    (encode_work_summary_payload(payload_json), source_created_at, body_sha256, body_bytes, task_id),
                )
                db.execute("update tasks set updated_at=current_timestamp where id=?", (task_id,))
            return task_id

    @staticmethod
    def _work_summary_input_provenance(payload_json: str | bytes) -> tuple[str, str, int]:
        payload_text = decode_work_summary_payload(payload_json)
        try:
            decoded = json.loads(payload_text)
        except json.JSONDecodeError:
            decoded = {}
        source = decoded.get("source", {}) if isinstance(decoded, dict) else {}
        source_created_at = str(source.get("created_at") or "") if isinstance(source, dict) else ""
        body = payload_text.encode("utf-8")
        return source_created_at, hashlib.sha256(body).hexdigest(), len(body)

    @staticmethod
    def _compact_work_summary_input(
        db: sqlite3.Connection, input_id: int, *, status: str, error: str
    ) -> None:
        row = db.execute(
            "select tasks.id from tasks join work_summary_inputs on work_summary_inputs.task_id=tasks.id "
            "where tasks.id=? and tasks.kind='work_summary' "
            "and tasks.status not in ('done', 'skipped') and work_summary_inputs.body_compacted=0",
            (input_id,),
        ).fetchone()
        if row is None:
            return
        db.execute(
            "update work_summary_inputs set payload_json='{}',body_compacted=1 where task_id=? and body_compacted=0",
            (input_id,),
        )
        db.execute(
            "update tasks set status=?,error=?,updated_at=current_timestamp where id=? and kind='work_summary' and status not in ('done','skipped')",
            (status, error, input_id),
        )

    def claim_work_summary_inputs(
        self,
        limit: int,
        *,
        now: str | None = None,
    ) -> list[WorkSummaryInput]:
        if limit <= 0:
            return []
        with self._immediate_write_transaction() as db:
            now_expression = "current_timestamp" if now is None else "?"
            args: list[object] = [] if now is None else [now]
            args.append(limit)
            rows = db.execute(
                f"""
                select *
                from ({WORK_SUMMARY_INPUT_SQL})
                where status='pending'
                  and (available_at='' or datetime(available_at) <= datetime({now_expression}))
                order by id
                limit ?
                """,
                args,
            ).fetchall()
            ids = [row["id"] for row in rows]
            if not ids:
                return []
            placeholders = ",".join("?" for _ in ids)
            db.execute(
                f"""
                update tasks
                set status='processing',attempts=attempts+1,error='',available_at='',updated_at=current_timestamp
                where kind='work_summary' and id in ({placeholders}) and status='pending'
                """,
                ids,
            )
            claimed = db.execute(
                f"""
                select *
                from ({WORK_SUMMARY_INPUT_SQL})
                where id in ({placeholders})
                order by id
                """,
                ids,
            ).fetchall()
            return [WorkSummaryInput.model_validate(dict(row)) for row in claimed]

    def get_work_summary_input(self, input_id: int) -> WorkSummaryInput | None:
        with self._connect() as db:
            row = db.execute(
                f'select * from ({WORK_SUMMARY_INPUT_SQL}) where id=?', (input_id,)
            ).fetchone()
        return WorkSummaryInput.model_validate(dict(row)) if row is not None else None

    @staticmethod
    def _close_task_runs_leaving_processing(
        db: sqlite3.Connection,
        input_ids: Sequence[int],
    ) -> int:
        """Close the runs and runtime attempts of inputs leaving 'processing'.

        recover_orphaned_task_agent_runs can only see an orphan once its parent
        input is no longer processing, so running it *before* the reset that
        creates the orphans finds nothing and the wreckage waits for the next
        restart. Closing in the same transaction as the status change removes
        the ordering question entirely: an input never leaves 'processing'
        while a live run or a leased runtime attempt still points at it.

        Only an attempt that has started no provider effect is closed; one that
        has is left alone for the ordinary effect reconciliation.
        """

        if not input_ids:
            return 0
        placeholders = ",".join("?" for _ in input_ids)
        run_rows = db.execute(
            f"""select r.id from runs r join run_provenance p on p.run_id=r.id
            where p.source_type='task_agent_runs' and r.status='running'
              and r.task_id in ({placeholders})""", list(input_ids),
        ).fetchall()
        if not run_rows:
            return 0
        run_ids = [int(row["id"]) for row in run_rows]
        run_placeholders = ",".join("?" for _ in run_ids)
        from app import run_entity_storage
        now = db.execute("select current_timestamp").fetchone()[0]
        for run_id in run_ids:
            run_entity_storage.update_run_cas(
                db, run_id=run_id, expected={"status": "running"},
                changes={"status": "failed", "error": "orphaned_task_agent_run_parent_not_processing",
                         "completed_at": now, "updated_at": now},
            )
        db.execute(
            f"""
            update runtime_attempts as agent_runtime_attempts
            set status='failed', failure_class='process',
                failure_code='runtime_parent_terminal_no_effect',
                failover_permitted=1, lease_owner='', lease_expires_at='',
                finished_at=current_timestamp, updated_at=current_timestamp
            where parent_id in ({run_placeholders}) and workload_kind='task'
              and status in ('starting', 'running')
              and first_effect_started_at=''
            """,
            run_ids,
        )
        return len(run_ids)

    def reset_stale_processing_work_summary_inputs(self, max_age_seconds: int) -> int:
        if max_age_seconds <= 0:
            return 0
        with self._connect() as db:
            db.execute("begin immediate")
            stale = [
                int(row["id"])
                for row in db.execute(
                    f"""
                    select id from ({WORK_SUMMARY_INPUT_SQL})
                    where status='processing'
                      and datetime(updated_at) <= datetime('now', ?)
                    """,
                    (f"-{int(max_age_seconds)} seconds",),
                )
            ]
            if not stale:
                return 0
            placeholders = ",".join("?" for _ in stale)
            cursor = db.execute(
                f"""
                update tasks
                set status='pending',attempts=max(attempts-1,0),error='',updated_at=current_timestamp where kind='work_summary' and id in ({placeholders}) and status='processing'
                """,
                stale,
            )
            self._close_task_runs_leaving_processing(db, stale)
            return cursor.rowcount

    def reset_processing_work_summary_inputs(self) -> list[WorkSummaryInput]:
        with self._immediate_write_transaction() as db:
            rows = db.execute(
                f"""
                select *
                from ({WORK_SUMMARY_INPUT_SQL})
                where status='processing'
                order by updated_at, id
                """
            ).fetchall()
            input_ids = [row["id"] for row in rows]
            if not input_ids:
                return []
            placeholders = ",".join("?" for _ in input_ids)
            db.execute(
                f"""
                update tasks
                set status='pending',attempts=max(attempts-1,0),error='',updated_at=current_timestamp where kind='work_summary' and id in ({placeholders}) and status='processing'
                """,
                input_ids,
            )
            self._close_task_runs_leaving_processing(db, input_ids)
            return [WorkSummaryInput.model_validate(dict(row)) for row in rows]

    def mark_work_summary_input_done(
        self, input_id: int, *, _db: sqlite3.Connection | None = None
    ) -> None:
        with self._optional_connection(_db) as db:
            self._compact_work_summary_input(db, input_id, status="done", error="")

    def mark_work_summary_input_skipped(
        self,
        input_id: int,
        reason: str,
        *,
        _db: sqlite3.Connection | None = None,
    ) -> None:
        with self._optional_connection(_db) as db:
            self._compact_work_summary_input(db, input_id, status="skipped", error=reason)

    def mark_work_summary_input_failed(self, input_id: int, error: str) -> None:
        with self._connect() as db:
            db.execute(
                """
                update tasks
                set status='failed',error=?,updated_at=current_timestamp where kind='work_summary' and id=? and status not in ('done','skipped')
                  and exists(select 1 from work_summary_inputs where task_id=tasks.id and body_compacted=0)
                """,
                (error, input_id),
            )

    def requeue_failed_work_summary_input(self, input_id: int, reason: str) -> bool:
        """Restore one reviewed failure after its root cause has been fixed."""
        with self._connect() as db:
            cursor = db.execute(
                """
                update tasks
                set status='pending',attempts=0,error=?,available_at='',updated_at=current_timestamp where kind='work_summary' and id=? and status='failed'
                  and exists(select 1 from work_summary_inputs where task_id=tasks.id and body_compacted=0)
                """,
                (reason.strip(), input_id),
            )
            return cursor.rowcount == 1

    def schedule_work_summary_input_retry(
        self, input_id: int, error: str, *, available_at: str
    ) -> None:
        with self._connect() as db:
            cursor = db.execute(
                """
                update tasks
                set status='pending',error=?,available_at=?,updated_at=current_timestamp where kind='work_summary' and id=? and status not in ('done','skipped')
                  and exists(select 1 from work_summary_inputs where task_id=tasks.id and body_compacted=0)
                """,
                (error, available_at, input_id),
            )
            if cursor.rowcount:
                self._close_task_runs_leaving_processing(db, [input_id])

    def defer_work_summary_input_for_capacity(
        self, input_id: int, error: str, *, available_at: str
    ) -> None:
        with self._connect() as db:
            cursor = db.execute(
                """
                update tasks
                set status='pending',attempts=max(attempts-1,0),error=?,available_at=?,updated_at=current_timestamp where kind='work_summary' and id=? and status in ('processing','failed')
                  and exists(select 1 from work_summary_inputs where task_id=tasks.id and body_compacted=0)
                """,
                (error, available_at, input_id),
            )
            if cursor.rowcount:
                self._close_task_runs_leaving_processing(db, [input_id])

    def defer_meeting_alignment_job_for_capacity(
        self, job_id: int, *, available_at: str, error: str
    ) -> None:
        from app.task_entity_storage import get_task, update_task_cas
        with self._immediate_write_transaction() as db:
            task = get_task(db, job_id)
            if task is None or task["kind"] != "meeting_alignment" or task["status"] != "processing":
                return
            update_task_cas(db, task_id=job_id,
                expected={"status": "processing", "locked_at": task["locked_at"]},
                changes={"status": "retry", "attempts": max((task["attempts"] or 0) - 1, 0),
                         "locked_at": None, "available_at": available_at, "error": error,
                         "updated_at": db.execute("select current_timestamp").fetchone()[0]})

    @staticmethod
    def _filter_allowed_values(
        values: dict[str, object],
        allowed_columns: set[str],
    ) -> dict[str, object]:
        unknown_columns = set(values) - allowed_columns
        if unknown_columns:
            unknown = ", ".join(sorted(unknown_columns))
            raise ValueError(f"Unsupported column(s): {unknown}")
        return dict(values)



    def get_work_project(
        self, project_id: int, *, _db: sqlite3.Connection | None = None
    ) -> WorkProject | None:
        with self._optional_connection(_db) as db:
            row = db.execute(f"select * from ({BUSINESS_PROJECTIONS['work_project']}) where id=?",
                             (project_id,)).fetchone()
            return None if row is None else WorkProject.model_validate(dict(row))


    def list_work_todos(
        self,
        *,
        project_id: int | None = None,
        statuses: tuple[str, ...] | None = None,
    ) -> list[WorkTodo]:
        query = f"select * from ({BUSINESS_PROJECTIONS['work_todo']})"
        clauses: list[str] = []
        args: list[str | int] = []
        if project_id is not None:
            clauses.append("project_id=?")
            args.append(project_id)
        if statuses:
            clauses.append(f"status in ({','.join('?' for _ in statuses)})")
            args.extend(statuses)
        if clauses:
            query = f"{query} where {' and '.join(clauses)}"
        query = f"{query} order by id"
        with self._connect() as db:
            return [WorkTodo.model_validate(dict(row)) for row in db.execute(query, args)]

