    def resolve_errors(self, error_ids: list[int], *, resolution: str) -> int:
        """Close verified historical incidents without removing their audit rows."""
        unique_ids = sorted({error_id for error_id in error_ids if error_id > 0})
        if not unique_ids:
            return 0
        if not resolution.strip():
            raise ValueError("error resolution must be non-empty")
        placeholders = ",".join("?" for _ in unique_ids)
        with self._connect() as db:
            cursor = db.execute(
                f"""
                update actions
                set {ERROR_RESOLVE_PARAM_SET_SQL}
                where record_type='errors' and cast(legacy_key as integer) in ({placeholders})
                  and error_resolved_at=''
                """,
                (resolution.strip(), *unique_ids),
            )
            return cursor.rowcount

    def resolve_errors_before_successful_component_tick(
        self, component: str, *, tick_at: datetime
    ) -> int:
        if not component.strip():
            raise ValueError("component must be non-empty")
        instant = tick_at if tick_at.tzinfo else tick_at.replace(tzinfo=timezone.utc)
        # SQLite incident timestamps have second precision; the tick's second
        # cannot establish whether an incident preceded or followed its start.
        cutoff = instant.astimezone(timezone.utc).replace(microsecond=0).isoformat()
        with self._connect() as db:
            eligible = db.execute(
                f"""
                select 1 from ({ERROR_SQL})
                where kind=? and coalesce(resolved_at, '')=''
                  and julianday(created_at) < julianday(?) limit 1
                """,
                (component, cutoff),
            ).fetchone()
        if eligible is None:
            return 0
        with self._immediate_write_transaction() as db:
            cursor = db.execute(
                f"""
                update actions
                set {ERROR_RESOLVE_PARAM_SET_SQL}
                where record_type='errors' and error_kind=? and coalesce(error_resolved_at, '')=''
                  and julianday(created_at) < julianday(?)
                """,
                (
                    f"recovered_by_successful_tick:{instant.isoformat()}",
                    component,
                    cutoff,
                ),
            )
            return cursor.rowcount

    def resolve_unresolved_errors_by_kind(
        self,
        kind: str,
        *,
        resolution: str,
    ) -> int:
        """Close service incidents after the same component succeeds later."""
        normalized_kind = kind.strip()
        normalized_resolution = resolution.strip()
        if not normalized_kind:
            raise ValueError("error kind must be non-empty")
        if not normalized_resolution:
            raise ValueError("error resolution must be non-empty")
        with self._immediate_write_transaction() as db:
            cursor = db.execute(
                f"""
                update actions
                set {ERROR_RESOLVE_PARAM_SET_SQL}
                where record_type='errors' and replace(error_kind, '-', '_')=replace(?, '-', '_')
                  and coalesce(error_resolved_at, '')=''
                """,
                (normalized_resolution, normalized_kind),
            )
            return cursor.rowcount

