    def list_operation_logs(
        self,
        limit: int | None = None,
        offset: int = 0,
        query: str = "",
        log_type: str = "",
        statuses: tuple[str, ...] | None = None,
        history_types: tuple[str, ...] | None = None,
        source_tables: tuple[str, ...] | None = None,
    ) -> list[OperationLog]:
        sql = f"select * from ({self._operation_logs_base_query(source_tables)}) as operation_logs"
        where_sql, where_args = self._operation_log_filters(
            query=query,
            log_type=log_type,
            statuses=statuses,
            history_types=history_types,
            source_tables=source_tables,
        )
        sql = f"""
            {sql}
            {where_sql}
            order by occurred_at desc, source_table desc, source_id desc
        """
        args: list[object] = [*where_args]
        if limit is not None:
            sql = f"{sql} limit ? offset ?"
            args.extend([limit, max(0, offset)])
        with self._connect() as db:
            rows = db.execute(sql, tuple(args)).fetchall()
            return [OperationLog.model_validate(dict(row)) for row in rows]

    def list_operation_logs_with_count(
        self,
        limit: int,
        offset: int = 0,
        query: str = "",
        log_type: str = "",
        statuses: tuple[str, ...] | None = None,
        history_types: tuple[str, ...] | None = None,
        source_tables: tuple[str, ...] | None = None,
    ) -> tuple[int, list[OperationLog]]:
        """Count compact keys, then hydrate only the page in one snapshot."""
        if (
            statuses == ("failed",)
            and not query.strip()
            and not log_type.strip()
            and not history_types
            and source_tables
        ):
            return self._list_failed_operation_logs_with_count(
                limit=limit,
                offset=offset,
                source_tables=source_tables,
            )
        where_sql, where_args = self._operation_log_filters(
            query=query,
            log_type=log_type,
            statuses=statuses,
            history_types=history_types,
            source_tables=source_tables,
        )
        compact_query, branch_count = self._operation_logs_key_query(
            source_tables, where_sql
        )
        sql = f"""
            with operation_logs as (
                {compact_query}
            )
            select source_table, source_id, count(*) over() as __total
            from operation_logs
            order by occurred_at desc, source_table desc, source_id desc
            limit ? offset ?
        """
        args = [*(where_args * branch_count), max(0, limit), max(0, offset)]
        with self.read_snapshot(), self._connect() as db:
            page_keys = db.execute(sql, tuple(args)).fetchall()
            if page_keys:
                total = int(page_keys[0]["__total"] or 0)
                items_by_key = {}
                for table in dict.fromkeys(row["source_table"] for row in page_keys):
                    ids = [
                        row["source_id"] for row in page_keys
                        if row["source_table"] == table
                    ]
                    # Keep parameters below SQLite's limit for larger callers.
                    for start in range(0, len(ids), 800):
                        batch = ids[start:start + 800]
                        placeholders = ",".join("?" for _ in batch)
                        rows = db.execute(
                            f"select * from ({self._operation_logs_base_query((table,))}) "
                            f"where source_id in ({placeholders})",
                            tuple(batch),
                        ).fetchall()
                        for row in rows:
                            item = OperationLog.model_validate(dict(row))
                            items_by_key[(item.source_table, item.source_id)] = item
                result = (
                    total,
                    [items_by_key[(row["source_table"], row["source_id"])]
                     for row in page_keys],
                )
            else:
                result = (
                    self.count_operation_logs(
                        query=query,
                        log_type=log_type,
                        statuses=statuses,
                        history_types=history_types,
                        source_tables=source_tables,
                    ),
                    [],
                )
        return result

    def _operation_logs_key_query(
        self, source_tables: tuple[str, ...] | None, where_sql: str
    ) -> tuple[str, int]:
        # Reuse each source's full projection and its existing source selection;
        # SQLite can omit display and status expressions for unfiltered keys.
        if source_tables:
            branches = [
                self._operation_logs_base_query((source,))
                for source in dict.fromkeys(source_tables)
            ]
        else:
            branches = self._operation_logs_base_query().split("union all")
        compact = [
            "select source_table, source_id, occurred_at from ("
            + branch + ") as source " + where_sql
            for branch in branches
        ]
        return " union all ".join(compact), len(compact)

    def _list_failed_operation_logs_with_count(
        self,
        *,
        limit: int,
        offset: int,
        source_tables: tuple[str, ...],
    ) -> tuple[int, list[OperationLog]]:
        """Project only raw rows that can still map to failed History status."""
        candidate_queries = {
            "reply_tasks": (
                f"select id as source_id, updated_at as occurred_at "
                f"from ({NATIVE_REPLY_TASK_CURRENT_SQL}) where status='failed'"
            ),
            "reply_attempts": (
                "select source_id, occurred_at from ("
                + self._operation_logs_base_query(("reply_attempts",))
                + ") where status='failed'"
            ),
            "meeting_alignment_runs": f"""
                select runs.id as source_id, runs.created_at as occurred_at
                from ({NATIVE_MEETING_RUN_SQL}) as runs
                join ({NATIVE_MEETING_TASK_SQL}) as jobs on jobs.id=runs.job_id
                where (
                    runs.status in ('retry', 'failed')
                    and jobs.status not in ('sent', 'no_action', 'skipped', 'done')
                ) or (runs.status='ready_to_send' and jobs.status in ('retry', 'failed'))
            """,
            "work_summary_inputs": (
                "select tasks.id as source_id, tasks.updated_at as occurred_at "
                "from tasks join work_summary_inputs on work_summary_inputs.task_id=tasks.id "
                "where tasks.kind='work_summary' and tasks.status='failed'"
            ),
            "todo_evidence_candidates": (
                "select id as source_id, updated_at as occurred_at "
                f"from ({BUSINESS_PROJECTIONS['todo_evidence_candidate']}) "
                "where status='failed'"
            ),
            "follow_up_drafts": (
                "select id as source_id, coalesce(nullif(sent_at, ''), created_at) as occurred_at "
                f"from ({SYNC_ACTION_PROJECTIONS['follow_up_drafts']}) where status='failed'"
            ),
            "work_todo_dingtalk_links": (
                "select id as source_id, updated_at as occurred_at "
                f"from ({SYNC_ACTION_PROJECTIONS['work_todo_dingtalk_links']}) where status='failed'"
            ),
            "scheduled_task_runs": f"""
                select runs.id as source_id,
                       coalesce(datetime(coalesce(nullif(runs.dispatched_at, ''), runs.created_at)),
                                runs.created_at) as occurred_at
                from schedule_occurrences as runs
                where runs.dispatch_status not in ('dispatched', 'skipped')
                  and {history_types.scheduled_run_filter_sql('runs')}
                  and not exists (
                      select 1 from schedule_occurrences as later_runs
                      where later_runs.scheduled_task_id=runs.scheduled_task_id
                        and later_runs.id>runs.id
                        and later_runs.dispatch_status='dispatched'
                  )
            """,
        }
        if (not source_tables or "actions" in source_tables) and self._email_actions_history_available():
            from app.email_store import DIRECT_ACTION_MAX_ATTEMPTS, DIRECT_EMAIL_ACTION_SQL

            candidate_queries["actions"] = f"""
                select actions.action_id as source_id,
                       coalesce(datetime(actions.updated_at), actions.updated_at) as occurred_at
                from ({DIRECT_EMAIL_ACTION_SQL}) as actions
                join ({email_classification_projection()}) as messages
                  on messages.id=actions.classification_id
                where actions.status='failed'
                  and actions.action_plan_id=coalesce(messages.current_action_plan_id, '')
                  and messages.status='processed'
                  and not (
                      actions.attempt_count<{DIRECT_ACTION_MAX_ATTEMPTS}
                      and trim(actions.next_attempt_at)<>''
                      and datetime(actions.next_attempt_at) is not null
                  )
            """

        candidate_keys: list[tuple[str, int, str]] = []
        with self.read_snapshot(), self._connect() as db:
            for source_table in source_tables:
                sql = candidate_queries.get(source_table)
                if sql is None:
                    continue
                candidate_keys.extend(
                    (source_table, int(row["source_id"]), row["occurred_at"] or "")
                    for row in db.execute(sql).fetchall()
                )

            candidate_keys.sort(key=lambda item: (item[2], item[0], item[1]), reverse=True)
            total = len(candidate_keys)
            start = max(0, offset)
            page_keys = candidate_keys[start:start + max(0, limit)]
            items_by_key: dict[tuple[str, int], OperationLog] = {}
            page_ids_by_source: dict[str, list[int]] = {}
            for source_table, source_id, _occurred_at in page_keys:
                page_ids_by_source.setdefault(source_table, []).append(source_id)

            for source_table, ids in page_ids_by_source.items():
                for start in range(0, len(ids), 800):
                    batch = ids[start:start + 800]
                    if source_table == "reply_attempts":
                        rows = self._failed_reply_attempt_operation_logs(db, batch)
                    else:
                        placeholders = ",".join("?" for _ in batch)
                        base = self._operation_logs_base_query((source_table,))
                        rows = db.execute(
                            f"select * from ({base}) as failed_candidates "
                            f"where source_id in ({placeholders}) and status='failed'",
                            tuple(batch),
                        ).fetchall()
                    for row in rows:
                        item = OperationLog.model_validate(dict(row))
                        items_by_key[(item.source_table, item.source_id)] = item
        items = [
            items_by_key[(source_table, source_id)]
            for source_table, source_id, _occurred_at in page_keys
            if (source_table, source_id) in items_by_key
        ]
        return total, items

    def _failed_reply_attempt_operation_logs(
        self, db: sqlite3.Connection, attempt_ids: list[int]
    ) -> list[sqlite3.Row]:
        placeholders = ",".join("?" for _ in attempt_ids)
        base = self._operation_logs_base_query(("reply_attempts",), attempt_ids)
        return db.execute(
            "select * from (" + base + ") as failed_attempts "
            f"where source_id in ({placeholders}) and status='failed'",
            tuple(attempt_ids),
        ).fetchall()

    def list_reply_attempt_operation_statuses(
        self, attempt_ids: list[int]
    ) -> dict[int, str]:
        """Project History statuses only for the attempts requested by a chart."""
        ids = list(dict.fromkeys(i for i in attempt_ids if type(i) is int and i > 0))
        if not ids:
            return {}
        statuses: dict[int, str] = {}
        with self._connect() as db:
            for start in range(0, len(ids), 800):
                chunk = ids[start : start + 800]
                placeholders = ", ".join("?" for _ in chunk)
                rows = db.execute(
                    "select source_id, status from ("
                    f"{self._operation_logs_base_query(('reply_attempts',), chunk)}"
                    f") where source_id in ({placeholders})",
                    tuple(chunk),
                ).fetchall()
                statuses.update(
                    {int(row["source_id"]): str(row["status"]) for row in rows}
                )
        return statuses

    def list_operation_log_types(self) -> list[str]:
        with self._connect() as db:
            rows = db.execute(
                f"""
                select distinct category
                from ({self._operation_logs_base_query()}) as operation_logs
                order by category asc
                """
            ).fetchall()
            return [str(row["category"]) for row in rows if row["category"]]

    def count_operation_logs(
        self,
        query: str = "",
        log_type: str = "",
        statuses: tuple[str, ...] | None = None,
        history_types: tuple[str, ...] | None = None,
        source_tables: tuple[str, ...] | None = None,
    ) -> int:
        where_sql, where_args = self._operation_log_filters(
            query=query,
            log_type=log_type,
            statuses=statuses,
            history_types=history_types,
            source_tables=source_tables,
        )
        with self._connect() as db:
            row = db.execute(
                f"""
                select count(*) as count
                from ({self._operation_logs_base_query(source_tables)}) as operation_logs {where_sql}
                """,
                tuple(where_args),
            ).fetchone()
            return int(row["count"] or 0)

    def _email_actions_history_available(self) -> bool:
        """Whether EmailStore has initialized the selected Email schema."""
        with self._connect() as db:
            return current_email_actions_available(db)

    def _operation_logs_base_query(
        self,
        source_tables: tuple[str, ...] | None = None,
        reply_attempt_ids: list[int] | tuple[int, ...] | None = None,
    ) -> str:
        oa_status_projection = """(
            (reply_attempts.action='oa_approval'
             or coalesce(reply_attempts.oa_process_instance_id, '')<>'')
            and reply_attempts.send_status in (
                'blocked', 'completed', 'commented', 'decision_selected', 'failed',
                'recovered', 'skipped'
            )
        )"""
        query = f"""
            select
                    'error:' || id as id,
                    'errors' as source_table,
                    id as source_id,
                    created_at as occurred_at,
                    'Error' as category,
                    kind as action,
                    case
                        when coalesce(resolved_at, '')<>'' then
                            'resolved: ' || coalesce(nullif(resolution, ''), 'verified recovery')
                        else 'active'
                    end as status,
                    '{history_types.SERVICE_ERROR}' as history_type,
                    'Service error' as source_actor,
                    coalesce(conversation_id, '') as context,
                    detail as summary,
                    case when coalesce(resolved_at, '')='' then detail
                         else detail || char(10) || 'Resolved: ' || resolution end as detail,
                    coalesce(conversation_id, '') as conversation_id,
                    coalesce(message_id, '') as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from ({ERROR_SQL})
                union all
                select
                    'reply-task:' || id as id,
                    'reply_tasks' as source_table,
                    id as source_id,
                    updated_at as occurred_at,
                    'Reply task' as category,
                    status as action,
                    status as status,
                    '{history_types.QUEUE}' as history_type,
                    'Reply task' as source_actor,
                    conversation_title as context,
                    trigger_text as summary,
                    error as detail,
                    conversation_id as conversation_id,
                    trigger_message_id as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from ({NATIVE_REPLY_TASK_CURRENT_SQL})
                union all
                select
                    'reply:' || id as id,
                    'reply_attempts' as source_table,
                    id as source_id,
                    updated_at as occurred_at,
                    'Reply' as category,
                    action as action,
                    case
                        -- A source-terminal closure skips further handling while
                        -- preserving the uncertain provider delivery as audit data.
                        when {TERMINAL_OA_SOURCE_SKIP_SQL} then 'skipped'
                        -- Current unresolved System Execution uncertainty
                        -- outranks a terminal task status. Resolved attempts
                        -- keep their existing resolution projection.
                        when send_status<>'skipped' and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as uncertain_attempt_run
                            join ({NATIVE_CANDIDATE_REVIEW_SQL}) as uncertain_review
                              on uncertain_review.audit_run_id=uncertain_attempt_run.id
                            join ({NATIVE_REVIEW_CANDIDATE_SQL}) as uncertain_candidate
                              on uncertain_candidate.id=uncertain_review.candidate_id
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as uncertain_task
                              on uncertain_task.id=uncertain_candidate.task_id
                             and uncertain_task.execution_generation=uncertain_candidate.execution_generation
                            join ({NATIVE_CANDIDATE_EXECUTION_SQL}) as uncertain_execution
                              on uncertain_execution.candidate_id=uncertain_candidate.id
                            where uncertain_attempt_run.id=reply_attempts.agent_run_id
                              and uncertain_task.execution_generation=uncertain_attempt_run.execution_generation
                              and uncertain_execution.status='uncertain'
                              and uncertain_candidate.id=(
                                  select max(current_candidate.id)
                                  from ({NATIVE_REVIEW_CANDIDATE_SQL}) as current_candidate
                                  where current_candidate.task_id=uncertain_task.id
                                    and current_candidate.execution_generation=uncertain_task.execution_generation
                              )
                        ) then 'uncertain'
                        -- A failed legacy OA Attempt can point to a task whose
                        -- current execution is still awaiting an external
                        -- receipt. Detail resolves this from the task even
                        -- when the historical run link is missing or stale.
                        -- Preserve that uncertainty before projecting the
                        -- task's terminal failure below.
                        when {oa_status_projection} and send_status='failed' and exists (
                            select 1
                            from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as uncertain_message_task
                            where uncertain_message_task.channel=reply_attempts.channel
                              and uncertain_message_task.conversation_id=reply_attempts.conversation_id
                              and uncertain_message_task.trigger_message_id=reply_attempts.trigger_message_id
                              and uncertain_message_task.status='failed'
                              and uncertain_message_task.error='external_action_uncertain'
                        ) then 'uncertain'
                        when send_status='needs_human' and trim(coalesce(resolved_at, ''))<>'' then 'skipped'
                        -- The list and Attempt detail share the current task
                        -- generation as their status source. Keep the action
                        -- column as the historical operation label; do not
                        -- leave successful terminal task states as legacy
                        -- Attempt labels such as completed/commented.
                        when {oa_status_projection} and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and projected_task.status in ('done', 'skipped', 'needs_human', 'failed')
                              and coalesce(projected_task.error, '')<>'external_action_uncertain'
                        ) then (
                            select case
                                when projected_task.status='done'
                                 and send_status='skipped'
                                 and projected_run.status='completed'
                                 and projected_run.id=(
                                     select latest_current_run.id
                                     from ({NATIVE_AGENT_RUN_SQL}) as latest_current_run
                                     where latest_current_run.reply_task_id=projected_task.id
                                       and latest_current_run.execution_generation=projected_task.execution_generation
                                     order by coalesce(latest_current_run.proposal_revision, 0) desc,
                                              case when latest_current_run.role='audit' then 1 else 0 end desc,
                                              coalesce(latest_current_run.turn_attempt, 0) desc,
                                              latest_current_run.id desc
                                     limit 1
                                 )
                                 and projected_run.id=reply_attempts.agent_run_id
                                then 'skipped'
                                else projected_task.status
                            end
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and projected_task.status in ('done', 'skipped', 'needs_human', 'failed')
                              and coalesce(projected_task.error, '')<>'external_action_uncertain'
                            limit 1
                        )
                        when {oa_status_projection}
                         and not exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as bound_attempt_run
                            where bound_attempt_run.id=reply_attempts.agent_run_id
                         ) and exists (
                            select 1
                            from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as message_task
                            where message_task.channel=reply_attempts.channel
                              and message_task.conversation_id=reply_attempts.conversation_id
                              and message_task.trigger_message_id=reply_attempts.trigger_message_id
                              and message_task.status in ('done', 'skipped', 'needs_human', 'failed')
                              and coalesce(message_task.error, '')<>'external_action_uncertain'
                        ) then (
                            select message_task.status
                            from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as message_task
                            where message_task.channel=reply_attempts.channel
                              and message_task.conversation_id=reply_attempts.conversation_id
                              and message_task.trigger_message_id=reply_attempts.trigger_message_id
                              and message_task.status in ('done', 'skipped', 'needs_human', 'failed')
                              and coalesce(message_task.error, '')<>'external_action_uncertain'
                            order by message_task.id desc
                            limit 1
                        )
                        when {oa_status_projection} and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and coalesce(projected_task.error, '')<>'external_action_uncertain'
                              and (
                                  select latest_current_run.status
                                  from ({NATIVE_AGENT_RUN_SQL}) as latest_current_run
                                  where latest_current_run.reply_task_id=projected_task.id
                                    and latest_current_run.execution_generation=projected_task.execution_generation
                                  order by coalesce(latest_current_run.proposal_revision, 0) desc,
                                           case when latest_current_run.role='audit' then 1 else 0 end desc,
                                           coalesce(latest_current_run.turn_attempt, 0) desc,
                                           latest_current_run.id desc
                                  limit 1
                              ) in ('pending', 'running', 'failed')
                        ) then (
                            select (
                                select latest_current_run.status
                                from ({NATIVE_AGENT_RUN_SQL}) as latest_current_run
                                where latest_current_run.reply_task_id=projected_task.id
                                  and latest_current_run.execution_generation=projected_task.execution_generation
                                order by coalesce(latest_current_run.proposal_revision, 0) desc,
                                         case when latest_current_run.role='audit' then 1 else 0 end desc,
                                         coalesce(latest_current_run.turn_attempt, 0) desc,
                                         latest_current_run.id desc
                                limit 1
                            )
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and coalesce(projected_task.error, '')<>'external_action_uncertain'
                            limit 1
                        )
                        when {oa_status_projection} and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and (
                                  coalesce(projected_task.error, '')<>'external_action_uncertain'
                                  or exists (
                                      select 1
                                      from ({NATIVE_REVIEW_CANDIDATE_SQL}) as verified_candidate
                                      join ({NATIVE_CANDIDATE_REVIEW_SQL}) as verified_review
                                        on verified_review.candidate_id=verified_candidate.id
                                       and verified_review.audit_run_id=projected_run.id
                                      join ({NATIVE_CANDIDATE_EXECUTION_SQL}) as verified_execution
                                        on verified_execution.candidate_id=verified_candidate.id
                                       and verified_execution.review_id=verified_review.id
                                      where verified_candidate.task_id=projected_task.id
                                        and verified_candidate.execution_generation=projected_task.execution_generation
                                        and verified_candidate.id=(
                                            select max(latest_candidate.id)
                                            from ({NATIVE_REVIEW_CANDIDATE_SQL}) as latest_candidate
                                            where latest_candidate.task_id=projected_task.id
                                              and latest_candidate.execution_generation=projected_task.execution_generation
                                        )
                                        and verified_execution.status='done'
                                  )
                              )
                              and projected_task.status in ('pending', 'processing', 'running')
                        ) then (
                            select case when projected_task.status='processing' then 'running'
                                        else projected_task.status end
                            from ({NATIVE_AGENT_RUN_SQL}) as projected_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as projected_task
                              on projected_task.id=projected_run.reply_task_id
                            where projected_run.id=reply_attempts.agent_run_id
                              and projected_run.execution_generation=projected_task.execution_generation
                              and (
                                  coalesce(projected_task.error, '')<>'external_action_uncertain'
                                  or exists (
                                      select 1
                                      from ({NATIVE_REVIEW_CANDIDATE_SQL}) as verified_candidate
                                      join ({NATIVE_CANDIDATE_REVIEW_SQL}) as verified_review
                                        on verified_review.candidate_id=verified_candidate.id
                                       and verified_review.audit_run_id=projected_run.id
                                      join ({NATIVE_CANDIDATE_EXECUTION_SQL}) as verified_execution
                                        on verified_execution.candidate_id=verified_candidate.id
                                       and verified_execution.review_id=verified_review.id
                                      where verified_candidate.task_id=projected_task.id
                                        and verified_candidate.execution_generation=projected_task.execution_generation
                                        and verified_candidate.id=(
                                            select max(latest_candidate.id)
                                            from ({NATIVE_REVIEW_CANDIDATE_SQL}) as latest_candidate
                                            where latest_candidate.task_id=projected_task.id
                                              and latest_candidate.execution_generation=projected_task.execution_generation
                                        )
                                        and verified_execution.status='done'
                                  )
                              )
                              and projected_task.status in ('pending', 'processing', 'running')
                            limit 1
                        )
                        -- With no owning task, keep the Attempt's own failure
                        -- or block status. The generic supersession rule can
                        -- call an old row `recovered`, but Attempt detail has
                        -- no current task generation to project in this case.
                        when {oa_status_projection} and send_status in ('blocked', 'failed')
                            then send_status
                        -- Candidate completion is independent of delivery.
                        -- Only the latest delivery for this object and its
                        -- owning task generation supplies its send outcome.
                        when channel='wechat' and send_status='failed' and exists (
                            select 1 from ({WECHAT_DELIVERY_SQL}) as delivery
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as delivery_task
                              on delivery_task.id=delivery.reply_task_id
                            where delivery_task.channel=reply_attempts.channel
                              and delivery.conversation_id=reply_attempts.conversation_id
                              and delivery_task.conversation_id=reply_attempts.conversation_id
                              and delivery_task.trigger_message_id=reply_attempts.trigger_message_id
                              and delivery.execution_generation=delivery_task.execution_generation
                              and delivery.status in ('failed', 'send_unknown')
                              and delivery.id=(
                                  select max(current_delivery.id) from ({WECHAT_DELIVERY_SQL}) as current_delivery
                                  where current_delivery.reply_task_id=delivery_task.id
                                    and current_delivery.execution_generation=delivery_task.execution_generation
                              )
                        ) then 'failed'
                        -- Attempt detail follows the stable AgentRun task ID.
                        -- The current task's DingTalk trigger key can change
                        -- during OA scanning, so terminal state must not be
                        -- inferred only from the historical message key.
                        when send_status='failed' and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as bound_attempt_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as bound_current_task
                              on bound_current_task.id=bound_attempt_run.reply_task_id
                            where bound_attempt_run.id=reply_attempts.agent_run_id
                              and coalesce(bound_current_task.error, '')='external_action_uncertain'
                        ) then 'uncertain'
                        when send_status='failed' and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as bound_attempt_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as bound_current_task
                              on bound_current_task.id=bound_attempt_run.reply_task_id
                            where bound_attempt_run.id=reply_attempts.agent_run_id
                              and bound_current_task.status in ('done', 'skipped', 'needs_human')
                              and coalesce(bound_current_task.error, '')<>'external_action_uncertain'
                        ) then (
                            select bound_current_task.status
                            from ({NATIVE_AGENT_RUN_SQL}) as bound_attempt_run
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as bound_current_task
                              on bound_current_task.id=bound_attempt_run.reply_task_id
                            where bound_attempt_run.id=reply_attempts.agent_run_id
                              and coalesce(bound_current_task.error, '')<>'external_action_uncertain'
                            limit 1
                        )
                        -- A failed attempt whose own task was handed to Derek
                        -- reads `needs_human`, not `recovered`. The task and
                        -- the attempt are two projections of one piece of
                        -- work, and only the task was updated: /attempts/9670
                        -- showed a failure for work already handed over, and
                        -- History listed no needs_human at all while four
                        -- tasks sat in it. The attempt row itself is left
                        -- alone -- it carries no structured decision, and
                        -- inventing one would be fabricating an answer.
                        when send_status='failed' and exists (
                            select 1
                            from ({NATIVE_AGENT_RUN_SQL}) as handed_over_runs
                            join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as handed_over_tasks
                              on handed_over_tasks.id=handed_over_runs.reply_task_id
                            where handed_over_runs.id=reply_attempts.agent_run_id
                              and handed_over_tasks.status='needs_human'
                              and handed_over_runs.execution_generation
                                  =handed_over_tasks.execution_generation
                        ) then 'needs_human'
                        when send_status='failed' and (
                            reply_attempts.terminal_id>reply_attempts.id
                            or exists (
                                select 1
                                from ({NATIVE_REPLY_TASK_CURRENT_SQL}) as terminal_tasks
                                where terminal_tasks.channel=reply_attempts.channel
                                  and terminal_tasks.conversation_id=reply_attempts.conversation_id
                                  and terminal_tasks.trigger_message_id=reply_attempts.trigger_message_id
                                  and terminal_tasks.status in ('done', 'skipped', 'needs_human')
                            )
                            or exists (
                                select 1
                                from ({NATIVE_REPLY_BUSINESS_KEY_SQL}) as current_business_object
                                join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                                  on current_task.id=current_business_object.reply_task_id
                                where current_business_object.business_object_key=(
                                    'message:' || reply_attempts.channel || ':' ||
                                    reply_attempts.conversation_id || ':' ||
                                    reply_attempts.trigger_message_id
                                )
                                  and current_task.status in ('done', 'skipped', 'needs_human')
                            )
                            or coalesce(reply_attempts.resolved_at, '')<>''
                        ) then 'recovered'
                        -- A superseded attempt is dead history whatever status
                        -- it stopped on, but only a strictly newer terminal
                        -- attempt on the same trigger proves it was superseded.
                        -- The terminal-task branches above must NOT apply here:
                        -- a needs_human attempt always sits on a task the
                        -- service closed as done, so they would retire every
                        -- open question, including ones nobody has answered.
                        when send_status in ('blocked', 'needs_human', 'pending')
                            and (
                            reply_attempts.terminal_id>reply_attempts.id
                            or coalesce(reply_attempts.resolved_at, '')<>''
                        ) then 'recovered'
                        else send_status
                    end as status,
                    {history_types.reply_attempt_history_type_sql()} as history_type,
                    trigger_sender as source_actor,
                    conversation_title as context,
                    trigger_text as summary,
                    -- What the run produced: the reply it sent, or the audit
                    -- conclusion when it sent nothing. Without it a reader has
                    -- only the trigger text and cannot tell the two apart.
                    trim(
                        coalesce(
                            nullif(final_reply_text, ''),
                            nullif(audit_summary, ''),
                            ''
                        )
                        || case when send_error<>''
                                then char(10) || send_error else '' end
                        || case when coalesce(resolved_at, '')<>''
                                then char(10) || 'Resolved: ' || resolution
                                else '' end
                    , char(10)) as detail,
                    conversation_id as conversation_id,
                    trigger_message_id as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from (
                  with terminal_attempts as materialized (
                    select attempt_channel as channel,
                           attempt_conversation_id as conversation_id,
                           attempt_trigger_message_id as trigger_message_id,
                           max(cast(legacy_key as integer)) as terminal_id
                    from actions
                    where record_type='reply_attempts'
                      and attempt_send_status in (
                          'sent', 'completed', 'skipped', 'needs_human',
                          'reacted', 'commented', 'calendar', 'document'
                      )
                    group by attempt_channel, attempt_conversation_id,
                             attempt_trigger_message_id
                  )
                  select reply_attempts_base.*,
                         (select terminal_id from terminal_attempts
                          where terminal_attempts.channel=reply_attempts_base.channel
                            and terminal_attempts.conversation_id=reply_attempts_base.conversation_id
                            and terminal_attempts.trigger_message_id=reply_attempts_base.trigger_message_id
                         ) as terminal_id
                  from ({REPLY_ATTEMPT_COMMON_SQL}) as reply_attempts_base
                ) as reply_attempts
                where {
            (
                "id in (" + ", ".join(str(int(i)) for i in reply_attempt_ids) + ") and "
                if reply_attempt_ids is not None
                else ""
            )
        }not exists (
                    select 1 from ({NATIVE_AGENT_RUN_SQL}) as attempt_run
                    join ({NATIVE_REPLY_TASK_CURRENT_SQL}) as current_task
                      on current_task.id=attempt_run.reply_task_id
                    where attempt_run.id=reply_attempts.agent_run_id
                      and attempt_run.execution_generation<>current_task.execution_generation
                )
                  and not exists (
                    with latest_task_attempt as materialized (
                        select runs.reply_task_id as task_id,
                               max(attempts.id) as attempt_id
                        from ({REPLY_ATTEMPT_COMMON_SQL}) as attempts
                        join ({NATIVE_AGENT_RUN_SQL}) as runs
                          on runs.id=attempts.agent_run_id
                        group by runs.reply_task_id
                    )
                    select 1
                    from ({NATIVE_AGENT_RUN_SQL}) as historical_run
                    join latest_task_attempt as latest
                      on latest.task_id=historical_run.reply_task_id
                    where historical_run.id = reply_attempts.agent_run_id
                      and latest.attempt_id > reply_attempts.id
                )
                union all
                select
                    'meeting:' || runs.id as id,
                    'meeting_alignment_runs' as source_table,
                    runs.id as source_id,
                    runs.created_at as occurred_at,
                    'Meeting' as category,
                    case
                        when jobs.status='no_action' then 'no_action'
                        else 'meeting_alignment'
                    end as action,
                    case
                        when runs.status='no_action' then 'skipped'
                        when runs.status in ('retry', 'failed')
                             and jobs.status in ('sent', 'no_action', 'skipped', 'done')
                            then 'recovered'
                        when runs.status in ('retry', 'failed') then 'failed'
                        when runs.status='ready_to_send' and jobs.status='sent' then 'sent'
                        when runs.status='ready_to_send' and jobs.status in ('retry', 'failed') then 'failed'
                        else runs.status
                    end as status,
                    '{history_types.MEETING}' as history_type,
                    'Meeting Alignment Agent' as source_actor,
                    jobs.title as context,
                    case when jobs.final_message<>'' then jobs.final_message
                         else '会议任务尚无已采用的最终消息。' end as summary,
                    case when jobs.final_message<>'' then jobs.final_message
                         else '会议任务尚无已采用的最终消息。' end as detail,
                    '' as conversation_id,
                    '' as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from ({NATIVE_MEETING_RUN_SQL}) as runs
                join ({NATIVE_MEETING_TASK_SQL}) as jobs on jobs.id=runs.job_id
                union all
                select
                    'task-input:' || id as id,
                    'work_summary_inputs' as source_table,
                    id as source_id,
                    updated_at as occurred_at,
                    'Task input' as category,
                    source_type || ':' || source_ref as action,
                    status as status,
                    '{history_types.TASK}' as history_type,
                    'Task input' as source_actor,
                    source_type || ':' || source_ref as context,
                    'Original input source: ' || source_type || ':' || source_ref ||
                    case when body_sha256<>'' then '; SHA-256 ' || body_sha256 ||
                        '; ' || body_bytes || ' bytes' else '' end as summary,
                    work_summary_tasks.error as detail,
                    '' as conversation_id,
                    '' as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from tasks as work_summary_tasks
                join work_summary_inputs on work_summary_inputs.task_id=work_summary_tasks.id
                where work_summary_tasks.kind='work_summary'
                union all
                select
                    'task-update:' || updates.id as id,
                    'work_updates' as source_table,
                    updates.id as source_id,
                    updates.created_at as occurred_at,
                    'Task update' as category,
                    updates.source_type || ':' || updates.source_ref as action,
                    'done' as status,
                    '{history_types.TASK}' as history_type,
                    'Task Agent' as source_actor,
                    projects.title as context,
                    updates.summary as summary,
                    updates.changes_json as detail,
                    '' as conversation_id,
                    '' as message_id,
                    updates.project_id as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from ({SYNC_ACTION_PROJECTIONS['work_updates']}) as updates
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=updates.project_id
                union all
                select
                    'todo-evidence:' || candidates.id as id,
                    'todo_evidence_candidates' as source_table,
                    candidates.id as source_id,
                    candidates.updated_at as occurred_at,
                    'TODO completion evidence' as category,
                    candidates.source_type || ':' || candidates.source_ref as action,
                    candidates.status as status,
                    '{history_types.TASK}' as history_type,
                    'Task Agent' as source_actor,
                    coalesce(nullif(todos.title, ''), projects.title) as context,
                    candidates.evidence_text as summary,
                    candidates.decision_json as detail,
                    '' as conversation_id,
                    '' as message_id,
                    candidates.project_id as project_id,
                    candidates.todo_id as todo_id,
                    0 as follow_up_id
                from ({BUSINESS_PROJECTIONS['todo_evidence_candidate']}) as candidates
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=candidates.project_id
                left join ({BUSINESS_PROJECTIONS['work_todo']}) as todos on todos.id=candidates.todo_id
                union all
                select
                    'follow-up:' || drafts.id as id,
                    'follow_up_drafts' as source_table,
                    drafts.id as source_id,
                    coalesce(nullif(drafts.sent_at, ''), drafts.created_at) as occurred_at,
                    'Follow-up' as category,
                    drafts.target_kind as action,
                    drafts.status as status,
                    '{history_types.TASK}' as history_type,
                    'Follow-up' as source_actor,
                    coalesce(nullif(todos.title, ''), drafts.owner_name, projects.title) as context,
                    drafts.question_text as summary,
                    drafts.send_result_json as detail,
                    drafts.target_conversation_id as conversation_id,
                    '' as message_id,
                    drafts.project_id as project_id,
                    drafts.todo_id as todo_id,
                    drafts.id as follow_up_id
                from ({SYNC_ACTION_PROJECTIONS['follow_up_drafts']}) as drafts
                join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=drafts.project_id
                left join ({BUSINESS_PROJECTIONS['work_todo']}) as todos on todos.id=drafts.todo_id
                union all
                select
                    'dingtalk-todo:' || links.id as id,
                    'work_todo_dingtalk_links' as source_table,
                    links.id as source_id,
                    links.updated_at as occurred_at,
                    'DingTalk Todo' as category,
                    links.dingtalk_task_id as action,
                    links.status as status,
                    '{history_types.TASK}' as history_type,
                    'DingTalk Todo' as source_actor,
                    coalesce(nullif(projects.title, ''), title_snapshot) as context,
                    links.title_snapshot as summary,
                    links.last_error as detail,
                    '' as conversation_id,
                    '' as message_id,
                    coalesce(projects.id, 0) as project_id,
                    links.work_todo_id as todo_id,
                    0 as follow_up_id
                from ({SYNC_ACTION_PROJECTIONS['work_todo_dingtalk_links']}) as links
                left join ({BUSINESS_PROJECTIONS['work_todo']}) as todos on todos.id=links.work_todo_id
                left join ({BUSINESS_PROJECTIONS['work_project']}) as projects on projects.id=todos.project_id
                union all
                select
                    'scheduled-run:' || runs.id as id,
                    'scheduled_task_runs' as source_table,
                    runs.id as source_id,
                    -- These tables write ISO-8601 with a 'T'; History sorts
                    -- the text, so it is put in the other sources' form.
                    coalesce(
                        datetime(coalesce(nullif(runs.dispatched_at, ''), runs.created_at)),
                        runs.created_at
                    ) as occurred_at,
                    'Scheduled task' as category,
                    coalesce(nullif(runs.execution_id, ''), runs.trigger_kind) as action,
                    case
                        when runs.dispatch_status='dispatched' then 'done'
                        when runs.dispatch_status='skipped' then 'skipped'
                        -- A later trigger of the same task that ran is the
                        -- recovery: the service resolves this failure's
                        -- Attention entry on that success.
                        when exists (
                            select 1 from schedule_occurrences as later_runs
                            where later_runs.scheduled_task_id=runs.scheduled_task_id
                              and later_runs.id>runs.id
                              and later_runs.dispatch_status='dispatched'
                        ) then 'recovered'
                        else 'failed'
                    end as status,
                    case
                        when coalesce(json_extract(configs.snapshot_json, '$.command'), '')<>''
                            then '{history_types.SCHEDULED_COMMAND}'
                        else '{history_types.SCHEDULED_AGENT}'
                    end as history_type,
                    case runs.trigger_kind
                        when 'manual' then 'Manual run'
                        else 'Scheduled task'
                    end as source_actor,
                    coalesce(
                        nullif(json_extract(configs.snapshot_json, '$.name'), ''),
                        'Scheduled task ' || runs.scheduled_task_id
                    ) as context,
                    coalesce(
                        nullif(runs.result_summary, ''),
                        nullif(runs.skip_or_error_reason, ''),
                        runs.dispatch_status
                    ) as summary,
                    runs.skip_or_error_reason as detail,
                    'scheduled-task:' || runs.scheduled_task_id as conversation_id,
                    runs.event_id as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from schedule_occurrences as runs
                join ({config_projection('scheduled_task_config_versions')}) as configs on configs.id=runs.snapshot_id
                where {history_types.scheduled_run_filter_sql("runs")}
        """
        if (not source_tables or "actions" in source_tables) and self._email_actions_history_available():
            # The EmailStore projection gives the common Action id and its
            # current receipt facts; the domain source label remains stable.
            from app.email_store import DIRECT_ACTION_MAX_ATTEMPTS, DIRECT_EMAIL_ACTION_SQL

            query += f"""
                union all
                select
                    'action:' || actions.action_id as id,
                    'actions' as source_table,
                    actions.action_id as source_id,
                    coalesce(datetime(actions.updated_at), actions.updated_at) as occurred_at,
                    'Email action' as category,
                    actions.action_type as action,
                    case
                        -- Only the current plan of a processed message is
                        -- still executed; anything else it left unfinished
                        -- never will be.
                        when actions.action_plan_id<>coalesce(messages.current_action_plan_id, '')
                             or messages.status<>'processed' then
                            case when actions.status in ('done', 'skipped')
                                 then actions.status else 'skipped' end
                        -- The same retry window as Attention and the status
                        -- page: a failure the worker will retry is pending.
                        when actions.status='failed'
                             and actions.attempt_count<{DIRECT_ACTION_MAX_ATTEMPTS}
                             and trim(actions.next_attempt_at)<>''
                             and datetime(actions.next_attempt_at) is not null
                            then 'pending'
                        else actions.status
                    end as status,
                    '{history_types.EMAIL_ACTION}' as history_type,
                    coalesce(nullif(messages.sender, ''), actions.account_id) as source_actor,
                    coalesce(
                        nullif(messages.subject, ''),
                        nullif(actions.provider_target, ''),
                        actions.action_type
                    ) as context,
                    case actions.action_type
                        when 'move' then '移动到「'
                            || coalesce(json_extract(actions.parameters_json, '$.target_folder'), '')
                            || '」'
                        when 'archive' then '归档'
                        when 'trash' then '移到垃圾箱'
                        when 'flag_important' then '标为重要'
                        when 'mark_read' then '标为已读'
                        when 'label' then '打标签'
                        else actions.action_type
                    end as summary,
                    actions.error as detail,
                    cast(actions.classification_id as text) as conversation_id,
                    '' as message_id,
                    0 as project_id,
                    0 as todo_id,
                    0 as follow_up_id
                from ({DIRECT_EMAIL_ACTION_SQL}) as actions
                join ({email_classification_projection()}) as messages
                  on messages.id=actions.classification_id
            """
        if not source_tables:
            return query
        requested = set(source_tables)
        branches = []
        for branch in query.split("union all"):
            match = re.search(r"'([^']+)' as source_table", branch)
            if match and match.group(1) in requested:
                branches.append(branch)
        return "union all".join(branches) if branches else f"select * from ({query}) where 0"

    def _operation_log_filters(
        self,
        query: str = "",
        log_type: str = "",
        statuses: tuple[str, ...] | None = None,
        history_types: tuple[str, ...] | None = None,
        source_tables: tuple[str, ...] | None = None,
    ) -> tuple[str, list[object]]:
        filters: list[str] = []
        args: list[object] = []
        if log_type.strip():
            filters.append("category = ?")
            args.append(log_type.strip())
        if statuses:
            placeholders = ",".join("?" for _ in statuses)
            filters.append(f"status in ({placeholders})")
            args.extend(statuses)
        if history_types:
            placeholders = ",".join("?" for _ in history_types)
            filters.append(f"history_type in ({placeholders})")
            args.extend(history_types)
        if source_tables:
            placeholders = ",".join("?" for _ in source_tables)
            filters.append(f"source_table in ({placeholders})")
            args.extend(source_tables)
        if query.strip():
            needle = f"%{query.strip().lower()}%"
            filters.append(
                "("
                " lower(coalesce(id, '')) like ?"
                " or lower(coalesce(category, '')) like ?"
                " or lower(coalesce(action, '')) like ?"
                " or lower(coalesce(status, '')) like ?"
                " or lower(coalesce(history_type, '')) like ?"
                " or lower(coalesce(source_actor, '')) like ?"
                " or lower(coalesce(source_table, '')) like ?"
                " or lower(coalesce(context, '')) like ?"
                " or lower(coalesce(summary, '')) like ?"
                " or lower(coalesce(detail, '')) like ?"
                ")"
            )
            args.extend([needle] * 10)
        if not filters:
            return "", args
        return "where " + " and ".join(filters), args

    def set_service_state(self, key: str, value: str) -> None:
        # Health and coordination state must use the same bounded lock retry as
        # other short writes; a transient writer collision must not terminate
        # a worker whose business queue is otherwise healthy.
        for attempt in range(STORE_WRITE_LOCK_RETRY_ATTEMPTS):
            try:
                with self._connect() as db:
                    db.execute("begin immediate")
                    upsert_state(
                        db, "service_state", {"key": key, "value": value},
                        {"value": state_json_field("value"),
                         "updated_at": "json_quote(current_timestamp)"},
                    )
                return
            except sqlite3.OperationalError as exc:
                if (
                    not _is_sqlite_lock_error(exc)
                    or attempt + 1 >= STORE_WRITE_LOCK_RETRY_ATTEMPTS
                ):
                    raise
                time.sleep(STORE_WRITE_LOCK_RETRY_DELAY_SECONDS * (attempt + 1))
        raise RuntimeError("service state write retry loop exhausted")




    @staticmethod
    def _as_utc(value: datetime) -> datetime:
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc)


    def active_codex_capacity_pause(self, *, now: datetime) -> str:
        """Return the shared retry timestamp while a Codex capacity pause is active."""
        raw = self.get_service_state(CODEX_CAPACITY_PAUSE_STATE_KEY)
        if not raw:
            return ""
        try:
            value = json.loads(raw)
            retry_at = str(value.get("retry_at") or "")
            retry_time = datetime.fromisoformat(retry_at)
        except (AttributeError, TypeError, ValueError, json.JSONDecodeError):
            return ""
        if retry_time.tzinfo is None:
            retry_time = retry_time.replace(tzinfo=timezone.utc)
        current = now.astimezone(timezone.utc)
        return retry_at if retry_time.astimezone(timezone.utc) > current else ""

    def codex_capacity_failure_count(self) -> int:
        raw = self.get_service_state(CODEX_CAPACITY_PAUSE_STATE_KEY)
        if not raw:
            return 0
        try:
            value = json.loads(raw)
            return max(int(value.get("failure_count") or 0), 0)
        except (AttributeError, TypeError, ValueError, json.JSONDecodeError):
            return 0

    def clear_codex_capacity_pause(self) -> None:
        with self._connect() as db:
            db.execute(
                "delete from state where record_type='service_state' and key=?",
                (CODEX_CAPACITY_PAUSE_STATE_KEY,),
            )

    def open_codex_capacity_pause(self, *, retry_at: str, now: datetime) -> bool:
        """Persist one shared capacity incident and report whether it is new."""
        retry_time = datetime.fromisoformat(retry_at)
        if retry_time.tzinfo is None:
            retry_time = retry_time.replace(tzinfo=timezone.utc)
        current = now.astimezone(timezone.utc)
        if retry_time.astimezone(timezone.utc) <= current:
            raise ValueError("codex capacity retry_at must be in the future")
        with self._immediate_write_transaction() as db:
            row = db.execute(
                f"select value from ({state_projection('service_state')}) where key=?",
                (CODEX_CAPACITY_PAUSE_STATE_KEY,),
            ).fetchone()
            active = False
            if row is not None:
                try:
                    previous = json.loads(row["value"])
                    previous_at = datetime.fromisoformat(
                        str(previous.get("retry_at") or "")
                    )
                    if previous_at.tzinfo is None:
                        previous_at = previous_at.replace(tzinfo=timezone.utc)
                    active = previous_at.astimezone(timezone.utc) > current
                except (AttributeError, TypeError, ValueError, json.JSONDecodeError):
                    active = False
            if active:
                return False
            failure_count = 1
            if row is not None:
                try:
                    previous = json.loads(row["value"])
                    failure_count = max(
                        int(previous.get("failure_count") or 0) + 1,
                        1,
                    )
                except (AttributeError, TypeError, ValueError, json.JSONDecodeError):
                    failure_count = 1
            upsert_state(
                db, 'service_state',
                {'key': CODEX_CAPACITY_PAUSE_STATE_KEY,
                 'value': json.dumps(
                     {'reason_code': 'workspace_credits_exhausted',
                      'retry_at': retry_at, 'failure_count': failure_count},
                     ensure_ascii=False, sort_keys=True,
                 )},
                {'value': state_json_field('value'),
                 'updated_at': 'json_quote(current_timestamp)'},
            )
            return True

    def claim_channel_login_request(
        self,
        *,
        channel: str,
        reason_code: str,
        now: datetime,
        suppression_seconds: int,
        reservation_owner: str,
    ) -> tuple[bool, dict[str, object]]:
        now_utc = now.astimezone(timezone.utc)
        key = f"channel_login_request:{channel}"
        with self._immediate_write_transaction() as db:
            row = db.execute(
                f"select value from ({state_projection('service_state')}) where key=?",
                (key,),
            ).fetchone()
            state = self._channel_login_state(row["value"] if row else None)
            reservation = db.execute(
                f"""
                select reservation_owner, reserved_at
                from ({state_projection('channel_login_reservations')})
                where channel=?
                """,
                (channel,),
            ).fetchone()
            started_at = state.get("started_at")
            if self._channel_login_timestamp_is_recent(
                started_at,
                now_utc,
                suppression_seconds,
            ) or (
                reservation is not None
                and self._channel_login_timestamp_is_recent(
                    reservation["reserved_at"],
                    now_utc,
                    suppression_seconds,
                )
            ):
                return False, state

            reserved_state = {
                **{
                    field: value
                    for field, value in state.items()
                    if field not in {"pid", "exited_at"}
                },
                "status": "starting",
                "reason_code": reason_code,
                "started_at": now_utc.isoformat(),
                "checked_at": now_utc.isoformat(),
            }
            upsert_state(
                db, 'channel_login_reservations',
                {'channel': channel, 'reservation_owner': reservation_owner,
                 'reserved_at': now_utc.isoformat()},
                {'reservation_owner': state_json_field('reservation_owner'),
                 'reserved_at': state_json_field('reserved_at')},
            )
            self._set_service_state_in_transaction(db, key, reserved_state)
            return True, reserved_state

    def update_claimed_channel_login_request(
        self,
        *,
        channel: str,
        reservation_owner: str,
        state: dict[str, object],
    ) -> bool:
        key = f"channel_login_request:{channel}"
        with self._immediate_write_transaction() as db:
            reservation = db.execute(
                f"""
                select reservation_owner
                from ({state_projection('channel_login_reservations')})
                where channel=?
                """,
                (channel,),
            ).fetchone()
            if (
                reservation is None
                or reservation["reservation_owner"] != reservation_owner
            ):
                return False
            row = db.execute(
                f"select value from ({state_projection('service_state')}) where key=?",
                (key,),
            ).fetchone()
            current = self._channel_login_state(row["value"] if row else None)
            self._set_service_state_in_transaction(db, key, {**current, **state})
            db.execute(
                "delete from state where record_type='channel_login_reservations' and channel=?",
                (channel,),
            )
            return True

    @staticmethod
    def _channel_login_state(raw: str | None) -> dict[str, object]:
        if not raw:
            return {}
        try:
            value = json.loads(raw)
        except json.JSONDecodeError:
            return {}
        return value if isinstance(value, dict) else {}

    @staticmethod
    def _channel_login_timestamp_is_recent(
        value: object,
        now: datetime,
        suppression_seconds: int,
    ) -> bool:
        if not isinstance(value, str):
            return False
        try:
            timestamp = datetime.fromisoformat(value)
        except ValueError:
            return False
        if timestamp.tzinfo is None:
            timestamp = timestamp.replace(tzinfo=timezone.utc)
        age_seconds = (now - timestamp.astimezone(timezone.utc)).total_seconds()
        return 0 <= age_seconds < suppression_seconds

    @staticmethod
    def _set_service_state_in_transaction(
        db: sqlite3.Connection,
        key: str,
        state: dict[str, object],
    ) -> None:
        safe_fields = {
            "status",
            "reason_code",
            "started_at",
            "checked_at",
            "exited_at",
            "pid",
        }
        safe_state = {
            field: value for field, value in state.items() if field in safe_fields
        }
        upsert_state(
            db, 'service_state',
            {'key': key, 'value': json.dumps(safe_state, ensure_ascii=False, sort_keys=True)},
            {'value': state_json_field('value'),
             'updated_at': 'json_quote(current_timestamp)'},
        )

    def get_service_state(self, key: str) -> str | None:
        projection = "(" + state_projection("service_state") + ")"
        with self._connect() as db:
            row = db.execute(
                f"select value from {projection} where key=?",
                (key,),
            ).fetchone()
            return None if row is None else row["value"]

    def upsert_setup_wizard_step(
        self,
        *,
        step_id: str,
        status: str,
        summary: str,
        manual_confirmed_by: str = "",
    ) -> None:
        with self._connect() as db:
            db.execute("begin")
            upsert_state(
                db, "setup_wizard_steps",
                {"step_id": step_id, "status": status, "summary": summary,
                 "manual_confirmed_by": manual_confirmed_by},
                {"status": state_json_field("status"),
                 "summary": state_json_field("summary"),
                 "manual_confirmed_at": (
                     "case when excluded.manual_confirmed_by != '' "
                     "then json_quote(current_timestamp) else " +
                     state_json_field("manual_confirmed_at", "state") + " end"
                 ),
                 "manual_confirmed_by": (
                     "case when excluded.manual_confirmed_by != '' then " +
                     state_json_field("manual_confirmed_by") + " else " +
                     state_json_field("manual_confirmed_by", "state") + " end"
                 ),
                 "updated_at": "json_quote(current_timestamp)"},
                insert_json={"manual_confirmed_at":
                             "json_quote(case when ? != '' then current_timestamp else '' end)"},
                insert_parameters=(manual_confirmed_by,),
            )

    def get_setup_wizard_step(self, step_id: str) -> dict[str, str] | None:
        projection = "(" + state_projection("setup_wizard_steps") + ")"
        with self._connect() as db:
            row = db.execute(
                f"""
                select step_id, status, summary, manual_confirmed_at,
                       manual_confirmed_by, updated_at
                from {projection}
                where step_id=?
                """,
                (step_id,),
            ).fetchone()
            return dict(row) if row is not None else None

    def list_setup_wizard_steps(self) -> list[dict[str, str]]:
        projection = "(" + state_projection("setup_wizard_steps") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"""
                select step_id, status, summary, manual_confirmed_at,
                       manual_confirmed_by, updated_at
                from {projection}
                order by updated_at desc, step_id
                """
            ).fetchall()
            return [dict(row) for row in rows]

    def record_setup_wizard_event(
        self,
        *,
        step_id: str,
        action_id: str,
        status: str,
        summary: str = "",
        evidence_json: str = "{}",
        stdout_excerpt: str = "",
        stderr_excerpt: str = "",
    ) -> int:
        with self._connect() as db:
            result = db.execute(
                "insert into setup_wizard_events "
                "(step_id,action_id,status,summary,evidence_json,stdout_excerpt,stderr_excerpt,created_at,finished_at) "
                "values(?,?,?,?,?,?,?,current_timestamp,case when ?='running' then '' else current_timestamp end)",
                (step_id, action_id, status, summary, evidence_json, stdout_excerpt,
                 stderr_excerpt, status),
            )
            return int(result.lastrowid)

    def list_setup_wizard_events(
        self,
        step_id: str | None = None,
        *,
        action_id: str | None = None,
        limit: int = 20,
    ) -> list[dict[str, str | int]]:
        with self._connect() as db:
            args: list[str | int] = []
            conditions: list[str] = []
            if step_id is not None:
                conditions.append("step_id=?")
                args.append(step_id)
            if action_id is not None:
                conditions.append("action_id=?")
                args.append(action_id)
            where = "where " + " and ".join(conditions) if conditions else ""
            args.append(limit)
            rows = db.execute(
                f"""
                select id, step_id, action_id, status, summary, evidence_json,
                       stdout_excerpt, stderr_excerpt, created_at as started_at, finished_at
                from setup_wizard_events
                {where}
                order by id desc
                limit ?
                """,
                args,
            ).fetchall()
            return [dict(row) for row in rows]

    def upsert_org_user_profile(
        self,
        user_id: str,
        name: str,
        open_dingtalk_id: str | None,
        manager_user_id: str | None,
        department_ids: set[str],
        title: str = "",
        manager_name: str = "",
        department_names: set[str] | None = None,
        org_labels: list[str] | None = None,
        has_subordinate: bool | None = None,
    ) -> None:
        department_names = department_names or set()
        org_labels = org_labels or []
        values = {
            "user_id": user_id, "name": name, "title": title,
            "open_dingtalk_id": open_dingtalk_id,
            "manager_user_id": manager_user_id, "manager_name": manager_name,
            "department_ids_json": json.dumps(sorted(department_ids), ensure_ascii=False),
            "department_names_json": json.dumps(sorted(department_names), ensure_ascii=False),
            "org_labels_json": json.dumps(org_labels, ensure_ascii=False),
            "has_subordinate": None if has_subordinate is None else int(has_subordinate),
        }
        with self._connect() as db:
            db.execute("begin")
            upsert_state(
                db, "org_user_profiles", values,
                {field: state_json_field(field) for field in values if field != "user_id"}
                | {"fetched_at": "json_quote(current_timestamp)"},
            )

    def get_org_user_profile(self, user_id: str) -> OrgUserProfile | None:
        projection = "(" + state_projection("org_user_profiles") + ")"
        with self._connect() as db:
            row = db.execute(
                f"select * from {projection} where user_id=?",
                (user_id,),
            ).fetchone()
            return self._org_user_profile_from_row(row)

    def find_org_user_by_open_dingtalk_id(
        self, open_dingtalk_id: str
    ) -> OrgUserProfile | None:
        projection = "(" + state_projection("org_user_profiles") + ")"
        with self._connect() as db:
            row = db.execute(
                f"""
                select * from {projection}
                where open_dingtalk_id=?
                """,
                (open_dingtalk_id,),
            ).fetchone()
            return self._org_user_profile_from_row(row)

    def find_org_users_by_name(self, name: str) -> list[OrgUserProfile]:
        projection = "(" + state_projection("org_user_profiles") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"select * from {projection} where name=? order by user_id",
                (name,),
            ).fetchall()
            return [
                profile
                for row in rows
                if (profile := self._org_user_profile_from_row(row)) is not None
            ]

    def list_org_user_ids(self) -> list[str]:
        projection = "(" + state_projection("org_user_profiles") + ")"
        with self._connect() as db:
            rows = db.execute(
                f"select user_id from {projection} order by user_id"
            ).fetchall()
            return [row["user_id"] for row in rows]

    def set_current_user_id(self, user_id: str) -> None:
        self._set_metadata("current_user_id", user_id)

    def get_current_user_id(self) -> str | None:
        return self._get_metadata("current_user_id")

    def set_hr_department_ids(self, department_ids: set[str]) -> None:
        self._set_metadata("hr_department_ids", sorted(department_ids))

    def get_hr_department_ids(self) -> set[str]:
        value = self._get_metadata("hr_department_ids")
        if not isinstance(value, list):
            return set()
        return {str(item) for item in value if item}

    def _set_metadata(self, key: str, value) -> None:
        with self._connect() as db:
            db.execute("begin")
            upsert_state(
                db, "org_cache_metadata",
                {"key": key, "value_json": json.dumps(value, ensure_ascii=False)},
                {"value_json": state_json_field("value_json"),
                 "updated_at": "json_quote(current_timestamp)"},
            )

    def _get_metadata(self, key: str):
        projection = "(" + state_projection("org_cache_metadata") + ")"
        with self._connect() as db:
            row = db.execute(
                f"select value_json from {projection} where key=?",
                (key,),
            ).fetchone()
            if row is None:
                return None
            return json.loads(row["value_json"])

    @staticmethod
    def _org_user_profile_from_row(row: sqlite3.Row | None) -> OrgUserProfile | None:
        if row is None:
            return None
        return OrgUserProfile(
            user_id=row["user_id"],
            name=row["name"],
            title=row["title"],
            open_dingtalk_id=row["open_dingtalk_id"],
            manager_user_id=row["manager_user_id"],
            manager_name=row["manager_name"],
            department_ids=set(json.loads(row["department_ids_json"])),
            department_names=set(json.loads(row["department_names_json"])),
            org_labels=list(json.loads(row["org_labels_json"])),
            has_subordinate=(
                None
                if row["has_subordinate"] is None
                else bool(row["has_subordinate"])
            ),
        )
